# =========================
# v33 confirm-target patch
# =========================
# Focus: P30 curl-clean family route, curl-template regression/projection, quadrant rotations;
# plus stricter execution contracts for P36/P41/P33/P32.

import math as _math_v33
import json as _json_v33
from pathlib import Path as _Path_v33

_run_p30_v32_for_v33 = run_p30_maskrandom_freeze_v32
_run_highz_v32_for_v33 = run_highz_unit_field_table_v32
_run_p41_v32_for_v33 = run_p41_structured_cp_v32
_run_p33_v32_for_v33 = run_p33_density_bao_measured_scaffold_v32
_run_p32_v32_for_v33 = run_ringdown_strain_plan_v32
_run_dashboard_v32_for_v33 = run_dashboard_v32


def _v33_write_json(path, obj):
    try:
        p=_Path_v33(path); p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(_json_v33.dumps(obj, indent=2, sort_keys=True), encoding='utf-8')
    except Exception:
        pass


def _v33_float(x):
    try:
        if x is None: return None
        f=float(x)
        if not _math_v33.isfinite(f): return None
        return f
    except Exception:
        return None


def _v33_binom_tail_ge(k, n, p=0.5):
    try:
        from math import comb
        return sum(comb(n, i)*(p**i)*((1-p)**(n-i)) for i in range(k, n+1))
    except Exception:
        return None


def _v33_p30_artifacts(base):
    outputs=_v32_outputs_dir()
    same_obj, variants, same_path = _v32_same_split_artifact(base, outputs)
    sci, curl = _v32_science_and_curl(variants)
    rem = base.get('p30_curl_remediation_v32') or {}
    basic = rem.get('basic') or base.get('p30_curl_diagnostics_v31') or {}
    cdelta = _v33_float(basic.get('curl_delta'))
    if cdelta is None:
        cdelta = _v33_float((curl or {}).get('delta_high_minus_low'))
    return outputs, same_obj, variants, sci, curl, cdelta, rem, same_path


def _v33_core_variant_report(sci, cdelta):
    core_names=['baseline','f150','tonly']
    weak_names=['f090','cibdeproj']
    rows=[]
    for v in sci:
        d=_v33_float(v.get('delta_high_minus_low'))
        if d is None: continue
        row={
            'variant': v.get('variant'),
            'science_delta': d,
            'density_shuffle_p_high': v.get('density_shuffle_p_high'),
            'jackknife_same_sign': bool(v.get('jackknife_same_sign')),
            'positive_pass': bool(v.get('positive_pass')),
        }
        if cdelta is not None:
            row.update({
                'curl_delta': cdelta,
                'science_minus_curl': d-cdelta,
                'science_minus_abs_curl': d-abs(cdelta),
                'survives_signed_curl_subtraction': bool(d-cdelta > 0),
                'survives_abs_curl_subtraction': bool(d-abs(cdelta) > 0),
                'science_over_abs_curl': (d/abs(cdelta)) if abs(cdelta)>0 else None,
            })
        rows.append(row)
    by={r['variant']:r for r in rows}
    core=[by[n] for n in core_names if n in by]
    weak=[by[n] for n in weak_names if n in by]
    core_survive=sum(1 for r in core if r.get('survives_abs_curl_subtraction'))
    weak_survive=sum(1 for r in weak if r.get('survives_abs_curl_subtraction'))
    return {
        'available': bool(rows) and cdelta is not None,
        'policy': 'route-specific diagnostic: core variants are baseline/f150/tonly; f090/cibdeproj are treated as weak/systematics-sensitive unless they also survive curl subtraction',
        'core_variant_names': core_names,
        'weak_or_systematics_sensitive_variant_names': weak_names,
        'variant_rows': rows,
        'n_core_available': len(core),
        'n_core_survive_abs_curl_subtraction': core_survive,
        'n_weak_available': len(weak),
        'n_weak_survive_abs_curl_subtraction': weak_survive,
        'core_family_pass': bool(len(core)>=3 and core_survive>=3),
        'interpretation': 'If core_family_pass is true but curl remediation still fails, keep P30-SDSS as near-confirm/curl-contaminated rather than confirm-like.'
    }


def _v33_science_vs_curl_likelihood(sci, cdelta):
    deltas=[_v33_float(v.get('delta_high_minus_low')) for v in sci]
    deltas=[d for d in deltas if d is not None]
    if cdelta is None or not deltas:
        return {'available': False, 'reason': 'requires science deltas and curl delta'}
    cabs=abs(cdelta)
    stronger=[d for d in deltas if abs(d)>cabs and d>0]
    positive=[d for d in deltas if d>0]
    k=len(stronger); n=len(deltas)
    p_tail=_v33_binom_tail_ge(k,n,0.5)
    # Lightweight paired bootstrap over variants.
    try:
        import random
        rng=random.Random(33033)
        ratios=[]
        for _ in range(2000):
            sample=[rng.choice(deltas) for __ in range(n)]
            med=sorted(abs(x) for x in sample)[n//2] if n%2 else 0.5*(sorted(abs(x) for x in sample)[n//2-1]+sorted(abs(x) for x in sample)[n//2])
            if med>0: ratios.append(cabs/med)
        ratios.sort()
        ci16=ratios[int(0.16*(len(ratios)-1))] if ratios else None
        ci84=ratios[int(0.84*(len(ratios)-1))] if ratios else None
    except Exception:
        ci16=ci84=None
    return {
        'available': True,
        'n_science_variants': n,
        'n_positive_science_variants': len(positive),
        'n_science_stronger_than_abs_curl': k,
        'one_sided_sign_tail_p_for_science_gt_curl': p_tail,
        'median_abs_science_delta': (sorted(abs(x) for x in deltas)[n//2] if n%2 else 0.5*(sorted(abs(x) for x in deltas)[n//2-1]+sorted(abs(x) for x in deltas)[n//2])),
        'curl_abs_delta': cabs,
        'curl_to_median_science_ratio': cabs/(sorted(abs(x) for x in deltas)[n//2] if n%2 else 0.5*(sorted(abs(x) for x in deltas)[n//2-1]+sorted(abs(x) for x in deltas)[n//2])),
        'bootstrap_ratio_ci16': ci16,
        'bootstrap_ratio_ci84': ci84,
        'likelihood_ratio_pass_suggestive': bool(k>=3 and (p_tail is not None and p_tail<=0.5)),
        'claim_note': 'suggestive only: variant-count tests are low-N and cannot by themselves confirm P30.'
    }


def _v33_project_out_curl_heavy(meta, args, variants=None):
    if not getattr(args, 'allow_large', False) or getattr(args, 'quick', False):
        return {'available': False, 'reason': 'rerun P30 with --allow-large to compute curl-template regression/projection'}
    try:
        import numpy as np
        import healpy as hp
    except Exception as e:
        return {'available': False, 'reason': 'numpy/healpy unavailable: '+str(e)}
    try:
        coords, coord_src = _v29_get_sdss_coords(meta, args)
        rand_path = _v29_cache_dir(args) / 'p30_sdss_random_catalogue_v28.csv'
        rand = _v28_coord_rows_from_dicts(_v28_safe_rows_from_csv(rand_path)) if rand_path.exists() else []
        split = _v29_build_random_normalized_split(coords, rand, density_nside=64)
        if not split.get('available'):
            return {'available': False, 'reason': 'random-normalized split unavailable'}
        data=split.get('_data_coords') or []
        if len(data)<50:
            return {'available': False, 'reason': 'too few SDSS data coordinates in split'}
        curl_map, curl_info = _v29_variant_map(meta, args, 'curl_control')
        if curl_map is None:
            return {'available': False, 'reason': 'curl map unavailable', 'curl_info': curl_info}
        curl_arr=np.asarray(curl_map, dtype=float); nside=hp.get_nside(curl_arr)
        ra=np.asarray([c['ra'] for c in data], dtype=float); dec=np.asarray([c['dec'] for c in data], dtype=float)
        pix=hp.ang2pix(nside, np.radians(90-dec), np.radians(ra))
        curl_vals=curl_arr[pix]
        hi=np.asarray(split['_hi_mask']); lo=np.asarray(split['_lo_mask'])
        rows=[]
        for variant in ['baseline','f090','f150','tonly','cibdeproj']:
            smap, sinfo = _v29_variant_map(meta, args, variant)
            if smap is None:
                rows.append({'variant': variant, 'available': False, 'reason': 'map unavailable', 'info': sinfo})
                continue
            sarr=np.asarray(smap, dtype=float); spix=hp.ang2pix(hp.get_nside(sarr), np.radians(90-dec), np.radians(ra))
            y=sarr[spix]
            finite=np.isfinite(y)&np.isfinite(curl_vals)&hi.astype(bool)| (np.isfinite(y)&np.isfinite(curl_vals)&lo.astype(bool))
            # Use all finite data for beta; high/low for delta.
            finite=np.isfinite(y)&np.isfinite(curl_vals)
            if finite.sum()<50:
                rows.append({'variant': variant, 'available': False, 'reason': 'too few finite samples', 'n_finite': int(finite.sum())})
                continue
            x=curl_vals[finite]; yy=y[finite]
            x0=x-np.nanmean(x); y0=yy-np.nanmean(yy)
            beta=float(np.nansum(x0*y0)/max(np.nansum(x0*x0), 1e-30))
            alpha=float(np.nanmean(yy)-beta*np.nanmean(x))
            resid=y-(alpha+beta*curl_vals)
            raw_delta=float(np.nanmean(y[hi])-np.nanmean(y[lo]))
            resid_delta=float(np.nanmean(resid[hi])-np.nanmean(resid[lo]))
            proj_delta=float(np.nanmean((y-beta*curl_vals)[hi])-np.nanmean((y-beta*curl_vals)[lo]))
            rows.append({
                'variant': variant,
                'available': True,
                'n_finite': int(finite.sum()),
                'beta_science_vs_curl': beta,
                'alpha': alpha,
                'raw_delta': raw_delta,
                'regression_residual_delta': resid_delta,
                'curl_orthogonal_projection_delta': proj_delta,
                'residual_positive': bool(resid_delta>0),
                'projection_positive': bool(proj_delta>0),
            })
        good=[r for r in rows if r.get('available')]
        return {
            'available': bool(good),
            'coord_source': coord_src,
            'n_data_coords': len(data),
            'rows': rows,
            'n_residual_positive': sum(1 for r in good if r.get('residual_positive')),
            'n_projection_positive': sum(1 for r in good if r.get('projection_positive')),
            'core_projection_pass': bool(sum(1 for r in good if r.get('variant') in ['baseline','f150','tonly'] and r.get('projection_positive'))>=3),
            'claim_note': 'template projection is a diagnostic contamination test; route confirmation still requires explicit gate policy.'
        }
    except Exception as e:
        return {'available': False, 'reason': 'curl template projection failed: '+repr(e)}


def _v33_quadrant_rotation_controls_heavy(meta, args):
    if not getattr(args, 'allow_large', False) or getattr(args, 'quick', False):
        return {'available': False, 'reason': 'rerun P30 with --allow-large to compute quadrant/stripe rotations'}
    try:
        import numpy as np
        import healpy as hp
    except Exception as e:
        return {'available': False, 'reason': 'numpy/healpy unavailable: '+str(e)}
    try:
        coords, coord_src = _v29_get_sdss_coords(meta, args)
        rand_path = _v29_cache_dir(args) / 'p30_sdss_random_catalogue_v28.csv'
        rand = _v28_coord_rows_from_dicts(_v28_safe_rows_from_csv(rand_path)) if rand_path.exists() else []
        split = _v29_build_random_normalized_split(coords, rand, density_nside=64)
        if not split.get('available'):
            return {'available': False, 'reason': 'random-normalized split unavailable'}
        kmap, info = _v29_variant_map(meta, args, 'curl_control')
        if kmap is None:
            return {'available': False, 'reason': 'curl map unavailable', 'info': info}
        arr=np.asarray(kmap,dtype=float); nside=hp.get_nside(arr)
        data=split.get('_data_coords') or []
        ra=np.asarray([c['ra'] for c in data], dtype=float); dec=np.asarray([c['dec'] for c in data], dtype=float)
        hi=np.asarray(split['_hi_mask']); lo=np.asarray(split['_lo_mask'])
        pix=hp.ang2pix(nside, np.radians(90-dec), np.radians(ra)); val=arr[pix]
        obs=float(np.nanmean(val[hi])-np.nanmean(val[lo]))
        med_ra=float(np.nanmedian(ra)); med_dec=float(np.nanmedian(dec))
        quads=[('q00',(ra<med_ra)&(dec<med_dec)),('q01',(ra<med_ra)&(dec>=med_dec)),('q10',(ra>=med_ra)&(dec<med_dec)),('q11',(ra>=med_ra)&(dec>=med_dec))]
        rot_deltas=[]; rows=[]
        offsets=[30,60,90,120,150,180]
        for qname,mask in quads:
            if mask.sum()<20: continue
            qrows=[]
            for off in offsets:
                ra2=ra.copy(); ra2[mask]=(ra2[mask]+off)%360.0
                pix2=hp.ang2pix(nside, np.radians(90-dec), np.radians(ra2)); v2=arr[pix2]
                d=float(np.nanmean(v2[hi])-np.nanmean(v2[lo]))
                rot_deltas.append(d); qrows.append({'offset_deg':off,'delta':d})
            rows.append({'quadrant':qname,'n':int(mask.sum()),'rotations':qrows})
        if not rot_deltas:
            return {'available': False, 'reason': 'no quadrant rotations produced'}
        absnull=[abs(x) for x in rot_deltas]; p_high=sum(1 for x in rot_deltas if x>=obs)/len(rot_deltas); abs_pct=sum(1 for x in absnull if x<=abs(obs))/len(absnull)
        return {
            'available': True,
            'coord_source': coord_src,
            'observed_curl_delta': obs,
            'n_rotation_deltas': len(rot_deltas),
            'rotation_p_high': p_high,
            'rotation_abs_percentile': abs_pct,
            'curl_weakened_by_quadrant_rotations': bool(0.05 < p_high < 0.95 and abs_pct < 0.95),
            'quadrant_rows': rows,
        }
    except Exception as e:
        return {'available': False, 'reason': 'quadrant rotation controls failed: '+repr(e)}


def run_p30_maskrandom_freeze_v33(meta, args):
    base=_run_p30_v32_for_v33(meta,args)
    outputs, same_obj, variants, sci, curl, cdelta, rem, same_path = _v33_p30_artifacts(base)
    core=_v33_core_variant_report(sci, cdelta)
    ratio=_v33_science_vs_curl_likelihood(sci, cdelta)
    projection=_v33_project_out_curl_heavy(meta,args,variants)
    quadrant=_v33_quadrant_rotation_controls_heavy(meta,args)
    report={
        'core_variant_family': core,
        'science_stronger_than_curl_likelihood': ratio,
        'curl_template_regression_projection': projection,
        'quadrant_rotation_controls': quadrant,
        'euclid_policy': 'quarantined from global P30 until photo-z/depth/quality cuts plus field randoms pass',
        'same_split_artifact_path': same_path,
        'claim_policy': 'P30-SDSS can only become route-specific confirm if core variants survive curl correction, curl template/projection checks pass, and curl/quadrant controls are non-significant or explainable.'
    }
    remediation_pass=bool(
        core.get('core_family_pass') and
        ratio.get('available') and ratio.get('n_science_stronger_than_abs_curl',0)>=3 and
        ((projection.get('available') and projection.get('core_projection_pass')) or not getattr(args,'allow_large',False)) and
        ((quadrant.get('available') and quadrant.get('curl_weakened_by_quadrant_rotations')) or not getattr(args,'allow_large',False)) and
        (rem.get('remediation_pass') is True)
    )
    # Keep this strict: v32 remediation must pass too; otherwise this is a curl-contaminated near-confirm only.
    report['v33_remediation_pass'] = remediation_pass
    _v33_write_json(outputs/'p30_curl_clean_route_v33.json', report)
    base['p30_curl_clean_route_v33']={
        'path': str(outputs/'p30_curl_clean_route_v33.json'),
        'core_family_pass': core.get('core_family_pass'),
        'n_core_survive_abs_curl_subtraction': core.get('n_core_survive_abs_curl_subtraction'),
        'science_stronger_than_curl_available': ratio.get('available'),
        'n_science_stronger_than_abs_curl': ratio.get('n_science_stronger_than_abs_curl'),
        'template_projection_available': projection.get('available'),
        'core_projection_pass': projection.get('core_projection_pass'),
        'quadrant_rotation_available': quadrant.get('available'),
        'curl_weakened_by_quadrant_rotations': quadrant.get('curl_weakened_by_quadrant_rotations'),
        'v33_remediation_pass': remediation_pass,
    }
    # Route-specific promotion is deliberately stricter than v31/v32 and will not overclaim if curl remains significant.
    prev_gate = base.get('p30_sdss_route_confirm_gate_v32') or base.get('p30_sdss_route_confirm_gate_v31') or {}
    rand_ok=bool(prev_gate.get('random_normalized_route'))
    same_ok=bool(prev_gate.get('same_split_science_variants'))
    jack_ok=bool(prev_gate.get('jackknife_stable'))
    boot_ok=bool(prev_gate.get('bootstrap_ci_positive'))
    base['p30_sdss_route_confirm_gate_v33']=_v32_gate(
        random_normalized_route=rand_ok,
        same_split_science_variants=same_ok,
        jackknife_stable=jack_ok,
        bootstrap_ci_positive=boot_ok,
        core_curl_clean_family=bool(core.get('core_family_pass')),
        curl_remediation_pass=remediation_pass,
        global_scope=False,
    )
    base['p30_global_confirm_gate_v33']=_v32_gate(
        sdss_route_confirm=base['p30_sdss_route_confirm_gate_v33']['eligible_for_confirm_like'],
        second_independent_route=False,
    )
    if base['p30_sdss_route_confirm_gate_v33']['eligible_for_confirm_like']:
        base['status']='p30_sdss_route_confirm_like'
    else:
        base['status']='density_kappa_sdss_route_curl_contaminated_near_confirm'
    return base


