def run_dashboard_v33(meta,args):
    base=_run_dashboard_v32_for_v33(meta,args)
    outputs=_v32_outputs_dir(); rows=[]
    for p in sorted(outputs.glob('test*.json')):
        obj=_v32_read_json(p)
        if isinstance(obj,dict): rows.append(obj)
    instr=[]; p30=[]; pub=[]; blocked=[]
    for r in rows:
        keys=[k for k in r if k.endswith('_v33') or '_v33_' in k]
        if keys:
            instr.append({'test_id':r.get('test_id'), 'prediction_id':r.get('prediction_id'), 'status':r.get('status'), 'v33_keys':sorted(keys)})
        if r.get('p30_curl_clean_route_v33'):
            p30.append({'test_id':r.get('test_id'), 'status':r.get('status'), 'curl_clean':r.get('p30_curl_clean_route_v33'), 'gate':r.get('p30_sdss_route_confirm_gate_v33')})
        st=str(r.get('status',''))
        if 'publication_confirm_like' in st or st in ['robust_confirm_like','void_morphology_publication_grade_confirm_like','p30_sdss_route_confirm_like']:
            pub.append({'test_id':r.get('test_id'), 'prediction_id':r.get('prediction_id'), 'status':st})
        for k,v in r.items():
            if isinstance(v,dict) and k.endswith('_gate_v33') and not v.get('eligible_for_confirm_like', True):
                blocked.append({'test_id':r.get('test_id'), 'prediction_id':r.get('prediction_id'), 'gate':k, 'missing':v.get('missing')})
    base['dashboard_v33']={
        'n_v33_instrumented_tests':len(instr),
        'v33_instrumented_tests':instr[:200],
        'publication_grade_confirm_like':pub,
        'p30_curl_clean_route':p30,
        'blocked_confirm_gates':blocked[:200],
        'claim_policy':'v33 separates P30 curl-clean core-family diagnostics from publication confirmation. Curl-contaminated routes remain near-confirm only.'
    }
    base['status']='dashboard_positive_summary'
    return base


