# =========================
# v34 confirm-target patch
# =========================
# Focus: P30-SDSS-core curl-projected residual test, paired bootstrap and patch jackknife;
# P3 endpoint prefilter; plus stricter consumers/contracts for P36/P41/P33/P32.

import math as _math_v34
import json as _json_v34
import re as _re_v34
from pathlib import Path as _Path_v34

_run_p30_v33_for_v34 = run_p30_maskrandom_freeze_v33
_run_p3_v33_for_v34 = run_p3_exact_metadata_v21
_run_highz_v33_for_v34 = run_highz_unit_field_table_v33
_run_p41_v33_for_v34 = run_p41_structured_cp_v33
_run_p33_v33_for_v34 = run_p33_density_bao_measured_scaffold_v33
_run_p32_v33_for_v34 = run_ringdown_strain_plan_v33
_run_dashboard_v33_for_v34 = run_dashboard_v33


def _v34_write_json(path, obj):
    try:
        p=_Path_v34(path); p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(_json_v34.dumps(obj, indent=2, sort_keys=True), encoding='utf-8')
    except Exception:
        pass


def _v34_float(x):
    try:
        if x is None: return None
        f=float(x)
        if not _math_v34.isfinite(f): return None
        return f
    except Exception:
        return None


def _v34_quantile(vals, q):
    vals=sorted([float(v) for v in vals if v is not None and _math_v34.isfinite(float(v))])
    if not vals: return None
    if len(vals)==1: return vals[0]
    pos=(len(vals)-1)*q
    lo=int(_math_v34.floor(pos)); hi=int(_math_v34.ceil(pos))
    if lo==hi: return vals[lo]
    return vals[lo]*(hi-pos)+vals[hi]*(pos-lo)


def _v34_p30_core_projection_heavy(meta, args):
    """Heavy P30-SDSS-core residual test. Runs only with --allow-large."""
    outputs=_v32_outputs_dir()
    if not getattr(args, 'allow_large', False) or getattr(args, 'quick', False):
        return {'available': False, 'reason': 'run P30 with --allow-large to compute v34 curl-projected residual test'}
    try:
        import numpy as np
        import healpy as hp
        import random as _random_v34
    except Exception as e:
        return {'available': False, 'reason': 'numpy/healpy unavailable: '+str(e)}
    try:
        coords, coord_src = _v29_get_sdss_coords(meta, args)
        rand_path = _v29_cache_dir(args) / 'p30_sdss_random_catalogue_v28.csv'
        rand = _v28_coord_rows_from_dicts(_v28_safe_rows_from_csv(rand_path)) if rand_path.exists() else []
        split = _v29_build_random_normalized_split(coords, rand, density_nside=64)
        if not split.get('available'):
            return {'available': False, 'reason': 'random-normalized SDSS split unavailable', 'split': {k:v for k,v in split.items() if not str(k).startswith('_')}}
        data=split.get('_data_coords') or []
        if len(data)<100:
            return {'available': False, 'reason': 'too few SDSS coordinates after split', 'n': len(data)}
        hi=np.asarray(split['_hi_mask'], dtype=bool); lo=np.asarray(split['_lo_mask'], dtype=bool)
        ra=np.asarray([c['ra'] for c in data], dtype=float); dec=np.asarray([c['dec'] for c in data], dtype=float)
        curl_map, curl_info = _v29_variant_map(meta, args, 'curl_control')
        if curl_map is None:
            return {'available': False, 'reason': 'curl map unavailable', 'curl_info': curl_info}
        c_arr=np.asarray(curl_map, dtype=float); cnside=hp.get_nside(c_arr)
        cpix=hp.ang2pix(cnside, np.radians(90-dec), np.radians(ra))
        cval=c_arr[cpix]
        core_names=['baseline','f150','tonly']
        variant_rows=[]; y_stack=[]
        for name in core_names:
            smap, sinfo = _v29_variant_map(meta, args, name)
            if smap is None:
                variant_rows.append({'variant': name, 'available': False, 'reason': 'map unavailable', 'info': sinfo})
                continue
            s_arr=np.asarray(smap, dtype=float); snside=hp.get_nside(s_arr)
            spix=hp.ang2pix(snside, np.radians(90-dec), np.radians(ra))
            y=s_arr[spix]
            finite=np.isfinite(y)&np.isfinite(cval)&(hi|lo)
            if finite.sum()<100:
                variant_rows.append({'variant': name, 'available': False, 'reason': 'too few finite high/low samples', 'n_finite': int(finite.sum())})
                continue
            # beta from all finite positions; residual delta on high/low masks.
            x=cval[finite]; yy=y[finite]
            x0=x-np.nanmean(x); y0=yy-np.nanmean(yy)
            beta=float(np.nansum(x0*y0)/max(np.nansum(x0*x0), 1e-30))
            alpha=float(np.nanmean(yy)-beta*np.nanmean(x))
            resid=y-(alpha+beta*cval)
            proj=y-beta*cval
            raw_delta=float(np.nanmean(y[hi])-np.nanmean(y[lo]))
            resid_delta=float(np.nanmean(resid[hi])-np.nanmean(resid[lo]))
            proj_delta=float(np.nanmean(proj[hi])-np.nanmean(proj[lo]))
            # label-shuffle null for residual delta.
            rng=np.random.default_rng(int(getattr(args,'seed',12345))+3400+len(variant_rows))
            labels=np.zeros(len(y), dtype=int); labels[hi]=1; labels[lo]=-1
            valid=(hi|lo)&np.isfinite(resid)
            resid_valid=resid[valid]; labels_valid=labels[valid]
            null=[]
            if len(resid_valid)>50:
                for _ in range(256):
                    sh=labels_valid.copy(); rng.shuffle(sh)
                    if np.any(sh==1) and np.any(sh==-1):
                        null.append(float(np.nanmean(resid_valid[sh==1])-np.nanmean(resid_valid[sh==-1])))
            p_high=(sum(1 for v in null if v>=resid_delta)/len(null)) if null else None
            variant_rows.append({
                'variant': name,
                'available': True,
                'n_finite': int(finite.sum()),
                'beta_science_vs_curl': beta,
                'alpha': alpha,
                'raw_delta': raw_delta,
                'projection_delta': proj_delta,
                'regression_residual_delta': resid_delta,
                'residual_shuffle_p_high': p_high,
                'residual_positive': bool(resid_delta>0),
                'residual_significant_positive': bool(resid_delta>0 and p_high is not None and p_high<=0.05),
            })
            y_stack.append(proj)
        good=[r for r in variant_rows if r.get('available')]
        if not good or len(y_stack)<2:
            return {'available': False, 'reason': 'too few core science maps available', 'variant_rows': variant_rows}
        core_proj=np.nanmean(np.vstack(y_stack), axis=0)
        core_delta=float(np.nanmean(core_proj[hi])-np.nanmean(core_proj[lo]))
        curl_delta=float(np.nanmean(cval[hi])-np.nanmean(cval[lo]))
        # paired bootstrap on high/low object indices for core-curl difference.
        rng=_random_v34.Random(int(getattr(args,'seed',12345))+3434)
        hi_idx=[i for i,b in enumerate(hi) if b and _math_v34.isfinite(float(core_proj[i])) and _math_v34.isfinite(float(cval[i]))]
        lo_idx=[i for i,b in enumerate(lo) if b and _math_v34.isfinite(float(core_proj[i])) and _math_v34.isfinite(float(cval[i]))]
        bs_core=[]; bs_curl=[]; bs_diff=[]
        if len(hi_idx)>20 and len(lo_idx)>20:
            for _ in range(1000):
                hs=[rng.choice(hi_idx) for __ in hi_idx]
                ls=[rng.choice(lo_idx) for __ in lo_idx]
                cd=float(np.nanmean(core_proj[hs])-np.nanmean(core_proj[ls]))
                kd=float(np.nanmean(cval[hs])-np.nanmean(cval[ls]))
                bs_core.append(cd); bs_curl.append(kd); bs_diff.append(cd-abs(kd))
        paired={
            'available': bool(bs_diff),
            'core_delta': core_delta,
            'curl_delta': curl_delta,
            'core_minus_abs_curl_delta': core_delta-abs(curl_delta),
            'core_ci16': _v34_quantile(bs_core,0.16),
            'core_ci84': _v34_quantile(bs_core,0.84),
            'curl_ci16': _v34_quantile(bs_curl,0.16),
            'curl_ci84': _v34_quantile(bs_curl,0.84),
            'core_minus_abs_curl_ci16': _v34_quantile(bs_diff,0.16),
            'core_minus_abs_curl_ci84': _v34_quantile(bs_diff,0.84),
            'p_core_minus_abs_curl_le_0': (sum(1 for v in bs_diff if v<=0)/len(bs_diff)) if bs_diff else None,
            'paired_bootstrap_pass': bool(bs_diff and _v34_quantile(bs_diff,0.16) is not None and _v34_quantile(bs_diff,0.16)>0),
        }
        # Residual curl null: regress curl against core science projection and inspect residual curl high-low.
        valid=np.isfinite(core_proj)&np.isfinite(cval)&(hi|lo)
        x=core_proj[valid]; y=cval[valid]
        x0=x-np.nanmean(x); y0=y-np.nanmean(y)
        beta_c=float(np.nansum(x0*y0)/max(np.nansum(x0*x0),1e-30))
        alpha_c=float(np.nanmean(y)-beta_c*np.nanmean(x))
        curl_resid=cval-(alpha_c+beta_c*core_proj)
        curl_resid_delta=float(np.nanmean(curl_resid[hi])-np.nanmean(curl_resid[lo]))
        # label-shuffle p for curl residual
        null=[]
        labels=np.zeros(len(core_proj), dtype=int); labels[hi]=1; labels[lo]=-1
        vmask=(hi|lo)&np.isfinite(curl_resid)
        vals=curl_resid[vmask]; labs=labels[vmask]
        rng=np.random.default_rng(int(getattr(args,'seed',12345))+3499)
        for _ in range(512):
            sh=labs.copy(); rng.shuffle(sh)
            if np.any(sh==1) and np.any(sh==-1):
                null.append(float(np.nanmean(vals[sh==1])-np.nanmean(vals[sh==-1])))
        p_hi=sum(1 for v in null if v>=curl_resid_delta)/len(null) if null else None
        p_abs=sum(1 for v in null if abs(v)>=abs(curl_resid_delta))/len(null) if null else None
        residual_curl_null={
            'available': True,
            'beta_curl_vs_core_science': beta_c,
            'curl_residual_delta': curl_resid_delta,
            'curl_residual_shuffle_p_high': p_hi,
            'curl_residual_two_sided_p_abs': p_abs,
            'residual_curl_null_pass': bool(p_abs is not None and p_abs>0.05 and abs(curl_resid_delta) < 0.5*abs(core_delta)),
        }
        # Patch-level jackknife by 4x2 RA/Dec tiles.
        ra_edges=np.quantile(ra, [0,0.25,0.5,0.75,1.0]); dec_edges=np.quantile(dec, [0,0.5,1.0])
        tiles=[]
        for i in range(4):
            for j in range(2):
                mask=(ra>=ra_edges[i])&(ra<=ra_edges[i+1])&(dec>=dec_edges[j])&(dec<=dec_edges[j+1])&(hi|lo)
                if mask.sum()<30 or not np.any(mask&hi) or not np.any(mask&lo):
                    continue
                d_core=float(np.nanmean(core_proj[mask&hi])-np.nanmean(core_proj[mask&lo]))
                d_curl=float(np.nanmean(cval[mask&hi])-np.nanmean(cval[mask&lo]))
                d_rescurl=float(np.nanmean(curl_resid[mask&hi])-np.nanmean(curl_resid[mask&lo]))
                tiles.append({'tile': f'ra{i}_dec{j}', 'n': int(mask.sum()), 'core_delta': d_core, 'curl_delta': d_curl, 'core_minus_abs_curl': d_core-abs(d_curl), 'curl_residual_delta': d_rescurl, 'core_positive': bool(d_core>0), 'core_gt_abs_curl': bool(d_core>abs(d_curl))})
        patch={
            'available': bool(tiles),
            'n_tiles': len(tiles),
            'n_core_positive': sum(1 for t in tiles if t.get('core_positive')),
            'n_core_gt_abs_curl': sum(1 for t in tiles if t.get('core_gt_abs_curl')),
            'tiles': tiles,
            'patch_jackknife_pass': bool(tiles and sum(1 for t in tiles if t.get('core_positive')) >= max(1, int(0.75*len(tiles))) and sum(1 for t in tiles if t.get('core_gt_abs_curl')) >= max(1, int(0.5*len(tiles))))
        }
        report={
            'available': True,
            'coord_source': coord_src,
            'n_data_coords': len(data),
            'core_variants': core_names,
            'variant_projection_rows': variant_rows,
            'core_projection_delta': core_delta,
            'curl_delta': curl_delta,
            'paired_bootstrap_science_vs_curl': paired,
            'residual_curl_null_after_projection': residual_curl_null,
            'patch_level_jackknife': patch,
            'route_specific_confirm_like_pass': bool(
                paired.get('paired_bootstrap_pass') and
                residual_curl_null.get('residual_curl_null_pass') and
                patch.get('patch_jackknife_pass') and
                sum(1 for r in good if r.get('residual_positive'))>=3
            ),
            'claim_scope': 'P30-SDSS-core only; global P30 still requires an independent route.'
        }
        _v34_write_json(outputs/'p30_sdss_core_curl_projected_residual_v34.json', report)
        return report | {'path': str(outputs/'p30_sdss_core_curl_projected_residual_v34.json')}
    except Exception as e:
        return {'available': False, 'reason': 'v34 P30 core projection failed: '+repr(e)}


def run_p30_maskrandom_freeze_v34(meta,args):
    base=_run_p30_v33_for_v34(meta,args)
    outputs=_v32_outputs_dir()
    v33=base.get('p30_curl_clean_route_v33') or {}
    core_projected=_v34_p30_core_projection_heavy(meta,args)
    base['p30_sdss_core_curl_projected_residual_v34']=core_projected
    # Keep route-specific. Do not use global P30 unless second route exists.
    rand_ok=bool((base.get('p30_sdss_route_confirm_gate_v33') or base.get('p30_sdss_route_confirm_gate_v32') or {}).get('random_normalized_route'))
    same_ok=bool((base.get('p30_sdss_route_confirm_gate_v33') or base.get('p30_sdss_route_confirm_gate_v32') or {}).get('same_split_science_variants'))
    boot_ok=bool((base.get('p30_sdss_route_confirm_gate_v33') or base.get('p30_sdss_route_confirm_gate_v32') or {}).get('bootstrap_ci_positive'))
    core_family_ok=bool(v33.get('core_family_pass'))
    projection_ok=bool(core_projected.get('route_specific_confirm_like_pass'))
    base['p30_sdss_core_route_confirm_gate_v34']=_v32_gate(
        random_normalized_route=rand_ok,
        same_split_science_variants=same_ok,
        bootstrap_ci_positive=boot_ok,
        core_family_survives_curl_subtraction=core_family_ok,
        curl_projected_residual_test=projection_ok,
        route_specific_scope=True,
        global_scope=False,
    )
    base['p30_global_confirm_gate_v34']=_v32_gate(
        p30_sdss_core_route_confirm=base['p30_sdss_core_route_confirm_gate_v34']['eligible_for_confirm_like'],
        second_independent_route=False,
    )
    base['p30_v34_claim_policy']={
        'route_specific_label':'P30-SDSS-core',
        'global_p30_policy':'blocked until Euclid/Planck/independent route passes same mask/random/variant gates',
        'curl_sensitive_variants':['f090','cibdeproj'],
        'core_variants':['baseline','f150','tonly'],
    }
    if base['p30_sdss_core_route_confirm_gate_v34']['eligible_for_confirm_like']:
        base['status']='p30_sdss_core_route_confirm_like'
    elif core_family_ok:
        base['status']='density_kappa_sdss_core_curl_projected_near_confirm'
    else:
        base['status']='density_kappa_sdss_route_curl_contaminated_near_confirm'
    return base


def run_p3_exact_metadata_v34(meta,args):
    """Metadata-first endpoint prefilter that avoids giant non-endpoint downloads."""
    if getattr(args,'quick',False) and not getattr(args,'allow_large',False):
        return base_result(meta, 'filament_orientation_proxy_ready_no_evidence',
            p3_endpoint_prefilter_v34={'quick_mode': True, 'download_policy':'skip downloads in quick mode'},
            interpretation='P3 v34 quick guard: endpoint-column prefilter implemented; run without --quick for small metadata probe.')
    # Prefer small metadata/ReadMe probes only; do not call the historical heavy downloader by default.
    attempts=[]; endpoint_hits=[]; candidate_tables=[]
    urls=[
        'https://vizier.cds.unistra.fr/viz-bin/ReadMe/J/A+A/530/A122?format=html',
        'https://vizier.cds.unistra.fr/viz-bin/asu-tsv?-source=J/A+A/530/A122&-out.max=20',
    ]
    for idx,u in enumerate(urls):
        try:
            p, at = download_candidates([u], Path(args.cache_dir), meta.get('test_id','R10-T09')+f'_v34_prefilter_{idx}', args)
            attempts.extend(at or [])
            if not p:
                continue
            txt=read_text_any(p, max_bytes=800_000)
            # Require explicit endpoint/node-pair coordinates; generic RA/DEC or filament words are not enough.
            hits=[ln[:300] for ln in txt.splitlines()[:500] if _re_v34.search(r'(?i)(RA1|DE1|DEC1|RA2|DE2|DEC2|X1|Y1|Z1|X2|Y2|Z2|node1|node2|endpoint)', ln)]
            endpoint_hits.extend(hits[:30])
            if hits:
                candidate_tables.append({'url':u, 'path':str(p), 'endpoint_hit_count':len(hits), 'size_bytes':Path(p).stat().st_size})
        except Exception as e:
            attempts.append({'url':u, 'error':repr(e)})
    status='filament_endpoint_columns_positive_ready' if endpoint_hits else 'filament_orientation_proxy_ready_no_evidence'
    return base_result(meta, status,
        p3_endpoint_prefilter_v34={
            'metadata_first': True,
            'giant_download_guard': True,
            'endpoint_hits': endpoint_hits[:50],
            'candidate_tables': candidate_tables,
            'attempts': attempts[:10],
            'promotion_rule':'Download/parse full tables only if explicit endpoint/node-pair columns are seen in metadata/preview.'
        },
        interpretation='P3 v34: avoids giant non-endpoint VizieR downloads; only endpoint/node-pair metadata can unlock full endpoint parsing.')


