# -----------------------------------------------------------------------------
# Round 10 v35 confirm-target patch
# Focus: make the v34 P30-SDSS-core curl-projected residual test executable and
# memory-safe; harden P3 endpoint skip; keep P36/P41/P33/P32 consumers strict.

from pathlib import Path as _Path_v35
import json as _json_v35
import math as _math_v35
import os as _os_v35
import re as _re_v35

_run_p30_v34_for_v35 = run_p30_maskrandom_freeze_v34
_run_p3_v34_for_v35 = run_p3_exact_metadata_v34
_run_highz_v34_for_v35 = run_highz_unit_field_table_v34
_run_p41_v34_for_v35 = run_p41_structured_cp_v34
_run_p33_v34_for_v35 = run_p33_density_bao_measured_scaffold_v34
_run_p32_v34_for_v35 = run_ringdown_strain_plan_v34
_run_dashboard_v34_for_v35 = run_dashboard_v34


def _v35_outputs_dir():
    p = _Path_v35.cwd() / 'outputs'
    p.mkdir(parents=True, exist_ok=True)
    return p


def _v35_cache_dir(args):
    p = _Path_v35(getattr(args, 'cache_dir', '.ccdr_round10_cache'))
    p.mkdir(parents=True, exist_ok=True)
    return p


def _v35_write_json(path, obj):
    try:
        p = _Path_v35(path)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(_json_v35.dumps(obj, indent=2, sort_keys=True, ensure_ascii=False), encoding='utf-8')
        return str(p)
    except Exception:
        return None


def _v35_read_json(path):
    try:
        if not path:
            return None
        return _json_v35.loads(_Path_v35(path).read_text(encoding='utf-8'))
    except Exception:
        return None


def _v35_float(x):
    try:
        if x is None:
            return None
        f = float(x)
        return f if _math_v35.isfinite(f) else None
    except Exception:
        return None


def _v35_quantile(vals, q):
    clean=[]
    for v in vals or []:
        f=_v35_float(v)
        if f is not None:
            clean.append(f)
    clean.sort()
    if not clean:
        return None
    if len(clean)==1:
        return clean[0]
    pos=(len(clean)-1)*q
    lo=int(_math_v35.floor(pos)); hi=int(_math_v35.ceil(pos))
    if lo==hi:
        return clean[lo]
    return clean[lo]*(hi-pos)+clean[hi]*(pos-lo)


def _v35_public(obj):
    if not isinstance(obj, dict):
        return obj
    return {k:v for k,v in obj.items() if not str(k).startswith('_')}


def _v35_projection_nside_candidates(meta, args):
    raw = str(_os_v35.environ.get('CCDR_P30_PROJECTION_NSIDE', '')).strip()
    out=[]
    for x in [raw, getattr(args, 'projection_nside', None), meta.get('projection_nside'), 128, 64]:
        try:
            if x is None or x == '':
                continue
            n=int(x)
            if n in [32,64,128,256,512] and n not in out:
                out.append(n)
        except Exception:
            continue
    return out or [128,64]


def _v35_variant_map_lowmem(meta, args, name, nside):
    """Use the existing ACT ALM reader at a lower nside and return a map plus diagnostic.
    This avoids full v34 256-only reconstruction and reports failures as data-limited JSON.
    """
    try:
        m2 = dict(meta)
        m2['sample_nside'] = int(nside)
        km, info = _v29_variant_map(m2, args, name)
        if km is None:
            return None, {'variant': name, 'nside': nside, 'available': False, 'info': info}
        return km, {'variant': name, 'nside': nside, 'available': True, 'info': info}
    except MemoryError as e:
        return None, {'variant': name, 'nside': nside, 'available': False, 'error_type': 'MemoryError', 'error': str(e)[:240]}
    except Exception as e:
        return None, {'variant': name, 'nside': nside, 'available': False, 'error_type': type(e).__name__, 'error': str(e)[:240]}


def _v35_shuffle_p(vals, hi, lo, observed, seed=12345, n=256):
    try:
        import numpy as np
        vals=np.asarray(vals, dtype=float); hi=np.asarray(hi, dtype=bool); lo=np.asarray(lo, dtype=bool)
        valid=(hi|lo)&np.isfinite(vals)
        if valid.sum()<50 or not np.any(valid&hi) or not np.any(valid&lo):
            return None, 0
        labels=np.zeros(len(vals), dtype=int); labels[hi]=1; labels[lo]=-1
        labs=labels[valid].copy(); x=vals[valid].copy()
        rng=np.random.default_rng(seed)
        null=[]
        for _ in range(n):
            sh=labs.copy(); rng.shuffle(sh)
            if np.any(sh==1) and np.any(sh==-1):
                null.append(float(np.nanmean(x[sh==1])-np.nanmean(x[sh==-1])))
        p=sum(1 for z in null if z>=observed)/len(null) if null else None
        return p, len(null)
    except Exception:
        return None, 0


def _v35_memory_safe_p30_core_projection(meta, args):
    """Memory-safe v35 residual test. It sequentially reconstructs low-Nside maps,
    samples only SDSS coordinates, deletes full maps immediately, and always emits JSON.
    """
    outputs=_v35_outputs_dir()
    out_path=outputs/'p30_sdss_core_curl_projected_residual_v35.json'
    started={
        'available': False,
        'version': 'v35',
        'claim_scope': 'P30-SDSS-core only; global P30 still requires an independent route.',
        'memory_policy': 'sequential low-Nside map reconstruction; no stacked full-sky maps; always emit JSON',
        'projection_nside_candidates': _v35_projection_nside_candidates(meta, args),
    }
    if getattr(args, 'quick', False):
        started['reason']='quick mode: projection skipped'
        _v35_write_json(out_path, started)
        return {**started, 'path': str(out_path)}
    if not getattr(args, 'allow_large', False):
        started['reason']='run with --allow-large to compute v35 P30 core curl-projected residual test'
        _v35_write_json(out_path, started)
        return {**started, 'path': str(out_path)}
    try:
        import numpy as np
        import healpy as hp
        import gc
    except Exception as e:
        started['reason']='numpy/healpy unavailable: '+str(e)
        _v35_write_json(out_path, started)
        return {**started, 'path': str(out_path)}
    try:
        coords, coord_src = _v29_get_sdss_coords(meta, args)
        rand_path = _v35_cache_dir(args) / 'p30_sdss_random_catalogue_v28.csv'
        if not rand_path.exists() and coords:
            try:
                _v28_random_catalogue_for_coords(coords, rand_path, seed=28031)
            except Exception:
                pass
        rand = _v28_coord_rows_from_dicts(_v28_safe_rows_from_csv(rand_path)) if rand_path.exists() else []
        split = _v29_build_random_normalized_split(coords, rand, density_nside=64)
        started['coord_source']=str(coord_src)
        started['split']={k:v for k,v in split.items() if not str(k).startswith('_')}
        if not split.get('available'):
            started['reason']='random-normalized SDSS split unavailable'
            _v35_write_json(out_path, started)
            return {**started, 'path': str(out_path)}
        data=split.get('_data_coords') or []
        if len(data)<100:
            started['reason']='too few SDSS coordinates after split'
            started['n_data_coords']=len(data)
            _v35_write_json(out_path, started)
            return {**started, 'path': str(out_path)}
        hi=np.asarray(split['_hi_mask'], dtype=bool); lo=np.asarray(split['_lo_mask'], dtype=bool)
        ra=np.asarray([c['ra'] for c in data], dtype=float); dec=np.asarray([c['dec'] for c in data], dtype=float)
        core_names=['baseline','f150','tonly']
        map_attempts=[]
        selected_nside=None; cval=None; curl_info=None
        for nside in _v35_projection_nside_candidates(meta,args):
            cmap, cinfo = _v35_variant_map_lowmem(meta,args,'curl_control',nside)
            map_attempts.append({'variant':'curl_control', 'attempt': cinfo})
            if cmap is None:
                continue
            try:
                carr=np.asarray(cmap, dtype=float)
                cpix=hp.ang2pix(hp.get_nside(carr), np.radians(90-dec), np.radians(ra))
                cval=np.asarray(carr[cpix], dtype=float)
                selected_nside=nside; curl_info=cinfo
                del cmap, carr, cpix; gc.collect()
                break
            except Exception as e:
                map_attempts.append({'variant':'curl_control', 'nside':nside, 'sampling_error':repr(e)[:240]})
                try: del cmap
                except Exception: pass
                gc.collect()
        if cval is None:
            started.update({'reason':'curl map unavailable at all low-memory nside candidates', 'map_attempts': map_attempts})
            _v35_write_json(out_path, started)
            return {**started, 'path': str(out_path)}
        variant_rows=[]; projected_series=[]; residual_series=[]
        raw_series=[]
        for idx,name in enumerate(core_names):
            smap, sinfo = _v35_variant_map_lowmem(meta,args,name,selected_nside)
            map_attempts.append({'variant':name, 'attempt':sinfo})
            if smap is None:
                variant_rows.append({'variant':name, 'available':False, 'reason':'map unavailable', 'info':sinfo})
                continue
            try:
                sarr=np.asarray(smap, dtype=float)
                spix=hp.ang2pix(hp.get_nside(sarr), np.radians(90-dec), np.radians(ra))
                y=np.asarray(sarr[spix], dtype=float)
                del smap, sarr, spix; gc.collect()
                finite=np.isfinite(y)&np.isfinite(cval)&(hi|lo)
                if finite.sum()<100:
                    variant_rows.append({'variant':name, 'available':False, 'reason':'too few finite high/low samples', 'n_finite':int(finite.sum())})
                    continue
                x=cval[finite]; yy=y[finite]
                x0=x-np.nanmean(x); y0=yy-np.nanmean(yy)
                beta=float(np.nansum(x0*y0)/max(np.nansum(x0*x0), 1e-30))
                alpha=float(np.nanmean(yy)-beta*np.nanmean(x))
                projected=y-beta*cval
                residual=y-(alpha+beta*cval)
                raw_delta=float(np.nanmean(y[hi])-np.nanmean(y[lo]))
                projection_delta=float(np.nanmean(projected[hi])-np.nanmean(projected[lo]))
                residual_delta=float(np.nanmean(residual[hi])-np.nanmean(residual[lo]))
                p_high,n_null=_v35_shuffle_p(residual,hi,lo,residual_delta,seed=int(getattr(args,'seed',12345))+3510+idx,n=256)
                row={
                    'variant':name,
                    'available':True,
                    'nside':selected_nside,
                    'n_finite':int(finite.sum()),
                    'beta_science_vs_curl':beta,
                    'alpha':alpha,
                    'raw_delta':raw_delta,
                    'projected_delta':projection_delta,
                    'residual_delta':residual_delta,
                    'residual_density_shuffle_p_high':p_high,
                    'residual_shuffle_n':n_null,
                    'residual_positive':bool(residual_delta>0),
                    'residual_significant_positive':bool(residual_delta>0 and p_high is not None and p_high<=0.05),
                }
                variant_rows.append(row)
                projected_series.append(projected)
                residual_series.append(residual)
                raw_series.append(y)
            except MemoryError as e:
                variant_rows.append({'variant':name, 'available':False, 'error_type':'MemoryError', 'error':str(e)[:240]})
                gc.collect()
            except Exception as e:
                variant_rows.append({'variant':name, 'available':False, 'error_type':type(e).__name__, 'error':repr(e)[:240]})
                gc.collect()
        if len(projected_series)<2:
            started.update({'reason':'too few core science maps available for projection', 'selected_nside':selected_nside, 'curl_info':curl_info, 'map_attempts':map_attempts, 'variant_projection_rows':variant_rows})
            _v35_write_json(out_path, started)
            return {**started, 'path': str(out_path)}
        core_projected=np.nanmean(np.vstack(projected_series), axis=0)
        core_residual=np.nanmean(np.vstack(residual_series), axis=0) if residual_series else core_projected
        core_raw=np.nanmean(np.vstack(raw_series), axis=0) if raw_series else core_projected
        core_delta=float(np.nanmean(core_projected[hi])-np.nanmean(core_projected[lo]))
        residual_delta=float(np.nanmean(core_residual[hi])-np.nanmean(core_residual[lo]))
        raw_core_delta=float(np.nanmean(core_raw[hi])-np.nanmean(core_raw[lo]))
        curl_delta=float(np.nanmean(cval[hi])-np.nanmean(cval[lo]))
        residual_p,n_resid_null=_v35_shuffle_p(core_residual,hi,lo,residual_delta,seed=int(getattr(args,'seed',12345))+3555,n=512)
        projected_p,n_proj_null=_v35_shuffle_p(core_projected,hi,lo,core_delta,seed=int(getattr(args,'seed',12345))+3556,n=512)
        # Paired bootstrap core projected vs curl.
        import random as _random_v35
        rng=_random_v35.Random(int(getattr(args,'seed',12345))+3535)
        hi_idx=[i for i,b in enumerate(hi) if b and _v35_float(core_projected[i]) is not None and _v35_float(cval[i]) is not None]
        lo_idx=[i for i,b in enumerate(lo) if b and _v35_float(core_projected[i]) is not None and _v35_float(cval[i]) is not None]
        bs_proj=[]; bs_resid=[]; bs_curl=[]; bs_diff=[]
        if len(hi_idx)>20 and len(lo_idx)>20:
            for _ in range(1000):
                hs=[rng.choice(hi_idx) for __ in hi_idx]
                ls=[rng.choice(lo_idx) for __ in lo_idx]
                pd=float(np.nanmean(core_projected[hs])-np.nanmean(core_projected[ls]))
                rd=float(np.nanmean(core_residual[hs])-np.nanmean(core_residual[ls]))
                kd=float(np.nanmean(cval[hs])-np.nanmean(cval[ls]))
                bs_proj.append(pd); bs_resid.append(rd); bs_curl.append(kd); bs_diff.append(pd-abs(kd))
        paired={
            'available':bool(bs_diff),
            'projected_delta':core_delta,
            'residual_delta':residual_delta,
            'curl_delta':curl_delta,
            'projected_minus_abs_curl_delta':core_delta-abs(curl_delta),
            'projected_ci16':_v35_quantile(bs_proj,0.16),
            'projected_ci84':_v35_quantile(bs_proj,0.84),
            'residual_ci16':_v35_quantile(bs_resid,0.16),
            'residual_ci84':_v35_quantile(bs_resid,0.84),
            'curl_ci16':_v35_quantile(bs_curl,0.16),
            'curl_ci84':_v35_quantile(bs_curl,0.84),
            'projected_minus_abs_curl_ci16':_v35_quantile(bs_diff,0.16),
            'projected_minus_abs_curl_ci84':_v35_quantile(bs_diff,0.84),
            'p_projected_minus_abs_curl_le_0':(sum(1 for v in bs_diff if v<=0)/len(bs_diff)) if bs_diff else None,
            'paired_bootstrap_pass':bool(bs_diff and (_v35_quantile(bs_diff,0.16) or -1e9)>0),
            'residual_ci_positive_pass':bool(bs_resid and (_v35_quantile(bs_resid,0.16) or -1e9)>0),
        }
        # Residual curl null after projection: project curl against core projected science.
        valid=np.isfinite(core_projected)&np.isfinite(cval)&(hi|lo)
        x=core_projected[valid]; y=cval[valid]
        x0=x-np.nanmean(x); y0=y-np.nanmean(y)
        beta_c=float(np.nansum(x0*y0)/max(np.nansum(x0*x0),1e-30))
        alpha_c=float(np.nanmean(y)-beta_c*np.nanmean(x))
        curl_resid=cval-(alpha_c+beta_c*core_projected)
        curl_resid_delta=float(np.nanmean(curl_resid[hi])-np.nanmean(curl_resid[lo]))
        p_hi,n_chi=_v35_shuffle_p(curl_resid,hi,lo,curl_resid_delta,seed=int(getattr(args,'seed',12345))+3590,n=512)
        # Two-sided absolute percentile
        p_abs=None
        try:
            # generate a fresh null for two-sided abs
            vals=curl_resid[(hi|lo)&np.isfinite(curl_resid)]
            labs=np.zeros(len(curl_resid), dtype=int); labs[hi]=1; labs[lo]=-1
            labs=labs[(hi|lo)&np.isfinite(curl_resid)]
            rng2=np.random.default_rng(int(getattr(args,'seed',12345))+3591)
            null=[]
            for _ in range(512):
                sh=labs.copy(); rng2.shuffle(sh)
                if np.any(sh==1) and np.any(sh==-1):
                    null.append(float(np.nanmean(vals[sh==1])-np.nanmean(vals[sh==-1])))
            p_abs=sum(1 for v in null if abs(v)>=abs(curl_resid_delta))/len(null) if null else None
        except Exception:
            pass
        residual_curl_null={
            'available':True,
            'beta_curl_vs_core_projected':beta_c,
            'curl_residual_delta':curl_resid_delta,
            'curl_residual_shuffle_p_high':p_hi,
            'curl_residual_two_sided_p_abs':p_abs,
            'shuffle_n':n_chi,
            'residual_curl_null_pass':bool(p_abs is not None and p_abs>0.05 and abs(curl_resid_delta)<0.5*max(abs(core_delta),1e-30)),
        }
        # Patch-level jackknife by 4x2 RA/Dec tiles on projected and residual signals.
        tiles=[]
        try:
            ra_edges=np.quantile(ra,[0,0.25,0.5,0.75,1.0]); dec_edges=np.quantile(dec,[0,0.5,1.0])
            for i in range(4):
                for j in range(2):
                    mask=(ra>=ra_edges[i])&(ra<=ra_edges[i+1])&(dec>=dec_edges[j])&(dec<=dec_edges[j+1])&(hi|lo)
                    if mask.sum()<30 or not np.any(mask&hi) or not np.any(mask&lo):
                        continue
                    d_proj=float(np.nanmean(core_projected[mask&hi])-np.nanmean(core_projected[mask&lo]))
                    d_res=float(np.nanmean(core_residual[mask&hi])-np.nanmean(core_residual[mask&lo]))
                    d_curl=float(np.nanmean(cval[mask&hi])-np.nanmean(cval[mask&lo]))
                    tiles.append({'tile':f'ra{i}_dec{j}','n':int(mask.sum()),'projected_delta':d_proj,'residual_delta':d_res,'curl_delta':d_curl,'projected_minus_abs_curl':d_proj-abs(d_curl),'projected_positive':bool(d_proj>0),'residual_positive':bool(d_res>0),'projected_gt_abs_curl':bool(d_proj>abs(d_curl))})
        except Exception as e:
            tiles=[{'error':repr(e)[:240]}]
        valid_tiles=[t for t in tiles if 'error' not in t]
        patch={
            'available':bool(valid_tiles),
            'n_tiles':len(valid_tiles),
            'n_projected_positive':sum(1 for t in valid_tiles if t.get('projected_positive')),
            'n_residual_positive':sum(1 for t in valid_tiles if t.get('residual_positive')),
            'n_projected_gt_abs_curl':sum(1 for t in valid_tiles if t.get('projected_gt_abs_curl')),
            'tiles':tiles,
            'patch_jackknife_pass':bool(valid_tiles and sum(1 for t in valid_tiles if t.get('projected_positive'))>=max(1,int(0.75*len(valid_tiles))) and sum(1 for t in valid_tiles if t.get('projected_gt_abs_curl'))>=max(1,int(0.5*len(valid_tiles))))
        }
        report={
            'available':True,
            'version':'v35',
            'coord_source':str(coord_src),
            'n_data_coords':len(data),
            'selected_projection_nside':selected_nside,
            'map_attempts':map_attempts,
            'curl_info':curl_info,
            'core_variants':['baseline','f150','tonly'],
            'variant_projection_rows':variant_rows,
            'raw_core_delta':raw_core_delta,
            'core_projected_delta':core_delta,
            'core_regression_residual_delta':residual_delta,
            'curl_delta':curl_delta,
            'projected_shuffle_p_high':projected_p,
            'projected_shuffle_n':n_proj_null,
            'residual_shuffle_p_high':residual_p,
            'residual_shuffle_n':n_resid_null,
            'paired_bootstrap_science_vs_curl':paired,
            'residual_curl_null_after_projection':residual_curl_null,
            'patch_level_jackknife':patch,
            'route_specific_confirm_like_pass':bool(
                core_delta>0 and
                (projected_p is not None and projected_p<=0.05) and
                paired.get('paired_bootstrap_pass') and
                residual_curl_null.get('residual_curl_null_pass') and
                patch.get('patch_jackknife_pass') and
                sum(1 for r in variant_rows if r.get('available') and r.get('residual_positive'))>=2
            ),
            'claim_scope':'P30-SDSS-core only; global P30 still requires an independent route.'
        }
        _v35_write_json(out_path, report)
        return {**report, 'path': str(out_path)}
    except Exception as e:
        started.update({'reason':'v35 P30 core projection failed but emitted JSON', 'error_type':type(e).__name__, 'error':repr(e)[:500]})
        _v35_write_json(out_path, started)
        return {**started, 'path':str(out_path)}


def run_p30_maskrandom_freeze_v35(meta,args):
    base=_run_p30_v34_for_v35(meta,args)
    v34=base.get('p30_sdss_core_route_confirm_gate_v34') or {}
    # Compute v35 residual test independently and always emit JSON.
    core_projected=_v35_memory_safe_p30_core_projection(meta,args)
    base['p30_sdss_core_curl_projected_residual_v35']=core_projected
    rand_ok=bool(v34.get('random_normalized_route') or (base.get('p30_sdss_route_confirm_gate_v33') or {}).get('random_normalized_route'))
    same_ok=bool(v34.get('same_split_science_variants') or (base.get('p30_sdss_route_confirm_gate_v33') or {}).get('same_split_science_variants'))
    boot_ok=bool(v34.get('bootstrap_ci_positive') or (base.get('p30_sdss_route_confirm_gate_v33') or {}).get('bootstrap_ci_positive'))
    core_family_ok=bool(v34.get('core_family_survives_curl_subtraction') or (base.get('p30_curl_clean_route_v33') or {}).get('core_family_pass'))
    residual_ok=bool(core_projected.get('route_specific_confirm_like_pass'))
    base['p30_sdss_core_route_confirm_gate_v35']=_v32_gate(
        random_normalized_route=rand_ok,
        same_split_science_variants=same_ok,
        bootstrap_ci_positive=boot_ok,
        core_family_survives_curl_subtraction=core_family_ok,
        curl_projected_residual_test=residual_ok,
        residual_json_emitted=bool(core_projected.get('path')),
        route_specific_scope=True,
        global_scope=False,
    )
    base['p30_global_confirm_gate_v35']=_v32_gate(
        p30_sdss_core_route_confirm=base['p30_sdss_core_route_confirm_gate_v35']['eligible_for_confirm_like'],
        second_independent_route=False,
    )
    base['p30_v35_claim_policy']={
        'route_specific_label':'P30-SDSS-core',
        'confirm_rule':'random-normalized route + same-split variants + bootstrap + core-family survival + v35 curl-projected residual pass',
        'global_p30_policy':'blocked until Euclid/Planck/independent route passes same mask/random/variant gates',
        'memory_safety':'projection uses low-Nside sequential map sampling and always emits JSON',
    }
    if base['p30_sdss_core_route_confirm_gate_v35']['eligible_for_confirm_like']:
        base['status']='p30_sdss_core_route_confirm_like'
    elif core_family_ok:
        base['status']='density_kappa_sdss_core_curl_projected_near_confirm'
    return base


def run_p3_exact_metadata_v35(meta,args):
    base=_run_p3_v34_for_v35(meta,args)
    pf=base.get('p3_endpoint_prefilter_v34') or {}
    hits=pf.get('endpoint_hits') or []
    tables=pf.get('candidate_tables') or []
    hard_skip={
        'metadata_first': True,
        'hard_skip_if_no_endpoint_columns': True,
        'endpoint_hits_n': len(hits),
        'candidate_tables_n': len(tables),
        'allowed_full_download': bool(hits or tables),
        'required_endpoint_patterns': ['RA1/DEC1 + RA2/DEC2', 'X1/Y1/Z1 + X2/Y2/Z2', 'node1/node2', 'endpoint columns'],
    }
    base['p3_endpoint_hard_skip_v35']=hard_skip
    if not (hits or tables):
        base['status']='endpoint_data_limited'
        base['interpretation']='P3 v35: no explicit endpoint/node-pair columns were found in metadata preview; giant non-endpoint table downloads are hard-skipped.'
    return base


