def run_dashboard_v35(meta,args):
    base=_run_dashboard_v34_for_v35(meta,args)
    outputs=_v35_outputs_dir(); rows=[]
    for p in sorted(outputs.glob('test*.json')):
        obj=_v35_read_json(p)
        if isinstance(obj,dict): rows.append(obj)
    instr=[]; p30=[]; pub=[]; blocked=[]
    for r in rows:
        keys=[k for k in r if k.endswith('_v35') or '_v35_' in k]
        if keys:
            instr.append({'test_id':r.get('test_id'), 'prediction_id':r.get('prediction_id'), 'status':r.get('status'), 'v35_keys':sorted(keys)})
        if r.get('p30_sdss_core_curl_projected_residual_v35'):
            p30.append({'test_id':r.get('test_id'), 'status':r.get('status'), 'projection':r.get('p30_sdss_core_curl_projected_residual_v35'), 'gate':r.get('p30_sdss_core_route_confirm_gate_v35')})
        st=str(r.get('status',''))
        if 'publication_confirm_like' in st or st in ['robust_confirm_like','void_morphology_publication_grade_confirm_like','p30_sdss_core_route_confirm_like']:
            pub.append({'test_id':r.get('test_id'), 'prediction_id':r.get('prediction_id'), 'status':st})
        for k,v in r.items():
            if isinstance(v,dict) and k.endswith('_gate_v35') and not v.get('eligible_for_confirm_like', True):
                blocked.append({'test_id':r.get('test_id'), 'prediction_id':r.get('prediction_id'), 'gate':k, 'missing':v.get('missing')})
    base['dashboard_v35']={
        'n_v35_instrumented_tests':len(instr),
        'v35_instrumented_tests':instr[:200],
        'publication_grade_confirm_like':pub,
        'p30_sdss_core_projection_route':p30,
        'blocked_confirm_gates':blocked[:200],
        'claim_policy':'v35 fixes P30 curl-projection execution: low-Nside sequential sampling, residual JSON on every path, route-specific promotion only. Global P30 remains blocked.'
    }
    base['status']='dashboard_positive_summary'
    return base


RUNNERS.update({
    'p30_maskrandom_freeze_v22': run_p30_maskrandom_freeze_v35,
    'p3_exact_metadata_v21': run_p3_exact_metadata_v35,
    'highz_unit_field_table_v22': run_highz_unit_field_table_v35,
    'p41_structured_cp_v22': run_p41_structured_cp_v35,
    'p33_density_bao_measured_scaffold_v22': run_p33_density_bao_measured_scaffold_v35,
    'ringdown_strain_plan_v22': run_ringdown_strain_plan_v35,
    'dashboard_v22': run_dashboard_v35,
})

# -----------------------------------------------------------------------------
# Round 10 v36 confirm-target patch
# Focus: P30 projection-consistency audit and canonical split/map/sign manifest.
# This layer prevents the v35 projection path from being interpreted as physics
# if its raw pre-projection deltas do not reproduce the canonical v29/v34 route.
# -----------------------------------------------------------------------------

from pathlib import Path as _Path_v36
import json as _json_v36
import math as _math_v36
import hashlib as _hashlib_v36
import os as _os_v36

_run_p30_v35_for_v36 = run_p30_maskrandom_freeze_v35
_run_p3_v35_for_v36 = run_p3_exact_metadata_v35
_run_highz_v35_for_v36 = run_highz_unit_field_table_v35
_run_p41_v35_for_v36 = run_p41_structured_cp_v35
_run_p33_v35_for_v36 = run_p33_density_bao_measured_scaffold_v35
_run_p32_v35_for_v36 = run_ringdown_strain_plan_v35
_run_dashboard_v35_for_v36 = run_dashboard_v35


def _v36_outputs_dir():
    p = _Path_v36.cwd() / 'outputs'
    p.mkdir(parents=True, exist_ok=True)
    return p


def _v36_cache_dir(args):
    p = _Path_v36(getattr(args, 'cache_dir', '.ccdr_round10_cache'))
    p.mkdir(parents=True, exist_ok=True)
    return p


def _v36_write_json(path, obj):
    p = _Path_v36(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(_json_v36.dumps(obj, indent=2, sort_keys=True, ensure_ascii=False, default=str), encoding='utf-8')
    return str(p)


def _v36_read_json(path):
    try:
        p = _Path_v36(path)
        if p.exists():
            return _json_v36.loads(p.read_text(encoding='utf-8'))
    except Exception:
        return None
    return None


def _v36_float(x):
    try:
        f = float(x)
        return f if _math_v36.isfinite(f) else None
    except Exception:
        return None


def _v36_quantile(vals, q):
    xs = sorted([_v36_float(v) for v in (vals or []) if _v36_float(v) is not None])
    if not xs:
        return None
    if len(xs) == 1:
        return xs[0]
    pos = (len(xs)-1)*float(q)
    lo = int(_math_v36.floor(pos)); hi = int(_math_v36.ceil(pos))
    if lo == hi:
        return xs[lo]
    return xs[lo]*(hi-pos) + xs[hi]*(pos-lo)


def _v36_sha16_text(text):
    return _hashlib_v36.sha256(str(text).encode('utf-8', errors='ignore')).hexdigest()[:16]


def _v36_public_split(split):
    if not isinstance(split, dict):
        return {'available': False, 'reason': 'split missing'}
    out = {k:v for k,v in split.items() if not str(k).startswith('_')}
    try:
        dens = list(split.get('_dens') or [])
        out['density_count'] = len(dens)
        out['density_hash16'] = _v36_sha16_text(','.join(f'{float(x):.8g}' for x in dens[:2000]))
    except Exception:
        pass
    try:
        hi = list(split.get('_hi_mask') or [])
        lo = list(split.get('_lo_mask') or [])
        out['n_high_label'] = int(sum(1 for x in hi if bool(x)))
        out['n_low_label'] = int(sum(1 for x in lo if bool(x)))
        out['label_hash16'] = _v36_sha16_text(''.join('H' if h else ('L' if l else '.') for h,l in zip(hi[:5000],lo[:5000])))
    except Exception:
        pass
    return out


def _v36_read_v29_variant_deltas():
    """Read canonical same-split v29 artifact if present."""
    paths = [
        _v36_outputs_dir()/'p30_sdss_same_split_variant_rerun_v29.json',
        _Path_v36.cwd()/'outputs'/'p30_sdss_same_split_variant_rerun_v29.json',
    ]
    for p in paths:
        obj = _v36_read_json(p)
        if isinstance(obj, dict):
            rows = obj.get('variant_results') or obj.get('variants') or []
            out = {}
            for r in rows:
                if not isinstance(r, dict):
                    continue
                name = r.get('variant') or r.get('label') or r.get('name')
                d = _v36_float(r.get('delta_high_minus_low') or r.get('delta') or r.get('science_delta') or r.get('raw_delta'))
                if name and d is not None:
                    out[str(name)] = d
            if out:
                return {'available': True, 'path': str(p), 'deltas': out, 'n_variants': len(out)}
    return {'available': False, 'reason': 'canonical v29 same-split artifact not found'}


def _v36_read_v34_or_v35_projection():
    outs = _v36_outputs_dir()
    v35 = _v36_read_json(outs/'p30_sdss_core_curl_projected_residual_v35.json') or {}
    v34 = _v36_read_json(outs/'p30_sdss_core_curl_projected_residual_v34.json') or {}
    return v34 if isinstance(v34, dict) else {}, v35 if isinstance(v35, dict) else {}


def _v36_extract_projection_raw_deltas(proj):
    rows = []
    if isinstance(proj, dict):
        rows = proj.get('variant_projection_rows') or proj.get('projection_rows') or []
    out = {}
    for r in rows or []:
        if not isinstance(r, dict):
            continue
        name = r.get('variant') or r.get('name')
        d = _v36_float(r.get('raw_delta') or r.get('science_delta'))
        if name and d is not None:
            out[str(name)] = d
    return out


def _v36_build_canonical_split_manifest(meta, args):
    """Create canonical split manifest with coord/label hashes and thresholds."""
    outputs = _v36_outputs_dir()
    out_path = outputs/'p30_canonical_split_manifest_v36.json'
    manifest = {
        'version': 'v36',
        'claim_scope': 'diagnostic manifest; required before interpreting P30 projection as physics',
        'canonical_route': 'P30-SDSS random-normalized split v28/v29-compatible',
        'required_consistency': 'projection raw deltas must match canonical same-split raw deltas before residual tests are claim-usable',
    }
    try:
        coords, coord_src = _v29_get_sdss_coords(meta, args)
        rand_path = _v36_cache_dir(args) / 'p30_sdss_random_catalogue_v28.csv'
        if not rand_path.exists() and coords:
            try:
                _v28_random_catalogue_for_coords(coords, rand_path, seed=28031)
            except Exception as e:
                manifest['random_generation_error'] = repr(e)[:240]
        rand = _v28_coord_rows_from_dicts(_v28_safe_rows_from_csv(rand_path)) if rand_path.exists() else []
        split = _v29_build_random_normalized_split(coords, rand, density_nside=64)
        manifest.update({
            'coord_source': str(coord_src),
            'n_coords': len(coords or []),
            'random_path': str(rand_path) if rand_path.exists() else None,
            'n_random': len(rand or []),
            'split': _v36_public_split(split),
        })
        if split.get('available'):
            data = split.get('_data_coords') or []
            hi = list(split.get('_hi_mask') or [])
            lo = list(split.get('_lo_mask') or [])
            labels = ['H' if bool(h) else ('L' if bool(l) else 'M') for h,l in zip(hi,lo)]
            sample = []
            for i,c in enumerate(data[:50]):
                sample.append({
                    'idx': i,
                    'ra': round(float(c.get('ra')), 8),
                    'dec': round(float(c.get('dec')), 8),
                    'density_label': labels[i] if i < len(labels) else None,
                })
            manifest['coord_label_sample_first50'] = sample
            manifest['coord_hash16_first5000'] = _v36_sha16_text('|'.join(f"{float(c.get('ra')):.8f},{float(c.get('dec')):.8f}" for c in data[:5000]))
            manifest['label_hash16_first5000'] = _v36_sha16_text(''.join(labels[:5000]))
    except Exception as e:
        manifest.update({'available': False, 'error_type': type(e).__name__, 'error': repr(e)[:500]})
    _v36_write_json(out_path, manifest)
    manifest['path'] = str(out_path)
    return manifest


def _v36_compare_raw_deltas(meta, args, base, split_manifest=None):
    """Compare v35 raw projection deltas against canonical v29 same-split deltas."""
    outputs = _v36_outputs_dir()
    out_path = outputs/'p30_projection_consistency_audit_v36.json'
    v29 = _v36_read_v29_variant_deltas()
    v34, v35 = _v36_read_v34_or_v35_projection()
    v35_raw = _v36_extract_projection_raw_deltas(v35)
    v34_raw = _v36_extract_projection_raw_deltas(v34)
    core = ['baseline','f150','tonly']
    tolerance_abs = float(_os_v36.environ.get('CCDR_P30_RAW_DELTA_TOL', '0.025'))
    rows = []
    for name in core:
        canon = _v36_float((v29.get('deltas') or {}).get(name))
        r35 = _v36_float(v35_raw.get(name))
        r34 = _v36_float(v34_raw.get(name))
        row = {'variant': name, 'v29_delta': canon, 'v35_raw_delta': r35, 'v34_raw_delta': r34}
        if canon is not None and r35 is not None:
            row['delta_abs_diff_v35_minus_v29'] = abs(r35 - canon)
            row['same_sign_v35_v29'] = bool((r35 > 0) == (canon > 0))
            row['within_tolerance'] = bool(abs(r35 - canon) <= tolerance_abs)
        else:
            row['within_tolerance'] = False
            row['same_sign_v35_v29'] = False
        rows.append(row)
    raw_consistency_pass = bool(rows and all(r.get('within_tolerance') and r.get('same_sign_v35_v29') for r in rows))
    audit = {
        'version': 'v36',
        'available': True,
        'purpose': 'Do not interpret curl-projected residuals unless pre-projection raw deltas reproduce the canonical same-split route.',
        'canonical_same_split_artifact': v29,
        'v35_projection_artifact_path': str(outputs/'p30_sdss_core_curl_projected_residual_v35.json'),
        'v34_projection_artifact_path': str(outputs/'p30_sdss_core_curl_projected_residual_v34.json'),
        'tolerance_abs': tolerance_abs,
        'rows': rows,
        'raw_projection_consistency_pass': raw_consistency_pass,
        'diagnosis': 'projection_pipeline_consistent' if raw_consistency_pass else 'projection_pipeline_mismatch',
        'action_if_failed': 'Abort claim-level P30 residual interpretation; audit split labels, map sign convention, coordinate order, pixelization, and variant file mapping.',
        'split_manifest_path': (split_manifest or {}).get('path'),
    }
    _v36_write_json(out_path, audit)
    audit['path'] = str(out_path)
    return audit


def _v36_map_sign_manifest(meta, args, split_manifest=None):
    outputs = _v36_outputs_dir(); out_path = outputs/'p30_map_sign_convention_manifest_v36.json'
    manifest = {
        'version': 'v36',
        'map_sign_convention': 'ACT_row_order_full_alm_v1',
        'claim_scope': 'checksum/sanity diagnostics; not physics evidence',
        'variants': [],
    }
    if getattr(args, 'quick', False) or not getattr(args, 'allow_large', False):
        manifest['available'] = False
        manifest['reason'] = 'run P30 with --allow-large to compute map sign checksums'
        _v36_write_json(out_path, manifest); manifest['path']=str(out_path); return manifest
    try:
        import numpy as np
        for name in ['baseline','f150','tonly','curl_control']:
            row = {'variant': name}
            # Use small Nside first for sign manifest. It is not used as claim evidence.
            km, info = _v35_variant_map_lowmem(meta, args, name, 64)
            row['map_info'] = info
            if km is not None:
                arr = np.asarray(km, dtype=float)
                finite = np.isfinite(arr)
                vals = arr[finite]
                row.update({
                    'available': True,
                    'nside': 64,
                    'finite_fraction': float(finite.mean()) if finite.size else 0.0,
                    'mean': float(np.nanmean(vals)) if vals.size else None,
                    'median': float(np.nanmedian(vals)) if vals.size else None,
                    'std': float(np.nanstd(vals)) if vals.size else None,
                    'min': float(np.nanmin(vals)) if vals.size else None,
                    'max': float(np.nanmax(vals)) if vals.size else None,
                    'checksum16_first4096': _v36_sha16_text(','.join(f'{x:.7g}' for x in vals[:4096])),
                })
                try:
                    del km, arr, finite, vals
                except Exception:
                    pass
            else:
                row['available'] = False
            manifest['variants'].append(row)
        manifest['available'] = any(v.get('available') for v in manifest['variants'])
    except Exception as e:
        manifest.update({'available': False, 'error_type': type(e).__name__, 'error': repr(e)[:500]})
    _v36_write_json(out_path, manifest); manifest['path']=str(out_path); return manifest


def _v36_compute_delta_on_map_values(vals, hi, lo):
    try:
        import numpy as np
        vals=np.asarray(vals,dtype=float); hi=np.asarray(hi,dtype=bool); lo=np.asarray(lo,dtype=bool)
        finite=np.isfinite(vals)&(hi|lo)
        h=finite&hi; l=finite&lo
        if h.sum()<10 or l.sum()<10:
            return None
        return float(np.nanmean(vals[h])-np.nanmean(vals[l]))
    except Exception:
        return None


def _v36_nside_raw_delta_comparison(meta, args):
    outputs = _v36_outputs_dir(); out_path = outputs/'p30_nside_raw_delta_comparison_v36.json'
    report = {'version':'v36', 'available':False, 'claim_scope':'pre-projection raw-delta stability check only'}
    if getattr(args,'quick',False) or not getattr(args,'allow_large',False):
        report['reason']='run P30 with --allow-large to compute nside raw-delta comparison'
        _v36_write_json(out_path, report); report['path']=str(out_path); return report
    try:
        import numpy as np
        import healpy as hp
        coords, _src = _v29_get_sdss_coords(meta, args)
        rand_path = _v36_cache_dir(args) / 'p30_sdss_random_catalogue_v28.csv'
        rand = _v28_coord_rows_from_dicts(_v28_safe_rows_from_csv(rand_path)) if rand_path.exists() else []
        split = _v29_build_random_normalized_split(coords, rand, density_nside=64)
        if not split.get('available'):
            report.update({'reason':'canonical split unavailable', 'split':_v36_public_split(split)})
            _v36_write_json(out_path, report); report['path']=str(out_path); return report
        data=split.get('_data_coords') or []
        hi=np.asarray(split.get('_hi_mask'), dtype=bool); lo=np.asarray(split.get('_lo_mask'), dtype=bool)
        ra=np.asarray([c['ra'] for c in data], dtype=float); dec=np.asarray([c['dec'] for c in data], dtype=float)
        rows=[]
        for nside in [256,128,64]:
            for variant in ['baseline','f150','tonly','curl_control']:
                km, info = _v35_variant_map_lowmem(meta,args,variant,nside)
                row={'nside':nside,'variant':variant,'map_info':info}
                if km is not None:
                    arr=np.asarray(km,dtype=float); pix=hp.ang2pix(hp.get_nside(arr), np.radians(90-dec), np.radians(ra))
                    vals=arr[pix]
                    row['raw_delta']=_v36_compute_delta_on_map_values(vals,hi,lo)
                    row['n_sampled']=len(vals)
                    row['available']=row['raw_delta'] is not None
                    try: del km, arr, pix, vals
                    except Exception: pass
                else:
                    row['available']=False
                rows.append(row)
        # require baseline/f150/tonly all positive at all available nsides for claim use
        science=[r for r in rows if r.get('variant') in ['baseline','f150','tonly'] and r.get('available')]
        report.update({
            'available': bool(rows),
            'coord_source': str(_src),
            'split': _v36_public_split(split),
            'rows': rows,
            'all_available_science_positive': bool(science and all((_v36_float(r.get('raw_delta')) or -1e9)>0 for r in science)),
            'n_science_rows': len(science),
            'note': 'If raw deltas change sign across nside, projection residual tests are diagnostic only.'
        })
    except Exception as e:
        report.update({'available':False,'error_type':type(e).__name__,'error':repr(e)[:500]})
    _v36_write_json(out_path, report); report['path']=str(out_path); return report


def _v36_pixel_level_sample_audit(meta, args):
    outputs = _v36_outputs_dir(); out_path = outputs/'p30_pixel_level_sample_audit_v36.json'
    report={'version':'v36','available':False,'claim_scope':'debug only; reveals coordinate/pixel/sign mismatch'}
    if getattr(args,'quick',False) or not getattr(args,'allow_large',False):
        report['reason']='run P30 with --allow-large for pixel-level sample audit'
        _v36_write_json(out_path, report); report['path']=str(out_path); return report
    try:
        import numpy as np, healpy as hp
        coords, src = _v29_get_sdss_coords(meta, args)
        rand_path=_v36_cache_dir(args)/'p30_sdss_random_catalogue_v28.csv'
        rand=_v28_coord_rows_from_dicts(_v28_safe_rows_from_csv(rand_path)) if rand_path.exists() else []
        split=_v29_build_random_normalized_split(coords, rand, density_nside=64)
        if not split.get('available'):
            report.update({'reason':'split unavailable','split':_v36_public_split(split)})
            _v36_write_json(out_path, report); report['path']=str(out_path); return report
        data=split.get('_data_coords') or []
        hi=list(split.get('_hi_mask') or []); lo=list(split.get('_lo_mask') or [])
        # choose first 10 high and first 10 low points, preserving canonical order
        idxs=[i for i,b in enumerate(hi) if b][:10] + [i for i,b in enumerate(lo) if b][:10]
        rows=[]
        for i in idxs:
            c=data[i]; rows.append({'idx':i,'ra':float(c['ra']),'dec':float(c['dec']),'density_label':'H' if hi[i] else 'L'})
        values={}
        nside=64
        for variant in ['baseline','f150','tonly','curl_control']:
            km, info=_v35_variant_map_lowmem(meta,args,variant,nside)
            values[variant]={'map_info':info}
            if km is not None:
                arr=np.asarray(km,dtype=float)
                for row in rows:
                    pix=int(hp.ang2pix(hp.get_nside(arr), _math_v36.radians(90-row['dec']), _math_v36.radians(row['ra'])))
                    row[f'{variant}_pix64']=pix
                    row[f'{variant}_kappa64']=_v36_float(arr[pix])
                try: del km, arr
                except Exception: pass
        report.update({'available':True,'coord_source':str(src),'nside':nside,'sample_rows':rows,'variant_map_info':values})
    except Exception as e:
        report.update({'available':False,'error_type':type(e).__name__,'error':repr(e)[:500]})
    _v36_write_json(out_path, report); report['path']=str(out_path); return report


def run_p30_maskrandom_freeze_v36(meta,args):
    base = _run_p30_v35_for_v36(meta,args)
    split_manifest = _v36_build_canonical_split_manifest(meta,args)
    consistency = _v36_compare_raw_deltas(meta,args,base,split_manifest)
    sign_manifest = _v36_map_sign_manifest(meta,args,split_manifest)
    nside_cmp = _v36_nside_raw_delta_comparison(meta,args)
    pixel_audit = _v36_pixel_level_sample_audit(meta,args)
    base['p30_canonical_split_manifest_v36'] = split_manifest
    base['p30_projection_consistency_audit_v36'] = consistency
    base['p30_map_sign_convention_manifest_v36'] = sign_manifest
    base['p30_nside_raw_delta_comparison_v36'] = nside_cmp
    base['p30_pixel_level_sample_audit_v36'] = pixel_audit
    v35_gate = base.get('p30_sdss_core_route_confirm_gate_v35') or {}
    residual = base.get('p30_sdss_core_curl_projected_residual_v35') or {}
    projection_consistent = bool(consistency.get('raw_projection_consistency_pass'))
    nside_raw_ok = bool(nside_cmp.get('all_available_science_positive')) if nside_cmp.get('available') else False
    sign_ok = bool(sign_manifest.get('available')) or not getattr(args,'allow_large',False)
    residual_ok = bool(residual.get('route_specific_confirm_like_pass'))
    base['p30_sdss_core_route_confirm_gate_v36'] = _v32_gate(
        v35_gate_preconditions=bool(v35_gate.get('random_normalized_route') and v35_gate.get('same_split_science_variants') and v35_gate.get('bootstrap_ci_positive') and v35_gate.get('core_family_survives_curl_subtraction')),
        projection_raw_delta_consistency=projection_consistent,
        canonical_split_manifest=bool(split_manifest.get('path')),
        map_sign_manifest=sign_ok,
        nside_raw_delta_stability=nside_raw_ok,
        curl_projected_residual_test=residual_ok,
        pixel_audit_emitted=bool(pixel_audit.get('path')),
        route_specific_scope=True,
        global_scope=False,
    )
    base['p30_projection_claim_guard_v36'] = {
        'claim_policy': 'Residual projection cannot be used as physics evidence unless raw pre-projection deltas reproduce v29/v34 same-split deltas.',
        'if_failed_label': 'projection_pipeline_mismatch',
        'projection_consistency_pass': projection_consistent,
        'nside_raw_delta_stability': nside_raw_ok,
        'v35_residual_pass': residual_ok,
    }
    base['p30_global_confirm_gate_v36'] = _v32_gate(
        p30_sdss_core_route_confirm=base['p30_sdss_core_route_confirm_gate_v36']['eligible_for_confirm_like'],
        second_independent_route=False,
    )
    if base['p30_sdss_core_route_confirm_gate_v36']['eligible_for_confirm_like']:
        base['status'] = 'p30_sdss_core_route_confirm_like'
    elif not projection_consistent:
        base['status'] = 'density_kappa_sdss_core_projection_pipeline_mismatch'
    else:
        base['status'] = 'density_kappa_sdss_core_curl_projected_near_confirm'
    return base


