def run_dashboard_v36(meta,args):
    base = _run_dashboard_v35_for_v36(meta,args)
    outputs=_v36_outputs_dir(); rows=[]
    for p in sorted(outputs.glob('test*.json')):
        obj=_v36_read_json(p)
        if isinstance(obj,dict): rows.append(obj)
    instr=[]; p30=[]; pub=[]; blocked=[]
    for r in rows:
        keys=[k for k in r if k.endswith('_v36') or '_v36_' in k]
        if keys:
            instr.append({'test_id':r.get('test_id'), 'prediction_id':r.get('prediction_id'), 'status':r.get('status'), 'v36_keys':sorted(keys)})
        if r.get('p30_projection_consistency_audit_v36'):
            p30.append({
                'test_id':r.get('test_id'),
                'status':r.get('status'),
                'consistency':r.get('p30_projection_consistency_audit_v36'),
                'gate':r.get('p30_sdss_core_route_confirm_gate_v36'),
            })
        st=str(r.get('status',''))
        if 'publication_confirm_like' in st or st in ['robust_confirm_like','void_morphology_publication_grade_confirm_like','p30_sdss_core_route_confirm_like']:
            pub.append({'test_id':r.get('test_id'), 'prediction_id':r.get('prediction_id'), 'status':st})
        for k,v in r.items():
            if isinstance(v,dict) and k.endswith('_gate_v36') and not v.get('eligible_for_confirm_like', True):
                blocked.append({'test_id':r.get('test_id'), 'prediction_id':r.get('prediction_id'), 'gate':k, 'missing':v.get('missing')})
    base['dashboard_v36']={
        'n_v36_instrumented_tests':len(instr),
        'v36_instrumented_tests':instr[:200],
        'publication_grade_confirm_like':pub,
        'p30_projection_consistency_routes':p30,
        'blocked_confirm_gates':blocked[:200],
        'claim_policy':'v36 blocks P30 route promotion unless projection raw deltas reproduce the canonical same-split route before residual projection. Global P30 remains blocked.',
    }
    base['status']='dashboard_positive_summary'
    return base


