def run_dashboard_v37(meta, args):
    base = _run_dashboard_v36_for_v37(meta, args)
    outputs = _v37_outputs_dir(); rows = []
    for p in sorted(outputs.glob('test*.json')):
        obj = _v37_read_json(p)
        if isinstance(obj, dict):
            rows.append(obj)
    instr = []; p30 = []; pub = []; blocked = []
    for r in rows:
        keys = [k for k in r if k.endswith('_v37') or '_v37_' in k]
        if keys:
            instr.append({'test_id': r.get('test_id'), 'prediction_id': r.get('prediction_id'), 'status': r.get('status'), 'v37_keys': sorted(keys)})
        if r.get('p30_projection_consistency_audit_v37'):
            p30.append({
                'test_id': r.get('test_id'),
                'status': r.get('status'),
                'split_manifest': r.get('p30_canonical_split_manifest_v37'),
                'consistency': r.get('p30_projection_consistency_audit_v37'),
                'gate': r.get('p30_sdss_core_route_confirm_gate_v37'),
            })
        st = str(r.get('status',''))
        if 'publication_confirm_like' in st or st in ['robust_confirm_like','void_morphology_publication_grade_confirm_like','p30_sdss_core_route_confirm_like']:
            pub.append({'test_id': r.get('test_id'), 'prediction_id': r.get('prediction_id'), 'status': st})
        for k, v in r.items():
            if isinstance(v, dict) and k.endswith('_gate_v37') and not v.get('eligible_for_confirm_like', True):
                blocked.append({'test_id': r.get('test_id'), 'prediction_id': r.get('prediction_id'), 'gate': k, 'missing': v.get('missing')})
    base['dashboard_v37'] = {
        'n_v37_instrumented_tests': len(instr),
        'v37_instrumented_tests': instr[:200],
        'publication_grade_confirm_like': pub,
        'p30_projection_consistency_routes': p30,
        'blocked_confirm_gates': blocked[:200],
        'claim_policy': 'v37 repairs the split manifest and forces P30 projection/residual tests to reuse canonical labels and reproduce v29 raw deltas before route promotion.',
    }
    base['status'] = 'dashboard_positive_summary'
    return base


