def run_dashboard_v38(meta, args):
    base = _run_dashboard_v37_for_v38(meta, args)
    outputs = _v38_outputs_dir(); rows = []
    for p in sorted(outputs.glob('test*.json')):
        obj = _v38_read_json(p)
        if isinstance(obj, dict):
            rows.append(obj)
    instr = []; p30 = []; pub = []; blocked = []
    for r in rows:
        keys = [k for k in r if k.endswith('_v38') or '_v38_' in k]
        if keys:
            instr.append({'test_id': r.get('test_id'), 'prediction_id': r.get('prediction_id'), 'status': r.get('status'), 'v38_keys': sorted(keys)})
        if r.get('p30_row_by_row_sampler_audit_v38') or r.get('p30_high_low_inversion_test_v38'):
            p30.append({
                'test_id': r.get('test_id'),
                'status': r.get('status'),
                'positive_route_preserved': r.get('p30_sdss_positive_route_preserved_v38'),
                'inversion_test': r.get('p30_high_low_inversion_test_v38'),
                'projection_guard': r.get('p30_projection_disabled_guard_v38'),
                'gate': r.get('p30_sdss_core_route_confirm_gate_v38'),
            })
        st = str(r.get('status',''))
        if 'publication_confirm_like' in st or st in ['robust_confirm_like','void_morphology_publication_grade_confirm_like','p30_sdss_core_route_confirm_like']:
            pub.append({'test_id': r.get('test_id'), 'prediction_id': r.get('prediction_id'), 'status': st})
        for k, v in r.items():
            if isinstance(v, dict) and k.endswith('_gate_v38') and not v.get('eligible_for_confirm_like', True):
                blocked.append({'test_id': r.get('test_id'), 'prediction_id': r.get('prediction_id'), 'gate': k, 'missing': v.get('missing')})
    base['dashboard_v38'] = {
        'n_v38_instrumented_tests': len(instr),
        'v38_instrumented_tests': instr[:200],
        'publication_grade_confirm_like': pub,
        'p30_sampler_audits': p30,
        'blocked_confirm_gates': blocked[:200],
        'claim_policy': 'v38 audits row/order/label/pixelfunc mismatch. Projection remains disabled until canonical raw deltas reproduce v29/v34; the positive P30-SDSS random-normalized route is preserved separately but not promoted.',
    }
    base['status'] = 'dashboard_positive_summary'
    return base


