# ---------------- Round-10 v39 patch: P30 H/L projection-label fix ----------------
# v39 directly addresses the v38 diagnosis: the P30 curl-projection sampler
# appears to compute L-H while labelling it H-L.  This layer makes the
# projection path consume the canonical manifest rows only, computes both
# orientations, applies an explicit raw-delta assertion against the canonical
# v29 same-split route, and refuses residual projection unless that assertion
# passes.  It also keeps P36/P41/P33/P32 strict gates in measurement-only mode.

try:
    _run_p30_v38_for_v39 = run_p30_maskrandom_freeze_v38
except Exception:
    _run_p30_v38_for_v39 = run_p30_maskrandom_freeze_v37
try:
    _run_p3_v38_for_v39 = run_p3_exact_metadata_v38
except Exception:
    _run_p3_v38_for_v39 = run_p3_exact_metadata_v37
try:
    _run_highz_v38_for_v39 = run_highz_unit_field_table_v38
except Exception:
    _run_highz_v38_for_v39 = run_highz_unit_field_table_v37
try:
    _run_p41_v38_for_v39 = run_p41_structured_cp_v38
except Exception:
    _run_p41_v38_for_v39 = run_p41_structured_cp_v37
try:
    _run_p33_v38_for_v39 = run_p33_density_bao_measured_scaffold_v38
except Exception:
    _run_p33_v38_for_v39 = run_p33_density_bao_measured_scaffold_v37
try:
    _run_p32_v38_for_v39 = run_ringdown_strain_plan_v38
except Exception:
    _run_p32_v38_for_v39 = run_ringdown_strain_plan_v37
try:
    _run_dashboard_v38_for_v39 = run_dashboard_v38
except Exception:
    _run_dashboard_v38_for_v39 = run_dashboard_v37


def _v39_outputs_dir():
    p = Path.cwd() / 'outputs'
    p.mkdir(exist_ok=True)
    return p


def _v39_write_json(path, obj):
    try:
        p = Path(path)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(json.dumps(obj, indent=2, sort_keys=True, default=str), encoding='utf-8')
    except Exception:
        pass


def _v39_read_json(path):
    try:
        p = Path(path)
        if p.exists():
            return json.loads(p.read_text(encoding='utf-8'))
    except Exception:
        return None
    return None


def _v39_float(x):
    try:
        import math
        v = float(x)
        return v if math.isfinite(v) else None
    except Exception:
        return None


def _v39_quantile(vals, q):
    try:
        import numpy as np
        arr = np.asarray([float(v) for v in vals if _v39_float(v) is not None], dtype=float)
        if arr.size == 0:
            return None
        return float(np.quantile(arr, q))
    except Exception:
        return None


def _v39_manifest_rows(split_manifest):
    # Reuse v38 parser where available so row/order semantics stay identical.
    if '_v38_manifest_rows' in globals():
        return _v38_manifest_rows(split_manifest)
    rows = []
    for r in (split_manifest or {}).get('rows') or []:
        try:
            rows.append({
                'idx': int(r.get('idx')),
                'object_id': str(r.get('object_id')),
                'ra': float(r.get('ra')),
                'dec': float(r.get('dec')),
                'density_label': str(r.get('density_label')),
                'density_value': _v39_float(r.get('density_value')),
                'density_pixel_nside64': int(r.get('density_pixel_nside64', -1)) if r.get('density_pixel_nside64') is not None else None,
            })
        except Exception:
            continue
    return rows


def _v39_canonical_deltas():
    try:
        return (_v37_read_v29_variant_deltas().get('deltas') or {})
    except Exception:
        return {}


def _v39_arrays_from_manifest(split_manifest):
    rows = _v39_manifest_rows(split_manifest)
    try:
        import numpy as np
        ra = np.asarray([r['ra'] for r in rows], dtype=float)
        dec = np.asarray([r['dec'] for r in rows], dtype=float)
        labels = np.asarray([r.get('density_label') for r in rows])
        hi = labels == 'H'
        lo = labels == 'L'
        return rows, ra, dec, labels, hi, lo
    except Exception:
        return rows, None, None, None, None, None


def _v39_delta(vals, hi, lo):
    try:
        import numpy as np
        vals = np.asarray(vals, dtype=float)
        finite = np.isfinite(vals)
        h = finite & hi
        l = finite & lo
        if int(h.sum()) < 10 or int(l.sum()) < 10:
            return None
        return {
            'H_minus_L': float(np.nanmean(vals[h]) - np.nanmean(vals[l])),
            'L_minus_H': float(np.nanmean(vals[l]) - np.nanmean(vals[h])),
            'mean_H': float(np.nanmean(vals[h])),
            'mean_L': float(np.nanmean(vals[l])),
            'n_high': int(h.sum()),
            'n_low': int(l.sum()),
        }
    except Exception:
        return None


def _v39_sample_variant_values(meta, args, variant, nside, ra, dec):
    try:
        import numpy as np, healpy as hp, gc
        kmap, info = _v35_variant_map_lowmem(meta, args, variant, nside)
        if kmap is None:
            return None, info
        arr = np.asarray(kmap, dtype=float)
        pix = hp.ang2pix(hp.get_nside(arr), np.radians(90.0 - dec), np.radians(ra))
        vals = np.asarray(arr[pix], dtype=float)
        try:
            del kmap, arr, pix
            gc.collect()
        except Exception:
            pass
        return vals, info
    except Exception as e:
        return None, {'available': False, 'error_type': type(e).__name__, 'error': repr(e)[:500], 'variant': variant, 'nside': nside}


def _v39_orientation_from_rows(rows, tolerance=0.03):
    normal_hits = 0
    inverted_hits = 0
    usable = 0
    out_rows = []
    for row in rows:
        c = _v39_float(row.get('canonical_H_minus_L'))
        h = _v39_float(row.get('observed_H_minus_L'))
        l = _v39_float(row.get('observed_L_minus_H'))
        item = dict(row)
        if c is not None and h is not None and l is not None:
            usable += 1
            item['abs_diff_H_minus_L_vs_canonical'] = abs(h - c)
            item['abs_diff_L_minus_H_vs_canonical'] = abs(l - c)
            item['H_minus_L_matches_canonical'] = bool(abs(h - c) <= tolerance)
            item['L_minus_H_matches_canonical'] = bool(abs(l - c) <= tolerance)
            if item['H_minus_L_matches_canonical']:
                normal_hits += 1
            if item['L_minus_H_matches_canonical']:
                inverted_hits += 1
        out_rows.append(item)
    if usable == 0:
        orientation = 'unavailable'
    elif normal_hits >= max(2, usable // 2 + 1):
        orientation = 'canonical_H_minus_L'
    elif inverted_hits >= max(2, usable // 2 + 1):
        orientation = 'inverted_masks_use_L_minus_H'
    else:
        orientation = 'unresolved_mixed_orientation'
    return orientation, normal_hits, inverted_hits, usable, out_rows


def _v39_projection_label_fix_test(meta, args, split_manifest):
    outputs = _v39_outputs_dir(); out_path = outputs / 'p30_projection_label_fix_test_v39.json'
    report = {
        'version': 'v39',
        'available': False,
        'claim_scope': 'debug/guard: detect and fix H/L projection-mask inversion before curl residual tests',
        'policy': 'Projection must consume p30_canonical_split_manifest_v37 rows only and compute both H-L and L-H.',
    }
    rows, ra, dec, labels, hi, lo = _v39_arrays_from_manifest(split_manifest)
    if not rows or ra is None:
        report['reason'] = 'canonical split manifest rows unavailable'
        _v39_write_json(out_path, report); report['path'] = str(out_path); return report
    if getattr(args, 'quick', False) or not getattr(args, 'allow_large', False):
        report.update({'reason': 'run P30 with --allow-large for v39 projection label fix test', 'manifest_rows': len(rows)})
        _v39_write_json(out_path, report); report['path'] = str(out_path); return report
    canonical = _v39_canonical_deltas()
    variant_rows = []
    map_attempts = []
    selected_nside = None
    for nside in [128, 64, 256]:
        variant_rows = []
        ok_any = False
        for variant in ['baseline', 'f150', 'tonly', 'curl_control']:
            vals, info = _v39_sample_variant_values(meta, args, variant, nside, ra, dec)
            map_attempts.append({'nside': nside, 'variant': variant, 'info': info})
            d = _v39_delta(vals, hi, lo) if vals is not None else None
            crow = {
                'variant': variant,
                'nside': nside,
                'canonical_H_minus_L': _v39_float(canonical.get(variant)),
                'available': d is not None,
            }
            if d:
                ok_any = True
                crow.update({
                    'observed_H_minus_L': d.get('H_minus_L'),
                    'observed_L_minus_H': d.get('L_minus_H'),
                    'mean_H': d.get('mean_H'),
                    'mean_L': d.get('mean_L'),
                    'n_high': d.get('n_high'),
                    'n_low': d.get('n_low'),
                })
            variant_rows.append(crow)
        if ok_any:
            selected_nside = nside
            break
    core_rows = [r for r in variant_rows if r.get('variant') in ['baseline','f150','tonly']]
    orientation, normal_hits, inverted_hits, usable, rows2 = _v39_orientation_from_rows(core_rows, tolerance=0.03)
    raw_consistency_pass = bool(orientation in ['canonical_H_minus_L', 'inverted_masks_use_L_minus_H'] and usable >= 2)
    report.update({
        'available': True,
        'selected_nside': selected_nside,
        'manifest_rows': len(rows),
        'manifest_high': int(hi.sum()),
        'manifest_low': int(lo.sum()),
        'variant_rows': rows2 + [r for r in variant_rows if r.get('variant') == 'curl_control'],
        'normal_orientation_hits': normal_hits,
        'inverted_orientation_hits': inverted_hits,
        'usable_core_variants': usable,
        'orientation_fix': orientation,
        'density_label_inversion_confirmed': bool(orientation == 'inverted_masks_use_L_minus_H'),
        'raw_delta_consistency_pass_after_orientation_fix': raw_consistency_pass,
        'map_attempts': map_attempts[-8:],
        'claim_policy': 'If orientation_fix is inverted, the projection sampler must swap H/L masks internally but report both signs. If raw consistency still fails, residual projection is disabled.',
    })
    _v39_write_json(out_path, report); report['path'] = str(out_path); return report


def _v39_fixed_curl_projection(meta, args, split_manifest, label_fix):
    outputs = _v39_outputs_dir(); out_path = outputs / 'p30_fixed_curl_projection_v39.json'
    report = {
        'version': 'v39',
        'available': False,
        'claim_scope': 'P30-SDSS-core route only; global P30 still requires an independent route.',
        'precondition': 'raw delta consistency must pass after v39 H/L orientation fix',
    }
    if not label_fix.get('raw_delta_consistency_pass_after_orientation_fix'):
        report.update({
            'reason': 'raw delta consistency did not pass; residual projection disabled',
            'projection_disabled': True,
            'orientation_fix': label_fix.get('orientation_fix'),
        })
        _v39_write_json(out_path, report); report['path'] = str(out_path); return report
    if getattr(args, 'quick', False) or not getattr(args, 'allow_large', False):
        report['reason'] = 'run P30 with --allow-large for fixed curl projection'
        _v39_write_json(out_path, report); report['path'] = str(out_path); return report
    try:
        import numpy as np, random as _random_v39
    except Exception as e:
        report['reason'] = 'numpy unavailable: ' + str(e)
        _v39_write_json(out_path, report); report['path'] = str(out_path); return report
    rows, ra, dec, labels, hi0, lo0 = _v39_arrays_from_manifest(split_manifest)
    if not rows or ra is None:
        report['reason'] = 'canonical split manifest rows unavailable'
        _v39_write_json(out_path, report); report['path'] = str(out_path); return report
    # Apply the explicit orientation correction identified above.
    if label_fix.get('orientation_fix') == 'inverted_masks_use_L_minus_H':
        hi = lo0.copy(); lo = hi0.copy(); orientation_applied = 'swapped_HL_masks_to_match_canonical'
    else:
        hi = hi0.copy(); lo = lo0.copy(); orientation_applied = 'canonical_H_minus_L_masks'
    nside = int(label_fix.get('selected_nside') or 128)
    cval, cinfo = _v39_sample_variant_values(meta, args, 'curl_control', nside, ra, dec)
    if cval is None:
        report.update({'reason': 'curl map unavailable', 'curl_info': cinfo})
        _v39_write_json(out_path, report); report['path'] = str(out_path); return report
    variant_rows = []
    projected_series = []
    residual_series = []
    raw_series = []
    canonical = _v39_canonical_deltas()
    for idx, variant in enumerate(['baseline', 'f150', 'tonly']):
        y, info = _v39_sample_variant_values(meta, args, variant, nside, ra, dec)
        row = {'variant': variant, 'nside': nside, 'map_info': info, 'available': y is not None, 'canonical_H_minus_L': _v39_float(canonical.get(variant))}
        if y is None:
            variant_rows.append(row); continue
        finite = np.isfinite(y) & np.isfinite(cval) & (hi | lo)
        if int(finite.sum()) < 100:
            row.update({'available': False, 'reason': 'too few finite samples', 'n_finite': int(finite.sum())})
            variant_rows.append(row); continue
        x = np.asarray(cval[finite], dtype=float); yy = np.asarray(y[finite], dtype=float)
        x0 = x - np.nanmean(x); y0 = yy - np.nanmean(yy)
        beta = float(np.nansum(x0 * y0) / max(np.nansum(x0 * x0), 1e-30))
        alpha = float(np.nanmean(yy) - beta * np.nanmean(x))
        projected = y - beta * cval
        residual = y - (alpha + beta * cval)
        raw_d = _v39_delta(y, hi, lo) or {}
        proj_d = _v39_delta(projected, hi, lo) or {}
        resid_d = _v39_delta(residual, hi, lo) or {}
        raw_delta = raw_d.get('H_minus_L')
        projected_delta = proj_d.get('H_minus_L')
        residual_delta = resid_d.get('H_minus_L')
        p_high, n_null = _v35_shuffle_p(residual, hi, lo, residual_delta, seed=int(getattr(args,'seed',12345))+3910+idx, n=256)
        row.update({
            'available': True,
            'orientation_applied': orientation_applied,
            'n_finite': int(finite.sum()),
            'beta_science_vs_curl': beta,
            'alpha': alpha,
            'raw_H_minus_L_after_fix': raw_delta,
            'raw_L_minus_H_after_fix': raw_d.get('L_minus_H'),
            'raw_delta_matches_canonical_after_fix': bool(raw_delta is not None and row['canonical_H_minus_L'] is not None and abs(raw_delta - row['canonical_H_minus_L']) <= 0.03),
            'projected_delta': projected_delta,
            'residual_delta': residual_delta,
            'residual_density_shuffle_p_high': p_high,
            'residual_shuffle_n': n_null,
            'residual_positive': bool(residual_delta is not None and residual_delta > 0),
            'residual_significant_positive': bool(residual_delta is not None and residual_delta > 0 and p_high is not None and p_high <= 0.05),
        })
        variant_rows.append(row)
        projected_series.append(projected)
        residual_series.append(residual)
        raw_series.append(y)
    if len(projected_series) < 2:
        report.update({'reason': 'too few science maps after H/L fix', 'variant_rows': variant_rows, 'orientation_applied': orientation_applied})
        _v39_write_json(out_path, report); report['path'] = str(out_path); return report
    core_projected = np.nanmean(np.vstack(projected_series), axis=0)
    core_residual = np.nanmean(np.vstack(residual_series), axis=0)
    core_raw = np.nanmean(np.vstack(raw_series), axis=0)
    raw_core_delta = (_v39_delta(core_raw, hi, lo) or {}).get('H_minus_L')
    core_delta = (_v39_delta(core_projected, hi, lo) or {}).get('H_minus_L')
    residual_delta = (_v39_delta(core_residual, hi, lo) or {}).get('H_minus_L')
    curl_delta = (_v39_delta(cval, hi, lo) or {}).get('H_minus_L')
    projected_p, n_proj = _v35_shuffle_p(core_projected, hi, lo, core_delta, seed=int(getattr(args,'seed',12345))+3956, n=512)
    residual_p, n_res = _v35_shuffle_p(core_residual, hi, lo, residual_delta, seed=int(getattr(args,'seed',12345))+3957, n=512)
    # paired bootstrap core projected vs curl under the corrected mask orientation
    rng = _random_v39.Random(int(getattr(args,'seed',12345))+3939)
    hi_idx = [i for i,b in enumerate(hi) if b and _v39_float(core_projected[i]) is not None and _v39_float(cval[i]) is not None]
    lo_idx = [i for i,b in enumerate(lo) if b and _v39_float(core_projected[i]) is not None and _v39_float(cval[i]) is not None]
    bs_proj=[]; bs_resid=[]; bs_curl=[]; bs_diff=[]
    if len(hi_idx)>20 and len(lo_idx)>20:
        for _ in range(1000):
            hs=[rng.choice(hi_idx) for __ in hi_idx]
            ls=[rng.choice(lo_idx) for __ in lo_idx]
            pd=float(np.nanmean(core_projected[hs])-np.nanmean(core_projected[ls]))
            rd=float(np.nanmean(core_residual[hs])-np.nanmean(core_residual[ls]))
            kd=float(np.nanmean(cval[hs])-np.nanmean(cval[ls]))
            bs_proj.append(pd); bs_resid.append(rd); bs_curl.append(kd); bs_diff.append(pd-abs(kd))
    paired = {
        'available': bool(bs_diff),
        'projected_ci16': _v39_quantile(bs_proj,0.16),
        'projected_ci84': _v39_quantile(bs_proj,0.84),
        'residual_ci16': _v39_quantile(bs_resid,0.16),
        'residual_ci84': _v39_quantile(bs_resid,0.84),
        'curl_ci16': _v39_quantile(bs_curl,0.16),
        'curl_ci84': _v39_quantile(bs_curl,0.84),
        'projected_minus_abs_curl_ci16': _v39_quantile(bs_diff,0.16),
        'projected_minus_abs_curl_ci84': _v39_quantile(bs_diff,0.84),
        'p_projected_minus_abs_curl_le_0': (sum(1 for v in bs_diff if v <= 0)/len(bs_diff)) if bs_diff else None,
        'paired_bootstrap_pass': bool(bs_diff and (_v39_quantile(bs_diff,0.16) or -1e9) > 0),
        'residual_ci_positive_pass': bool(bs_resid and (_v39_quantile(bs_resid,0.16) or -1e9) > 0),
    }
    # residual curl null: curl residual after regressing against core_projected
    residual_curl_null = {'available': False}
    try:
        valid = np.isfinite(core_projected) & np.isfinite(cval) & (hi|lo)
        x = core_projected[valid]; y = cval[valid]
        x0=x-np.nanmean(x); y0=y-np.nanmean(y)
        beta_c=float(np.nansum(x0*y0)/max(np.nansum(x0*x0),1e-30))
        alpha_c=float(np.nanmean(y)-beta_c*np.nanmean(x))
        curl_resid = cval - (alpha_c + beta_c * core_projected)
        curl_resid_delta = (_v39_delta(curl_resid, hi, lo) or {}).get('H_minus_L')
        p_hi, n_chi = _v35_shuffle_p(curl_resid, hi, lo, curl_resid_delta, seed=int(getattr(args,'seed',12345))+3990, n=512)
        residual_curl_null = {
            'available': True,
            'beta_curl_vs_core_projected': beta_c,
            'curl_residual_delta': curl_resid_delta,
            'curl_residual_shuffle_p_high': p_hi,
            'shuffle_n': n_chi,
            'residual_curl_null_pass': bool(p_hi is not None and 0.05 < p_hi < 0.95 and abs(curl_resid_delta or 0) < 0.5 * max(abs(core_delta or 0), 1e-30)),
        }
    except Exception as e:
        residual_curl_null = {'available': False, 'error_type': type(e).__name__, 'error': repr(e)[:300]}
    raw_match_count = sum(1 for r in variant_rows if r.get('raw_delta_matches_canonical_after_fix'))
    raw_consistency_pass = bool(raw_match_count >= 2)
    residual_gate = bool(
        raw_consistency_pass and
        core_delta is not None and core_delta > 0 and
        projected_p is not None and projected_p <= 0.05 and
        paired.get('paired_bootstrap_pass') and
        residual_curl_null.get('residual_curl_null_pass') and
        sum(1 for r in variant_rows if r.get('available') and r.get('residual_positive')) >= 2
    )
    report.update({
        'available': True,
        'selected_nside': nside,
        'orientation_applied': orientation_applied,
        'raw_delta_consistency_pass_after_fix': raw_consistency_pass,
        'raw_match_count': raw_match_count,
        'variant_projection_rows': variant_rows,
        'raw_core_delta_after_fix': raw_core_delta,
        'core_projected_delta_after_fix': core_delta,
        'core_regression_residual_delta_after_fix': residual_delta,
        'curl_delta_after_fix': curl_delta,
        'projected_shuffle_p_high': projected_p,
        'projected_shuffle_n': n_proj,
        'residual_shuffle_p_high': residual_p,
        'residual_shuffle_n': n_res,
        'paired_bootstrap_science_vs_curl': paired,
        'residual_curl_null_after_projection': residual_curl_null,
        'route_specific_confirm_like_pass': residual_gate,
        'claim_policy': 'May only promote P30-SDSS-core if raw deltas reproduce canonical route after orientation fix and residual gates pass; global P30 still blocked.',
    })
    _v39_write_json(out_path, report); report['path'] = str(out_path); return report


def _v39_p30_gate(base, split_manifest, label_fix, fixed_projection):
    return _v32_gate(
        canonical_split_manifest_available=bool((split_manifest or {}).get('available')),
        manifest_only_labels=True,
        dual_sign_output=bool(label_fix.get('available')),
        high_low_orientation_resolved=bool(label_fix.get('orientation_fix') in ['canonical_H_minus_L','inverted_masks_use_L_minus_H']),
        raw_delta_consistency_pass_after_fix=bool(label_fix.get('raw_delta_consistency_pass_after_orientation_fix')),
        projection_residual_ran_after_fix=bool(fixed_projection.get('available')),
        residual_confirm_gate=bool(fixed_projection.get('route_specific_confirm_like_pass')),
        route_specific_scope=True,
        global_scope=False,
    )


def run_p30_maskrandom_freeze_v39(meta, args):
    base = _run_p30_v38_for_v39(meta, args)
    split_manifest = base.get('p30_canonical_split_manifest_v37') or _v39_read_json(_v39_outputs_dir()/'p30_canonical_split_manifest_v37.json') or {}
    label_fix = _v39_projection_label_fix_test(meta, args, split_manifest)
    fixed_projection = _v39_fixed_curl_projection(meta, args, split_manifest, label_fix)
    base['p30_projection_label_fix_test_v39'] = label_fix
    base['p30_fixed_curl_projection_v39'] = fixed_projection
    base['p30_manifest_only_projection_policy_v39'] = {
        'enabled': True,
        'canonical_manifest_required': True,
        'manifest_path': (split_manifest or {}).get('path'),
        'policy': 'Projection may not recompute density labels or reorder objects; it must consume manifest rows and aligned idx order only.',
    }
    base['p30_dual_sign_raw_delta_v39'] = {
        'enabled': True,
        'source': 'p30_projection_label_fix_test_v39.variant_rows',
        'interpretation': 'Both H_minus_L and L_minus_H are emitted; if L_minus_H matches canonical route, v38 H/L inversion diagnosis is confirmed and masks are swapped internally for fixed projection.',
    }
    base['p30_projection_raw_delta_assertion_v39'] = {
        'raw_delta_consistency_pass_after_fix': bool(label_fix.get('raw_delta_consistency_pass_after_orientation_fix')),
        'orientation_fix': label_fix.get('orientation_fix'),
        'claim_policy': 'If false, P30 remains projection_pipeline_mismatch and residual projection cannot be used as physics evidence.',
    }
    gate = _v39_p30_gate(base, split_manifest, label_fix, fixed_projection)
    base['p30_sdss_core_route_confirm_gate_v39'] = gate
    base['p30_global_confirm_gate_v39'] = _v32_gate(
        p30_sdss_core_route_confirm=bool(gate.get('eligible_for_confirm_like')),
        second_independent_route=False,
    )
    # Preserve the v38 positive route separate from projection path.
    base['p30_sdss_positive_route_preserved_v39'] = base.get('p30_sdss_positive_route_preserved_v38') or (_v38_positive_route_preservation(base) if '_v38_positive_route_preservation' in globals() else {})
    if gate.get('eligible_for_confirm_like'):
        base['status'] = 'p30_sdss_core_route_confirm_like'
    elif label_fix.get('density_label_inversion_confirmed'):
        base['status'] = 'density_kappa_sdss_core_projection_HL_inversion_fixed_pending_residual'
    else:
        base['status'] = 'density_kappa_sdss_core_projection_pipeline_mismatch'
    return base


def run_p3_exact_metadata_v39(meta, args):
    base = _run_p3_v38_for_v39(meta, args)
    base['p3_endpoint_hard_skip_v39'] = {
        'hard_skip_enabled': True,
        'inherits_v38': base.get('p3_endpoint_hard_skip_v38'),
        'policy': 'No endpoint/node-pair metadata preview => endpoint_data_limited; avoid giant non-endpoint downloads.',
    }
    if str(base.get('status','')).startswith('endpoint'):
        base['status'] = 'endpoint_data_limited'
    return base


def run_highz_unit_field_table_v39(meta, args):
    base = _run_highz_v38_for_v39(meta, args)
    old = base.get('highz_objectlevel_confirm_gate_v38') or {}
    base['highz_objectlevel_confirm_gate_v39'] = _v32_gate(
        object_rows_ge_30=bool(old.get('object_rows_ge_30')),
        two_sources=bool(old.get('two_sources')),
        units_visible=bool(old.get('units_visible')),
        median_above_local=bool(old.get('median_above_local')),
        leave_one_source_stable=bool(old.get('leave_one_source_stable')),
        source_specific_catalogue_required=True,
        generic_scan_exhausted=True,
    )
    base['highz_v39_required_catalogues'] = base.get('highz_v38_required_catalogues') or {
        'required_output': ['source','object_id','z','vrot_km_s','radius_kpc','a_m_s2','unit_provenance']
    }
    return base


def run_p41_structured_cp_v39(meta, args):
    base = _run_p41_v38_for_v39(meta, args)
    old = base.get('p41_major_claim_gate_v38') or {}
    base['p41_major_claim_gate_v39'] = _v32_gate(
        q2_numeric_rows=bool(old.get('q2_numeric_rows')),
        cp_control_rows=bool(old.get('cp_control_rows')),
        likelihood_values=bool(old.get('likelihood_values')),
        wilson_sm_delta_chi2=bool(old.get('wilson_sm_delta_chi2')),
        cp_controls_null_or_weak=bool(old.get('cp_controls_null_or_weak')),
        delta_chi2_required=True,
    )
    base['p41_v39_required_likelihood_product'] = base.get('p41_v38_required_likelihood_product') or {
        'path': 'outputs/p41_wilson_sm_likelihood_rows_v39.json',
        'required_summary': ['chi2_sm','chi2_best_wilson','delta_chi2_sm_minus_wilson','cp_control_null_p'],
    }
    return base


