def run_dashboard_v39(meta, args):
    base = _run_dashboard_v38_for_v39(meta, args)
    outputs = _v39_outputs_dir(); rows=[]
    for p in sorted(outputs.glob('test*.json')):
        obj = _v39_read_json(p)
        if isinstance(obj, dict):
            rows.append(obj)
    instr=[]; p30=[]; pub=[]; blocked=[]
    for r in rows:
        keys=[k for k in r if k.endswith('_v39') or '_v39_' in k]
        if keys:
            instr.append({'test_id':r.get('test_id'), 'prediction_id':r.get('prediction_id'), 'status':r.get('status'), 'v39_keys':sorted(keys)})
        if r.get('p30_projection_label_fix_test_v39') or r.get('p30_fixed_curl_projection_v39'):
            p30.append({
                'test_id': r.get('test_id'),
                'status': r.get('status'),
                'positive_route_preserved': r.get('p30_sdss_positive_route_preserved_v39'),
                'label_fix': r.get('p30_projection_label_fix_test_v39'),
                'fixed_projection': r.get('p30_fixed_curl_projection_v39'),
                'gate': r.get('p30_sdss_core_route_confirm_gate_v39'),
            })
        st=str(r.get('status',''))
        if 'publication_confirm_like' in st or st in ['robust_confirm_like','void_morphology_publication_grade_confirm_like','p30_sdss_core_route_confirm_like']:
            pub.append({'test_id':r.get('test_id'), 'prediction_id':r.get('prediction_id'), 'status':st})
        for k,v in r.items():
            if isinstance(v, dict) and k.endswith('_gate_v39') and not v.get('eligible_for_confirm_like', True):
                blocked.append({'test_id':r.get('test_id'), 'prediction_id':r.get('prediction_id'), 'gate':k, 'missing':v.get('missing')})
    base['dashboard_v39'] = {
        'n_v39_instrumented_tests': len(instr),
        'v39_instrumented_tests': instr[:200],
        'p30_projection_label_fix_routes': p30,
        'publication_grade_confirm_like': pub,
        'blocked_v39_gates': blocked,
        'claim_policy': 'v39 fixes/tests P30 projection H/L orientation. P30 can only promote route-specifically if raw deltas reproduce canonical positives and residual curl projection passes.',
    }
    return _v60_scrub_manual_fill_references(base)

