def run_dashboard_v40(meta,args):
    base=_run_dashboard_v39_for_v40(meta,args)
    outputs=_v40_outputs_dir(); rows=[]
    for p in sorted(outputs.glob('test*.json')):
        obj=_v40_read_json(p)
        if isinstance(obj,dict):
            rows.append(obj)
    instr=[]; p30=[]; pub=[]; blocked=[]
    for r in rows:
        keys=[k for k in r if k.endswith('_v40') or '_v40_' in k]
        if keys:
            instr.append({'test_id':r.get('test_id'),'prediction_id':r.get('prediction_id'),'status':r.get('status'),'v40_keys':sorted(keys)})
        if r.get('p30_patch_level_curl_residual_separation_v40'):
            p30.append({'test_id':r.get('test_id'),'status':r.get('status'),'positive_route_preserved':r.get('p30_sdss_positive_route_preserved_v40'),'curl_residual_separation':r.get('p30_patch_level_curl_residual_separation_v40'),'gate':r.get('p30_sdss_core_route_confirm_gate_v40')})
        st=str(r.get('status',''))
        if 'publication_confirm_like' in st or st in ['robust_confirm_like','void_morphology_publication_grade_confirm_like','p30_sdss_core_route_confirm_like']:
            pub.append({'test_id':r.get('test_id'),'prediction_id':r.get('prediction_id'),'status':st})
        for k,v in r.items():
            if isinstance(v,dict) and k.endswith('_gate_v40') and not v.get('eligible_for_confirm_like', True):
                blocked.append({'test_id':r.get('test_id'),'prediction_id':r.get('prediction_id'),'gate':k,'missing':v.get('missing')})
    base['dashboard_v40']={
        'n_v40_instrumented_tests':len(instr),
        'v40_instrumented_tests':instr[:200],
        'p30_curl_residual_separation_routes':p30,
        'publication_grade_confirm_like':pub,
        'blocked_v40_gates':blocked,
        'claim_policy':'v40 can promote only P30-SDSS-core route if orientation-fixed raw deltas, patch-level science-vs-curl bootstrap, residual curl-null, and family-specific residual gates pass. Global P30 remains blocked.',
    }
    return _v60_scrub_manual_fill_references(base)

