def _v41_outputs_dir():
    d = Path.cwd() / 'outputs'
    d.mkdir(exist_ok=True)
    return d


def _v41_cache_dir(args=None):
    try:
        d = Path(getattr(args, 'cache_dir', DEFAULT_CACHE))
    except Exception:
        d = Path(DEFAULT_CACHE)
    d.mkdir(parents=True, exist_ok=True)
    return d


def _v41_write_json(path, obj):
    path = Path(path); path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(obj, indent=2, sort_keys=True, ensure_ascii=False, default=json_default, allow_nan=False), encoding='utf-8')


def _v41_read_json(path):
    try:
        path = Path(path)
        if path.exists():
            return json.loads(path.read_text(encoding='utf-8'))
    except Exception:
        return None
    return None


def _v41_float(x):
    try:
        y = float(x)
        return y if math.isfinite(y) else None
    except Exception:
        return None


def _v41_quantile(vals, q):
    vals = sorted([float(v) for v in vals if _v41_float(v) is not None])
    if not vals:
        return None
    if len(vals) == 1:
        return vals[0]
    pos = q * (len(vals) - 1)
    lo = int(math.floor(pos)); hi = int(math.ceil(pos))
    if lo == hi:
        return vals[lo]
    return vals[lo] * (hi - pos) + vals[hi] * (pos - lo)


def _v41_links(text, base=''):
    links = re.findall(r'href=["\']([^"\']+)["\']', text or '', flags=re.I)
    out=[]
    for l in links:
        if base and not re.match(r'https?://', l, flags=re.I):
            l = urllib.parse.urljoin(base, l)
        out.append(l)
    return out


def _v41_empirical_mask_product(p30_base):
    out = _v41_outputs_dir() / 'p30_empirical_finite_support_mask_product_v41.json'
    gate = p30_base.get('p30_act_mask_or_equivalent_v26') or p30_base.get('p30_act_mask_gate_v25') or {}
    prod = {
        'version': 'v41',
        'available': bool(gate.get('empirical_finite_support_mask') or gate.get('empirical_finite_support_mask_available')),
        'claim_scope': 'empirical finite-support mask product; diagnostic/equivalent only unless official ACT mask is provided',
        'official_mask_found': bool(gate.get('official_mask_found')),
        'n_finite_pixels': gate.get('n_finite_pixels'),
        'n_total_pixels': gate.get('n_total_pixels'),
        'finite_fraction': gate.get('finite_fraction'),
        'required_for_publication': True,
        'rule': 'All P30 variants/randoms must be run through the same persisted mask product before any route claim is publishable.',
    }
    _v41_write_json(out, prod); prod['path'] = str(out)
    return prod


def _v41_p30_route_gate(p30_base):
    sep = p30_base.get('p30_patch_level_curl_residual_separation_v40') or {}
    v40_gate = p30_base.get('p30_sdss_core_route_confirm_gate_v40') or {}
    empirical_mask = p30_base.get('p30_empirical_finite_support_mask_product_v41') or {}
    residual_gate = sep.get('residual_curl_null_gate_v40') or p30_base.get('p30_residual_curl_null_gate_v40') or {}
    patch_gate = sep.get('patch_level_gate_v40') or {}
    family = p30_base.get('p30_curl_family_specificity_test_v40') or sep.get('curl_family_specificity') or {}
    # v41 intentionally removes global_scope from the route gate. Global P30 remains a separate gate.
    gate = _v32_gate(
        orientation_fixed=bool(v40_gate.get('orientation_fixed')),
        raw_delta_consistency=bool(v40_gate.get('raw_delta_consistency')),
        sampled_cache_available=bool(v40_gate.get('sampled_cache_available')),
        patch_level_bootstrap_pass=bool(patch_gate.get('pass') or v40_gate.get('patch_level_bootstrap_pass')),
        residual_curl_patch_null_pass=bool(residual_gate.get('pass')),
        leave_one_patch_out_stable=bool(sep.get('leave_one_patch_out_stable_v41')),
        family_specificity_pass=bool(v40_gate.get('family_specificity_pass') or family.get('pass')),
        empirical_mask_product_available=bool(empirical_mask.get('available')),
        route_specific_scope=True,
    )
    gate['claim_scope'] = 'P30-SDSS-core route only; global P30 is evaluated by p30_global_confirm_gate_v41.'
    gate['global_scope_required_for_this_gate'] = False
    gate['promotion_label_if_passes'] = 'p30_sdss_core_route_confirm_like'
    return gate


def _v41_p30_patch_null_extension(p30_base):
    # Prefer v40 report; add v41 policy fields and a stricter patch-based interpretation.
    sep = dict(p30_base.get('p30_patch_level_curl_residual_separation_v40') or {})
    out = _v41_outputs_dir() / 'p30_patch_based_residual_curl_null_v41.json'
    rep = {
        'version': 'v41',
        'available': bool(sep.get('available')),
        'source': sep.get('path'),
        'policy': 'curl null must be evaluated at sky-patch level, not object level, to avoid correlated-pixel overcounting',
        'object_level_overcounting_guard': True,
        'residual_curl_null_pass': bool(((sep.get('residual_curl_null_gate_v40') or {}).get('pass'))),
        'patch_level_bootstrap_pass': bool(((sep.get('patch_level_gate_v40') or {}).get('pass'))),
    }
    # Leave-one-patch-out support when v40 rows are available.
    patch_rows = sep.get('patch_rows_residual') or sep.get('patch_rows') or sep.get('patch_level_rows') or []
    usable=[]
    if isinstance(patch_rows, list):
        for r in patch_rows:
            sd = _v41_float((r or {}).get('science_delta'))
            cd = _v41_float((r or {}).get('curl_delta'))
            if sd is not None and cd is not None:
                usable.append({'patch': (r or {}).get('patch'), 'science_delta': sd, 'curl_delta': cd, 'science_minus_abs_curl': sd-abs(cd)})
    rep['n_patch_rows'] = len(usable)
    rep['leave_one_patch_out'] = []
    if len(usable) >= 4:
        diffs=[]
        for i in range(len(usable)):
            rest=[r for j,r in enumerate(usable) if j != i]
            val=sum(r['science_minus_abs_curl'] for r in rest)/len(rest)
            diffs.append(val)
            rep['leave_one_patch_out'].append({'held_out': usable[i].get('patch', i), 'mean_science_minus_abs_curl': val, 'pass': val > 0})
        rep['leave_one_patch_out_stable'] = all(x > 0 for x in diffs)
    else:
        rep['leave_one_patch_out_stable'] = False
        rep['leave_one_patch_out_reason'] = 'not enough patch rows in v40 report; rerun P30 --allow-large with v41 for full leave-one-patch-out diagnostics'
    _v41_write_json(out, rep); rep['path']=str(out)
    return rep


def run_p30_maskrandom_freeze_v41(meta,args):
    base = _run_p30_v40_for_v41(meta,args)
    base['p30_empirical_finite_support_mask_product_v41'] = _v41_empirical_mask_product(base)
    patch_null = _v41_p30_patch_null_extension(base)
    base['p30_patch_based_residual_curl_null_v41'] = patch_null
    # expose leave-one-patch-out result back into v40 sep-like object for the gate
    if isinstance(base.get('p30_patch_level_curl_residual_separation_v40'), dict):
        base['p30_patch_level_curl_residual_separation_v40']['leave_one_patch_out_stable_v41'] = bool(patch_null.get('leave_one_patch_out_stable'))
    base['p30_sdss_core_route_confirm_gate_v41'] = _v41_p30_route_gate(base)
    base['p30_global_confirm_gate_v41'] = _v32_gate(
        p30_sdss_core_route_confirm=bool(base['p30_sdss_core_route_confirm_gate_v41'].get('eligible_for_confirm_like')),
        second_independent_route_confirm=False,
        global_scope=True,
    )
    if base['p30_sdss_core_route_confirm_gate_v41'].get('eligible_for_confirm_like'):
        base['status'] = 'p30_sdss_core_route_confirm_like'
    elif bool((base.get('p30_patch_level_curl_residual_separation_v40') or {}).get('available')):
        base['status'] = 'density_kappa_sdss_core_v41_residual_curl_blocked'
    else:
        base['status'] = base.get('status','density_kappa_sdss_core_v41_measurement_pending')
    return base


# ---------------- P36 v41: source-specific object catalogue parser ----------------
_V41_HIGHZ_SOURCE_PATTERNS = {
    'KMOS3D': re.compile(r'kmos|k3d', re.I),
    'KROSS': re.compile(r'kross', re.I),
    'KGES': re.compile(r'kges', re.I),
    'MOSDEF': re.compile(r'mosdef', re.I),
    'SAMI': re.compile(r'sami', re.I),
}


def _v41_source_from_name(name):
    for src,pat in _V41_HIGHZ_SOURCE_PATTERNS.items():
        if pat.search(str(name)):
            return src
    return None


def _v41_col_lookup(cols, aliases):
    norm={re.sub(r'[^a-z0-9]','',str(c).lower()): c for c in cols}
    for a in aliases:
        key=re.sub(r'[^a-z0-9]','',a.lower())
        if key in norm:
            return norm[key]
    # fuzzy contains fallback but reject known unsafe velocity fields elsewhere
    for c in cols:
        lc=re.sub(r'[^a-z0-9]','',str(c).lower())
        for a in aliases:
            ak=re.sub(r'[^a-z0-9]','',a.lower())
            if ak and ak in lc:
                return c
    return None


def _v41_extract_highz_rows_from_dicts(rows, source, path):
    out=[]
    if not rows:
        return out
    cols=set()
    for r in rows[:20]:
        cols.update(list((r or {}).keys()))
    cols=list(cols)
    id_col=_v41_col_lookup(cols, ['object_id','objid','id','name','galaxy','source','kid','krossid','maskname'])
    z_col=_v41_col_lookup(cols, ['z','zspec','redshift','z_spec','z_best'])
    v_col=_v41_col_lookup(cols, ['vrot','v_rot','vrotation','rotationvelocity','rotvel','vcirc','v_circ','vmax','v_max','v22','v_2_2','v80','vflat','v_flat'])
    r_col=_v41_col_lookup(cols, ['radius_kpc','r_kpc','rkpc','rgal_kpc','r_e_kpc','re_kpc','re','r50_kpc','rd_kpc','rd','disk_radius_kpc','effective_radius_kpc','hlr_kpc','size_kpc'])
    unsafe_v = bool(v_col and re.search(r'(?i)(sig|sigma|disp|pa|angle|incl|err|error)', str(v_col)))
    if not (z_col and v_col and r_col) or unsafe_v:
        return out
    for i,r in enumerate(rows):
        z=_v41_float((r or {}).get(z_col)); v=_v41_float((r or {}).get(v_col)); rad=_v41_float((r or {}).get(r_col))
        if z is None or v is None or rad is None:
            continue
        if not (0.01 < z < 5.0 and 20.0 <= abs(v) <= 600.0 and 0.05 <= rad <= 100.0):
            continue
        a=(abs(v)*1000.0)**2/(rad*3.085677581e19)
        out.append({
            'source': source or _v41_source_from_name(path) or 'unknown',
            'object_id': str((r or {}).get(id_col, i)) if id_col else str(i),
            'z': z,
            'vrot_km_s': abs(v),
            'radius_kpc': rad,
            'a_m_s2': a,
            'unit_provenance': {'velocity_col': str(v_col), 'radius_col': str(r_col), 'z_col': str(z_col), 'assumed_velocity_unit': 'km/s', 'assumed_radius_unit': 'kpc', 'path': str(path)},
        })
    return out


def _v41_table_dicts_from_text(path, max_rows=20000):
    rows=[]
    try:
        txt=read_text_any(Path(path), max_bytes=25_000_000)
        # CSV/TSV/whitespace with header
        lines=[ln for ln in txt.splitlines() if ln.strip() and not ln.lstrip().startswith('#')]
        if not lines:
            return []
        delim=',' if ',' in lines[0] else ('\t' if '\t' in lines[0] else None)
        if delim:
            reader=csv.DictReader(lines, delimiter=delim)
            for i,r in enumerate(reader):
                if i>=max_rows: break
                rows.append(dict(r))
        else:
            header=re.split(r'\s+', lines[0].strip())
            for ln in lines[1:max_rows+1]:
                parts=re.split(r'\s+', ln.strip())
                if len(parts)>=min(3,len(header)):
                    rows.append({h:v for h,v in zip(header,parts)})
    except Exception:
        return []
    return rows


def _v41_table_dicts_from_fits(path, max_rows=20000):
    try:
        from astropy.io import fits
        rows=[]
        with fits.open(path, memmap=False) as hdul:
            for hdu in hdul:
                data=getattr(hdu,'data',None)
                names=getattr(data,'names',None)
                if data is None or not names:
                    continue
                n=min(len(data), max_rows)
                for i in range(n):
                    row={}
                    for c in names:
                        try:
                            v=data[c][i]
                            if hasattr(v,'item'):
                                v=v.item()
                            row[c]=v
                        except Exception:
                            pass
                    rows.append(row)
        return rows
    except Exception:
        return []


def _v41_highz_candidate_files(args, meta):
    cache=_v41_cache_dir(args); candidates=[]; attempts=[]
    # local cache scan first
    for p in cache.rglob('*'):
        if p.is_file() and p.suffix.lower() in {'.fits','.fit','.csv','.tsv','.txt','.dat'}:
            if _v41_source_from_name(p.name) or re.search(r'(?i)(vrot|kinematic|catalog|katalog|galaxy|rotation)', p.name):
                candidates.append(p)
    # pages and direct data links from test metadata
    if not getattr(args, 'quick', False):
        source_urls=[]
        for u in (meta.get('urls') or []): source_urls.append(u)
        for s in (meta.get('sources') or []):
            if isinstance(s,dict) and s.get('url'): source_urls.append(s.get('url'))
        extra=[
            'https://www.mpe.mpg.de/ir/KMOS3D/data',
            'https://www.mpe.mpg.de/resources/IR/KMOS3D/data/README',
            'https://www.nottingham.ac.uk/astronomy/kross/data.aspx',
        ]
        source_urls=list(dict.fromkeys(source_urls+extra))
        for u in source_urls[:12]:
            info=download_one(u, cache, label='highz_v41_page', timeout=args.timeout, max_mb=args.max_mb, allow_large=args.allow_large)
            attempts.append(info)
            p=Path(info.get('path',''))
            if not p.exists() or info.get('error') or info.get('skipped'):
                continue
            txt=read_text_any(p, max_bytes=5_000_000)
            links=_v41_links(txt, u)
            data_links=[l for l in links if re.search(r'(?i)(kmos|k3d|kross|kges|mosdef|sami|vrot|kinematic|catalog|table).*(fits|fit|csv|tsv|txt|dat|gz|zip|tar)', l)]
            for l in data_links[:10]:
                di=download_one(l, cache, label='highz_v41_data', timeout=args.timeout, max_mb=args.max_mb, allow_large=args.allow_large)
                attempts.append(di)
                dp=Path(di.get('path',''))
                if dp.exists() and not di.get('error') and not di.get('skipped'):
                    candidates.append(dp)
    return list(dict.fromkeys([Path(c) for c in candidates])), attempts


def _v41_scan_highz_objects(args, meta):
    out_path=_v41_outputs_dir()/'p36_highz_real_object_catalogue_rows_v41.json'
    files, attempts=_v41_highz_candidate_files(args, meta)
    all_rows=[]; reports=[]
    for p in files[:80]:
        source=_v41_source_from_name(str(p))
        extracted=[]
        suf=p.suffix.lower()
        if suf in {'.fits','.fit'}:
            extracted=_v41_extract_highz_rows_from_dicts(_v41_table_dicts_from_fits(p), source, p)
        elif suf in {'.csv','.tsv','.txt','.dat'}:
            extracted=_v41_extract_highz_rows_from_dicts(_v41_table_dicts_from_text(p), source, p)
        reports.append({'path':str(p),'source_guess':source,'n_rows_extracted':len(extracted)})
        all_rows.extend(extracted)
    # De-duplicate roughly by source/object_id
    seen=set(); dedup=[]
    for r in all_rows:
        key=(r.get('source'),r.get('object_id'),round(float(r.get('z') or 0),4))
        if key in seen: continue
        seen.add(key); dedup.append(r)
    sources=sorted({r.get('source') for r in dedup if r.get('source')})
    a_vals=[r.get('a_m_s2') for r in dedup if _v41_float(r.get('a_m_s2')) is not None]
    med=_v41_quantile(a_vals,0.5)
    local_ref=1.2e-10
    loo=[]
    for s in sources:
        vals=[r.get('a_m_s2') for r in dedup if r.get('source')!=s and _v41_float(r.get('a_m_s2')) is not None]
        m=_v41_quantile(vals,0.5)
        loo.append({'held_out_source':s,'n_remaining':len(vals),'median_a_m_s2':m,'median_above_local': bool((m or 0)>local_ref)})
    report={
        'version':'v41',
        'n_candidate_files':len(files),
        'download_attempts':attempts[:50],
        'file_reports':reports[:80],
        'n_rows':len(dedup),
        'n_sources':len(sources),
        'sources':sources,
        'median_a_m_s2':med,
        'fraction_above_local_reference': (sum(1 for v in a_vals if v>local_ref)/len(a_vals) if a_vals else None),
        'rows':dedup[:5000],
        'leave_one_source':loo,
        'required_schema':['source','object_id','z','vrot_km_s','radius_kpc','a_m_s2','unit_provenance'],
        'claim_policy':'Major P36 high-z confirm requires >=30 strict rows from >=2 sources, visible units, median above local a0, and leave-one-source stability.',
    }
    _v41_write_json(out_path, report); report['path']=str(out_path)
    return report


def run_highz_unit_field_table_v41(meta,args):
    base=_run_highz_v40_for_v41(meta,args)
    scan=_v41_scan_highz_objects(args, meta)
    n=scan.get('n_rows') or 0; ns=scan.get('n_sources') or 0; med=scan.get('median_a_m_s2')
    loo=scan.get('leave_one_source') or []
    gate=_v32_gate(
        object_rows_ge_30=bool(n>=30),
        two_sources=bool(ns>=2),
        units_visible=bool(n>0),
        median_above_local=bool((med or 0)>1.2e-10),
        leave_one_source_stable=bool(loo and all(x.get('median_above_local') for x in loo)),
        source_specific_real_parser=True,
    )
    base['highz_real_object_catalogue_parser_v41']=scan
    base['highz_objectlevel_confirm_gate_v41']=gate
    if gate.get('eligible_for_confirm_like'):
        base['status']='highz_a0_objectlevel_publication_confirm_like'
    else:
        base['status']='highz_a0_objectlevel_gate_ready'
    return base


# ---------------- P41 v41: numerical Wilson/SM likelihood consumer ----------------

def _v41_flatten_json_rows(obj):
    rows=[]
    if isinstance(obj, list):
        for x in obj:
            rows.extend(_v41_flatten_json_rows(x))
    elif isinstance(obj, dict):
        if any(k in obj for k in ['value','error','q2','q2_low','observable','sm_prediction','wilson_prediction']):
            rows.append(obj)
        for v in obj.values():
            if isinstance(v,(list,dict)):
                rows.extend(_v41_flatten_json_rows(v))
    return rows


def _v41_load_likelihood_candidate_rows(args):
    outs=_v41_outputs_dir(); cache=_v41_cache_dir(args)
    files=[]
    for root in [outs, cache]:
        try:
            for p in root.rglob('*'):
                if p.is_file() and re.search(r'(?i)(p41|lhcb|bsll|wilson|q2|angular|mumu)', p.name) and p.suffix.lower() in {'.json','.csv','.txt','.dat','.tsv'}:
                    files.append(p)
        except Exception:
            pass
    rows=[]; reports=[]
    for p in files[:120]:
        got=[]
        try:
            if p.suffix.lower()=='.json':
                obj=json.loads(p.read_text(encoding='utf-8'))
                got=_v41_flatten_json_rows(obj)
            else:
                got=_v41_table_dicts_from_text(p, max_rows=20000)
        except Exception:
            got=[]
        norm=[]
        for r in got:
            if not isinstance(r,dict): continue
            cols=list(r.keys())
            obs_col=_v41_col_lookup(cols,['observable','obs','name'])
            q2_col=_v41_col_lookup(cols,['q2','q2_low','q2min','q2_min'])
            val_col=_v41_col_lookup(cols,['value','measurement','measured','central','data'])
            err_col=_v41_col_lookup(cols,['error','err','sigma','total_error','stat_error'])
            sm_col=_v41_col_lookup(cols,['sm_prediction','sm','sm_value','standard_model'])
            wil_col=_v41_col_lookup(cols,['wilson_prediction','wilson','best_wilson','np_prediction','c9_prediction'])
            cp_col=_v41_col_lookup(cols,['cp_label','cp','control','category'])
            val=_v41_float(r.get(val_col)) if val_col else None
            err=_v41_float(r.get(err_col)) if err_col else None
            sm=_v41_float(r.get(sm_col)) if sm_col else None
            wil=_v41_float(r.get(wil_col)) if wil_col else None
            q2=_v41_float(r.get(q2_col)) if q2_col else None
            if val is not None and err is not None and err>0 and (sm is not None or wil is not None or q2 is not None):
                norm.append({'observable':str(r.get(obs_col,'')) if obs_col else '', 'q2':q2, 'value':val, 'error':abs(err), 'sm_prediction':sm, 'wilson_prediction':wil, 'cp_label':str(r.get(cp_col,'')) if cp_col else '', 'source_file':str(p)})
        if norm:
            rows.extend(norm)
        reports.append({'path':str(p),'raw_rows':len(got),'accepted_rows':len(norm)})
    return rows, reports


def _v41_wilson_sm_likelihood(args):
    out=_v41_outputs_dir()/'p41_wilson_sm_likelihood_rows_v41.json'
    rows,reports=_v41_load_likelihood_candidate_rows(args)
    fit_rows=[r for r in rows if r.get('sm_prediction') is not None and r.get('wilson_prediction') is not None and r.get('error')]
    chi2_sm=chi2_wil=None; delta=None
    if fit_rows:
        chi2_sm=sum(((r['value']-r['sm_prediction'])/r['error'])**2 for r in fit_rows)
        chi2_wil=sum(((r['value']-r['wilson_prediction'])/r['error'])**2 for r in fit_rows)
        delta=chi2_sm-chi2_wil
    cp_rows=[r for r in rows if re.search(r'(?i)(cp|asym|A_|ACP)', str(r.get('cp_label',''))+' '+str(r.get('observable','')))]
    noncp=[r for r in rows if r not in cp_rows]
    cp_z=[abs((r['value']-(r.get('sm_prediction') or 0))/r['error']) for r in cp_rows if r.get('error')]
    cp_null=bool(cp_rows and (max(cp_z) if cp_z else 99) < 2.5)
    report={'version':'v41','candidate_reports':reports[:100],'n_rows':len(rows),'n_fit_rows':len(fit_rows),'n_cp_control_rows':len(cp_rows),'n_noncp_rows':len(noncp),'chi2_sm':chi2_sm,'chi2_best_wilson':chi2_wil,'delta_chi2_sm_minus_wilson':delta,'cp_controls_null_or_weak':cp_null,'rows':rows[:1000],'minimum_delta_chi2_for_confirm_like':9.0,'claim_policy':'P41 major claim requires numeric q2/value/error rows, Wilson/SM chi2, and CP controls null or weak.'}
    _v41_write_json(out,report); report['path']=str(out)
    return report


def run_p41_structured_cp_v41(meta,args):
    base=_run_p41_v40_for_v41(meta,args)
    like=_v41_wilson_sm_likelihood(args)
    gate=_v32_gate(
        q2_numeric_rows=bool(like.get('n_rows',0)>=20),
        cp_control_rows=bool(like.get('n_cp_control_rows',0)>=3),
        likelihood_values=bool(like.get('n_fit_rows',0)>=20),
        wilson_sm_delta_chi2=bool((like.get('delta_chi2_sm_minus_wilson') or 0)>=9.0),
        cp_controls_null_or_weak=bool(like.get('cp_controls_null_or_weak')),
        real_likelihood_consumer=True,
    )
    base['p41_wilson_sm_likelihood_v41']=like
    base['p41_major_claim_gate_v41']=gate
    if gate.get('eligible_for_confirm_like'):
        base['status']='p41_wilson_sm_likelihood_confirm_like'
    else:
        base['status']='p41_q2_likelihood_gate_ready'
    return base


# ---------------- P33 v41: density-split alpha measurement consumer ----------------

def _v41_load_alpha_products(args):
    outs=_v41_outputs_dir(); cache=_v41_cache_dir(args); files=[]
    for root in [outs, cache]:
        for p in root.rglob('*'):
            if p.is_file() and re.search(r'(?i)(p33|density.*bao|alpha.*split|bao.*alpha)', p.name) and p.suffix.lower() in {'.json','.csv','.txt','.dat','.tsv'}:
                files.append(p)
    rows=[]; reports=[]
    for p in files[:80]:
        got=[]
        try:
            if p.suffix.lower()=='.json':
                obj=json.loads(p.read_text(encoding='utf-8'))
                got=_v41_flatten_json_rows(obj)
                if isinstance(obj,dict): got.append(obj)
            else:
                got=_v41_table_dicts_from_text(p, max_rows=2000)
        except Exception:
            got=[]
        for r in got:
            if not isinstance(r,dict): continue
            ah=_v41_float(r.get('alpha_high') or r.get('alpha_high_density'))
            al=_v41_float(r.get('alpha_low') or r.get('alpha_low_density'))
            da=_v41_float(r.get('delta_alpha') or r.get('delta_alpha_high_minus_low'))
            if ah is not None and al is not None:
                if da is None: da=ah-al
                rows.append({'alpha_high':ah,'alpha_low':al,'delta_alpha':da,'source_file':str(p),'covariance':bool(r.get('covariance') or r.get('covariance_ready')),'density_label_shuffle_p':_v41_float(r.get('density_label_shuffle_p') or r.get('density_shuffle_p')),'sky_shuffle_p':_v41_float(r.get('sky_shuffle_p')),'redshift_jackknife_stable':bool(r.get('redshift_jackknife_stable'))})
        reports.append({'path':str(p),'rows_seen':len(got)})
    return rows,reports


def _v41_p33_alpha_measurement(args):
    out=_v41_outputs_dir()/'p33_density_split_alpha_measurement_v41.json'
    rows,reports=_v41_load_alpha_products(args)
    best=rows[0] if rows else None
    if rows:
        # prefer product with covariance/nulls if available
        rows=sorted(rows, key=lambda r:(r.get('covariance'), r.get('density_label_shuffle_p') is not None, abs(r.get('delta_alpha') or 0)), reverse=True)
        best=rows[0]
    report={'version':'v41','measurement_present':bool(best),'candidate_reports':reports[:100],'n_alpha_rows':len(rows),'best_measurement':best,'required_fields':['alpha_high','alpha_low','delta_alpha','covariance','density_label_shuffle_p','sky_shuffle_p','redshift_jackknife_stable'],'claim_policy':'P33 confirm requires a real density-split BAO alpha measurement with covariance and nulls, not a contract.'}
    _v41_write_json(out,report); report['path']=str(out)
    return report


def run_p33_density_bao_measured_scaffold_v41(meta,args):
    base=_run_p33_v40_for_v41(meta,args)
    meas=_v41_p33_alpha_measurement(args)
    best=meas.get('best_measurement') or {}
    da=_v41_float(best.get('delta_alpha'))
    dsh=_v41_float(best.get('density_label_shuffle_p'))
    sky=_v41_float(best.get('sky_shuffle_p'))
    gate=_v32_gate(
        alpha_high_low_measured=bool(meas.get('measurement_present')),
        covariance_ready=bool(best.get('covariance')),
        density_label_shuffle_pass=bool(dsh is not None and dsh<=0.05),
        sky_shuffle_pass=bool(sky is not None and sky<=0.05),
        redshift_jackknife_stable=bool(best.get('redshift_jackknife_stable')),
        delta_alpha_nonzero=bool(da is not None and abs(da)>0),
        real_alpha_measurement_consumer=True,
    )
    base['p33_density_split_alpha_measurement_v41']=meas
    base['p33_publication_confirm_gate_v41']=gate
    if gate.get('eligible_for_confirm_like'):
        base['status']='p33_density_bao_alpha_split_confirm_like'
    else:
        base['status']='p33_density_bao_measurement_ready_not_confirmed'
    return base


# ---------------- P32 v41: GW150914 one-event strain product consumer ----------------

def _v41_load_strain_products(args):
    outs=_v41_outputs_dir(); cache=_v41_cache_dir(args); files=[]
    for root in [outs, cache]:
        for p in root.rglob('*'):
            if p.is_file() and re.search(r'(?i)(p32|gw150914|ringdown|strain|gwosc)', p.name) and p.suffix.lower() in {'.json','.csv','.txt','.dat','.tsv'}:
                files.append(p)
    products=[]; reports=[]
    for p in files[:100]:
        obj=None
        try:
            if p.suffix.lower()=='.json':
                obj=json.loads(p.read_text(encoding='utf-8'))
            else:
                rows=_v41_table_dicts_from_text(p, max_rows=1000); obj={'rows':rows}
        except Exception:
            obj=None
        if isinstance(obj,dict):
            products.append({'path':str(p),'obj':obj})
            reports.append({'path':str(p),'keys':list(obj.keys())[:30]})
    return products,reports


def _v41_p32_one_event_consumer(args):
    out=_v41_outputs_dir()/'p32_gw150914_one_event_strain_result_v41.json'
    products,reports=_v41_load_strain_products(args)
    accepted=None
    for pr in products:
        o=pr['obj']
        checks={
            'strain_downloaded': bool(o.get('strain_downloaded') or o.get('strain_files') or o.get('h1_strain') or o.get('l1_strain')),
            'psd_estimated': bool(o.get('psd_estimated') or o.get('psd') or o.get('noise_psd')),
            'gr_ringdown_fit': bool(o.get('gr_ringdown_fit') or o.get('gr_fit') or o.get('ringdown_gr')),
            'ccdr_residual_template_fit': bool(o.get('ccdr_residual_template_fit') or o.get('ccdr_fit') or o.get('residual_template_fit')),
            'residual_improves_gr': bool(o.get('residual_improves_gr') or ((_v41_float(o.get('delta_chi2_gr_minus_ccdr')) or 0)>0)),
            'injection_nulls': bool(o.get('injection_nulls') or o.get('injection_null_pass')),
            'detector_split': bool(o.get('detector_split') or o.get('h1_l1_split')),
            'leave_one_event_out': bool(o.get('leave_one_event_out') or o.get('single_event_only')),
        }
        if sum(checks.values()) >= 4:
            accepted={'path':pr['path'],'checks':checks,'delta_chi2_gr_minus_ccdr':_v41_float(o.get('delta_chi2_gr_minus_ccdr'))}
            break
    if not accepted:
        accepted={'path':None,'checks':{k:False for k in ['strain_downloaded','psd_estimated','gr_ringdown_fit','ccdr_residual_template_fit','residual_improves_gr','injection_nulls','detector_split','leave_one_event_out']}}
    report={'version':'v41','n_candidate_products':len(products),'candidate_reports':reports[:100],'accepted_product':accepted,'required_event':'GW150914','claim_policy':'One-event result is diagnostic unless injection nulls, detector split, residual improves GR, and leave-one-event/leave-detector robustness pass.'}
    _v41_write_json(out,report); report['path']=str(out)
    return report


def run_ringdown_strain_plan_v41(meta,args):
    base=_run_p32_v40_for_v41(meta,args)
    prod=_v41_p32_one_event_consumer(args)
    checks=(prod.get('accepted_product') or {}).get('checks') or {}
