def run_dashboard_v41(meta,args):
    base=_run_dashboard_v40_for_v41(meta,args)
    outputs=_v41_outputs_dir(); rows=[]
    for p in sorted(outputs.glob('test*.json')):
        obj=_v41_read_json(p)
        if isinstance(obj,dict): rows.append(obj)
    instr=[]; blocked=[]; pub=[]; priorities=[]
    for r in rows:
        keys=[k for k in r if k.endswith('_v41') or '_v41_' in k]
        if keys:
            instr.append({'test_id':r.get('test_id'),'prediction_id':r.get('prediction_id'),'status':r.get('status'),'v41_keys':sorted(keys)})
        st=str(r.get('status',''))
        if 'publication_confirm_like' in st or st in {'robust_confirm_like','void_morphology_publication_grade_confirm_like','p30_sdss_core_route_confirm_like'}:
            pub.append({'test_id':r.get('test_id'),'prediction_id':r.get('prediction_id'),'status':st})
        for k,v in r.items():
            if isinstance(v,dict) and k.endswith('_gate_v41') and not v.get('eligible_for_confirm_like', True):
                blocked.append({'test_id':r.get('test_id'),'prediction_id':r.get('prediction_id'),'gate':k,'missing':v.get('missing')})
        for key in ['p36','p41','p33','p32']:
            if key in str(r.get('prediction_id','')).lower() or key in st.lower():
                priorities.append({'test_id':r.get('test_id'),'prediction_id':r.get('prediction_id'),'status':st})
    base['dashboard_v41']={
        'n_v41_instrumented_tests':len(instr),
        'v41_instrumented_tests':instr[:200],
        'publication_grade_confirm_like':pub,
        'blocked_v41_gates':blocked,
        'priority_7_10_measurement_tests':priorities,
        'claim_policy':'v41 removes global_scope from route-specific P30 gate, but keeps global P30 separate. P36/P41/P33/P32 require actual measured rows/products before promotion.',
    }
    return _v60_scrub_manual_fill_references(base)

