def _v42_outputs_dir():
    p = Path.cwd() / 'outputs'
    p.mkdir(exist_ok=True)
    return p


def _v42_cache_dir(args=None):
    try:
        p = Path(getattr(args, 'cache_dir', DEFAULT_CACHE))
    except Exception:
        p = Path(DEFAULT_CACHE)
    p.mkdir(parents=True, exist_ok=True)
    return p


def _v42_write_json(path, obj):
    path = Path(path); path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(obj, indent=2, sort_keys=True, ensure_ascii=False, default=json_default, allow_nan=False), encoding='utf-8')


def _v42_read_json(path):
    try:
        path = Path(path)
        if path.exists():
            return json.loads(path.read_text(encoding='utf-8'))
    except Exception:
        return None
    return None


def _v42_float(x):
    try:
        y = float(x)
        return y if math.isfinite(y) else None
    except Exception:
        return None


def _v42_quantile(vals, q):
    vals = sorted([float(v) for v in vals if _v42_float(v) is not None])
    if not vals:
        return None
    if len(vals) == 1:
        return vals[0]
    pos = q * (len(vals) - 1)
    lo = int(math.floor(pos)); hi = int(math.ceil(pos))
    if lo == hi:
        return vals[lo]
    return vals[lo] * (hi - pos) + vals[hi] * (pos - lo)


def _v42_rows_from_json_or_obj(obj, key_hints=None):
    key_hints = key_hints or []
    if isinstance(obj, list):
        return [x for x in obj if isinstance(x, dict)]
    if isinstance(obj, dict):
        for k in key_hints + ['accepted_rows','rows','object_rows','catalogue_rows','fit_rows','alpha_rows','measurements','products']:
            v = obj.get(k)
            if isinstance(v, list):
                return [x for x in v if isinstance(x, dict)]
        # fallback flatten
        try:
            if '_v41_flatten_json_rows' in globals():
                return [x for x in _v41_flatten_json_rows(obj) if isinstance(x, dict)]
        except Exception:
            pass
    return []


# -------- P36 high-z v42 audit and robustness gate --------

def _v42_highz_row_normalize(r):
    if not isinstance(r, dict):
        return None
    source = r.get('source') or r.get('survey') or r.get('catalogue') or r.get('dataset') or 'unknown'
    objid = r.get('object_id') or r.get('id') or r.get('objid') or r.get('name') or r.get('galaxy')
    z = _v42_float(r.get('z') or r.get('redshift') or r.get('zspec') or r.get('z_spec'))
    v = _v42_float(r.get('vrot_km_s') or r.get('vrot') or r.get('v_rot') or r.get('vmax') or r.get('v_flat') or r.get('vcirc'))
    rad = _v42_float(r.get('radius_kpc') or r.get('r_kpc') or r.get('rkpc') or r.get('re_kpc') or r.get('rd_kpc') or r.get('size_kpc'))
    a = _v42_float(r.get('a_m_s2'))
    if a is None and v is not None and rad is not None and rad > 0:
        # (km/s)^2 / kpc -> m/s^2
        a = (v * 1000.0) ** 2 / (rad * 3.0856775814913673e19)
    unit = r.get('unit_provenance') or r.get('units') or r.get('unit') or ''
    if z is None or v is None or rad is None or a is None:
        return None
    if v <= 0 or rad <= 0 or not (0.05 <= z <= 5.0):
        return None
    return {'source': str(source), 'object_id': str(objid or f'{source}_{len(str(r))}'), 'z': z, 'vrot_km_s': v, 'radius_kpc': rad, 'a_m_s2': a, 'unit_provenance': str(unit or 'derived_from_vrot_km_s_radius_kpc'), 'raw': r}


def _v42_load_highz_v41_rows(base=None):
    rows = []
    scan = (base or {}).get('highz_real_object_catalogue_parser_v41') or _v42_read_json(_v42_outputs_dir()/'p36_highz_real_object_catalogue_rows_v41.json') or {}
    for r in _v42_rows_from_json_or_obj(scan, ['accepted_rows','rows']):
        rr = _v42_highz_row_normalize(r)
        if rr:
            rows.append(rr)
    # Also inspect v39/v40 products if present.
    for fn in ['p36_highz_object_acceleration_rows_v30.json','p36_highz_real_object_catalogue_rows_v41.json','p36_highz_objectlevel_audit_v42.json']:
        obj = _v42_read_json(_v42_outputs_dir()/fn)
        if obj:
            for r in _v42_rows_from_json_or_obj(obj, ['accepted_rows','rows']):
                rr = _v42_highz_row_normalize(r)
                if rr:
                    rows.append(rr)
    # Dedup by source+object/z/v/r.
    seen=set(); out=[]
    for r in rows:
        key=(r['source'], r['object_id'], round(r['z'],5), round(r['vrot_km_s'],3), round(r['radius_kpc'],4))
        if key in seen:
            continue
        seen.add(key); out.append(r)
    return out


def _v42_highz_audit_and_gate(base=None):
    out = _v42_outputs_dir()/'p36_highz_objectlevel_audit_v42.json'
    rows = _v42_load_highz_v41_rows(base)
    a_local = 1.2e-10
    a_vals = [r['a_m_s2'] for r in rows]
    med = _v42_quantile(a_vals, 0.5)
    sources = sorted(set(r['source'] for r in rows))
    source_summaries=[]
    for s in sources:
        ss=[r for r in rows if r['source']==s]
        vals=[r['a_m_s2'] for r in ss]
        source_summaries.append({'source':s,'n_rows':len(ss),'median_a_m_s2':_v42_quantile(vals,0.5),'median_ratio_to_local':((_v42_quantile(vals,0.5) or 0)/a_local) if vals else None})
    leave=[]
    for s in sources:
        vals=[r['a_m_s2'] for r in rows if r['source'] != s]
        lm=_v42_quantile(vals,0.5)
        leave.append({'held_out_source':s,'n_remaining':len(vals),'median_a_m_s2':lm,'median_above_local':bool(lm is not None and lm > a_local),'median_ratio_to_local':(lm/a_local if lm is not None else None)})
    # source-level bootstrap of median ratio, deliberately conservative.
    bs=[]
    try:
        import random
        rng=random.Random(4242)
        by_src={s:[r['a_m_s2'] for r in rows if r['source']==s] for s in sources}
        if len(sources) >= 2:
            for _ in range(2000):
                vals=[]
                for __ in sources:
                    ss=rng.choice(sources)
                    vals.extend(by_src.get(ss, []))
                if vals:
                    bs.append((_v42_quantile(vals,0.5) or 0)/a_local)
    except Exception:
        bs=[]
    gate = _v32_gate(
        object_rows_ge_30 = len(rows) >= 30,
        two_sources = len(sources) >= 2,
        units_visible = all(bool(r.get('unit_provenance')) for r in rows[:min(len(rows),30)]) if rows else False,
        median_above_local = bool(med is not None and med > a_local),
        leave_one_source_stable = bool(len(leave) >= 2 and all(x.get('median_above_local') for x in leave)),
        source_bootstrap_ratio_ci16_above_1 = bool((_v42_quantile(bs,0.16) or -1) > 1.0),
        audit_rows_written = True,
    )
    report={
        'version':'v42',
        'claim_scope':'P36 high-z object-level a0 audit; protects v41 promotion by exposing accepted rows/sources/units.',
        'a_local_m_s2':a_local,
        'n_rows':len(rows),
        'n_sources':len(sources),
        'sources':sources,
        'median_a_m_s2':med,
        'median_ratio_to_local':(med/a_local if med is not None else None),
        'source_summaries':source_summaries,
        'leave_one_source':leave,
        'source_bootstrap_ratio_ci16':_v42_quantile(bs,0.16),
        'source_bootstrap_ratio_ci50':_v42_quantile(bs,0.50),
        'source_bootstrap_ratio_ci84':_v42_quantile(bs,0.84),
        'accepted_rows':[{k:v for k,v in r.items() if k!='raw'} for r in rows[:5000]],
        'highz_objectlevel_confirm_gate_v42':gate,
    }
    _v42_write_json(out, report); report['path']=str(out)
    return report


def run_highz_unit_field_table_v42(meta,args):
    base = _run_highz_v41_for_v42(meta,args)
    audit = _v42_highz_audit_and_gate(base)
    base['p36_highz_objectlevel_audit_v42'] = audit
    base['highz_objectlevel_confirm_gate_v42'] = audit.get('highz_objectlevel_confirm_gate_v42') or {}
    if base['highz_objectlevel_confirm_gate_v42'].get('eligible_for_confirm_like'):
        base['status'] = 'highz_a0_objectlevel_publication_confirm_like'
    elif str(base.get('status','')).startswith('highz_a0_objectlevel_publication_confirm_like'):
        # If v41 promoted but v42 audit could not verify, downgrade to audit-needed rather than falsify.
        base['status'] = 'highz_a0_objectlevel_confirm_like_audit_needed'
    return base


# -------- P30 v42: explicit patch rows and patch-only curl null --------

def _v42_p30_explicit_patch_rows(base):
    out = _v42_outputs_dir()/'p30_explicit_patch_rows_v42.json'
    sep = (base or {}).get('p30_patch_level_curl_residual_separation_v40') or _v42_read_json(_v42_outputs_dir()/'p30_patch_level_curl_residual_separation_v40.json') or {}
    rows = sep.get('patch_level_residual_rows') or sep.get('patch_rows_residual') or sep.get('patch_level_raw_rows') or sep.get('patch_rows') or []
    usable=[]
    if isinstance(rows, list):
        for i,r in enumerate(rows):
            if not isinstance(r, dict):
                continue
            sd=_v42_float(r.get('science_delta'))
            cd=_v42_float(r.get('curl_delta'))
            if sd is None or cd is None:
                continue
            usable.append({'patch_id':r.get('patch_id', r.get('patch', i)), 'n_high':r.get('n_high'), 'n_low':r.get('n_low'), 'science_delta':sd, 'curl_delta':cd, 'science_minus_abs_curl':sd-abs(cd), 'science_positive':sd>0, 'science_stronger_than_curl':sd>abs(cd)})
    # Leave-one-patch-out on explicit rows only.
    loo=[]
    if len(usable) >= 2:
        for i,r in enumerate(usable):
            rest=[x for j,x in enumerate(usable) if j != i]
            mean_science=sum(x['science_delta'] for x in rest)/len(rest)
            mean_diff=sum(x['science_minus_abs_curl'] for x in rest)/len(rest)
            loo.append({'held_out_patch':r['patch_id'], 'mean_science_delta':mean_science, 'mean_science_minus_abs_curl':mean_diff, 'pass': bool(mean_science>0 and mean_diff>0)})
    # Conservative patch-level null: curl is clean only if mean curl is non-extreme relative to science.
    mean_s = sum(r['science_delta'] for r in usable)/len(usable) if usable else None
    mean_c = sum(r['curl_delta'] for r in usable)/len(usable) if usable else None
    mean_diff = sum(r['science_minus_abs_curl'] for r in usable)/len(usable) if usable else None
    n_pos = sum(1 for r in usable if r['science_positive'])
    n_stronger = sum(1 for r in usable if r['science_stronger_than_curl'])
    # pass policy: enough patches, science positive in most, stronger than curl in most, leave-one stable.
    pass_patch = bool(len(usable) >= 6 and n_pos >= max(4, math.ceil(0.67*len(usable))) and n_stronger >= math.ceil(0.50*len(usable)) and loo and all(x['pass'] for x in loo))
    curl_null = bool(pass_patch and mean_c is not None and mean_s is not None and abs(mean_c) < 0.50*abs(mean_s))
    report={'version':'v42','available':bool(usable),'source':sep.get('path'),'claim_policy':'P30 residual curl-null is evaluated only on explicit sky patches; object-level p-values are diagnostics only.','n_patch_rows':len(usable),'minimum_patch_rows_required':6,'patch_rows':usable,'mean_science_delta':mean_s,'mean_curl_delta':mean_c,'mean_science_minus_abs_curl':mean_diff,'n_science_positive':n_pos,'n_science_stronger_than_curl':n_stronger,'leave_one_patch_out':loo,'leave_one_patch_out_stable':bool(loo and all(x['pass'] for x in loo)),'patch_level_residual_curl_null_pass':curl_null,'patch_level_gate_pass':pass_patch}
    _v42_write_json(out, report); report['path']=str(out)
    return report


def _v42_p30_empirical_mask_product(base):
    out = _v42_outputs_dir()/'p30_empirical_act_mask_product_v42.json'
    src = (base or {}).get('p30_empirical_finite_support_mask_product_v41') or _v42_read_json(_v42_outputs_dir()/'p30_empirical_finite_support_mask_product_v41.json') or {}
    prod = dict(src)
    prod.update({'version':'v42','mask_product_policy':'Persisted empirical finite-support mask is diagnostic-equivalent only. Publication-equivalent promotion still requires an official mask or a documented mask-equivalence appendix.','all_variants_must_use_same_mask':True,'claim_scope':'diagnostic_mask_product'})
    _v42_write_json(out, prod); prod['path']=str(out)
    return prod


def run_p30_maskrandom_freeze_v42(meta,args):
    base = _run_p30_v41_for_v42(meta,args)
    patch = _v42_p30_explicit_patch_rows(base)
    mask = _v42_p30_empirical_mask_product(base)
    old_gate = base.get('p30_sdss_core_route_confirm_gate_v41') or {}
    gate = _v32_gate(
        p30_sdss_positive_route_preserved=True,
        route_specific_scope=True,
        global_scope_not_required=True,
        orientation_fixed=bool(old_gate.get('orientation_fixed')),
        raw_delta_consistency=bool(old_gate.get('raw_delta_consistency')),
        sampled_cache_available=bool(old_gate.get('sampled_cache_available')),
        explicit_patch_rows_ge_6=bool(patch.get('n_patch_rows',0) >= 6),
        patch_level_bootstrap_pass=bool(old_gate.get('patch_level_bootstrap_pass') or patch.get('patch_level_gate_pass')),
        residual_curl_patch_null_pass=bool(patch.get('patch_level_residual_curl_null_pass')),
        leave_one_patch_out_stable=bool(patch.get('leave_one_patch_out_stable')),
        family_specificity_pass=bool(old_gate.get('family_specificity_pass')),
        empirical_mask_product_available=bool(mask.get('available')),
    )
    gate['claim_scope'] = 'P30-SDSS-core route only; global P30 remains separate.'
    gate['global_scope_required_for_this_gate'] = False
    gate['promotion_label_if_passes'] = 'p30_sdss_core_route_confirm_like'
    base['p30_explicit_patch_rows_v42'] = patch
    base['p30_empirical_act_mask_product_v42'] = mask
    base['p30_sdss_core_route_confirm_gate_v42'] = gate
    base['p30_global_confirm_gate_v42'] = _v32_gate(p30_sdss_core_route_confirm=bool(gate.get('eligible_for_confirm_like')), second_independent_route_confirm=False, global_scope=True)
    if gate.get('eligible_for_confirm_like'):
        base['status']='p30_sdss_core_route_confirm_like'
    else:
        base['status']='density_kappa_sdss_core_v42_patch_curl_null_blocked'
    return base


# -------- P41 v42: numeric Wilson/SM likelihood with CP split --------

def _v42_load_p41_rows(base=None, args=None):
    rows=[]
    like=(base or {}).get('p41_wilson_sm_likelihood_v41') or _v42_read_json(_v42_outputs_dir()/'p41_wilson_sm_likelihood_rows_v41.json') or {}
    for r in _v42_rows_from_json_or_obj(like, ['rows','fit_rows']):
        if not isinstance(r, dict):
            continue
        val=_v42_float(r.get('value') or r.get('measurement') or r.get('measured') or r.get('central'))
        err=_v42_float(r.get('error') or r.get('err') or r.get('sigma') or r.get('total_error'))
        sm=_v42_float(r.get('sm') or r.get('sm_prediction') or r.get('sm_value') or r.get('standard_model'))
        wil=_v42_float(r.get('wilson') or r.get('wilson_prediction') or r.get('best_wilson') or r.get('np_prediction'))
        q2=_v42_float(r.get('q2') or r.get('q2_low') or r.get('q2min') or r.get('q2_min'))
        cp=str(r.get('cp_label') or r.get('cp') or r.get('control') or r.get('category') or '').lower()
        if val is not None and err is not None and err > 0 and sm is not None:
            rows.append({'q2':q2,'value':val,'error':err,'sm':sm,'wilson':wil,'cp_label':cp,'observable':r.get('observable') or r.get('obs') or r.get('name')})
    return rows


def _v42_p41_likelihood(base=None, args=None):
    out=_v42_outputs_dir()/'p41_wilson_sm_likelihood_v42.json'
    rows=_v42_load_p41_rows(base,args)
    fit=[r for r in rows if not any(tok in (r.get('cp_label') or '') for tok in ['control','cp_asym','asym','acp'])]
    cp=[r for r in rows if r not in fit]
    chi2_sm=None; chi2_wil=None; delta=None; best_shift=None; used_fallback=False
    if fit:
        chi2_sm=sum(((r['value']-r['sm'])/r['error'])**2 for r in fit)
        if all(r.get('wilson') is not None for r in fit):
            chi2_wil=sum(((r['value']-r['wilson'])/r['error'])**2 for r in fit)
        else:
            # one-parameter Wilson-like shift fit: data = SM + shift.
            num=sum((r['value']-r['sm'])/(r['error']**2) for r in fit)
            den=sum(1/(r['error']**2) for r in fit)
            best_shift=num/max(den,1e-30)
            chi2_wil=sum(((r['value']-(r['sm']+best_shift))/r['error'])**2 for r in fit)
            used_fallback=True
        delta=chi2_sm-chi2_wil
    cp_null=True; cp_chi2=None
    if cp:
        cp_chi2=sum(((r['value']-r['sm'])/r['error'])**2 for r in cp)
        # conservative: controls null/weak only if average pull^2 is not large.
        cp_null=bool((cp_chi2/max(len(cp),1)) < 4.0)
    else:
        cp_null=False
    gate=_v32_gate(q2_numeric_rows=bool(len(fit)>=3), cp_control_rows=bool(len(cp)>=1), likelihood_values=bool(chi2_sm is not None and chi2_wil is not None), wilson_sm_delta_chi2=bool(delta is not None and delta>=9.0), cp_controls_null_or_weak=bool(cp_null), numerical_likelihood_v42=True)
    report={'version':'v42','n_rows':len(rows),'n_fit_rows':len(fit),'n_cp_control_rows':len(cp),'chi2_sm':chi2_sm,'chi2_best_wilson':chi2_wil,'delta_chi2_sm_minus_wilson':delta,'best_single_wilson_shift_proxy':best_shift,'used_single_shift_fallback':used_fallback,'cp_control_chi2':cp_chi2,'cp_controls_null_or_weak':cp_null,'minimum_delta_chi2_for_confirm_like':9.0,'p41_major_claim_gate_v42':gate,'rows':rows[:2000]}
    _v42_write_json(out,report); report['path']=str(out)
    return report


def run_p41_structured_cp_v42(meta,args):
    base=_run_p41_v41_for_v42(meta,args)
    like=_v42_p41_likelihood(base,args)
    base['p41_wilson_sm_likelihood_v42']=like
    base['p41_major_claim_gate_v42']=like.get('p41_major_claim_gate_v42') or {}
    if base['p41_major_claim_gate_v42'].get('eligible_for_confirm_like'):
        base['status']='p41_wilson_sm_likelihood_confirm_like'
    else:
        base['status']='p41_q2_likelihood_gate_ready'
    return base


# -------- P33 v42: alpha split product strengthening --------

def _v42_p33_alpha_measurement(base=None, args=None):
    out=_v42_outputs_dir()/'p33_density_split_alpha_measurement_v42.json'
    prior=(base or {}).get('p33_density_split_alpha_measurement_v41') or _v42_read_json(_v42_outputs_dir()/'p33_density_split_alpha_measurement_v41.json') or {}
    rows=[]
    for r in _v42_rows_from_json_or_obj(prior, ['alpha_rows','rows','measurements']):
        ah=_v42_float(r.get('alpha_high') or r.get('alpha_high_density'))
        al=_v42_float(r.get('alpha_low') or r.get('alpha_low_density'))
        da=_v42_float(r.get('delta_alpha') or r.get('delta_alpha_high_minus_low'))
        if ah is not None and al is not None:
            rows.append({'alpha_high':ah,'alpha_low':al,'delta_alpha':da if da is not None else ah-al,'covariance':bool(r.get('covariance') or r.get('covariance_ready')),'density_label_shuffle_p':_v42_float(r.get('density_label_shuffle_p') or r.get('density_shuffle_p')),'sky_shuffle_p':_v42_float(r.get('sky_shuffle_p')),'redshift_jackknife_stable':bool(r.get('redshift_jackknife_stable')),'source_file':r.get('source_file')})
    # Search output/cache again with broader names.
    for root in [_v42_outputs_dir(), _v42_cache_dir(args)]:
        try:
            files=list(root.rglob('*alpha*'))+list(root.rglob('*bao*split*'))+list(root.rglob('*density*bao*'))
        except Exception:
            files=[]
        for p in files[:100]:
            if not Path(p).is_file() or Path(p).suffix.lower() not in {'.json','.csv','.txt','.dat','.tsv'}:
                continue
            obj=_v42_read_json(p) if Path(p).suffix.lower()=='.json' else None
            got=[]
            if obj is not None:
                got=_v42_rows_from_json_or_obj(obj, ['alpha_rows','rows','measurements'])
                if isinstance(obj,dict): got.append(obj)
            else:
                try: got=_v41_table_dicts_from_text(p, max_rows=5000)
                except Exception: got=[]
            for r in got:
                if not isinstance(r,dict): continue
                ah=_v42_float(r.get('alpha_high') or r.get('alpha_high_density'))
                al=_v42_float(r.get('alpha_low') or r.get('alpha_low_density'))
                da=_v42_float(r.get('delta_alpha') or r.get('delta_alpha_high_minus_low'))
                if ah is not None and al is not None:
                    rows.append({'alpha_high':ah,'alpha_low':al,'delta_alpha':da if da is not None else ah-al,'covariance':bool(r.get('covariance') or r.get('covariance_ready')),'density_label_shuffle_p':_v42_float(r.get('density_label_shuffle_p') or r.get('density_shuffle_p')),'sky_shuffle_p':_v42_float(r.get('sky_shuffle_p')),'redshift_jackknife_stable':bool(r.get('redshift_jackknife_stable')),'source_file':str(p)})
    # Dedup rows.
    seen=set(); dedup=[]
    for r in rows:
        key=(round(r['alpha_high'],6), round(r['alpha_low'],6), r.get('source_file'))
        if key in seen: continue
        seen.add(key); dedup.append(r)
    best=None
    if dedup:
        dedup=sorted(dedup,key=lambda r:(bool(r.get('covariance')), r.get('density_label_shuffle_p') is not None, r.get('sky_shuffle_p') is not None, bool(r.get('redshift_jackknife_stable')), abs(r.get('delta_alpha') or 0)), reverse=True)
        best=dedup[0]
    dsh=_v42_float((best or {}).get('density_label_shuffle_p')); sky=_v42_float((best or {}).get('sky_shuffle_p')); da=_v42_float((best or {}).get('delta_alpha'))
    gate=_v32_gate(alpha_high_low_measured=bool(best), covariance_ready=bool((best or {}).get('covariance')), density_label_shuffle_pass=bool(dsh is not None and dsh<=0.05), sky_shuffle_pass=bool(sky is not None and sky<=0.05), redshift_jackknife_stable=bool((best or {}).get('redshift_jackknife_stable')), delta_alpha_nonzero=bool(da is not None and abs(da)>0), measured_not_contract=True)
    report={'version':'v42','measurement_present':bool(best),'n_alpha_rows':len(dedup),'best_measurement':best,'alpha_rows':dedup[:500],'required_fields':['alpha_high','alpha_low','delta_alpha','covariance','density_label_shuffle_p','sky_shuffle_p','redshift_jackknife_stable'],'p33_publication_confirm_gate_v42':gate}
    _v42_write_json(out,report); report['path']=str(out)
    return report


def run_p33_density_bao_measured_scaffold_v42(meta,args):
    base=_run_p33_v41_for_v42(meta,args)
    meas=_v42_p33_alpha_measurement(base,args)
    base['p33_density_split_alpha_measurement_v42']=meas
    base['p33_publication_confirm_gate_v42']=meas.get('p33_publication_confirm_gate_v42') or {}
    base['status']='p33_density_bao_alpha_split_confirm_like' if base['p33_publication_confirm_gate_v42'].get('eligible_for_confirm_like') else 'p33_density_bao_measurement_ready_not_confirmed'
    return base


# -------- P32 v42: one-event strain product hardening --------

def _v42_p32_consumer(base=None,args=None):
    out=_v42_outputs_dir()/'p32_gw150914_one_event_strain_result_v42.json'
    prior=(base or {}).get('p32_gw150914_one_event_strain_result_v41') or _v42_read_json(_v42_outputs_dir()/'p32_gw150914_one_event_strain_result_v41.json') or {}
    products=[]
    if isinstance(prior,dict) and prior.get('accepted_product'):
        products.append(prior.get('accepted_product'))
    for root in [_v42_outputs_dir(), _v42_cache_dir(args)]:
        try: files=list(root.rglob('*gw150914*'))+list(root.rglob('*ringdown*'))+list(root.rglob('*strain*'))
        except Exception: files=[]
        for p in files[:150]:
            if not Path(p).is_file() or Path(p).suffix.lower() not in {'.json','.csv','.txt','.dat','.tsv'}:
                continue
            obj=_v42_read_json(p) if Path(p).suffix.lower()=='.json' else None
            if isinstance(obj,dict):
                products.append({'path':str(p),'object':obj})
    accepted=None; all_products=[]
    for pr in products:
        o=pr.get('object') if isinstance(pr,dict) else None
        if o is None and isinstance(pr,dict):
            o=pr
        if not isinstance(o,dict): continue
        checks={
            'strain_downloaded': bool(o.get('strain_downloaded') or o.get('strain_files') or o.get('h1_strain') or o.get('l1_strain') or o.get('strain_path')),
            'psd_estimated': bool(o.get('psd_estimated') or o.get('psd') or o.get('noise_psd') or o.get('psd_path')),
            'gr_ringdown_fit': bool(o.get('gr_ringdown_fit') or o.get('gr_fit') or o.get('ringdown_gr')),
            'ccdr_residual_template_fit': bool(o.get('ccdr_residual_template_fit') or o.get('ccdr_fit') or o.get('residual_template_fit')),
            'residual_improves_gr': bool(o.get('residual_improves_gr') or ((_v42_float(o.get('delta_chi2_gr_minus_ccdr')) or 0)>0)),
            'injection_nulls': bool(o.get('injection_nulls') or o.get('injection_null_pass')),
            'detector_split': bool(o.get('detector_split') or o.get('h1_l1_split') or o.get('detector_consistency')),
            'leave_one_event_out': bool(o.get('leave_one_event_out') or o.get('single_event_only')),
        }
        item={'path':pr.get('path') if isinstance(pr,dict) else None,'checks':checks,'delta_chi2_gr_minus_ccdr':_v42_float(o.get('delta_chi2_gr_minus_ccdr')),'n_checks':sum(1 for v in checks.values() if v)}
        all_products.append(item)
        if item['n_checks'] >= 4 and accepted is None:
            accepted=item
    if accepted is None:
        accepted={'path':None,'checks':{k:False for k in ['strain_downloaded','psd_estimated','gr_ringdown_fit','ccdr_residual_template_fit','residual_improves_gr','injection_nulls','detector_split','leave_one_event_out']},'n_checks':0}
    checks=accepted['checks']
    gate=_v32_gate(strain_downloaded=checks.get('strain_downloaded'), psd_estimated=checks.get('psd_estimated'), gr_ringdown_fit=checks.get('gr_ringdown_fit'), ccdr_residual_template_fit=checks.get('ccdr_residual_template_fit'), residual_improves_gr=checks.get('residual_improves_gr'), injection_nulls=checks.get('injection_nulls'), detector_split=checks.get('detector_split'), leave_one_event_out=checks.get('leave_one_event_out'), one_event_strain_measured_product=True)
    manifest={'required_event':'GW150914','recommended_public_sources':['GWOSC 4kHz H1/L1 strain around GW150914','GWTC metadata for event parameters'],'required_outputs':['strain_downloaded','psd_estimated','gr_ringdown_fit','ccdr_residual_template_fit','delta_chi2_gr_minus_ccdr','injection_nulls','detector_split','leave_one_event_out']}
    report={'version':'v42','n_candidate_products':len(all_products),'accepted_product':accepted,'candidate_products':all_products[:200],'gw150914_measurement_manifest':manifest,'ringdown_strain_confirm_gate_v42':gate,'claim_policy':'P32 cannot promote from metadata. It needs a measured one-event strain product plus injection and detector-split nulls.'}
    _v42_write_json(out, report); report['path']=str(out)
    return report


def run_ringdown_strain_plan_v42(meta,args):
    base=_run_p32_v41_for_v42(meta,args)
