def run_dashboard_v42(meta,args):
    base=_run_dashboard_v41_for_v42(meta,args)
    outputs=_v42_outputs_dir(); rows=[]
    for p in sorted(outputs.glob('test*.json')):
        obj=_v42_read_json(p)
        if isinstance(obj,dict): rows.append(obj)
    instr=[]; blocked=[]; pub=[]; p36=[]; p30=[]; priority=[]
    for r in rows:
        st=str(r.get('status',''))
        keys=[k for k in r if k.endswith('_v42') or '_v42_' in k]
        if keys:
            instr.append({'test_id':r.get('test_id'),'prediction_id':r.get('prediction_id'),'status':st,'v42_keys':sorted(keys)})
        if 'publication_confirm_like' in st or st in {'robust_confirm_like','void_morphology_publication_grade_confirm_like','p30_sdss_core_route_confirm_like','p41_wilson_sm_likelihood_confirm_like','p33_density_bao_alpha_split_confirm_like'}:
            pub.append({'test_id':r.get('test_id'),'prediction_id':r.get('prediction_id'),'status':st})
        if r.get('p36_highz_objectlevel_audit_v42'):
            p36.append({'test_id':r.get('test_id'),'status':st,'audit':r.get('p36_highz_objectlevel_audit_v42'),'gate':r.get('highz_objectlevel_confirm_gate_v42')})
        if r.get('p30_explicit_patch_rows_v42'):
            p30.append({'test_id':r.get('test_id'),'status':st,'patch_rows':r.get('p30_explicit_patch_rows_v42'),'gate':r.get('p30_sdss_core_route_confirm_gate_v42')})
        for k,v in r.items():
            if isinstance(v,dict) and k.endswith('_gate_v42') and not v.get('eligible_for_confirm_like', True):
                blocked.append({'test_id':r.get('test_id'),'prediction_id':r.get('prediction_id'),'gate':k,'missing':v.get('missing')})
        if any(x in (str(r.get('prediction_id','')).lower()+st.lower()) for x in ['p30','p36','p41','p33','p32']):
            priority.append({'test_id':r.get('test_id'),'prediction_id':r.get('prediction_id'),'status':st})
    base['dashboard_v42']={'n_v42_instrumented_tests':len(instr),'v42_instrumented_tests':instr[:200],'publication_grade_confirm_like':pub,'p36_highz_audit_routes':p36,'p30_patch_curl_routes':p30,'blocked_v42_gates':blocked,'priority_confirm_targets':priority,'claim_policy':'v42 hardens new P36 high-z confirm-like via audit/robustness; P30 requires explicit patch curl-null; P41/P33/P32 need measured likelihood/alpha/strain products.'}
    return _v60_scrub_manual_fill_references(base)

