def _v43_outputs_dir():
    d = Path('outputs')
    d.mkdir(parents=True, exist_ok=True)
    return d


def _v43_cache_dir(args=None):
    try:
        return Path(getattr(args, 'cache_dir', DEFAULT_CACHE))
    except Exception:
        return DEFAULT_CACHE


def _v43_write_json(path, obj):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(obj, indent=2, sort_keys=True, default=json_default, allow_nan=False), encoding='utf-8')


def _v43_read_json(path):
    try:
        p = Path(path)
        if p.exists():
            return json.loads(p.read_text(encoding='utf-8', errors='replace'))
    except Exception:
        return None
    return None


def _v43_float(x):
    try:
        if x is None or x == '': return None
        v = float(x)
        return v if math.isfinite(v) else None
    except Exception:
        return None


def _v43_quantile(vals, q):
    vals = sorted([float(v) for v in vals if _v43_float(v) is not None])
    if not vals: return None
    if len(vals) == 1: return vals[0]
    pos = float(q) * (len(vals)-1)
    lo = int(math.floor(pos)); hi = int(math.ceil(pos))
    if lo == hi: return vals[lo]
    return vals[lo]*(hi-pos)+vals[hi]*(pos-lo)


def _v43_rows_from_json_or_obj(obj, key_hints=None):
    rows=[]
    hints = key_hints or ['rows','accepted_rows','alpha_rows','measurements','fit_rows','patch_rows','candidate_products']
    if isinstance(obj, list):
        for x in obj:
            if isinstance(x, dict): rows.append(x)
            else: rows.extend(_v43_rows_from_json_or_obj(x, hints))
    elif isinstance(obj, dict):
        # A single measurement-like dict counts as a row.
        row_like = any(k in obj for k in ['source','object_id','z','vrot_km_s','radius_kpc','a_m_s2','alpha_high','alpha_low','value','error','science_delta'])
        if row_like: rows.append(obj)
        for h in hints:
            v=obj.get(h)
            if isinstance(v, list):
                rows.extend([r for r in v if isinstance(r,dict)])
            elif isinstance(v, dict):
                rows.extend(_v43_rows_from_json_or_obj(v, hints))
    return rows

# ---------- P36 v43: second source discovery + hard source robustness ----------

_V43_HIGHZ_EXTRA_URLS = [
    'https://www.mpe.mpg.de/ir/KMOS3D/data',
    'https://www.mpe.mpg.de/resources/IR/KMOS3D/data/README',
    'https://www.nottingham.ac.uk/astronomy/kross/data.aspx',
    'https://mosdef.astro.berkeley.edu/for-scientists/data-releases/',
    'https://sami-survey.org/edr/',
]


def _v43_highz_norm_source(name):
    s = str(name or '').lower()
    if re.search(r'kmos|k3d', s): return 'KMOS3D'
    if 'kross' in s: return 'KROSS'
    if 'kges' in s: return 'KGES'
    if 'mosdef' in s: return 'MOSDEF'
    if 'sami' in s: return 'SAMI'
    if 'sinfo' in s or 'massiv' in s: return 'SINFONI_OR_MASSIV'
    return None


def _v43_highz_row_normalize(r, fallback_source=None, source_file=None):
    if not isinstance(r, dict): return None
    src = r.get('source') or r.get('catalogue') or fallback_source or _v43_highz_norm_source(source_file or r.get('source_file')) or 'unknown'
    oid = r.get('object_id') or r.get('id') or r.get('name') or r.get('galaxy') or r.get('kid') or r.get('krossid') or ''
    z = _v43_float(r.get('z') or r.get('redshift') or r.get('zspec') or r.get('z_spec') or r.get('z_best'))
    v = _v43_float(r.get('vrot_km_s') or r.get('vrot') or r.get('v_rot') or r.get('vrotation') or r.get('vmax') or r.get('v_flat') or r.get('vcirc') or r.get('Vrot'))
    rad = _v43_float(r.get('radius_kpc') or r.get('r_kpc') or r.get('rkpc') or r.get('re_kpc') or r.get('rd_kpc') or r.get('size_kpc') or r.get('R_kpc'))
    a = _v43_float(r.get('a_m_s2') or r.get('acceleration_m_s2') or r.get('a'))
    if a is None and v is not None and rad is not None and rad > 0:
        a = (v*1000.0)**2/(rad*3.085677581491367e19)
    if z is None or v is None or rad is None or a is None:
        return None
    if not (0.05 <= z <= 5.0 and 5 <= abs(v) <= 600 and 0.05 <= rad <= 100):
        return None
    unit = r.get('unit_provenance') or r.get('units') or 'vrot_km_s + radius_kpc'
    return {'source': str(src), 'object_id': str(oid) or f'{src}_{round(z,5)}_{round(v,3)}', 'z': z, 'vrot_km_s': v, 'radius_kpc': rad, 'a_m_s2': a, 'ratio_to_local_a0': a/1.2e-10, 'unit_provenance': str(unit), 'source_file': str(source_file or r.get('source_file') or '')}


def _v43_highz_scan_candidate_file(path):
    p=Path(path); rows=[]; report={'path':str(p),'source_guess':_v43_highz_norm_source(str(p)),'accepted_rows':0,'raw_rows':0,'error':None}
    try:
        if p.suffix.lower() in {'.fits','.fit'}:
            raw=_v41_table_dicts_from_fits(p)
        elif p.suffix.lower() in {'.csv','.tsv','.txt','.dat'}:
            raw=_v41_table_dicts_from_text(p, max_rows=50000)
        else:
            raw=[]
        report['raw_rows']=len(raw)
        for r in raw:
            rr=_v43_highz_row_normalize(r, fallback_source=report['source_guess'], source_file=p)
            if rr: rows.append(rr)
    except Exception as e:
        report['error']=repr(e)
    report['accepted_rows']=len(rows)
    return rows, report


def _v43_highz_discover_second_source_files(args, meta):
    cache=_v43_cache_dir(args); attempts=[]; candidates=[]
    # Start with existing cache/output products.
    for root in [_v43_outputs_dir(), cache]:
        try:
            for p in root.rglob('*'):
                if not p.is_file(): continue
                if p.suffix.lower() not in {'.fits','.fit','.csv','.tsv','.txt','.dat','.json'}: continue
                nm=str(p)
                if _v43_highz_norm_source(nm) or re.search(r'(?i)(vrot|rot|kinematic|galaxy|radius|redshift|mosdef|sami|kross|kmos|kges)', nm):
                    candidates.append(p)
        except Exception:
            pass
    if not getattr(args, 'quick', False):
        urls=[]
        for u in meta.get('urls') or []: urls.append(u)
        for s in meta.get('sources') or []:
            if isinstance(s,dict) and s.get('url'): urls.append(s.get('url'))
        urls=list(dict.fromkeys(urls+_V43_HIGHZ_EXTRA_URLS))
        for u in urls[:16]:
            info=download_one(u, cache, label='highz_v43_page', timeout=getattr(args,'timeout',SMALL_TIMEOUT), max_mb=getattr(args,'max_mb',250), allow_large=getattr(args,'allow_large',False))
            attempts.append(info)
            p=Path(info.get('path',''))
            if info.get('error') or info.get('skipped') or not p.exists(): continue
            txt=read_text_any(p, max_bytes=4_000_000)
            links=[]
            try: links=_v41_links(txt, u)
            except Exception: links=[]
            data_links=[l for l in links if re.search(r'(?i)(kmos|k3d|kross|kges|mosdef|sami|vrot|rot|kinematic|catalog|table|data).*(fits|fit|csv|tsv|txt|dat|gz|zip)', l)]
            for l in data_links[:20]:
                di=download_one(l, cache, label='highz_v43_data', timeout=getattr(args,'timeout',SMALL_TIMEOUT), max_mb=getattr(args,'max_mb',250), allow_large=getattr(args,'allow_large',False))
                attempts.append(di)
                dp=Path(di.get('path',''))
                if not di.get('error') and not di.get('skipped') and dp.exists(): candidates.append(dp)
    # Keep unique while preserving order.
    seen=set(); out=[]
    for c in candidates:
        s=str(c)
        if s in seen: continue
        seen.add(s); out.append(c)
    return out, attempts


def _v43_highz_second_source_audit(base, args, meta):
    out=_v43_outputs_dir()/'p36_highz_second_source_audit_v43.json'
    rows=[]
    # Consume v42/v41 accepted audit rows first.
    for key_obj in [
        (base or {}).get('p36_highz_objectlevel_audit_v42'),
        (base or {}).get('highz_real_object_catalogue_parser_v41'),
        _v43_read_json(_v43_outputs_dir()/'p36_highz_objectlevel_audit_v42.json'),
        _v43_read_json(_v43_outputs_dir()/'p36_highz_real_object_catalogue_rows_v41.json')]:
        for r in _v43_rows_from_json_or_obj(key_obj, ['accepted_rows','rows']):
            rr=_v43_highz_row_normalize(r, source_file=r.get('source_file') if isinstance(r,dict) else None)
            if rr: rows.append(rr)
    files, attempts = _v43_highz_discover_second_source_files(args, meta)
    file_reports=[]
    for p in files[:160]:
        # Do not recurse into our own already-normalized audit jsons here; they were consumed above.
        if Path(p).suffix.lower()=='.json':
            continue
        rr, rep=_v43_highz_scan_candidate_file(p)
        file_reports.append(rep)
        rows.extend(rr)
    # Deduplicate by source/object/z/v/radius.
    seen=set(); dedup=[]
    for r in rows:
        key=(r.get('source'), r.get('object_id'), round(r.get('z') or 0,5), round(r.get('vrot_km_s') or 0,3), round(r.get('radius_kpc') or 0,3))
        if key in seen: continue
        seen.add(key); dedup.append(r)
    sources=sorted({r['source'] for r in dedup if r.get('source') and r.get('source')!='unknown'})
    a_vals=[r['a_m_s2'] for r in dedup]
    med=_v43_quantile(a_vals,0.5); a_local=1.2e-10
    source_summaries=[]; loo=[]
    for s in sources:
        vals=[r['a_m_s2'] for r in dedup if r.get('source')==s]
        source_summaries.append({'source':s,'n_rows':len(vals),'median_a_m_s2':_v43_quantile(vals,0.5),'median_ratio_to_local':(_v43_quantile(vals,0.5) or 0)/a_local})
        rest=[r['a_m_s2'] for r in dedup if r.get('source')!=s]
        lm=_v43_quantile(rest,0.5)
        loo.append({'held_out_source':s,'n_remaining':len(rest),'median_a_m_s2':lm,'median_ratio_to_local':(lm or 0)/a_local if lm is not None else None,'pass':bool(lm is not None and lm>a_local)})
    # Source bootstrap samples entire sources so one-source domination cannot pass.
    bs=[]
    if len(sources)>=2:
        import random as _random_v43
        rng=_random_v43.Random(43036)
        bysrc={s:[r['a_m_s2'] for r in dedup if r.get('source')==s] for s in sources}
        for _ in range(1000):
            pick=[rng.choice(sources) for __ in sources]
            vals=[]
            for s in pick: vals.extend(bysrc.get(s,[]))
            if vals: bs.append((_v43_quantile(vals,0.5) or 0)/a_local)
    ci16=_v43_quantile(bs,0.16); ci50=_v43_quantile(bs,0.50); ci84=_v43_quantile(bs,0.84)
    gate=_v32_gate(
        object_rows_ge_30=bool(len(dedup)>=30),
        two_sources=bool(len(sources)>=2),
        units_visible=bool(dedup and all(r.get('unit_provenance') for r in dedup[:min(len(dedup),50)])),
        median_above_local=bool(med is not None and med>a_local),
        leave_one_source_stable=bool(loo and all(x.get('pass') for x in loo)),
        source_bootstrap_ratio_ci16_above_1=bool(ci16 is not None and ci16>1.0),
        second_source_real_parser_v43=True,
    )
    report={'version':'v43','n_rows':len(dedup),'n_sources':len(sources),'sources':sources,'median_a_m_s2':med,'median_ratio_to_local':(med/a_local if med else None),'source_summaries':source_summaries,'leave_one_source':loo,'source_bootstrap_ratio_ci16':ci16,'source_bootstrap_ratio_ci50':ci50,'source_bootstrap_ratio_ci84':ci84,'download_attempts':attempts[:120],'file_reports':file_reports[:160],'rows':dedup[:5000],'highz_objectlevel_confirm_gate_v43':gate,'claim_policy':'P36 high-z requires >=30 strict Vrot/R/z rows from >=2 independent sources, units, source bootstrap CI16>1, and leave-one-source stability.'}
    _v43_write_json(out,report); report['path']=str(out)
    return report


def run_highz_unit_field_table_v43(meta,args):
    base=_run_highz_v42_for_v43(meta,args)
