# ---------- P32 v43: optional GW150914 strain download/product gate ----------

_GW150914_URLS_V43 = {
    'H1_32s_4k': 'https://www.gwosc.org/eventapi/html/GWTC-1-confident/GW150914/v3/H-H1_LOSC_4_V2-1126259446-32.hdf5',
    'L1_32s_4k': 'https://www.gwosc.org/eventapi/html/GWTC-1-confident/GW150914/v3/L-L1_LOSC_4_V2-1126259446-32.hdf5',
}


def _v43_p32_try_download_strain(args):
    attempts=[]; products=[]
    if not getattr(args,'allow_large',False):
        return {'attempted':False,'reason':'rerun P32 with --allow-large to download GWOSC GW150914 strain','attempts':attempts,'products':products}
    cache=_v43_cache_dir(args)
    for label,url in _GW150914_URLS_V43.items():
        info=download_one(url, cache, label='p32_gw150914_'+label, timeout=getattr(args,'timeout',SMALL_TIMEOUT), max_mb=max(getattr(args,'max_mb',250),50), allow_large=True)
        attempts.append(info)
        p=Path(info.get('path',''))
        if p.exists() and not info.get('error') and not info.get('skipped'):
            products.append({'detector':label[:2], 'path':str(p), 'strain_downloaded':True, 'size_bytes':p.stat().st_size})
    return {'attempted':True,'attempts':attempts,'products':products}


def _v43_p32_consumer(base=None,args=None):
    out=_v43_outputs_dir()/'p32_gw150914_one_event_strain_result_v43.json'
    prior=[]
    for obj in [(base or {}).get('p32_gw150914_one_event_strain_result_v42'), (base or {}).get('p32_gw150914_one_event_strain_result_v41'), _v43_read_json(_v43_outputs_dir()/'p32_gw150914_one_event_strain_result_v42.json')]:
        prior.extend(_v43_rows_from_json_or_obj(obj, ['candidate_products','products']))
        if isinstance(obj,dict) and obj.get('accepted_product'): prior.append(obj.get('accepted_product'))
    dl=_v43_p32_try_download_strain(args)
    for p in dl.get('products') or []: prior.append({'path':p.get('path'),'strain_downloaded':True,'detector':p.get('detector')})
    candidates=[]
    for pr in prior:
        if not isinstance(pr,dict): continue
        o=pr.get('checks') if isinstance(pr.get('checks'),dict) else pr
        dchi=_v43_float(o.get('delta_chi2_gr_minus_ccdr') or pr.get('delta_chi2_gr_minus_ccdr'))
        checks={
            'strain_downloaded': bool(o.get('strain_downloaded') or o.get('strain') or o.get('path')),
            'psd_estimated': bool(o.get('psd_estimated') or o.get('psd')),
            'gr_ringdown_fit': bool(o.get('gr_ringdown_fit') or o.get('gr_fit')),
            'ccdr_residual_template_fit': bool(o.get('ccdr_residual_template_fit') or o.get('ccdr_fit') or o.get('residual_template_fit')),
            'residual_improves_gr': bool(o.get('residual_improves_gr') or (dchi is not None and dchi>0)),
            'injection_nulls': bool(o.get('injection_nulls') or o.get('injection_null_pass')),
            'detector_split': bool(o.get('detector_split') or o.get('h1_l1_split') or o.get('detector_consistency')),
            'leave_one_event_out': bool(o.get('leave_one_event_out') or o.get('single_event_only')),
        }
        candidates.append({'path':pr.get('path'), 'detector':pr.get('detector'), 'checks':checks, 'n_checks':sum(1 for v in checks.values() if v), 'delta_chi2_gr_minus_ccdr':dchi})
    accepted=max(candidates, key=lambda x:x.get('n_checks',0), default={'checks':{},'n_checks':0})
    c=accepted.get('checks') or {}
    gate=_v32_gate(strain_downloaded=c.get('strain_downloaded'), psd_estimated=c.get('psd_estimated'), gr_ringdown_fit=c.get('gr_ringdown_fit'), ccdr_residual_template_fit=c.get('ccdr_residual_template_fit'), residual_improves_gr=c.get('residual_improves_gr'), injection_nulls=c.get('injection_nulls'), detector_split=c.get('detector_split'), leave_one_event_out=c.get('leave_one_event_out'), gw150914_product_gate_v43=True)
    report={'version':'v43','gwosc_download':dl,'n_candidate_products':len(candidates),'accepted_product':accepted,'candidate_products':candidates[:200],'ringdown_strain_confirm_gate_v43':gate,'required_outputs':['strain_downloaded','psd_estimated','gr_ringdown_fit','ccdr_residual_template_fit','residual_improves_gr','injection_nulls','detector_split','leave_one_event_out'],'claim_policy':'Downloading strain is not enough. P32 needs PSD, GR ringdown, CCDR residual fit, injection nulls and detector split.'}
    _v43_write_json(out,report); report['path']=str(out)
    return report


def run_ringdown_strain_plan_v43(meta,args):
    base=_run_p32_v42_for_v43(meta,args)
    res=_v43_p32_consumer(base,args)
    base['p32_gw150914_one_event_strain_result_v43']=res
    base['ringdown_strain_confirm_gate_v43']=res.get('ringdown_strain_confirm_gate_v43') or {}
    base['status']='p32_ringdown_strain_confirm_like_candidate' if base['ringdown_strain_confirm_gate_v43'].get('eligible_for_confirm_like') else 'ringdown_ready_positive_bound'
    return base


def run_p3_exact_metadata_v43(meta,args):
    base=_run_p3_v42_for_v43(meta,args)
    base['p3_endpoint_hard_skip_v43']={'hard_skip_enabled':True,'policy':'No endpoint/node-pair metadata preview -> endpoint_data_limited and no giant downloads.','status_if_no_endpoint':'endpoint_data_limited'}
    if str(base.get('status','')).startswith('endpoint') or 'no_evidence' in str(base.get('status','')):
        base['status']='endpoint_data_limited'
    return base


def run_dashboard_v43(meta,args):
    base=_run_dashboard_v42_for_v43(meta,args)
    outputs=_v43_outputs_dir(); rows=[]
    for p in sorted(outputs.glob('test*.json')):
        obj=_v43_read_json(p)
        if isinstance(obj,dict): rows.append(obj)
    instr=[]; blocked=[]; pub=[]; targets=[]
    for r in rows:
        st=str(r.get('status',''))
        keys=[k for k in r if k.endswith('_v43') or '_v43_' in k]
        if keys: instr.append({'test_id':r.get('test_id'),'prediction_id':r.get('prediction_id'),'status':st,'v43_keys':sorted(keys)})
        if 'publication_confirm_like' in st or st in {'robust_confirm_like','void_morphology_publication_grade_confirm_like','p30_sdss_core_route_confirm_like','p41_wilson_sm_likelihood_confirm_like','p33_density_bao_alpha_split_confirm_like'}:
            pub.append({'test_id':r.get('test_id'),'prediction_id':r.get('prediction_id'),'status':st})
        for k,v in r.items():
            if isinstance(v,dict) and k.endswith('_gate_v43') and not v.get('eligible_for_confirm_like', True):
                blocked.append({'test_id':r.get('test_id'),'prediction_id':r.get('prediction_id'),'gate':k,'missing':v.get('missing')})
        if any(x in (str(r.get('prediction_id','')).lower()+st.lower()) for x in ['p30','p36','p41','p33','p32']):
            targets.append({'test_id':r.get('test_id'),'prediction_id':r.get('prediction_id'),'status':st})
    base['dashboard_v43']={'n_v43_instrumented_tests':len(instr),'v43_instrumented_tests':instr[:200],'publication_grade_confirm_like':pub,'blocked_v43_gates':blocked,'priority_confirm_targets':targets,'claim_policy':'v43 keeps strict dashboard separation: P36 needs second-source robustness; P30 needs patch stability and mask equivalence; P41/P33/P32 need measured likelihood/alpha/strain products.'}
    return _v60_scrub_manual_fill_references(base)

