def _v44_outputs_dir():
    p = Path('outputs'); p.mkdir(exist_ok=True); return p

def _v44_cache_dir(args=None):
    p = Path(getattr(args, 'cache_dir', '.ccdr_round10_cache') if args is not None else '.ccdr_round10_cache')
    p.mkdir(parents=True, exist_ok=True); return p

def _v44_write_json(path, obj):
    path = Path(path); path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(obj, indent=2, sort_keys=True, default=str), encoding='utf-8')

def _v44_read_json(path):
    try:
        p=Path(path)
        if p.exists():
            return json.loads(p.read_text(encoding='utf-8', errors='replace'))
    except Exception:
        return None
    return None

def _v44_float(x):
    try:
        if x is None: return None
        if isinstance(x, str):
            s=x.strip().replace(',', '')
            if not s or s.lower() in {'nan','none','null','--'}: return None
            # strip simple units and uncertainty decorations
            m=re.search(r'[-+]?\d+(?:\.\d+)?(?:[eE][-+]?\d+)?', s)
            if not m: return None
            return float(m.group(0))
        return float(x)
    except Exception:
        return None

def _v44_quantile(vals, q):
    vals=sorted([float(v) for v in vals if _v44_float(v) is not None])
    if not vals: return None
    if len(vals)==1: return vals[0]
    pos=(len(vals)-1)*q; lo=int(math.floor(pos)); hi=int(math.ceil(pos))
    if lo==hi: return vals[lo]
    return vals[lo]*(hi-pos)+vals[hi]*(pos-lo)

def _v44_rows_from_json_or_obj(obj, key_hints=None):
    hints=set(key_hints or [])
    rows=[]
    if obj is None: return rows
    if isinstance(obj, list):
        for x in obj:
            if isinstance(x, dict): rows.append(x)
            else: rows.extend(_v44_rows_from_json_or_obj(x,hints))
    elif isinstance(obj, dict):
        # If it looks like a row, keep it, but also recurse to nested row collections.
        if any(k in obj for k in ['z','redshift','vrot','vrot_km_s','radius_kpc','alpha_high','value','measurement','q2']):
            rows.append(obj)
        for k,v in obj.items():
            if k in hints or isinstance(v,(list,dict)):
                rows.extend(_v44_rows_from_json_or_obj(v,hints))
    return rows

# ---------- P36 v44: hard second-source robustness and audit table ----------

_V44_HIGHZ_SOURCE_REGISTRY = {
    'kmos3d': [
        'https://www.mpe.mpg.de/ir/KMOS3D/data',
        'https://www.mpe.mpg.de/resources/IR/KMOS3D/data/README',
    ],
    'kross': [
        'https://astro.dur.ac.uk/KROSS/data.html',
        'https://vizier.cds.unistra.fr/viz-bin/VizieR?-source=J/MNRAS/465/1454',
    ],
    'kges': [
        'https://vizier.cds.unistra.fr/viz-bin/VizieR?-source=J/MNRAS/496/3708',
    ],
    'mosdef': [
        'https://mosdef.astro.berkeley.edu/for-scientists/data-releases/',
    ],
    'sami': [
        'https://sami-survey.org/edr',
        'https://datacentral.org.au/services/schema/',
    ],
}

def _v44_highz_source_group(name):
    s=str(name or '').lower()
    if 'kross' in s: return 'KROSS'
    if 'kges' in s: return 'KGES'
    if 'mosdef' in s or 'mos' in s: return 'MOSDEF'
    if 'sami' in s: return 'SAMI'
    if 'kmos' in s or 'k3d' in s: return 'KMOS3D'
    if 'km13' in s: return 'KMOS3D'
    return None

def _v44_highz_row(r, source_file=None):
    if not isinstance(r, dict): return None
    src = r.get('source') or r.get('catalogue') or r.get('survey') or r.get('source_group') or source_file or r.get('source_file') or 'unknown'
    group = _v44_highz_source_group(src) or _v44_highz_source_group(r.get('name') or r.get('object_id')) or 'UNKNOWN'
    z=_v44_float(r.get('z') or r.get('redshift') or r.get('zspec') or r.get('z_spec') or r.get('z_best'))
    v=_v44_float(r.get('vrot_km_s') or r.get('vrot') or r.get('v_rot') or r.get('vrotation') or r.get('vmax') or r.get('v_flat') or r.get('vcirc') or r.get('Vrot') or r.get('v_2.2'))
    rad=_v44_float(r.get('radius_kpc') or r.get('r_kpc') or r.get('rkpc') or r.get('re_kpc') or r.get('rd_kpc') or r.get('size_kpc') or r.get('R_kpc') or r.get('r_turnover_kpc'))
    a=_v44_float(r.get('a_m_s2') or r.get('acceleration_m_s2') or r.get('a'))
    if a is None and v is not None and rad is not None and rad>0:
        a=(v*1000.0)**2/(rad*3.0856775814913673e19)
    unit_prov = r.get('unit_provenance') or r.get('units') or r.get('unit') or ('computed_from_vrot_km_s_radius_kpc' if (v is not None and rad is not None) else None)
    oid = r.get('object_id') or r.get('id') or r.get('galaxy') or r.get('name') or r.get('objid')
    if z is None or a is None or not unit_prov: return None
    # High-z object-level route should not be polluted by local samples.
    if z < 0.1: return None
    return {'source':str(src), 'source_group':group, 'object_id':str(oid or f'{group}_{len(str(src))}_{z:.4g}_{a:.4g}'), 'z':z, 'vrot_km_s':v, 'radius_kpc':rad, 'a_m_s2':a, 'ratio_to_local_a0':a/1.2e-10, 'unit_provenance':str(unit_prov), 'source_file':str(source_file or r.get('source_file') or '')}

def _v44_highz_table_rows_from_file(path):
    p=Path(path); raw=[]; reports=[]
    try:
        if p.suffix.lower()=='.json':
            obj=_v44_read_json(p); raw=_v44_rows_from_json_or_obj(obj, ['rows','accepted_rows','alpha_rows','measurements'])
        elif p.suffix.lower() in {'.csv','.txt','.tsv','.dat'}:
            raw=_v41_table_dicts_from_text(p, max_rows=100000)
    except Exception as e:
        reports.append({'path':str(p),'error':repr(e)})
    out=[]
    for r in raw:
        rr=_v44_highz_row(r, source_file=str(p))
        if rr: out.append(rr)
    return out, {'path':str(p),'raw_rows':len(raw),'accepted_rows':len(out),'source_guess':_v44_highz_source_group(str(p))}

def _v44_highz_collect_rows(base,args,meta):
    rows=[]; file_reports=[]; attempts=[]
    # Prior v41/v42/v43 products.
    objs=[
        (base or {}).get('p36_highz_second_source_audit_v43'),
        (base or {}).get('p36_highz_objectlevel_audit_v42'),
        (base or {}).get('p36_highz_real_object_catalogue_rows_v41'),
        _v44_read_json(_v44_outputs_dir()/'p36_highz_second_source_audit_v43.json'),
        _v44_read_json(_v44_outputs_dir()/'p36_highz_objectlevel_audit_v42.json'),
        _v44_read_json(_v44_outputs_dir()/'p36_highz_real_object_catalogue_rows_v41.json'),
    ]
    for obj in objs:
        for r in _v44_rows_from_json_or_obj(obj, ['rows','accepted_rows']):
            rr=_v44_highz_row(r, source_file=(r.get('source_file') if isinstance(r,dict) else None))
            if rr: rows.append(rr)
    # Local outputs/cache/manual products first.
    roots=[_v44_outputs_dir(), _v44_cache_dir(args), Path('data'), Path('inputs')]
    for root in roots:
        try:
            files=[p for p in root.rglob('*') if p.is_file() and p.suffix.lower() in {'.json','.csv','.txt','.tsv','.dat'} and re.search(r'(?i)(kmos|kross|kges|mosdef|sami|highz|vrot|rot|radius|kinematic)', str(p))]
        except Exception:
            files=[]
        for p in files[:300]:
            rr, rep=_v44_highz_table_rows_from_file(p); file_reports.append(rep); rows.extend(rr)
    # Public registry downloads are attempted only with --allow-large to avoid surprise traffic.
    if getattr(args,'allow_large',False):
        urls=[]
        for ulist in _V44_HIGHZ_SOURCE_REGISTRY.values(): urls.extend(ulist)
        for u in list(dict.fromkeys(urls)):
            info=download_one(u, _v44_cache_dir(args), label='highz_v44_registry', timeout=getattr(args,'timeout',SMALL_TIMEOUT), max_mb=getattr(args,'max_mb',250), allow_large=getattr(args,'allow_large',False))
            attempts.append(info)
            p=Path(info.get('path',''))
            if p.exists() and p.suffix.lower() in {'.json','.csv','.txt','.tsv','.dat'}:
                rr,rep=_v44_highz_table_rows_from_file(p); file_reports.append(rep); rows.extend(rr)
            # If HTML page downloaded, harvest direct data-ish links already implemented elsewhere is intentionally not recursive-heavy here.
            if p.exists() and p.suffix.lower() in {'.html','.htm',''}:
                try:
                    html=p.read_text(encoding='utf-8', errors='replace')[:2000000]
                    links=re.findall(r'href=["\']([^"\']+)["\']', html, flags=re.I)
                    for l in links[:120]:
                        if not re.search(r'(?i)(csv|fits|fit|txt|dat|tsv|json|vot|xml|table|catalog)', l): continue
                        if l.startswith('//'): l='https:'+l
                        elif l.startswith('/'): l='/'.join(u.split('/')[:3])+l
                        elif not l.startswith('http'): l=u.rstrip('/').rsplit('/',1)[0]+'/'+l
                        di=download_one(l, _v44_cache_dir(args), label='highz_v44_data', timeout=getattr(args,'timeout',SMALL_TIMEOUT), max_mb=getattr(args,'max_mb',250), allow_large=getattr(args,'allow_large',False))
                        attempts.append(di)
                        pp=Path(di.get('path',''))
                        if pp.exists() and pp.suffix.lower() in {'.json','.csv','.txt','.tsv','.dat'}:
                            rr,rep=_v44_highz_table_rows_from_file(pp); file_reports.append(rep); rows.extend(rr)
                except Exception as e:
                    attempts.append({'url':u,'html_parse_error':repr(e)})
    # Deduplicate by source group/object/z/a.
    seen=set(); ded=[]
    for r in rows:
        key=(r['source_group'], r['object_id'], round(r['z'],5), round(r['a_m_s2'],18))
        if key in seen: continue
        seen.add(key); ded.append(r)
    return ded, file_reports, attempts

def _v44_highz_second_source_robustness(base,args,meta):
    out=_v44_outputs_dir()/'p36_highz_second_source_robustness_v44.json'
    csv_out=_v44_outputs_dir()/'p36_highz_source_audit_v44.csv'
    rows, file_reports, attempts=_v44_highz_collect_rows(base,args,meta)
    a_local=1.2e-10
    groups=sorted(set(r['source_group'] for r in rows if r['source_group']!='UNKNOWN'))
    source_summaries=[]
    for g in sorted(set(r['source_group'] for r in rows)):
        vals=[r['a_m_s2'] for r in rows if r['source_group']==g]
        zs=[r['z'] for r in rows if r['source_group']==g]
        source_summaries.append({'source_group':g,'n_rows':len(vals),'median_a_m_s2':_v44_quantile(vals,0.5),'median_ratio_to_local':(_v44_quantile(vals,0.5) or 0)/a_local,'z_min':min(zs) if zs else None,'z_max':max(zs) if zs else None})
    vals=[r['a_m_s2'] for r in rows]
    med=_v44_quantile(vals,0.5); ratio=(med/a_local if med is not None else None)
    loo=[]; stable=True
    usable_groups=[g for g in sorted(set(r['source_group'] for r in rows)) if g!='UNKNOWN']
    for g in usable_groups:
        rest=[r['a_m_s2'] for r in rows if r['source_group']!=g and r['source_group']!='UNKNOWN']
        lm=_v44_quantile(rest,0.5); ok=bool(lm is not None and lm/a_local>1.0)
        stable=stable and ok
        loo.append({'held_out_source_group':g,'remaining_n_rows':len(rest),'median_a_m_s2':lm,'median_ratio_to_local':(lm/a_local if lm is not None else None),'pass':ok})
    bs=[]
    if len(usable_groups)>=2:
        import random as _random_v44
        rng=_random_v44.Random(44036)
        by={g:[r['a_m_s2'] for r in rows if r['source_group']==g] for g in usable_groups}
        for _ in range(2000):
            drawn=[]
            for __ in usable_groups:
                g=rng.choice(usable_groups); drawn.extend(by.get(g,[]))
            if drawn: bs.append((_v44_quantile(drawn,0.5) or 0)/a_local)
    ci16=_v44_quantile(bs,0.16); ci50=_v44_quantile(bs,0.50); ci84=_v44_quantile(bs,0.84)
    gate=_v32_gate(
        object_rows_ge_30=bool(len(rows)>=30),
        two_sources=bool(len(usable_groups)>=2),
        units_visible=bool(rows and all(r.get('unit_provenance') for r in rows[:min(len(rows),1000)])),
        median_above_local=bool(ratio is not None and ratio>1.0),
        leave_one_source_stable=bool(stable and len(usable_groups)>=2),
        source_bootstrap_ratio_ci16_above_1=bool(ci16 is not None and ci16>1.0),
        second_source_robustness_v44=True,
    )
    # Write compact CSV audit.
    try:
        import csv
        with csv_out.open('w', newline='', encoding='utf-8') as f:
            w=csv.DictWriter(f, fieldnames=['source_group','source','object_id','z','vrot_km_s','radius_kpc','a_m_s2','ratio_to_local_a0','unit_provenance','source_file'])
            w.writeheader(); w.writerows(rows[:20000])
    except Exception as e:
        csv_out = f'csv_write_error:{e!r}'
    report={'version':'v44','n_rows':len(rows),'n_source_groups':len(usable_groups),'source_groups':usable_groups,'median_a_m_s2':med,'median_ratio_to_local':ratio,'source_summaries':source_summaries,'leave_one_source':loo,'source_bootstrap_ratio_ci16':ci16,'source_bootstrap_ratio_ci50':ci50,'source_bootstrap_ratio_ci84':ci84,'audit_csv_path':str(csv_out),'download_attempts':attempts[:250],'file_reports':file_reports[:250],'rows':rows[:5000],'highz_objectlevel_confirm_gate_v44':gate,'claim_policy':'P36 high-z v44 promotion requires >=30 object rows from >=2 independent source groups, visible Vrot/R/z units, median above local a0, leave-one-source stability, and source-bootstrap CI16>1.'}
    _v44_write_json(out,report); report['path']=str(out)
    return report

