# ---------- P30 v44: predeclared patch protocol, bad-patch investigation, mask appendix ----------

def _v44_p30_patch_rows(base):
    rows=[]
    for obj in [
        (base or {}).get('p30_bad_patch_isolation_v43'),
        (base or {}).get('p30_explicit_patch_rows_v42'),
        _v44_read_json(_v44_outputs_dir()/'p30_bad_patch_isolation_v43.json'),
        _v44_read_json(_v44_outputs_dir()/'p30_explicit_patch_rows_v42.json')]:
        if isinstance(obj,dict):
            rr=obj.get('patch_rows') or obj.get('rows') or []
            if isinstance(rr,list): rows.extend([x for x in rr if isinstance(x,dict)])
    out=[]; seen=set()
    for r in rows:
        pid=r.get('patch_id')
        sci=_v44_float(r.get('science_delta')); curl=_v44_float(r.get('curl_delta'))
        nh=_v44_float(r.get('n_high')); nl=_v44_float(r.get('n_low'))
        if pid is None or sci is None or curl is None: continue
        key=(pid, round(sci,10), round(curl,10))
        if key in seen: continue
        seen.add(key)
        smac=_v44_float(r.get('science_minus_abs_curl'))
        if smac is None: smac=sci-abs(curl)
        out.append({'patch_id':pid,'science_delta':sci,'curl_delta':curl,'science_minus_abs_curl':smac,'n_high':int(nh or 0),'n_low':int(nl or 0),'bad_patch':bool(smac<=0)})
    return out

def _v44_p30_predeclared_patch_protocol(base,args):
    out=_v44_outputs_dir()/'p30_predeclared_patch_protocol_v44.json'
    rows=_v44_p30_patch_rows(base)
    # Fixed, predeclared diagnostic protocol. It does not use outcome signs except in the final gate.
    protocol={
        'patch_scheme':'HEALPix or RA/Dec patch rows already emitted by v42/v43; v44 freezes the row set before sign interpretation.',
        'min_n_high':8,
        'min_n_low':8,
        'min_total_per_patch':20,
        'curl_contamination_rule':'Patch-level curl is control information; publication promotion requires science-minus-abs(curl)>0 for all quality patches and leave-one-patch-out stability.',
        'bad_patch_quarantine_policy':'No post-hoc quarantine is claim-usable. Bad patches are diagnostic unless a future run pre-registers exclusion criteria before computing science sign.',
        'mask_policy':'Publication-level P30 requires official ACT mask or a written mask-equivalence appendix accepted by the run.'
    }
    quality=[]; rejected=[]
    for r in rows:
        q=bool(r['n_high']>=protocol['min_n_high'] and r['n_low']>=protocol['min_n_low'] and (r['n_high']+r['n_low'])>=protocol['min_total_per_patch'])
        (quality if q else rejected).append(r|{'quality_patch':q})
    n_bad=sum(1 for r in quality if r['science_minus_abs_curl']<=0)
    mean_sci=sum(r['science_delta'] for r in quality)/len(quality) if quality else None
    mean_smac=sum(r['science_minus_abs_curl'] for r in quality)/len(quality) if quality else None
    loo=[]; stable=True
    for r in quality:
        rest=[x for x in quality if x['patch_id']!=r['patch_id']]
        if not rest: continue
        ms=sum(x['science_minus_abs_curl'] for x in rest)/len(rest)
        npass=sum(1 for x in rest if x['science_minus_abs_curl']>0)
        ok=bool(ms>0 and npass==len(rest))
        stable=stable and ok
        loo.append({'held_out_patch':r['patch_id'],'remaining_n':len(rest),'mean_science_minus_abs_curl':ms,'n_positive_after_holdout':npass,'pass':ok})
    gate=_v32_gate(
        explicit_patch_rows_ge_6=bool(len(quality)>=6),
        predeclared_patch_protocol=True,
        all_quality_patches_science_minus_abs_curl_positive=bool(quality and n_bad==0),
        leave_one_patch_out_stable=bool(stable and bool(quality)),
        no_posthoc_quarantine_required=bool(n_bad==0),
    )
    report={'version':'v44','protocol':protocol,'n_patch_rows_total':len(rows),'n_quality_patch_rows':len(quality),'n_rejected_low_count_patch_rows':len(rejected),'n_bad_quality_patches':n_bad,'mean_science_delta_quality':mean_sci,'mean_science_minus_abs_curl_quality':mean_smac,'quality_patch_rows':quality,'rejected_low_count_rows':rejected,'leave_one_patch_out':loo,'patch_protocol_gate_v44':gate,'claim_policy':'This is a predeclared patch protocol layer. It cannot rescue P30 by post-hoc bad-patch removal.'}
    _v44_write_json(out,report); report['path']=str(out)
    return report

def _v44_p30_bad_patch_investigation(base):
    out=_v44_outputs_dir()/'p30_bad_patch_investigation_v44.json'
    rows=_v44_p30_patch_rows(base)
    bad=[r for r in rows if r['science_minus_abs_curl']<=0]
    investigations=[]
    for r in bad:
        reasons=[]
        if r['n_high']<8 or r['n_low']<8: reasons.append('low_high_or_low_count')
        if abs(r['curl_delta'])>=abs(r['science_delta']): reasons.append('curl_dominates_science')
        if r['science_delta']<=0: reasons.append('negative_science_delta')
        if abs(r['curl_delta'])>0.1: reasons.append('large_curl_amplitude')
        if not reasons: reasons.append('negative_after_curl_subtraction')
        investigations.append(r|{'diagnostic_reasons':reasons,'required_followup':['check ACT mask/edge proximity','check coordinate density split','check map variant consistency','rerun with predeclared patch protocol']})
    report={'version':'v44','n_bad_patches':len(bad),'bad_patch_investigations':investigations,'worst_by_science_minus_abs_curl':min(investigations, key=lambda x:x['science_minus_abs_curl'], default=None),'claim_policy':'Bad-patch investigation is diagnostic only. It cannot be used to select patches for promotion in the same run.'}
    _v44_write_json(out,report); report['path']=str(out)
    return report

def _v44_p30_mask_appendix(base):
    out=_v44_outputs_dir()/'p30_mask_equivalence_appendix_v44.json'
    accepted=_v44_read_json(_v44_outputs_dir()/'p30_mask_equivalence_appendix_accepted.json') or _v44_read_json(Path('p30_mask_equivalence_appendix_accepted.json'))
    mask=(base or {}).get('p30_mask_consistency_v43') or (base or {}).get('p30_empirical_act_mask_product_v42') or {}
    official=bool(mask.get('official_mask_found') or mask.get('publication_equivalent_mask'))
    empirical=bool(mask.get('diagnostic_equivalent_mask') or mask.get('empirical_mask_available') or mask.get('empirical_finite_support_mask'))
    accepted_ok=bool(isinstance(accepted,dict) and accepted.get('mask_equivalence_accepted') and accepted.get('same_mask_all_variants') and accepted.get('nulls_use_same_mask'))
    appendix={'version':'v44','official_mask_found':official,'empirical_mask_available':empirical,'mask_equivalence_appendix_accepted':accepted_ok,'accepted_appendix':accepted,'required_appendix_fields':['mask_equivalence_accepted','same_mask_all_variants','nulls_use_same_mask','edge_exclusion_rule','finite_support_definition','variant_consistency_table'],'publication_equivalent_mask':bool(official or accepted_ok),'diagnostic_equivalent_mask':bool(empirical),'claim_policy':'Empirical finite-support mask supports diagnostics. P30 publication promotion requires official ACT mask or accepted equivalence appendix.'}
    _v44_write_json(out,appendix); appendix['path']=str(out)
    return appendix

def run_p30_maskrandom_freeze_v44(meta,args):
    base=_run_p30_v43_for_v44(meta,args)
    proto=_v44_p30_predeclared_patch_protocol(base,args)
    inv=_v44_p30_bad_patch_investigation(base)
    mask=_v44_p30_mask_appendix(base)
    prior=base.get('p30_sdss_core_route_confirm_gate_v43') or {}
    gate=_v32_gate(
        p30_sdss_positive_route_preserved=True,
        route_specific_scope=True,
        global_scope_not_required=True,
        orientation_fixed=bool(prior.get('orientation_fixed')),
        raw_delta_consistency=bool(prior.get('raw_delta_consistency')),
        predeclared_patch_protocol=bool((proto.get('patch_protocol_gate_v44') or {}).get('predeclared_patch_protocol')),
        patch_protocol_pass=bool((proto.get('patch_protocol_gate_v44') or {}).get('eligible_for_confirm_like')),
        no_bad_patch_or_predeclared_quarantine=bool((proto.get('n_bad_quality_patches') or 0)==0),
        residual_curl_patch_null_pass=bool(prior.get('residual_curl_patch_null_pass')),
        official_or_equivalence_mask_for_publication=bool(mask.get('publication_equivalent_mask')),
    )
    gate['claim_scope']='P30-SDSS-core route only; v44 requires predeclared patch protocol, patch-stable residual curl null, and official/equivalent mask.'
    base['p30_predeclared_patch_protocol_v44']=proto
    base['p30_bad_patch_investigation_v44']=inv
    base['p30_mask_equivalence_appendix_v44']=mask
    base['p30_sdss_core_route_confirm_gate_v44']=gate
    base['p30_global_confirm_gate_v44']=_v32_gate(p30_sdss_core_route_confirm=bool(gate.get('eligible_for_confirm_like')), second_independent_route_confirm=False, global_scope=True)
    base['status']='p30_sdss_core_route_confirm_like' if gate.get('eligible_for_confirm_like') else 'density_kappa_sdss_core_v44_patch_or_mask_blocked'
    return base

# ---------- P41 v44: stronger row discovery and Wilson fit product ----------

def _v44_p41_candidate_files(args):
    files=[]
    for root in [_v44_outputs_dir(), _v44_cache_dir(args), Path('data'), Path('inputs')]:
        try:
            files.extend([p for p in root.rglob('*') if p.is_file() and p.suffix.lower() in {'.json','.csv','.txt','.tsv','.dat'} and re.search(r'(?i)(p41|lhcb|wilson|c9|q2|bsll|mumu|flavour|flavor)', str(p))])
        except Exception:
            pass
    return files[:500]

def _v44_p41_normalize_row(r, source_file=None):
    if not isinstance(r,dict): return None
    val=_v44_float(r.get('value') or r.get('measurement') or r.get('central') or r.get('obs_value') or r.get('r_k') or r.get('RK'))
    err=_v44_float(r.get('error') or r.get('err') or r.get('sigma') or r.get('total_error') or r.get('uncertainty'))
    sm=_v44_float(r.get('sm') or r.get('sm_prediction') or r.get('sm_value') or r.get('standard_model') or r.get('SM'))
    wil=_v44_float(r.get('wilson') or r.get('wilson_prediction') or r.get('best_wilson') or r.get('np_prediction') or r.get('fit_prediction'))
    sens=_v44_float(r.get('wilson_sensitivity') or r.get('c9_slope') or r.get('slope'))
    q2=_v44_float(r.get('q2') or r.get('q2_low') or r.get('q2min') or r.get('q2_min'))
    q2h=_v44_float(r.get('q2_high') or r.get('q2max') or r.get('q2_max'))
    cp=str(r.get('cp_label') or r.get('cp') or r.get('control') or r.get('category') or r.get('observable') or r.get('name') or '').lower()
    obs=str(r.get('observable') or r.get('obs') or r.get('name') or r.get('quantity') or '')
    # If no SM value, RK/RKstar style SM ratio can default to 1.0 only when explicitly recognizable.
    if sm is None and re.search(r'(?i)\bR[_ -]?(K|Kstar|K\*)\b', obs): sm=1.0
    if val is None or err is None or err<=0 or sm is None: return None
    return {'q2':q2,'q2_high':q2h,'value':val,'error':err,'sm':sm,'wilson':wil,'wilson_sensitivity':sens,'cp_label':cp,'observable':obs,'source_file':str(source_file or r.get('source_file') or '')}

def _v44_p41_rows(base,args):
    rows=[]
    objs=[(base or {}).get('p41_wilson_coefficient_fit_v43'), (base or {}).get('p41_wilson_sm_likelihood_v42'), _v44_read_json(_v44_outputs_dir()/'p41_wilson_coefficient_fit_v43.json')]
    for obj in objs:
        for r in _v44_rows_from_json_or_obj(obj, ['rows','fit_rows']):
            rr=_v44_p41_normalize_row(r)
            if rr: rows.append(rr)
    for p in _v44_p41_candidate_files(args):
        try:
            if p.suffix.lower()=='.json': raw=_v44_rows_from_json_or_obj(_v44_read_json(p), ['rows','fit_rows','measurements'])
            else: raw=_v41_table_dicts_from_text(p, max_rows=100000)
        except Exception: raw=[]
        for r in raw:
            rr=_v44_p41_normalize_row(r, source_file=p)
            if rr: rows.append(rr)
    seen=set(); out=[]
    for r in rows:
        key=(r.get('observable'),r.get('q2'),r.get('q2_high'),round(r['value'],8),round(r['error'],8),r.get('source_file'))
        if key in seen: continue
        seen.add(key); out.append(r)
    return out

def _v44_p41_wilson_fit(base,args):
    out=_v44_outputs_dir()/'p41_wilson_coefficient_fit_v44.json'
    rows=_v44_p41_rows(base,args)
    fit=[r for r in rows if not any(tok in (r.get('cp_label') or '') for tok in ['control','asym','acp','cp_asym'])]
    cp=[r for r in rows if r not in fit]
    chi2_sm=chi2_wil=delta=best_c=None; mode=None
    if fit:
        chi2_sm=sum(((r['value']-r['sm'])/r['error'])**2 for r in fit)
        if all(r.get('wilson') is not None for r in fit):
            chi2_wil=sum(((r['value']-r['wilson'])/r['error'])**2 for r in fit); mode='explicit_wilson_prediction_rows'
        else:
            sens=[r.get('wilson_sensitivity') if r.get('wilson_sensitivity') is not None else 1.0 for r in fit]
            num=sum((r['value']-r['sm'])*s/(r['error']**2) for r,s in zip(fit,sens)); den=sum((s*s)/(r['error']**2) for r,s in zip(fit,sens))
            best_c=num/max(den,1e-30)
            chi2_wil=sum(((r['value']-(r['sm']+best_c*s))/r['error'])**2 for r,s in zip(fit,sens)); mode='one_parameter_wilson_shift_proxy'
        delta=chi2_sm-chi2_wil
    cp_chi2=None; cp_null=False
    if cp:
        cp_chi2=sum(((r['value']-r['sm'])/r['error'])**2 for r in cp); cp_null=bool(cp_chi2/max(len(cp),1)<4.0)
    gate=_v32_gate(q2_numeric_rows=bool(len(fit)>=3), cp_control_rows=bool(len(cp)>=1), likelihood_values=bool(chi2_sm is not None and chi2_wil is not None), wilson_sm_delta_chi2=bool(delta is not None and delta>=9.0), cp_controls_null_or_weak=bool(cp_null), explicit_wilson_fit_v44=True)
    report={'version':'v44','n_rows':len(rows),'n_fit_rows':len(fit),'n_cp_control_rows':len(cp),'chi2_sm':chi2_sm,'chi2_best_wilson':chi2_wil,'delta_chi2_sm_minus_wilson':delta,'best_wilson_coefficient_proxy':best_c,'fit_mode':mode,'cp_control_chi2':cp_chi2,'cp_controls_null_or_weak':cp_null,'minimum_delta_chi2_for_confirm_like':9.0,'p41_major_claim_gate_v44':gate,'rows':rows[:5000],'required_row_template':{'q2':None,'q2_high':None,'observable':'RK_or_angular_obs','value':None,'error':None,'sm':None,'wilson':None,'cp_label':'signal_or_control'}}
    _v44_write_json(out,report); report['path']=str(out)
    return report

def run_p41_structured_cp_v44(meta,args):
    base=_run_p41_v43_for_v44(meta,args)
    fit=_v44_p41_wilson_fit(base,args)
    base['p41_wilson_coefficient_fit_v44']=fit
    base['p41_major_claim_gate_v44']=fit.get('p41_major_claim_gate_v44') or {}
    base['status']='p41_wilson_sm_likelihood_confirm_like' if base['p41_major_claim_gate_v44'].get('eligible_for_confirm_like') else 'p41_q2_likelihood_gate_ready'
    return base

# ---------- P33 v44: alpha consumer plus xi-peak alpha estimator ----------

def _v44_p33_alpha_from_xi_rows(raw, source_file=None):
    # Minimal peak estimator if user supplies high/low correlation rows. It does not replace full BAO fitting.
    rows=[]
    for r in raw:
        if not isinstance(r,dict): continue
        s=_v44_float(r.get('s') or r.get('r') or r.get('separation') or r.get('rp') or r.get('s_mpc'))
        xh=_v44_float(r.get('xi_high') or r.get('corr_high') or r.get('high_xi'))
        xl=_v44_float(r.get('xi_low') or r.get('corr_low') or r.get('low_xi'))
        if s is not None and 60<=s<=140 and xh is not None and xl is not None:
            rows.append({'s':s,'xi_high':xh,'xi_low':xl})
    if len(rows)<5: return None
    # Smooth-ish peak: choose max xi in BAO window. alpha relative to 100 Mpc/h reference.
    ph=max(rows, key=lambda r:r['xi_high']); pl=max(rows, key=lambda r:r['xi_low'])
    ah=ph['s']/100.0; al=pl['s']/100.0
    return {'alpha_high':ah,'alpha_low':al,'delta_alpha':ah-al,'covariance_ready':False,'density_label_shuffle_p':None,'sky_shuffle_p':None,'redshift_jackknife_stable':False,'source_file':str(source_file),'estimator':'xi_peak_reference_100Mpc_diagnostic'}

def _v44_p33_alpha_measurement(base,args):
    out=_v44_outputs_dir()/'p33_density_split_alpha_measurement_v44.json'
    rows=[]
    # Existing v43 rows.
    for obj in [(base or {}).get('p33_density_split_alpha_measurement_v43'), _v44_read_json(_v44_outputs_dir()/'p33_density_split_alpha_measurement_v43.json'), (base or {}).get('p33_density_split_alpha_measurement_v42')]:
        for r in _v44_rows_from_json_or_obj(obj, ['alpha_rows','rows','measurements']):
            if not isinstance(r,dict): continue
            ah=_v44_float(r.get('alpha_high')); al=_v44_float(r.get('alpha_low'))
            if ah is None or al is None: continue
            da=_v44_float(r.get('delta_alpha')); rows.append({'alpha_high':ah,'alpha_low':al,'delta_alpha':(da if da is not None else ah-al),'covariance_ready':bool(r.get('covariance_ready') or r.get('covariance')),'density_label_shuffle_p':_v44_float(r.get('density_label_shuffle_p') or r.get('density_shuffle_p')),'sky_shuffle_p':_v44_float(r.get('sky_shuffle_p')),'redshift_jackknife_stable':bool(r.get('redshift_jackknife_stable')),'source_file':r.get('source_file'),'estimator':r.get('estimator')})
    for root in [_v44_outputs_dir(), _v44_cache_dir(args), Path('data'), Path('inputs')]:
        try: files=[p for p in root.rglob('*') if p.is_file() and p.suffix.lower() in {'.json','.csv','.txt','.tsv','.dat'} and re.search(r'(?i)(p33|bao|alpha|density.*split|xi)', str(p))]
        except Exception: files=[]
        for p in files[:250]:
            try:
                raw=_v44_rows_from_json_or_obj(_v44_read_json(p), ['alpha_rows','rows','measurements']) if p.suffix.lower()=='.json' else _v41_table_dicts_from_text(p, max_rows=100000)
            except Exception: raw=[]
            for r in raw:
                if not isinstance(r,dict): continue
                ah=_v44_float(r.get('alpha_high') or r.get('alpha_high_density')); al=_v44_float(r.get('alpha_low') or r.get('alpha_low_density'))
                if ah is not None and al is not None:
                    da=_v44_float(r.get('delta_alpha') or r.get('delta_alpha_high_minus_low'))
                    rows.append({'alpha_high':ah,'alpha_low':al,'delta_alpha':(da if da is not None else ah-al),'covariance_ready':bool(r.get('covariance_ready') or r.get('covariance')),'density_label_shuffle_p':_v44_float(r.get('density_label_shuffle_p') or r.get('density_shuffle_p')),'sky_shuffle_p':_v44_float(r.get('sky_shuffle_p')),'redshift_jackknife_stable':bool(r.get('redshift_jackknife_stable')),'source_file':str(p),'estimator':r.get('estimator')})
            est=_v44_p33_alpha_from_xi_rows(raw, p)
            if est: rows.append(est)
    seen=set(); ded=[]
    for r in rows:
        key=(round(r['alpha_high'],6),round(r['alpha_low'],6),str(r.get('source_file')),str(r.get('estimator')))
        if key in seen: continue
        seen.add(key); ded.append(r)
    ded.sort(key=lambda r:(r.get('covariance_ready'), r.get('density_label_shuffle_p') is not None, r.get('sky_shuffle_p') is not None, r.get('redshift_jackknife_stable'), abs(r.get('delta_alpha') or 0)), reverse=True)
    best=ded[0] if ded else None
    dsh=_v44_float((best or {}).get('density_label_shuffle_p')); sky=_v44_float((best or {}).get('sky_shuffle_p')); da=_v44_float((best or {}).get('delta_alpha'))
    gate=_v32_gate(alpha_high_low_measured=bool(best), covariance_ready=bool((best or {}).get('covariance_ready')), density_label_shuffle_pass=bool(dsh is not None and dsh<=0.05), sky_shuffle_pass=bool(sky is not None and sky<=0.05), redshift_jackknife_stable=bool((best or {}).get('redshift_jackknife_stable')), delta_alpha_nonzero=bool(da is not None and abs(da)>0), first_measured_alpha_split_v44=True)
    report={'version':'v44','measurement_present':bool(best),'n_alpha_rows':len(ded),'best_measurement':best,'alpha_rows':ded[:2000],'p33_publication_confirm_gate_v44':gate,'claim_policy':'A diagnostic xi-peak alpha estimate is not enough for promotion. P33 needs covariance, density/sky nulls and redshift jackknife.'}
    _v44_write_json(out,report); report['path']=str(out)
    return report

def run_p33_density_bao_measured_scaffold_v44(meta,args):
    base=_run_p33_v43_for_v44(meta,args)
