# ---------- v44 dashboard ----------

def run_dashboard_v44(meta,args):
    base=_run_dashboard_v43_for_v44(meta,args)
    outputs=_v44_outputs_dir(); rows=[]
    for p in sorted(outputs.glob('test*.json')):
        obj=_v44_read_json(p)
        if isinstance(obj,dict): rows.append(obj)
    instr=[]; blocked=[]; pub=[]; targets=[]
    confirm_statuses={'robust_confirm_like','void_morphology_publication_grade_confirm_like','p30_sdss_core_route_confirm_like','p41_wilson_sm_likelihood_confirm_like','p33_density_bao_alpha_split_confirm_like','p32_ringdown_strain_confirm_like_candidate'}
    for r in rows:
        st=str(r.get('status',''))
        keys=[k for k in r if k.endswith('_v44') or '_v44_' in k]
        if keys: instr.append({'test_id':r.get('test_id'),'prediction_id':r.get('prediction_id'),'status':st,'v44_keys':sorted(keys)})
        if st in confirm_statuses or st=='highz_a0_objectlevel_publication_confirm_like':
            # high-z status is allowed only if v44 gate is present and eligible.
            if st=='highz_a0_objectlevel_publication_confirm_like' and not ((r.get('highz_objectlevel_confirm_gate_v44') or {}).get('eligible_for_confirm_like')):
                pass
            else:
                pub.append({'test_id':r.get('test_id'),'prediction_id':r.get('prediction_id'),'status':st})
        for k,v in r.items():
            if isinstance(v,dict) and k.endswith('_gate_v44') and not v.get('eligible_for_confirm_like', True):
                blocked.append({'test_id':r.get('test_id'),'prediction_id':r.get('prediction_id'),'gate':k,'missing':v.get('missing')})
        if any(x in (str(r.get('prediction_id','')).lower()+st.lower()) for x in ['p30','p36','p41','p33','p32']):
            targets.append({'test_id':r.get('test_id'),'prediction_id':r.get('prediction_id'),'status':st})
    base['dashboard_v44']={'n_v44_instrumented_tests':len(instr),'v44_instrumented_tests':instr[:250],'publication_grade_confirm_like':pub,'blocked_v44_gates':blocked,'priority_confirm_targets':targets,'claim_policy':'v44 strict separation: P36 needs second-source source-bootstrap; P30 needs predeclared patch+mask; P41/P33/P32 need measured likelihood/alpha/strain products.'}
    return _v60_scrub_manual_fill_references(base)

