def _v46_outputs_dir():
    p = Path.cwd() / 'outputs'
    p.mkdir(exist_ok=True)
    return p


def _v46_cache_dir(args=None):
    p = Path(getattr(args, 'cache_dir', DEFAULT_CACHE) if args is not None else DEFAULT_CACHE)
    p.mkdir(exist_ok=True)
    return p


def _v46_write_json(path, obj):
    path = Path(path); path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(obj, indent=2, sort_keys=True, ensure_ascii=False, default=json_default, allow_nan=False), encoding='utf-8')


def _v46_read_json(path):
    try:
        p = Path(path)
        if p.exists():
            return json.loads(p.read_text(encoding='utf-8', errors='replace'))
    except Exception:
        return None
    return None


def _v46_float(x):
    try:
        if x is None or x == '':
            return None
        f = float(x)
        return f if math.isfinite(f) else None
    except Exception:
        return None


def _v46_quantile(vals, q):
    vals = sorted([float(v) for v in vals if _v46_float(v) is not None])
    if not vals:
        return None
    if len(vals) == 1:
        return vals[0]
    pos = q * (len(vals) - 1)
    lo = int(math.floor(pos)); hi = int(math.ceil(pos)); frac = pos - lo
    return vals[lo] * (1-frac) + vals[hi] * frac


def _v46_sha16(obj):
    try:
        s = json.dumps(obj, sort_keys=True, ensure_ascii=False, default=json_default)
    except Exception:
        s = str(obj)
    return hashlib.sha256(s.encode('utf-8', errors='replace')).hexdigest()[:16]


def _v46_rows(obj, hints=None):
    hints = hints or ['rows','accepted_rows','measurements','alpha_rows','candidate_rows','patch_rows','source_rows']
    out = []
    if obj is None:
        return out
    if isinstance(obj, list):
        for x in obj:
            out.extend(_v46_rows(x, hints))
    elif isinstance(obj, dict):
        if any(k in obj for k in ['q2','alpha_high','patch_id','vrot_km_s','radius_kpc','a_m_s2','object_id']):
            out.append(obj)
        for h in hints:
            if h in obj:
                out.extend(_v46_rows(obj.get(h), hints))
        # do not recursively walk the entire p30 manifest rows by default; it can be very large.
        if not any(h in obj for h in hints):
            for v in obj.values():
                if isinstance(v, (list, dict)):
                    out.extend(_v46_rows(v, hints))
    return out

# ---------- P36 v46: publication audit appendix + blinded unit stress ----------

def _v46_p36_all_rows(base):
    candidates = [
        (base or {}).get('p36_publication_audit_appendix_v45'),
        (base or {}).get('p36_highz_second_source_robustness_v44'),
        (base or {}).get('p36_highz_second_source_audit_v43'),
        _v46_read_json(_v46_outputs_dir()/'p36_publication_audit_appendix_v45.json'),
        _v46_read_json(_v46_outputs_dir()/'p36_highz_second_source_robustness_v44.json'),
        _v46_read_json(_v46_outputs_dir()/'p36_highz_objectlevel_audit_v42.json'),
    ]
    rows=[]
    for obj in candidates:
        rows.extend(_v46_rows(obj, ['rows','accepted_rows','source_rows']))
    clean=[]
    for r in rows:
        if not isinstance(r,dict):
            continue
        z = _v46_float(r.get('z') or r.get('redshift') or r.get('zspec') or r.get('z_spec'))
        v = _v46_float(r.get('vrot_km_s') or r.get('vrot') or r.get('Vrot') or r.get('v_rot') or r.get('vmax') or r.get('v_2.2'))
        rad = _v46_float(r.get('radius_kpc') or r.get('r_kpc') or r.get('R_kpc') or r.get('radius') or r.get('re_kpc'))
        a = _v46_float(r.get('a_m_s2') or r.get('acceleration_m_s2') or r.get('a'))
        if a is None and v is not None and rad is not None and rad > 0:
            a = (v*1000.0)**2 / (rad*3.085677581491367e19)
        if z is not None and v is not None and rad is not None and a is not None and z > 0 and rad > 0:
            src = str(r.get('source') or r.get('catalogue') or r.get('source_group') or r.get('survey') or r.get('source_file') or 'unknown')
            clean.append({
                'source': src,
                'object_id': str(r.get('object_id') or r.get('id') or r.get('name') or len(clean)),
                'z': z,
                'vrot_km_s': v,
                'radius_kpc': rad,
                'a_m_s2': a,
                'ratio_to_local_a0': a/1.2e-10,
                'unit_provenance': str(r.get('unit_provenance') or r.get('units') or 'vrot_km_s+radius_kpc'),
                'source_file': r.get('source_file')
            })
    # Deduplicate on source/object/z/v/r to prevent previous audit rows from multiplying counts.
    seen=set(); dedup=[]
    for r in clean:
        key=(r['source'], r['object_id'], round(r['z'],6), round(r['vrot_km_s'],6), round(r['radius_kpc'],6))
        if key not in seen:
            seen.add(key); dedup.append(r)
    return dedup


def _v46_p36_audit(base,args):
    rows = _v46_p36_all_rows(base)
    out = _v46_outputs_dir()/'p36_publication_audit_appendix_v46.json'
    csv_out = _v46_outputs_dir()/'p36_publication_audit_appendix_v46.csv'
    groups={}
    for r in rows:
        groups.setdefault(r['source'], []).append(r)
    loo=[]; bysrc=[]
    for src,gs in sorted(groups.items()):
        med=_v46_quantile([x['a_m_s2'] for x in gs],0.5)
        rest=[x['a_m_s2'] for s,gg in groups.items() if s != src for x in gg]
        rm=_v46_quantile(rest,0.5)
        bysrc.append({'source':src,'n_rows':len(gs),'median_a_m_s2':med,'median_ratio_to_local_a0':(med/1.2e-10 if med else None)})
        loo.append({'held_out_source':src,'remaining_n':len(rest),'remaining_median_a_m_s2':rm,'remaining_ratio_to_local_a0':(rm/1.2e-10 if rm else None),'pass': bool(rm and rm > 1.2e-10)})
    bs=[]
    if groups:
        import random as _random_v46
        rng=_random_v46.Random(46036)
        srcs=list(groups)
        for _ in range(512):
            draw=[]
            for s in [rng.choice(srcs) for __ in srcs]:
                draw.extend([r['a_m_s2'] for r in groups[s]])
            if draw:
                bs.append((_v46_quantile(draw,0.5) or 0)/1.2e-10)
    ci16=_v46_quantile(bs,0.16); ci50=_v46_quantile(bs,0.5); ci84=_v46_quantile(bs,0.84)
    # Blinded unit stress: recompute all rows from v and r, compare to stored a.
    rel=[]
    for r in rows:
        recalc=(r['vrot_km_s']*1000.0)**2/(r['radius_kpc']*3.085677581491367e19)
        if r['a_m_s2']:
            rel.append(abs(recalc-r['a_m_s2'])/max(abs(r['a_m_s2']),1e-99))
    max_rel=max(rel) if rel else None
    unit_stress_pass=bool(max_rel is not None and max_rel < 1e-6)
    gate=_v32_gate(object_rows_ge_30=len(rows)>=30, two_sources=len(groups)>=2, units_visible=all(bool(r.get('unit_provenance')) for r in rows) if rows else False, median_above_local=bool(rows and (_v46_quantile([r['a_m_s2'] for r in rows],0.5) or 0) > 1.2e-10), leave_one_source_stable=bool(loo and all(x.get('pass') for x in loo)), source_bootstrap_ratio_ci16_above_1=bool(ci16 is not None and ci16>1.0), blinded_unit_conversion_stress_pass=unit_stress_pass, publication_audit_appendix_v46=True)
    try:
        with open(csv_out,'w',newline='',encoding='utf-8') as f:
            wr=csv.DictWriter(f,fieldnames=['source','object_id','z','vrot_km_s','radius_kpc','a_m_s2','ratio_to_local_a0','unit_provenance','source_file'])
            wr.writeheader(); wr.writerows(rows)
    except Exception:
        pass
    rep={'version':'v46','n_rows':len(rows),'n_source_groups':len(groups),'source_summaries':bysrc,'median_ratio_to_local_a0':((_v46_quantile([r['a_m_s2'] for r in rows],0.5) or 0)/1.2e-10 if rows else None),'leave_one_source':loo,'source_bootstrap_ratio_ci16':ci16,'source_bootstrap_ratio_ci50':ci50,'source_bootstrap_ratio_ci84':ci84,'unit_stress_max_relative_error':max_rel,'unit_stress_pass':unit_stress_pass,'highz_publication_gate_v46':gate,'audit_csv_path':str(csv_out),'rows':rows[:10000],'claim_policy':'P36 high-z is publication-grade only if audit rows are real object rows with >=2 sources, source-bootstrap CI16>1, leave-one-source stability, and blinded unit conversion stress passing.'}
    _v46_write_json(out,rep); rep['path']=str(out); return rep


def run_highz_unit_field_table_v46(meta,args):
    base = _run_highz_v45_for_v46(meta,args) if callable(_run_highz_v45_for_v46) else base_result(meta,'broken',error='missing previous highz runner')
    audit=_v46_p36_audit(base,args)
    base['p36_publication_audit_appendix_v46']=audit
    base['highz_publication_gate_v46']=audit.get('highz_publication_gate_v46') or {}
    base['status']='highz_a0_objectlevel_publication_confirm_like' if base['highz_publication_gate_v46'].get('eligible_for_confirm_like') else 'highz_a0_objectlevel_second_source_needed'
    return base

# ---------- P30 v46: accepted/rejected mask equivalence + frozen fresh patch rerun ----------

def _v46_p30_patch_rows(base):
    rows=[]
    objs=[
        (base or {}).get('p30_predeclared_patch_protocol_v45'),
        (base or {}).get('p30_bad_patch_isolation_v43'),
        _v46_read_json(_v46_outputs_dir()/'p30_predeclared_patch_protocol_v45.json'),
        _v46_read_json(_v46_outputs_dir()/'p30_bad_patch_isolation_v43.json'),
        _v46_read_json(_v46_outputs_dir()/'p30_explicit_patch_rows_v42.json'),
    ]
    for obj in objs:
        for r in _v46_rows(obj, ['quality_patch_rows','patch_rows','rows']):
            if not isinstance(r,dict) or r.get('patch_id') is None:
                continue
            sci=_v46_float(r.get('science_delta')); curl=_v46_float(r.get('curl_delta'))
            nh=_v46_float(r.get('n_high')); nl=_v46_float(r.get('n_low'))
            smac=_v46_float(r.get('science_minus_abs_curl'))
            if smac is None and sci is not None and curl is not None:
                smac=sci-abs(curl)
            if sci is not None and curl is not None:
                rows.append({'patch_id':r.get('patch_id'),'science_delta':sci,'curl_delta':curl,'science_minus_abs_curl':smac,'n_high':nh,'n_low':nl})
    # Dedup by patch id, prefer rows with larger counts.
    best={}
    for r in rows:
        key=str(r.get('patch_id'))
        score=(r.get('n_high') or 0)+(r.get('n_low') or 0)
        if key not in best or score>((best[key].get('n_high') or 0)+(best[key].get('n_low') or 0)):
            best[key]=r
    return list(best.values())


def _v46_p30_mask_acceptance(base,args):
    out=_v46_outputs_dir()/'p30_mask_equivalence_acceptance_v46.json'
    accepted=_v46_read_json(_v46_outputs_dir()/'p30_mask_equivalence_appendix_accepted.json') or _v46_read_json(Path('p30_mask_equivalence_appendix_accepted.json'))
    candidate=_v46_read_json(_v46_outputs_dir()/'p30_mask_equivalence_appendix_candidate_v46.json') or _v46_read_json(_v46_outputs_dir()/'p30_mask_equivalence_validator_v45.json') or {}
    required=['same_mask_all_variants','nulls_use_same_mask','edge_exclusion_rule','finite_support_definition','variant_consistency_table']
    official=bool(((base or {}).get('p30_act_mask_gate_v25') or {}).get('official_mask_found') or ((base or {}).get('p30_mask_equivalence_appendix_v44') or {}).get('official_mask_found'))
    # v46 deliberately does not auto-accept. It writes an explicit candidate template that the user can copy to accepted JSON.
    candidate_template={
        'same_mask_all_variants': False,
        'nulls_use_same_mask': False,
        'edge_exclusion_rule': '',
        'finite_support_definition': '',
        'variant_consistency_table': False,
        'accepted_by': '',
        'accepted_utc': '',
        'notes': 'Fill true/text fields only after verifying all ACT variants and nulls use identical empirical/official mask.'
    }
    cand_path=_v46_outputs_dir()/'p30_mask_equivalence_appendix_candidate_v46.json'
    if not cand_path.exists():
        _v46_write_json(cand_path,candidate_template)
    missing=[]
    if isinstance(accepted,dict):
        for k in required:
            if not accepted.get(k): missing.append(k)
    else:
        missing=['accepted_appendix_missing'] + required
    gate=_v32_gate(official_mask_found=official, accepted_equivalence_appendix=bool(isinstance(accepted,dict) and not missing), same_mask_all_variants=bool(isinstance(accepted,dict) and accepted.get('same_mask_all_variants')), nulls_use_same_mask=bool(isinstance(accepted,dict) and accepted.get('nulls_use_same_mask')), edge_exclusion_rule=bool(isinstance(accepted,dict) and accepted.get('edge_exclusion_rule')), finite_support_definition=bool(isinstance(accepted,dict) and accepted.get('finite_support_definition')), variant_consistency_table=bool(isinstance(accepted,dict) and accepted.get('variant_consistency_table')), mask_acceptance_v46=True)
    rep={'version':'v46','official_mask_found':official,'candidate_or_prior_validator':candidate,'accepted_appendix_present':isinstance(accepted,dict),'accepted_appendix':accepted,'missing_or_false_fields':missing,'candidate_template_path':str(cand_path),'p30_mask_acceptance_gate_v46':gate,'claim_policy':'P30 cannot promote until an official ACT mask is found or p30_mask_equivalence_appendix_accepted.json is supplied with all required fields true/non-empty. v46 refuses auto-acceptance.'}
    _v46_write_json(out,rep); rep['path']=str(out); return rep


def _v46_p30_frozen_patch_protocol(base,args):
    out=_v46_outputs_dir()/'p30_frozen_patch_protocol_v46.json'
    rows=_v46_p30_patch_rows(base)
    protocol={
        'version':'v46',
        'min_high_per_patch':10,
        'min_low_per_patch':10,
        'max_abs_curl_delta':0.20,
        'require_positive_science_minus_abs_curl':True,
        'min_fraction_quality_patches_positive':0.80,
        'min_quality_patch_rows':6,
        'posthoc_patch_removal_allowed':False,
        'protocol_hash16':'pending'
    }
    protocol['protocol_hash16']=_v46_sha16({k:v for k,v in protocol.items() if k!='protocol_hash16'})
    quality=[]; rejected=[]; bad=[]
    for r in rows:
        reasons=[]
        if (r.get('n_high') or 0) < protocol['min_high_per_patch'] or (r.get('n_low') or 0) < protocol['min_low_per_patch']:
            reasons.append('low_counts')
        if abs(r.get('curl_delta') or 0) > protocol['max_abs_curl_delta']:
            reasons.append('curl_amplitude_over_threshold')
        if reasons:
            rr=dict(r); rr['rejected_reasons']=reasons; rejected.append(rr); continue
        rr=dict(r); rr['quality_pass']=bool((r.get('science_minus_abs_curl') or -1e99)>0); quality.append(rr)
        if not rr['quality_pass']:
            bad.append(rr)
    frac=(sum(1 for r in quality if r.get('quality_pass'))/len(quality)) if quality else 0
    # leave-one-patch-out under frozen rules.
    loo=[]
    for r in quality:
        rem=[x for x in quality if x.get('patch_id') != r.get('patch_id')]
        rem_frac=(sum(1 for x in rem if x.get('quality_pass'))/len(rem)) if rem else 0
        mean_smac=_v46_quantile([x.get('science_minus_abs_curl') for x in rem],0.5)
        loo.append({'held_out_patch':r.get('patch_id'),'remaining_n':len(rem),'remaining_positive_fraction':rem_frac,'remaining_median_science_minus_abs_curl':mean_smac,'pass':bool(rem and rem_frac>=protocol['min_fraction_quality_patches_positive'] and mean_smac is not None and mean_smac>0)})
    stable=bool(loo and all(x.get('pass') for x in loo))
    # Fresh rerun marker: users can provide a manifest whose protocol_hash matches this exact frozen protocol, produced before final claim interpretation.
    rerun_manifest=_v46_read_json(_v46_outputs_dir()/'p30_frozen_patch_rerun_manifest_v46.json') or _v46_read_json(Path('p30_frozen_patch_rerun_manifest_v46.json'))
    fresh=bool(isinstance(rerun_manifest,dict) and rerun_manifest.get('protocol_hash16')==protocol['protocol_hash16'] and rerun_manifest.get('fresh_rerun_under_protocol') is True)
    gate=_v32_gate(frozen_protocol_defined=True, n_quality_patch_rows_ge_6=len(quality)>=protocol['min_quality_patch_rows'], positive_fraction_ge_80=frac>=protocol['min_fraction_quality_patches_positive'], leave_one_patch_out_stable=stable, no_posthoc_patch_removal=True, fresh_rerun_under_frozen_protocol=fresh, patch_protocol_v46=True)
    rep={'version':'v46','protocol':protocol,'protocol_hash16':protocol['protocol_hash16'],'n_patch_rows_total':len(rows),'n_quality_patch_rows':len(quality),'n_rejected_patch_rows':len(rejected),'n_bad_quality_patches':len(bad),'positive_fraction_quality_patches':frac,'quality_patch_rows':quality,'rejected_patch_rows':rejected,'bad_quality_patches':bad,'leave_one_patch_out':loo,'fresh_rerun_manifest_present':isinstance(rerun_manifest,dict),'fresh_rerun_manifest':rerun_manifest,'p30_patch_protocol_gate_v46':gate,'claim_policy':'v46 uses old patch rows only to define/diagnose. Promotion requires a fresh rerun manifest matching protocol_hash16; no same-run post-hoc rescue.'}
    _v46_write_json(out,rep); rep['path']=str(out); return rep


def run_p30_maskrandom_freeze_v46(meta,args):
    base = _run_p30_v45_for_v46(meta,args) if callable(_run_p30_v45_for_v46) else base_result(meta,'broken',error='missing previous p30 runner')
    mask=_v46_p30_mask_acceptance(base,args)
    proto=_v46_p30_frozen_patch_protocol(base,args)
    route_gate=_v32_gate(mask_accepted=bool((mask.get('p30_mask_acceptance_gate_v46') or {}).get('eligible_for_confirm_like')), frozen_patch_protocol_pass=bool((proto.get('p30_patch_protocol_gate_v46') or {}).get('eligible_for_confirm_like')), p30_sdss_positive_route_preserved=bool((base.get('p30_sdss_positive_route_preserved_v38') or {}).get('positive_route_preserved') or 'density_kappa' in str(base.get('status',''))), route_scope=True, global_scope=False)
    base['p30_mask_equivalence_acceptance_v46']=mask
    base['p30_frozen_patch_protocol_v46']=proto
