def run_p33_density_bao_measurement_gate_v48(meta, args):
    base = _v48_call(_v48_prev.get("p33_density_bao_measured_scaffold_v22"), meta, args, fallback_status="measurement_ready_not_confirmed")
    gate = _v48_gate(
        density_split_catalogue_loaded=bool(base.get("density_split_catalogue_loaded") or base.get("density_split_alpha")),
        alpha_high_low_measured=bool(base.get("alpha_high") is not None and base.get("alpha_low") is not None or base.get("density_split_alpha_high_low")),
        desi_randoms_loaded=bool(base.get("desi_randoms_loaded") or base.get("random_catalogue_loaded")),
        covariance_aware_fit=bool(base.get("covariance_aware_fit") or base.get("cov_file") or base.get("covariance_loaded")),
        sky_shuffle_null=bool(base.get("sky_shuffle_p") is not None or base.get("sky_shuffle_null")),
        density_label_shuffle_null=bool(base.get("density_label_shuffle_p") is not None or base.get("density_label_shuffle_null")),
        redshift_jackknife_stable=bool(base.get("redshift_jackknife_stable") or base.get("leave_one_redshift_bin_out")),
    )
    gate["promotion_rule"] = "P33 confirm requires measured high/low-density BAO alpha, DESI randoms, covariance-aware fit, sky shuffle, density-label shuffle, and redshift jackknife stability. Baseline BAO parsing is not evidence for density-coupled BAO."
    base["p33_density_bao_confirm_gate_v48"] = gate
    if gate["eligible_for_confirm_like"]:
        base["status"] = "p33_density_bao_confirm_like"
    else:
        base["status"] = "p33_density_bao_measurement_ready_not_confirmed"
    base["interpretation"] = "P33 v48: scaffold is now explicitly measurement-ready/not-confirmed until a real density-split BAO alpha statistic exists."
    return base


