def run_nanograv_coordinate_gate_v48(meta, args):
    base = _v48_call(_v48_prev.get("nanograv_retry_cache_v22"), meta, args, fallback_status="readiness_only")
    coords_n = base.get("n_pulsar_coordinates") or base.get("n_coords") or base.get("n_parsed_pulsars") or base.get("n_par_like")
    gate = _v48_gate(
        pulsar_coordinates_parsed=bool(coords_n and coords_n >= 20),
        residual_or_toa_weights_loaded=bool(base.get("residual_weights_loaded") or base.get("toa_weights_loaded")),
        kappa_map_sampled_at_pulsars=bool(base.get("kappa_samples") or base.get("n_finite_kappa_samples")),
        sky_shuffle_null=bool(base.get("sky_shuffle_p") is not None or base.get("sky_shuffle_null")),
    )
    gate["promotion_rule"] = "P8/P8c cannot confirm from coordinates alone; requires residual/TOA weights, kappa samples at pulsars, and sky-shuffle null."
    base["p8_pta_confirm_gate_v48"] = gate
    if not gate["eligible_for_confirm_like"]:
        base["status"] = "pta_coordinate_ready_statistic_required" if gate.get("pulsar_coordinates_parsed") else base.get("status", "readiness_only")
    return base


def run_cl2_pta_density_gate_v48(meta, args):
    base = _v48_call(_v48_prev.get("cl2_weighted_parse_v21"), meta, args, fallback_status="partial_positive_bridge")
    nfinite = base.get("n_finite_kappa_samples") or base.get("n_finite_pulsars") or base.get("n_pulsars")
    p = base.get("sky_shuffle_p") or base.get("sky_shuffle_p_high")
    gate = _v48_gate(
        finite_pulsar_kappa_samples=bool(nfinite and nfinite >= 20),
        residual_or_toa_weights_loaded=bool(base.get("residual_weights_loaded") or base.get("toa_weights_loaded") or base.get("weighted_statistic")),
        weighted_kappa_residual_statistic=bool(base.get("weighted_statistic") or base.get("kappa_residual_correlation")),
        sky_shuffle_p_le_005=bool(p is not None and p <= 0.05),
    )
    gate["promotion_rule"] = "CL2/PTA confirm-like requires finite kappa samples, residual/TOA weights, weighted statistic, and sky-shuffle p<=0.05."
    base["cl2_pta_density_confirm_gate_v48"] = gate
    if gate["eligible_for_confirm_like"]:
        base["status"] = "pta_density_cross_confirm_like"
    elif _v48_status_has_confirm(base.get("status")):
        base["pre_v48_status"] = base.get("status"); base["status"] = "pta_density_cross_statistic_required"
    return base


