def run_ringdown_strain_gate_v48(meta, args):
    base = _v48_call(_v48_prev.get("ringdown_strain_plan_v22"), meta, args, fallback_status="ringdown_ready_positive_bound")
    g = base.get("ringdown_strain_confirm_gate_v46") or base.get("ringdown_strain_confirm_gate_v45") or base.get("ringdown_strain_confirm_gate_v44") or {}
    gate = _v48_gate(
        strain_downloaded=bool(g.get("strain_downloaded") or base.get("strain_downloaded")),
        h1_l1_available=bool(g.get("h1_l1_available") or base.get("h1_l1_available")),
        psd_estimated=bool(g.get("psd_estimated") or base.get("psd_estimated")),
        gr_ringdown_fit=bool(g.get("gr_ringdown_fit") or base.get("gr_ringdown_fit")),
        ccdr_residual_template_fit=bool(g.get("ccdr_residual_template_fit") or base.get("ccdr_residual_template_fit")),
        residual_improves_gr=bool(g.get("residual_improves_gr") or base.get("residual_improves_gr")),
        injection_nulls=bool(g.get("injection_nulls") or base.get("injection_nulls")),
        detector_split=bool(g.get("detector_split") or base.get("detector_split")),
        leave_one_event_out=bool(g.get("leave_one_event_out") or base.get("leave_one_event_out")),
    )
    gate["promotion_rule"] = "P32 ringdown confirm requires strain download, H1/L1 split, PSD, GR fit, CCDR residual fit, improvement over GR, injection nulls, detector split, and leave-one-event-out."
    base["p32_ringdown_confirm_gate_v48"] = gate
    if gate["eligible_for_confirm_like"]:
        base["status"] = "p32_ringdown_strain_confirm_like"
    elif _v48_status_has_confirm(base.get("status")) or "candidate" in str(base.get("status")):
        base["pre_v48_status"] = base.get("status"); base["status"] = "ringdown_strain_analysis_required"
    return base


