def run_p41_likelihood_gate_v48(meta, args):
    base = _v48_call(_v48_prev.get("p41_structured_cp_v22"), meta, args, fallback_status="p41_pattern_positive_ready_sign_unfixed")
    g = base.get("p41_structured_cp_gate_v22") or base.get("p41_confirm_gate_v20") or {}
    gate = _v48_gate(
        q2_value_error_rows=bool(g.get("structured_q2_value_error_rows") or g.get("q2_value_error_rows") or base.get("q2_value_error_rows")),
        sign_basis=bool(g.get("sign_basis") or g.get("has_sign_basis") or base.get("sign_basis")),
        sm_vs_wilson_delta_chi2=bool(base.get("sm_vs_wilson_delta_chi2") or base.get("delta_chi2_sm_minus_wilson")),
        cp_asymmetry_null=bool(g.get("cp_asymmetry_null") or base.get("cp_asymmetry_null")),
        observable_bin_jackknife=bool(base.get("observable_bin_jackknife") or base.get("leave_one_q2_bin_out")),
    )
    gate["promotion_rule"] = "P41 confirm-like requires q²/value/error rows, sign basis, SM-vs-Wilson Δχ², CP-asymmetry null, and q²/observable-bin jackknife. Parser readiness is not enough."
    base["p41_likelihood_confirm_gate_v48"] = gate
    if gate["eligible_for_confirm_like"]:
        base["status"] = "p41_q2_wilson_confirm_like"
    elif _v48_status_has_confirm(base.get("status")):
        base["pre_v48_status"] = base.get("status"); base["status"] = "p41_likelihood_required"
    return base


