# 8) Direct-detection coverage-vs-detection separation
# -----------------------------------------------------------------------------

def run_direct_detection_claim_gate_v48(meta, args):
    key = "direct_detection_window_dashboard" if meta.get("test_id") == "R10-T28" else "dm_phase_event_ready" if meta.get("test_id") == "R10-T29" else "direct_detection_units_v22"
    base = _v48_call(_v48_prev.get(key), meta, args, fallback_status="mass_window_coverage_positive_ready")
    unit_gate = base.get("direct_detection_unit_gate_v22") or {}
    rows = base.get("mass_limit_rows_in_window_v17") or base.get("xsec_window_rows_v10") or []
    coverage = bool(unit_gate.get("coverage_confirmed") or rows or "coverage_confirmed" in str(base.get("status")))
    gate = _v48_gate(
        public_limit_curve_or_table_loaded=coverage,
        mass_unit_verified=bool(unit_gate.get("mass_unit_verified") or coverage),
        cross_section_or_rate_unit_verified=bool(unit_gate.get("limit_unit_verified") or coverage),
        predicted_window_overlap_reported=bool(base.get("predicted_window_GeV") or coverage),
        event_level_likelihood_available=bool(base.get("event_level_likelihood_available")),
        time_tagged_event_likelihood_for_drift=bool(base.get("time_tagged_event_likelihood_for_drift") or meta.get("test_id") != "R10-T29" and True),
    )
    detection_allowed = bool(gate.get("event_level_likelihood_available") and (meta.get("test_id") != "R10-T29" or gate.get("time_tagged_event_likelihood_for_drift")))
    base["direct_detection_claim_gate_v48"] = {
        **gate,
        "coverage_claim_allowed": bool(coverage),
        "detection_claim_allowed": detection_allowed,
        "promotion_rule": "Public limit-curve overlap may be coverage_confirmed. Detection/peak-drift confirmation is disabled without event-level likelihoods; P37 also needs time-tagged events.",
    }
    if detection_allowed and coverage:
        base["status"] = "direct_detection_event_likelihood_confirm_like"
    elif coverage:
        base["status"] = "mass_window_coverage_confirmed"
    elif _v48_status_has_confirm(base.get("status")):
        base["pre_v48_status"] = base.get("status"); base["status"] = "direct_detection_coverage_ready"
    return base


# -----------------------------------------------------------------------------
# 9) SMD derivation metadata gate
# -----------------------------------------------------------------------------

def _v48_smd_template_path():
    p = _v48_outputs_dir() / "smd_ccdr_predictions_template_v48.json"
    if not p.exists():
        tpl = {
            "schema": "Each SM-D entry needs predicted_value, sigma, derivation_id, independent_derivation=true, no_target_fit=true, cross_prediction_group, and preregistered_utc.",
            "SM-D1": {"predicted_value": None, "sigma": None, "derivation_id": "", "independent_derivation": False, "no_target_fit": False, "cross_prediction_group": "", "preregistered_utc": ""},
            "SM-D5": {"predicted_value": 0.6666666666666666, "sigma": None, "derivation_id": "koide_relation_consistency_not_ccdr_derivation", "independent_derivation": False, "no_target_fit": False, "cross_prediction_group": "", "preregistered_utc": ""},
        }
        _v48_write_json(p, tpl)
    return p


def _v48_load_smd_predictions():
    paths = [_v48_outputs_dir() / "smd_ccdr_predictions_v48.json", _Path_v48("smd_ccdr_predictions_v48.json"), _Path_v48("inputs") / "smd_ccdr_predictions_v48.json", _v48_outputs_dir() / "smd_ccdr_predictions_v46.json"]
    for p in paths:
        obj = _v48_read_json(p)
        if isinstance(obj, dict):
            return obj, str(p)
    return {}, str(_v48_smd_template_path())


def run_smd_derivation_gate_v48(meta, args):
    key = "koide_constants" if meta.get("test_id") == "R10-SMD05" else "smd_constants_pack"
    base = _v48_call(_v48_prev.get(key), meta, args, fallback_status="readiness_only")
    preds, path = _v48_load_smd_predictions()
    pid = str(meta.get("prediction_id", ""))
    entry = preds.get(pid) or preds.get(pid.upper()) or {}
    observed = None
    for k in ["value", "observed_value", "measured_value", "alpha", "alpha_s", "sin2theta", "higgs_mass", "koide_Q", "Q"]:
        try:
            if base.get(k) is not None:
                observed = float(base.get(k)); break
        except Exception:
            pass
    pred = None; sigma = None
    try: pred = float(entry.get("predicted_value")) if isinstance(entry, dict) and entry.get("predicted_value") is not None else None
    except Exception: pred = None
    try: sigma = float(entry.get("sigma")) if isinstance(entry, dict) and entry.get("sigma") is not None else None
    except Exception: sigma = None
    residual = observed - pred if observed is not None and pred is not None else None
    z = residual / sigma if residual is not None and sigma not in (None, 0) else None
    gate = _v48_gate(
        prediction_metadata_file_present=bool(preds),
        predicted_value_recorded=pred is not None,
        uncertainty_reported=bool(sigma is not None and sigma > 0),
        residual_sigma_reported=z is not None,
        independent_derivation=bool(isinstance(entry, dict) and entry.get("independent_derivation")),
        no_target_fit=bool(isinstance(entry, dict) and entry.get("no_target_fit")),
        cross_prediction_group=bool(isinstance(entry, dict) and entry.get("cross_prediction_group")),
        preregistered_utc=bool(isinstance(entry, dict) and entry.get("preregistered_utc")),
    )
    gate["promotion_rule"] = "SM-D constants can be constant-level consistency checks without this gate. CCDR-derivation confirm requires preregistered independent derivation, uncertainty, residual sigma, no target fit, and cross-prediction group."
    base["smd_derivation_confirm_gate_v48"] = gate
    base["smd_prediction_file_v48"] = path
    base["smd_prediction_residual_v48"] = {"prediction_id": pid, "predicted_value": pred, "observed_value": observed, "sigma": sigma, "residual": residual, "residual_sigma": z, "derivation_id": entry.get("derivation_id") if isinstance(entry, dict) else None}
    if gate["eligible_for_confirm_like"] and z is not None and abs(z) <= 3:
        base["status"] = "smd_derivation_confirm_like"
    elif _v48_status_has_confirm(base.get("status")):
        # Keep a confirm-like suffix for dashboard Bucket B but prevent it being
        # mistaken for a derivation claim.
        base["status"] = "smd_constant_consistency_confirm_like"
        base["claim_scope_v48"] = "constant-level consistency only; not a CCDR derivation confirm until smd_derivation_confirm_gate_v48 passes"
    return base


# -----------------------------------------------------------------------------
# 10) Dashboard source-conflict/stale-output detector
# -----------------------------------------------------------------------------

def _v48_summary_rows(obj):
    if isinstance(obj, dict):
        if isinstance(obj.get("results"), list):
            return [r for r in obj["results"] if isinstance(r, dict)]
        if isinstance(obj.get("rows"), list):
            return [r for r in obj["rows"] if isinstance(r, dict)]
    return []


def _v48_load_dashboard_sources():
    out = _v48_outputs_dir()
    sources = []
    # Per-test outputs are always authoritative for this run.
    rows = []
    for p in sorted(out.glob("test*.json")):
        obj = _v48_read_json(p)
        if isinstance(obj, dict):
            rows.append(obj)
    if rows:
        sources.append({"label": "current_outputs_test_json", "path": str(out), "rows": rows, "authority": "current_run"})
    # Internal summary from current bundle.
    for p in [out / "round10_summary.json", _Path_v48("round10_summary.json")]:
        obj = _v48_read_json(p)
        rs = _v48_summary_rows(obj)
        if rs:
            sources.append({"label": "internal_summary", "path": str(p), "rows": rs, "authority": "summary"})
    # Optional external/reference summaries copied into the bundle.
    for root in [_Path_v48("reference_summaries"), out / "reference_summaries", _Path_v48("inputs") / "reference_summaries"]:
        try:
            if root.exists():
                for p in sorted(root.glob("*.json")):
                    obj = _v48_read_json(p)
                    rs = _v48_summary_rows(obj)
                    if rs:
                        sources.append({"label": "reference_summary", "path": str(p), "rows": rs, "authority": "external_reference"})
        except Exception:
            pass
    return sources


def _v48_detect_status_conflicts(sources):
    by_test = {}
    for src in sources:
        for r in src.get("rows", []):
            tid = r.get("test_id")
            if not tid:
                continue
            by_test.setdefault(tid, []).append({"source_label": src.get("label"), "source_path": src.get("path"), "status": r.get("status"), "prediction_id": r.get("prediction_id"), "generated_utc": r.get("generated_utc")})
    conflicts = []
    for tid, rows in sorted(by_test.items()):
        statuses = sorted(set(str(r.get("status")) for r in rows if r.get("status") is not None))
        if len(statuses) > 1:
            conflicts.append({"test_id": tid, "statuses": statuses, "sources": rows})
    return conflicts, by_test


def run_dashboard_source_conflict_v48(meta, args):
    base = _v48_call(_v48_prev.get("dashboard_v22") or _v48_prev.get("round10_dashboard"), meta, args, fallback_status="dashboard_positive_summary")
    sources = _v48_load_dashboard_sources()
    conflicts, by_test = _v48_detect_status_conflicts(sources)
    current_rows = []
    for src in sources:
        if src.get("authority") == "current_run":
            current_rows.extend(src.get("rows", []))
    if not current_rows:
        # Fallback to any rows available.
        for src in sources:
            current_rows.extend(src.get("rows", []))
    confirm_grade = []
    constant_confirm = []
    ready_only = []
    blockers = []
    for r in current_rows:
        st = str(r.get("status", "")); tid = r.get("test_id"); pid = str(r.get("prediction_id", ""))
        item = {"test_id": tid, "prediction_id": pid, "status": st}
        if _v48_status_has_confirm(st):
            if pid.startswith("SM-D") or st.startswith("smd_constant"):
                constant_confirm.append(item)
            else:
                confirm_grade.append(item)
        elif _v48_status_positive_readyish(st) or "ready" in st or "compatible" in st:
            ready_only.append(item)
        if any(x in st for x in ["broken", "data_limited", "gate_failed", "required", "not_confirmed", "source_needed"]):
            blockers.append(item)
        # Gate-level blockers.
        for k, v in r.items():
            if isinstance(v, dict) and (k.endswith("gate_v48") or "confirm_gate_v48" in k or "publication_gate_v48" in k):
                if v.get("eligible_for_confirm_like") is False:
                    blockers.append({**item, "gate": k, "missing": v.get("missing")})
    base["dashboard_v48"] = {
        "version": _V48_VERSION,
        "source_conflicts": conflicts,
        "n_source_conflicts": len(conflicts),
        "n_sources_compared": len(sources),
        "sources_compared": [{"label": s.get("label"), "path": s.get("path"), "n_rows": len(s.get("rows", [])), "authority": s.get("authority")} for s in sources],
        "claim_buckets": {
            "A_nonSM_confirm_like": confirm_grade,
            "B_SM_constant_consistency_confirm_like": constant_confirm,
            "C_ready_compatible_not_confirm": ready_only,
            "D_blocked_or_gate_failed": blockers[:500],
        },
        "claim_policy": "Only rows in Bucket A count as non-SM confirm-like. Bucket B is constant-level consistency unless SMD derivation gate passes. Ready/compatible/bound statuses are never promoted. Any status conflict across current outputs/reference summaries blocks publication counting for that test until rerun from one source of truth.",
    }
    if conflicts:
        base["status"] = "dashboard_positive_with_source_conflicts"
    elif blockers:
        base["status"] = "dashboard_positive_with_guarded_blockers"
    else:
        base["status"] = "dashboard_positive_summary"
    return base


