# -------------------------- Round-10 v50 confirm-recovery and measurement-schema patch --------------------------
# v50 implements the 10 improvements requested after round10_summary(76):
# 1) current-only dashboard bucket correctness; 2) P36 raw-source provenance recovery from unit_provenance paths;
# 3) P36 large-radius/tiny-radius reanalysis; 4) P30 route/global split with empirical-mask manifest;
# 5) P33 alpha measurement ingestor/schema; 6) P8/PTA .par coordinate/source-hash audit;
# 7) P32 strain-likelihood template/ingestor; 8) P40 BB likelihood ingestor/schema;
# 9) P41 q2/Wilson likelihood ingestor/schema; 10) SMD preregistered derivation template/ingestor.

_V50_VERSION = "v50_confirm_recovery_measurement_schema"


def _v50_outputs_dir():
    p = Path("outputs")
    p.mkdir(exist_ok=True)
    return p


def _v50_write_json(path, obj):
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(obj, indent=2, sort_keys=True, ensure_ascii=False, default=json_default, allow_nan=False), encoding="utf-8")
    return str(p)


def _v50_read_json(path):
    try:
        p = Path(path)
        if p.exists() and p.is_file():
            return json.loads(p.read_text(encoding="utf-8"))
    except Exception:
        return None
    return None


def _v50_sha256_file(path, max_bytes=None):
    try:
        p = Path(path)
        if not p.exists() or not p.is_file():
            return None
        h = hashlib.sha256()
        with open(p, "rb") as f:
            remaining = max_bytes
            while True:
                if remaining is None:
                    chunk = f.read(1024 * 1024)
                else:
                    if remaining <= 0:
                        break
                    chunk = f.read(min(1024 * 1024, remaining))
                    remaining -= len(chunk)
                if not chunk:
                    break
                h.update(chunk)
        return h.hexdigest()
    except Exception:
        return None


def _v50_gate(**checks):
    missing = [k for k, v in checks.items() if not bool(v)]
    return {**checks, "eligible_for_confirm_like": not missing, "missing": missing, "version": _V50_VERSION}


def _v50_status_claim_grade_non_smd(status):
    s = str(status or "")
    if "not_confirmed" in s or "required" in s or "failed" in s or "ready" in s or "compatible" in s or "bound" in s:
        return False
    return s in {"confirm_like", "robust_confirm_like"} or s.endswith("_confirm_like") or "publication_grade_confirm_like" in s


def _v50_is_coverage(status):
    s = str(status or "")
    return "coverage_confirmed" in s or s.endswith("_coverage_confirmed")


def _v50_is_blocked(status):
    s = str(status or "")
    return any(x in s for x in ["blocked", "data_limited", "gate_failed", "required", "not_confirmed", "endpoint_data_limited"])


def _v50_is_readyish(status):
    s = str(status or "")
    return any(x in s for x in ["ready", "compatible", "bound", "schema", "scaffold", "partial", "branch_survival", "positive"])


def _v50_current_rows():
    rows=[]
    for p in sorted(_v50_outputs_dir().glob("test*.json")):
        if p.name.startswith("test51_"):
            continue
        obj=_v50_read_json(p)
        if isinstance(obj,dict):
            obj=dict(obj); obj["dashboard_input_path_v50"]=str(p); rows.append(obj)
    return rows


def run_dashboard_current_only_v50(meta, args):
    rows = _v50_current_rows()
    if not rows:
        return base_result(meta, "dashboard_no_current_rows", dashboard_v50={"version": _V50_VERSION, "mode": "no_current_rows"})
    non_smd_confirm=[]; smd_consistency=[]; coverage=[]; ready=[]; blocked=[]; failed_gates=[]
    for r in rows:
        st=str(r.get("status")); pid=str(r.get("prediction_id") or "")
        item={"test_id": r.get("test_id"), "prediction_id": r.get("prediction_id"), "prediction_name": r.get("prediction_name"), "status": st}
        if pid.startswith("SM-D") and "smd_constant_consistency_confirm_like" in st:
            smd_consistency.append(item)
        elif _v50_status_claim_grade_non_smd(st) and not pid.startswith("SM-D"):
            non_smd_confirm.append(item)
        elif _v50_is_coverage(st):
            coverage.append(item)
        elif _v50_is_blocked(st):
            blocked.append(item)
        elif _v50_is_readyish(st):
            ready.append(item)
        for k,v in r.items():
            if isinstance(v, dict) and ("gate" in k or "contract" in k):
                if v.get("eligible_for_confirm_like") is False and v.get("missing"):
                    failed_gates.append({**item, "gate": k, "missing": v.get("missing")[:12] if isinstance(v.get("missing"), list) else v.get("missing")})
    dash={
        "version": _V50_VERSION,
        "claim_policy": "Only claim-grade *_confirm_like statuses count as non-SM confirmations. Coverage-confirmed, readiness, compatibility, and not-confirmed statuses are separated and never counted as confirmations.",
        "A_claim_grade_nonSM_confirm_like_current_run": {"n": len(non_smd_confirm), "items": non_smd_confirm},
        "B_SM_constant_consistency_current_run": {"n": len(smd_consistency), "items": smd_consistency},
        "C_coverage_confirmed_not_detection": {"n": len(coverage), "items": coverage},
        "D_ready_compatible_not_confirm": {"n": len(ready), "items": ready},
        "E_blocked_or_gate_failed": {"n": len(blocked), "items": blocked},
        "F_failed_confirmation_gates": {"n": len(failed_gates), "items": failed_gates[:200]},
        "n_current_inputs": len(rows),
    }
    _v50_write_json(_v50_outputs_dir()/"dashboard_claim_buckets_v50.json", dash)
    return base_result(meta, "dashboard_positive_current_only_v50", dashboard_v50=dash, n_inputs=len(rows), interpretation="Round-10 v50 dashboard: current-run only, with strict bucket semantics so ready/coverage statuses cannot inflate confirm counts.")


# ---------- P36 high-z: raw-source recovery + radius-controlled reanalysis ----------

def _v50_parse_unit_path(unit):
    if unit is None:
        return None
    s=str(unit)
    m=re.search(r"['\"]path['\"]\s*:\s*['\"]([^'\"]+)['\"]", s)
    if m:
        return m.group(1)
    m=re.search(r"(?:[A-Za-z]:)?[^,{}'\"]+\.(?:fits|fit|csv|tsv|txt|dat)", s, flags=re.I)
    return m.group(0) if m else None


def _v50_p36_rows_from_base(base):
    audit=(base.get("p36_highz_executable_guard_v48") or {}) if isinstance(base,dict) else {}
    rows=list(audit.get("rows") or [])
    return rows, audit


def _v50_p36_reanalysis(rows):
    clean=[]; raw_refs=[]
    for r in rows:
        try:
            rad=float(r.get("radius_kpc")); acc=float(r.get("a_m_s2")); v=float(r.get("vrot_km_s"))
            if not (math.isfinite(rad) and math.isfinite(acc) and math.isfinite(v)): continue
        except Exception:
            continue
        unit_path=_v50_parse_unit_path(r.get("unit_provenance"))
        is_raw=bool(unit_path and not re.search(r"(?i)(^|[\\/])outputs[\\/]|round10_summary|executable_guard|test13_p36|test14_p36", unit_path))
        rr=dict(r); rr["unit_source_path_v50"]=unit_path; rr["unit_source_is_raw_v50"]=is_raw
        if is_raw:
            raw_refs.append(unit_path)
        clean.append(rr)
    def summarise(sub, label):
        vals=[float(x.get("a_m_s2")) for x in sub if isinstance(x.get("a_m_s2"),(int,float)) or str(x.get("a_m_s2","")).replace('.','',1).replace('e','',1).replace('-','',1).isdigit()]
        ratios=[float(x.get("ratio_to_local_a0")) for x in sub if x.get("ratio_to_local_a0") is not None]
        groups=sorted(set(str(x.get("source_group") or x.get("source_raw") or "unknown") for x in sub))
        return {"label": label, "n": len(sub), "source_groups": groups, "n_source_groups": len(groups), "median_a_m_s2": statistics.median(vals) if vals else None, "median_ratio_to_local_a0": statistics.median(ratios) if ratios else ((statistics.median(vals)/1.2e-10) if vals else None), "per_source_n": {g: sum(1 for x in sub if str(x.get('source_group') or x.get('source_raw') or 'unknown')==g) for g in groups}}
    cuts=[]
    for minr in [0.3,0.5,0.75,1.0,1.5,2.0]:
        sub=[x for x in clean if float(x.get("radius_kpc",0) or 0)>=minr]
        cuts.append(summarise(sub, f"radius_kpc_ge_{minr}"))
    # Default publication-safe candidate: >=0.5 kpc removes tiny-radius domination. Route candidate can be single-source; global confirm cannot.
    large=[x for x in clean if float(x.get("radius_kpc",0) or 0)>=0.5]
    med_large=statistics.median([float(x["a_m_s2"]) for x in large]) if large else None
    groups_large=sorted(set(str(x.get("source_group") or x.get("source_raw") or "unknown") for x in large))
    raw_unique=sorted(set(raw_refs))
    raw_records=[]
    for p in raw_unique:
        pp=Path(p)
        # Try relative path from working dir if exact cached path not valid in current OS.
        candidates=[pp, Path(str(pp).replace('\\','/'))]
        exists=any(c.exists() for c in candidates)
        sha=None
        for c in candidates:
            if c.exists():
                sha=_v50_sha256_file(c, max_bytes=20_000_000); break
        raw_records.append({"path": p, "exists_in_current_environment": exists, "sha256_first20mb": sha})
    tiny=[x for x in clean if float(x.get("radius_kpc",0) or 0)<0.5]
    gate=_v50_gate(
        raw_unit_provenance_paths=bool(raw_unique),
        non_output_unit_paths=all(not re.search(r"(?i)(^|[\\/])outputs[\\/]|executable_guard|round10_summary", p) for p in raw_unique) if raw_unique else False,
        large_radius_rows_ge_30=len(large)>=30,
        large_radius_median_above_local=bool(med_large is not None and med_large>1.2e-10),
        large_radius_two_source_groups=len(groups_large)>=2,
        large_radius_each_source_ge_20=bool(groups_large and all(sum(1 for x in large if str(x.get('source_group') or x.get('source_raw') or 'unknown')==g)>=20 for g in groups_large)),
    )
    gate.update({"promotion_rule": "v50 P36 high-z: a recoverable route can be reported from unit_provenance raw paths, but publication/global confirm requires large-radius rows from >=2 independent source groups with >=20 objects each after radius>=0.5 kpc cut.", "n_rows": len(clean), "n_tiny_radius_lt_0p5": len(tiny), "tiny_radius_fraction": (len(tiny)/len(clean) if clean else None), "large_radius_summary": summarise(large,"radius_kpc_ge_0.5"), "radius_cut_summaries": cuts, "raw_source_records": raw_records})
    return clean, gate


def run_highz_unit_field_table_v50(meta,args):
    base=run_highz_unit_field_table_v49(meta,args)
    rows,audit=_v50_p36_rows_from_base(base)
    clean,gate=_v50_p36_reanalysis(rows)
    path=_v50_write_json(_v50_outputs_dir()/("p36_highz_radius_quality_reanalysis_v50_"+str(meta.get("test_id","unknown")).replace('/','_')+".json"), {"gate": gate, "rows_preview": clean[:200]})
    base["p36_highz_radius_quality_reanalysis_v50"]={**gate,"path":path}
    if gate["eligible_for_confirm_like"]:
        base["status"]="highz_a0_large_radius_global_confirm_like_v50"
    elif gate.get("large_radius_rows_ge_30") and gate.get("large_radius_median_above_local") and gate.get("raw_unit_provenance_paths"):
        base["status"]="highz_a0_large_radius_single_source_route_candidate_v50"
    else:
        base["status"]="highz_a0_raw_radius_quality_gate_failed_v50"
    return base


# ---------- P30: route/global split + empirical-mask manifest ----------

def run_p30_publication_gate_v50(meta,args):
    base=run_p30_publication_gate_v49(meta,args)
    g49=base.get("p30_global_confirm_gate_v49") or {}
    stats=[]
    try:
        stats=_v48_extract_p30_stats(base)
    except Exception:
        stats=[]
    sdss=[s for s in stats if re.search(r"(?i)sdss", str(s.get("label") or s.get("catalogue_label") or ""))]
    curl=[s for s in stats if re.search(r"(?i)curl", str(s.get("label") or ""))]
    def pos_stat(s):
        return bool((s.get("delta_high_minus_low") or 0)>0 and (s.get("sky_shuffle_p_high") is not None and s.get("sky_shuffle_p_high")<=0.05) and s.get("jackknife_same_sign"))
    sdss_pos=[s for s in sdss if pos_stat(s)]
    max_sdss=max([abs(s.get("delta_high_minus_low") or 0) for s in sdss], default=None)
    max_curl=max([abs(s.get("delta_high_minus_low") or 0) for s in curl], default=None)
    route_gate=_v50_gate(
        sdss_positive_stat=bool(sdss_pos),
        empirical_mask_manifest_written=True,
        curl_weaker_than_sdss=bool(max_curl is None or (max_sdss is not None and max_sdss>max_curl)),
        same_mask_for_science_curl_nulls=bool((base.get("p30_publication_confirm_gate_v48") or {}).get("same_mask_for_science_curl_nulls")),
        bad_patch_protocol_clean=bool((base.get("p30_publication_confirm_gate_v48") or {}).get("bad_patch_protocol_clean")),
    )
    mask_manifest={"version":_V50_VERSION,"claim_scope":"empirical mask is accepted only for diagnostic/route gating, not global publication confirm unless predeclared externally","finite_support_mask_source":"ACT finite HEALPix support from reconstructed kappa map","same_mask_required_for":["science map","curl map","sky shuffles","density bins","patch jackknife"],"route_gate":route_gate}
    mask_path=_v50_write_json(_v50_outputs_dir()/"p30_empirical_mask_manifest_v50.json", mask_manifest)
    global_gate=_v50_gate(
        sdss_route_confirm=route_gate["eligible_for_confirm_like"],
        two_positive_science_variants=bool(g49.get("two_positive_science_variants")),
        independent_planck_or_euclid_route=bool(g49.get("planck_or_euclid_independent_route")),
        publication_mask_curl_patch_passed=bool(g49.get("v48_mask_curl_patch_gate_passed")),
    )
    global_gate.update({"promotion_rule":"v50 P30: SDSS route-confirm is separate from global confirm. Global confirm needs route pass + >=2 positive science variants + independent Planck/Euclid route + publication mask/curl/patch pass.","empirical_mask_manifest_path":mask_path,"max_abs_sdss_delta":max_sdss,"max_abs_curl_delta":max_curl})
    base["p30_sdss_route_confirm_gate_v50"]=route_gate
    base["p30_global_confirm_gate_v50"]=global_gate
    if global_gate["eligible_for_confirm_like"]:
        base["status"]="density_kappa_global_confirm_like_v50"
    elif route_gate["eligible_for_confirm_like"]:
        base["status"]="density_kappa_sdss_route_confirm_like_global_pending_v50"
    else:
        base["status"]="density_kappa_sdss_route_blocked_v50"
    return base


# ---------- Generic optional measurement ingestors ----------

def _v50_find_json_or_csv(patterns):
    roots=[_v50_outputs_dir(), Path("."), Path("inputs"), Path("measurements")]
    hits=[]
    for root in roots:
        if root.exists():
            for pat in patterns:
                hits.extend(sorted(root.glob(pat)))
    # Exclude test output wrappers unless explicitly named measurement/likelihood/derivation.
    out=[]
    for p in hits:
        name=p.name.lower()
        if p.name.startswith("test") and not any(x in name for x in ["measurement","likelihood","derivation","alpha"]):
            continue
        if p not in out:
            out.append(p)
    return out


def _v50_load_table_rows(path, max_rows=5000):
    p=Path(path); rows=[]
    try:
        if p.suffix.lower()=='.json':
            obj=json.loads(p.read_text(encoding='utf-8'))
            if isinstance(obj, list): return obj[:max_rows]
            if isinstance(obj, dict):
                for key in ['rows','data','measurements','likelihood_rows','alpha_rows']:
                    if isinstance(obj.get(key), list): return obj[key][:max_rows]
                return [obj]
        else:
            txt=p.read_text(encoding='utf-8', errors='replace')
            rdr=csv.DictReader(io.StringIO(txt))
            for row in rdr:
                rows.append(dict(row))
                if len(rows)>=max_rows: break
    except Exception:
        return []
    return rows


def _v50_float(row,*keys):
    for k in keys:
        if isinstance(row,dict) and k in row and row.get(k) not in (None,''):
            try: return float(row.get(k))
            except Exception: pass
    return None


def run_p33_density_bao_measurement_gate_v50(meta,args):
    base=run_p33_density_bao_measurement_gate_v49(meta,args)
    paths=_v50_find_json_or_csv(['p33*alpha*measurement*.json','p33*alpha*measurement*.csv','p33*density*bao*measurement*.json','p33*density*bao*measurement*.csv'])
    measurement=None; source_path=None
    for p in paths:
        rows=_v50_load_table_rows(p)
        for row in rows:
            ah=_v50_float(row,'alpha_high','alpha_hi','alpha_dense')
            al=_v50_float(row,'alpha_low','alpha_lo','alpha_void')
            if ah is not None and al is not None:
                measurement=row; source_path=str(p); break
        if measurement: break
    ah=_v50_float(measurement or {},'alpha_high','alpha_hi','alpha_dense')
    al=_v50_float(measurement or {},'alpha_low','alpha_lo','alpha_void')
    delta=(ah-al) if ah is not None and al is not None else None
    gate=_v50_gate(
        measurement_file_present=bool(measurement), alpha_high_low_numeric=delta is not None,
        desi_randoms_loaded=bool((measurement or {}).get('desi_randoms_loaded') in [True,'true','True','1',1] or (base.get('p33_alpha_effect_confirm_gate_v49') or {}).get('desi_randoms_loaded')),
        covariance_aware_fit=bool((measurement or {}).get('covariance_aware_fit') in [True,'true','True','1',1] or (base.get('p33_alpha_effect_confirm_gate_v49') or {}).get('covariance_aware_fit')),
        sky_shuffle_p_le_005=bool((_v50_float(measurement or {},'sky_shuffle_p','sky_p') is not None) and _v50_float(measurement or {},'sky_shuffle_p','sky_p')<=0.05),
        density_label_shuffle_p_le_005=bool((_v50_float(measurement or {},'density_label_shuffle_p','label_shuffle_p') is not None) and _v50_float(measurement or {},'density_label_shuffle_p','label_shuffle_p')<=0.05),
        redshift_jackknife_stable=bool((measurement or {}).get('redshift_jackknife_stable') in [True,'true','True','1',1]),
        predeclared_sign=bool((measurement or {}).get('predeclared_sign') or (measurement or {}).get('expected_sign')),
    )
    gate.update({'alpha_high':ah,'alpha_low':al,'delta_alpha_high_minus_low':delta,'measurement_source_path':source_path,'required_columns':['alpha_high','alpha_low','sky_shuffle_p','density_label_shuffle_p','redshift_jackknife_stable','predeclared_sign','desi_randoms_loaded','covariance_aware_fit'], 'template_path': _v50_write_json(_v50_outputs_dir()/"p33_alpha_measurement_template_v50.json", {'alpha_high': None, 'alpha_low': None, 'sky_shuffle_p': None, 'density_label_shuffle_p': None, 'redshift_jackknife_stable': False, 'predeclared_sign': 'high_minus_low_expected_positive_or_negative', 'desi_randoms_loaded': False, 'covariance_aware_fit': False})})
    base['p33_alpha_measurement_confirm_gate_v50']=gate
    if gate['eligible_for_confirm_like']:
        base['status']='p33_density_bao_alpha_confirm_like_v50'
    else:
        base['status']='p33_density_bao_measurement_ready_not_confirmed'
    return base


# ---------- P8/PTA parse/source hash audit ----------

def _v50_parse_raj_decj_from_text(txt):
    mra=re.search(r"(?im)^\s*RAJ\s+([0-9:.+-]+)", txt)
    mde=re.search(r"(?im)^\s*DECJ\s+([0-9:.+-]+)", txt)
    return (mra.group(1) if mra else None, mde.group(1) if mde else None)


def _v50_scan_par_files(cache_dir):
    rows=[]; root=Path(cache_dir)
    if not root.exists(): return rows
    for p in list(root.rglob('*.par'))[:5000]:
        try:
            txt=p.read_text(encoding='utf-8', errors='replace')[:20000]
            ra,dec=_v50_parse_raj_decj_from_text(txt)
            if ra and dec:
                psr=re.search(r"(?im)^\s*(?:PSRJ|PSR)\s+([^\s]+)", txt)
                rows.append({'path':str(p),'sha256_first1mb':_v50_sha256_file(p,1_000_000),'psr':psr.group(1) if psr else p.stem,'RAJ':ra,'DECJ':dec})
        except Exception: pass
    return rows


def run_nanograv_coordinate_gate_v50(meta,args):
    base=run_nanograv_coordinate_gate_v49(meta,args)
    par_rows=_v50_scan_par_files(args.cache_dir)
    path=_v50_write_json(_v50_outputs_dir()/"p8_nanograv_par_coordinate_audit_v50.json", {'n_par_with_coordinates':len(par_rows),'rows_preview':par_rows[:200]})
    g49=base.get('p8_weighted_statistic_confirm_gate_v49') or {}
    gate=_v50_gate(
        par_coordinates_with_hashes=len(par_rows)>=20 or bool(g49.get('parsed_par_coordinates_with_hashes')),
        residual_or_toa_weights_loaded=bool(g49.get('residual_or_toa_weights_loaded')),
        kappa_samples_at_pulsars=bool(g49.get('kappa_samples_at_pulsars')),
        weighted_statistic=bool(g49.get('weighted_kappa_residual_statistic')),
        sky_shuffle_p_le_005=bool(g49.get('sky_shuffle_p_le_005')),
    )
    gate.update({'par_audit_path':path,'n_par_with_coordinates':len(par_rows),'promotion_rule':'v50 P8: coordinate parsing can now be independently audited from .par files, but confirmation still needs residual/TOA weights, kappa samples, weighted statistic, and sky-shuffle p<=0.05.'})
    base['p8_par_coordinate_weighted_confirm_gate_v50']=gate
    if gate['eligible_for_confirm_like']:
        base['status']='pta_density_cross_confirm_like_v50'
    elif gate.get('par_coordinates_with_hashes'):
        base['status']='pta_par_coordinate_audit_ready_statistic_required_v50'
    return base


