    tmpl_path=_v50_write_json(_v50_outputs_dir()/"smd_derivation_predictions_template_v50.json", template)
    paths=_v50_find_json_or_csv(['smd_derivation_predictions*.json','smd*predictions*.json','sm_d*derivation*.json'])
    pid=str(meta.get('prediction_id') or '')
    entry=None; src=None
    for p in paths:
        obj=_v50_read_json(p)
        if isinstance(obj,dict):
            e=obj.get(pid) or obj.get(pid.upper()) or obj.get(pid.replace('SM-D','SMD'))
            if isinstance(e,dict): entry=e; src=str(p); break
    gate=_v50_gate(
        prediction_file_present=bool(entry), predicted_value_recorded=bool(entry and entry.get('predicted_value') is not None), uncertainty_reported=bool(entry and (entry.get('uncertainty_sigma') is not None or entry.get('sigma') is not None)), residual_sigma_reported=bool(entry and entry.get('residual_sigma') is not None), independent_derivation=bool(entry and entry.get('independent_derivation')), no_target_fit=bool(entry and entry.get('no_target_fit')), cross_prediction_group=bool(entry and entry.get('cross_prediction_group')), preregistered_utc=bool(entry and entry.get('preregistered_utc')), derivation_not_postdictive=bool(entry and entry.get('derivation_not_postdictive'))
    )
    gate.update({'prediction_source_path':src,'template_path':tmpl_path})
    base['smd_derivation_metadata_ingest_gate_v50']=gate
    if gate['eligible_for_confirm_like']:
        base['status']='smd_derivation_confirm_like_v50'
    elif _v50_status_claim_grade_non_smd(base.get('status')) or 'smd_constant_consistency_confirm_like' in str(base.get('status')):
        base['status']='smd_constant_consistency_confirm_like'
        base['claim_scope_v50']='constant-level consistency only; derivation metadata gate is not satisfied'
    return base


