# -------------------------- Round-10 v51 confirm-recovery patch --------------------------
# v51 is based on the partial v50 run analysis. It does not loosen the scientific gates;
# it adds concrete recovery inputs, offline/cached fallbacks, and full-run completeness
# reporting so the next run can recover confirms without stale-output promotion.
from pathlib import Path as _Path_v51
import json as _json_v51
import csv as _csv_v51
import io as _io_v51
import re as _re_v51
import math as _math_v51
import hashlib as _hashlib_v51
import statistics as _statistics_v51

_V51_VERSION = "v51"
_run_dashboard_v50_for_v51 = RUNNERS.get('dashboard_v22', run_dashboard_current_only_v50)
_run_p38_for_v51 = RUNNERS.get('p38_catalogue_nulls_v22', run_p38_catalogue_nulls_v24 if 'run_p38_catalogue_nulls_v24' in globals() else run_p38_catalogue_nulls_v22)
_run_highz_v50_for_v51 = RUNNERS.get('highz_unit_field_table_v22', run_highz_unit_field_table_v50)
_run_p30_v50_for_v51 = RUNNERS.get('p30_maskrandom_freeze_v22', run_p30_publication_gate_v50)
_run_p33_v50_for_v51 = RUNNERS.get('p33_density_bao_measured_scaffold_v22', run_p33_density_bao_measurement_gate_v50)
_run_cl2_v50_for_v51 = RUNNERS.get('cl2_weighted_parse_v21', run_cl2_pta_density_gate_v50)
_run_ringdown_v50_for_v51 = RUNNERS.get('ringdown_strain_plan_v22', run_ringdown_strain_gate_v50)
_run_p40_v50_for_v51 = RUNNERS.get('bk18_bandpower_bound_v10', run_p40_bmode_likelihood_gate_v50)
_run_p41_v50_for_v51 = RUNNERS.get('p41_structured_cp_v22', run_p41_likelihood_gate_v50)
_run_smd_v50_for_v51 = RUNNERS.get('smd_constants_pack', run_smd_derivation_gate_v50)
_run_koide_v50_for_v51 = RUNNERS.get('koide_constants', run_smd_derivation_gate_v50)


def _v51_outputs_dir():
    p = _Path_v51.cwd() / 'outputs'
    p.mkdir(parents=True, exist_ok=True)
    return p


def _v51_inputs_dir():
    p = _Path_v51.cwd() / 'inputs'
    p.mkdir(parents=True, exist_ok=True)
    return p


def _v51_measurements_dir():
    p = _Path_v51.cwd() / 'measurements'
    p.mkdir(parents=True, exist_ok=True)
    return p


def _v51_write_json(path, obj):
    p = _Path_v51(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(_json_v51.dumps(obj, indent=2, sort_keys=True, ensure_ascii=False, default=json_default), encoding='utf-8')
    return str(p)


def _v51_write_csv(path, rows, header):
    p = _Path_v51(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    with p.open('w', encoding='utf-8', newline='') as f:
        w = _csv_v51.DictWriter(f, fieldnames=header)
        w.writeheader()
        for row in rows:
            w.writerow({k: row.get(k, '') for k in header})
    return str(p)


def _v51_gate(**items):
    missing = [k for k, v in items.items() if not bool(v)]
    out = dict(items)
    out['eligible_for_confirm_like'] = not missing
    out['missing'] = missing
    out['gate_version'] = _V51_VERSION
    return out


def _v51_bool(x):
    return x in [True, 1, '1', 'true', 'True', 'TRUE', 'yes', 'YES', 'pass', 'passed']


def _v51_float(x):
    try:
        if x is None or x == '':
            return None
        v = float(str(x).strip())
        return v if _math_v51.isfinite(v) else None
    except Exception:
        return None


def _v51_hash_file(path, max_bytes=50_000_000):
    try:
        h = _hashlib_v51.sha256()
        with _Path_v51(path).open('rb') as f:
            remain = max_bytes
            while remain > 0:
                b = f.read(min(1024 * 1024, remain))
                if not b:
                    break
                h.update(b); remain -= len(b)
        return h.hexdigest()
    except Exception:
        return None


def _v51_find_files(patterns, roots=None):
    roots = roots or [_v51_inputs_dir(), _v51_measurements_dir(), _v51_outputs_dir(), _Path_v51.cwd()]
    hits = []
    for root in roots:
        if not root.exists():
            continue
        for pat in patterns:
            hits.extend(sorted(root.glob(pat)))
    out = []
    for p in hits:
        if p not in out and p.is_file():
            out.append(p)
    return out


def _v51_load_rows(path, max_rows=200000):
    p = _Path_v51(path)
    rows = []
    try:
        if p.suffix.lower() == '.json':
            obj = _json_v51.loads(p.read_text(encoding='utf-8'))
            if isinstance(obj, list):
                return obj[:max_rows]
            if isinstance(obj, dict):
                for key in ['rows', 'data', 'measurements', 'objects', 'likelihood_rows', 'alpha_rows']:
                    if isinstance(obj.get(key), list):
                        return obj[key][:max_rows]
                return [obj]
        text = p.read_text(encoding='utf-8', errors='replace')
        snip = text[:4096]
        try:
            dialect = _csv_v51.Sniffer().sniff(snip, delimiters=',;\t| ')
        except Exception:
            dialect = _csv_v51.excel
        reader = _csv_v51.DictReader(_io_v51.StringIO(text), dialect=dialect)
        for i, row in enumerate(reader):
            if i >= max_rows:
                break
            rows.append({str(k).strip(): v for k, v in row.items() if k is not None})
    except Exception:
        return []
    return rows


def _v51_write_templates_once():
    inp = _v51_inputs_dir(); meas = _v51_measurements_dir(); out = _v51_outputs_dir()
    templates = {}
    templates['p36'] = _v51_write_csv(inp / 'p36_highz_object_rows_raw_template_v51.csv', [], ['source_group','object_id','z','vrot_km_s','radius_kpc','vrot_unit','radius_unit','raw_source_file','quality_flag'])
