    base['pta_weighted_kappa_residual_gate_v52']=gate | {'measurement_source_path':src,'template_path':templates['pta'],'weighted_statistic':wstat,'sky_shuffle_p':pval}
    if gate['eligible_for_confirm_like']:
        base['status']='pta_density_cross_confirm_like_v52'
