# 10) Dashboard: v52 artifact index + strict counts + full-run current-run-id check.
def run_dashboard_v52(meta,args):
    templates=_v52_templates_once(); base=_run_dashboard_v51_for_v52(meta,args)
    out=_v52_outputs_dir(); rows=[]
    for p in sorted(out.glob('test*.json')):
        if p.name.startswith('test51'): continue
        obj=_v52_read_json(p)
        if isinstance(obj,dict): rows.append(obj)
    current_ids={r.get('current_run_id_v51') or r.get('current_run_id_v52') for r in rows if r.get('current_run_id_v51') or r.get('current_run_id_v52')}
    def item(r): return {'test_id':r.get('test_id'),'prediction_id':r.get('prediction_id'),'prediction_name':r.get('prediction_name'),'status':r.get('status')}
    non_sm=[]; sm=[]; coverage=[]; blocked=[]; ready=[]; failed=[]
    for r in rows:
        st=str(r.get('status','')); pid=str(r.get('prediction_id',''))
        if 'smd_constant_consistency_confirm_like' in st: sm.append(item(r))
        elif 'coverage_confirmed' in st: coverage.append(item(r))
        elif 'confirm_like' in st and not pid.startswith('SM'): non_sm.append(item(r))
        elif any(x in st for x in ['blocked','failed','data_limited','required','not_confirmed']): blocked.append(item(r))
        else: ready.append(item(r))
        for k,v in r.items():
            if isinstance(v,dict) and 'gate_v52' in k and not v.get('eligible_for_confirm_like', True):
                failed.append({'test_id':r.get('test_id'),'prediction_id':r.get('prediction_id'),'gate':k,'missing':v.get('missing')})
    progress={}
    pr=_v52_read_json(out/'current_run_progress_v51.json')
    if isinstance(pr,dict): progress=pr
    base['dashboard_v52']={'claim_policy':'Only confirm_like statuses are scientific confirms; coverage_confirmed is exposure/coverage; ready/compatible/schema states are not evidence claims.','artifact_templates':templates,'run_progress':progress,'n_current_run_ids':len(current_ids),'current_run_ids':sorted([x for x in current_ids if x]),'all_tests_same_current_run_id':len(current_ids)<=1,'nonSM_confirm_like':non_sm,'SM_constant_consistency':sm,'coverage_confirmed':coverage,'ready_or_compatible':ready,'blocked_or_gate_failed':blocked,'failed_v52_gates':failed[:250],'n_nonSM_confirm_like':len(non_sm),'n_SM_constant_consistency':len(sm),'n_coverage_confirmed':len(coverage),'n_blocked_or_gate_failed':len(blocked)}
    base['status']='dashboard_positive_current_only_v52'
    return base


