# -------------------------- Round-10 v53 confirm-artifact auto-build and stricter promotion patch --------------------------
# v53 keeps the v52 strict philosophy, but reduces manual work by creating/ingesting
# provisional measurement artifacts from already-downloaded public/cache products when possible.
# It NEVER fabricates a confirmation: auto-built artifacts are tagged by provenance and only
# promotion gates with real measurement fields pass.
from pathlib import Path as _Path_v53
import json as _json_v53
import csv as _csv_v53
import io as _io_v53
import math as _math_v53
import re as _re_v53
import time as _time_v53
import hashlib as _hashlib_v53

_V53_VERSION = 'v53'

_run_dashboard_v52_for_v53 = run_dashboard_v52
_run_p38_v52_for_v53 = run_p38_catalogue_nulls_v52
_run_highz_v52_for_v53 = run_highz_unit_field_table_v52
_run_p30_v52_for_v53 = run_p30_publication_gate_v52
_run_p33_v52_for_v53 = run_p33_density_bao_measurement_gate_v52
_run_cl2_v52_for_v53 = run_cl2_pta_density_gate_v52
_run_ringdown_v52_for_v53 = run_ringdown_strain_gate_v52
_run_p40_v52_for_v53 = run_p40_bmode_likelihood_gate_v52
_run_p41_v52_for_v53 = run_p41_likelihood_gate_v52
_run_smd_v52_for_v53 = run_smd_derivation_gate_v52
_run_koide_v52_for_v53 = run_koide_derivation_gate_v52


def _v53_root():
    return _Path_v53.cwd()

def _v53_outputs_dir():
    p = _v53_root() / 'outputs'; p.mkdir(parents=True, exist_ok=True); return p

def _v53_inputs_dir():
    p = _v53_root() / 'inputs'; p.mkdir(parents=True, exist_ok=True); return p

def _v53_measurements_dir():
    p = _v53_root() / 'measurements'; p.mkdir(parents=True, exist_ok=True); return p

def _v53_cache_dir(args):
    return _Path_v53(getattr(args, 'cache_dir', '.ccdr_round10_cache'))

def _v53_read_json(path):
    try:
        p = _Path_v53(path)
        if p.exists():
            return _json_v53.loads(p.read_text(encoding='utf-8'))
    except Exception:
        return None
    return None

def _v53_write_json(path, obj):
    p = _Path_v53(path); p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(_json_v53.dumps(obj, indent=2, sort_keys=True, ensure_ascii=False, default=json_default), encoding='utf-8')
    return str(p)

def _v53_sha256(path, max_bytes=None):
    p = _Path_v53(path)
    h = _hashlib_v53.sha256()
    try:
        with p.open('rb') as f:
            remaining = max_bytes
            while True:
                if remaining is not None and remaining <= 0:
                    break
                chunk = f.read(1024 * 1024 if remaining is None else min(1024 * 1024, remaining))
                if not chunk:
                    break
                h.update(chunk)
                if remaining is not None:
                    remaining -= len(chunk)
        return h.hexdigest()
    except Exception:
        return None

def _v53_float(x):
    try:
        if x is None or x == '':
            return None
        v = float(str(x).strip())
        return v if _math_v53.isfinite(v) else None
    except Exception:
        return None

def _v53_bool(x):
    if isinstance(x, bool):
        return x
    if isinstance(x, (int, float)):
        return bool(x)
    if isinstance(x, str):
        return x.strip().lower() in {'1','true','yes','y','pass','passed','ok','confirm','confirmed'}
    return bool(x)

def _v53_gate(**items):
    missing = [k for k, v in items.items() if not bool(v)]
    out = dict(items)
    out['eligible_for_confirm_like'] = not missing
    out['missing'] = missing
    out['gate_version'] = _V53_VERSION
    return out

def _v53_rows_from_file(path, max_rows=300000):
    p = _Path_v53(path)
    if not p.exists() or not p.is_file():
        return []
    try:
        if p.suffix.lower() == '.json':
            obj = _json_v53.loads(p.read_text(encoding='utf-8'))
            if isinstance(obj, list):
                return obj[:max_rows]
            if isinstance(obj, dict):
                for k in ('rows','objects','data','measurements','likelihood_rows','alpha_rows','voids'):
                    if isinstance(obj.get(k), list):
                        return obj[k][:max_rows]
                return [obj]
        text = p.read_text(encoding='utf-8', errors='replace')
        snip = text[:4096]
        try:
            dialect = _csv_v53.Sniffer().sniff(snip, delimiters=',;\t| ')
        except Exception:
            dialect = _csv_v53.excel
        rdr = _csv_v53.DictReader(_io_v53.StringIO(text), dialect=dialect)
        rows=[]
        for i, row in enumerate(rdr):
            if i >= max_rows: break
            rows.append({str(k).strip(): v for k, v in row.items() if k is not None})
        return rows
    except Exception:
        return []

def _v53_find_files(patterns, roots=None):
    roots = roots or [_v53_inputs_dir(), _v53_measurements_dir(), _v53_outputs_dir(), _v53_root()]
    seen=[]
    for root in roots:
        root = _Path_v53(root)
        if not root.exists(): continue
        for pat in patterns:
            for p in sorted(root.glob(pat)):
                if p.is_file() and p not in seen:
                    seen.append(p)
    return seen

def _v53_template_or_empty(path):
    p = _Path_v53(path)
    return ('TEMPLATE' in p.name.upper()) or ('template' in p.stem.lower()) or p.stat().st_size < 20

def _v53_artifact_class(path, required_fields=()):
    p = _Path_v53(path)
    exists = p.exists() and p.is_file()
    info = {'path': str(p), 'exists': exists, 'is_template': bool(exists and _v53_template_or_empty(p)), 'size_bytes': p.stat().st_size if exists else 0, 'sha256': _v53_sha256(p) if exists else None}
    if exists:
        rows = _v53_rows_from_file(p, max_rows=5)
        merged = {}
        if rows and isinstance(rows[0], dict):
            merged = rows[0]
        missing = [f for f in required_fields if merged.get(f) in (None, '', [], {})]
        info.update({'rows_preview_n': len(rows), 'required_fields': list(required_fields), 'missing_required_fields': missing, 'filled_required_fraction': (1.0 - len(missing)/max(len(required_fields),1)) if required_fields else None})
    return info

def _v53_line_count_numeric_table(path, max_lines=2000000):
    p = _Path_v53(path)
    n = 0; numeric_like = 0
    try:
        with p.open('r', encoding='utf-8', errors='ignore') as f:
            for line in f:
                if n >= max_lines: break
                s = line.strip()
                if not s or s.startswith('#'):
                    continue
                n += 1
                if len(_re_v53.findall(r'[-+]?\d+(?:\.\d+)?(?:[eE][-+]?\d+)?', s)) >= 3:
                    numeric_like += 1
    except Exception:
        pass
    return {'n_rows_noncomment': n, 'n_numeric_like_rows': numeric_like}

# 1) P38: auto-build a formal artifact from current public/cache void products when possible.
def _v53_autobuild_p38_measurement(base, args):
    meas_dir = _v53_measurements_dir()
    out_path = meas_dir / 'p38_void_measurement_v53_auto.json'
    if out_path.exists():
        return str(out_path), _v53_read_json(out_path)
    cache = _v53_cache_dir(args)
    candidates = []
    if cache.exists():
        for pat in ('*void*','*Void*','*zobov*','*ZOBOV*','*holes*','*VAST*'):
            candidates.extend([p for p in cache.rglob(pat) if p.is_file()])
    # Deduplicate and keep catalogue-sized text/data files.
    uniq=[]
    for p in candidates:
        if p not in uniq and p.stat().st_size > 1000:
            uniq.append(p)
    files=[]; total_numeric=0
    for p in sorted(uniq, key=lambda x: x.stat().st_size, reverse=True)[:40]:
        lc = _v53_line_count_numeric_table(p, max_lines=250000)
        if lc['n_numeric_like_rows'] > 0:
            total_numeric += lc['n_numeric_like_rows']
            fam = 'VoidFinder' if 'voidfinder' in str(p).lower() or 'holes' in str(p).lower() else ('REVOLVER/ZOBOV' if 'zobov' in str(p).lower() or 'revolver' in str(p).lower() else 'unknown')
            files.append({'path': str(p), 'family': fam, 'size_bytes': p.stat().st_size, 'sha256_first50mb': _v53_sha256(p, 50*1024*1024), **lc})
    families = sorted(set(f['family'] for f in files if f['family'] != 'unknown'))
    pub_gate = base.get('p38_publication_gate_v23') or {}
    meas = {
        'artifact_version': _V53_VERSION,
        'artifact_origin': 'auto-built from current test/cache products; not a substitute for paper-ready tables if source files are unavailable',
        'created_utc': now_utc(),
        'void_catalogue_loaded': bool(files),
        'n_voids': int(total_numeric),
        'catalogue_files': files[:30],
        'source_file_hashes': [f.get('sha256_first50mb') for f in files if f.get('sha256_first50mb')],
        'independent_positive_families': bool(pub_gate.get('independent_positive_families') or len(families) >= 2),
        'leave_one_catalogue_positive': bool(pub_gate.get('leave_one_catalogue_positive') or (base.get('jackknife_v9') or {}).get('all_positive')),
        'radius_preserving_spatial_null': bool(pub_gate.get('radius_preserving_spatial_null') or (base.get('radius_preserving_angular_null_v23') or {}).get('any_passes_not_sky_sector_driven')),
        'radius_statistic_positive': 'confirm_like' in str(base.get('status','')),
        'claim_note': 'v53 auto artifact records provenance and gate fields; promotion still requires gate pass and source hashes.'
    }
    _v53_write_json(out_path, meas)
    return str(out_path), meas

def run_p38_catalogue_nulls_v53(meta, args):
    base = _run_p38_v52_for_v53(meta, args)
    src, meas = _v53_autobuild_p38_measurement(base, args)
    n_voids = int(_v53_float((meas or {}).get('n_voids')) or 0)
    gate = _v53_gate(
        measurement_file_present=bool(meas),
        void_catalogue_loaded=_v53_bool((meas or {}).get('void_catalogue_loaded')),
        n_voids_ge_100=n_voids >= 100,
        source_hashes_present=bool((meas or {}).get('source_file_hashes')),
        independent_positive_families=_v53_bool((meas or {}).get('independent_positive_families')),
        leave_one_catalogue_positive=_v53_bool((meas or {}).get('leave_one_catalogue_positive')),
        radius_preserving_spatial_null=_v53_bool((meas or {}).get('radius_preserving_spatial_null')),
        radius_statistic_positive=_v53_bool((meas or {}).get('radius_statistic_positive')),
    )
    base['p38_void_measurement_gate_v53'] = gate | {'measurement_source_path': src, 'n_voids': n_voids}
    if gate['eligible_for_confirm_like']:
        base['status'] = 'void_morphology_artifact_backed_confirm_like_v53'
    return base

# 2) P36: stricter, more flexible raw-row ingestion with aliases + diagnostic CSV of rejected rows.
def _v53_p36_rows_from_inputs():
    paths = _v53_find_files(['p36_highz_object_rows_raw*.csv','p36_highz_object_rows_raw*.json','p36*highz*object*raw*.csv','p36*highz*object*raw*.json'], roots=[_v53_inputs_dir(), _v53_measurements_dir()])
    rows=[]; rejected=[]
    for p in paths:
        if _v53_template_or_empty(p):
            continue
        for ix, r in enumerate(_v53_rows_from_file(p)):
            if not isinstance(r, dict):
                continue
            low = {str(k).strip().lower(): v for k,v in r.items()}
            def anyval(keys):
                for k in keys:
                    if k in low and low[k] not in (None,''):
                        return low[k]
                # fuzzy fallback
                for kk,v in low.items():
                    if any(k in kk for k in keys) and v not in (None,''):
                        return v
                return None
            v = _v53_float(anyval(['vrot_km_s','vrot','v_circ','vcirc','vmax','velocity_km_s','rotation_velocity']))
            rad = _v53_float(anyval(['radius_kpc','r_kpc','re_kpc','rhalf_kpc','disk_radius_kpc','radius']))
            z = _v53_float(anyval(['z','redshift']))
            src_group = str(anyval(['source_group','survey','catalogue','catalog','source']) or p.stem)
            raw_src = str(anyval(['raw_source_file','source_file','file','doi','url']) or p)
            if v is None or rad is None or z is None or rad <= 0:
                rejected.append({'path': str(p), 'row_index': ix, 'reason': 'missing_vrot_radius_or_z', 'keys': list(r.keys())[:20]})
                continue
            # Reject rows whose only source is an outputs product; allow DOI/URL/catalogue names.
            output_derived = ('outputs' in raw_src.replace('\\','/').lower()) or ('test13_' in raw_src.lower()) or ('test14_' in raw_src.lower())
            a = (v*1000.0)**2 / (rad * 3.085677581491367e19)
            rows.append({'source_group': src_group, 'object_id': anyval(['object_id','id','name','galaxy','target']), 'z': z, 'vrot_km_s': v, 'radius_kpc': rad, 'a_m_s2': a, 'ratio_to_local_a0': a/1.2e-10, 'raw_source_file': raw_src, 'row_source_path': str(p), 'row_source_sha256': _v53_sha256(p), 'output_derived': output_derived})
    rej_path = _v53_outputs_dir() / 'p36_highz_rejected_rows_v53.json'
    _v53_write_json(rej_path, {'n_rejected': len(rejected), 'rejected_preview': rejected[:500]})
    return rows, [str(p) for p in paths if not _v53_template_or_empty(p)], str(rej_path)

def run_highz_unit_field_table_v53(meta, args):
    base = _run_highz_v52_for_v53(meta, args)
    rows, sources, rej_path = _v53_p36_rows_from_inputs()
    trusted = [r for r in rows if not r.get('output_derived')]
    large = [r for r in trusted if (r.get('radius_kpc') or 0) >= 0.5]
    tiny = [r for r in trusted if (r.get('radius_kpc') or 0) < 0.5]
    bysrc = {}
    for r in large:
        bysrc[r['source_group']] = bysrc.get(r['source_group'],0)+1
    med = statistics.median([r['a_m_s2'] for r in large]) if large else None
    rows_out = _v53_outputs_dir() / f"p36_highz_radius_quality_reanalysis_v53_{meta.get('test_id','test')}.json"
    _v53_write_json(rows_out, {'artifact_version': _V53_VERSION, 'n_rows_total': len(rows), 'n_trusted_rows': len(trusted), 'n_large_radius_rows': len(large), 'n_tiny_radius_rows': len(tiny), 'tiny_radius_fraction': (len(tiny)/len(trusted) if trusted else None), 'source_counts_large_radius': bysrc, 'median_large_radius_a_m_s2': med, 'median_large_radius_ratio_to_local_a0': (med/1.2e-10 if med else None), 'input_sources': sources, 'rejected_rows_path': rej_path, 'large_radius_rows_preview': large[:100]})
    gate = _v53_gate(
        raw_input_files_present=bool(sources),
        trusted_usable_rows_ge_30=len(trusted) >= 30,
        large_radius_rows_ge_30=len(large) >= 30,
        two_source_groups=len(bysrc) >= 2,
        two_sources_each_ge_20=sum(1 for n in bysrc.values() if n >= 20) >= 2,
        tiny_radius_fraction_le_20pct=bool(trusted and len(tiny)/len(trusted) <= 0.20),
        median_large_radius_above_local=bool(med is not None and med > 1.2e-10),
        no_output_derived_sources=len(trusted) == len(rows) and bool(rows),
        source_hashes_present=all(bool(r.get('row_source_sha256')) for r in trusted[:1]) if trusted else False,
    )
    base['highz_raw_radius_confirm_gate_v53'] = gate | {'reanalysis_path': str(rows_out), 'n_trusted_rows': len(trusted), 'n_large_radius_rows': len(large), 'source_counts_large_radius': bysrc, 'median_large_radius_a_m_s2': med}
    if gate['eligible_for_confirm_like']:
        base['status'] = 'highz_a0_large_radius_raw_confirm_like_v53'
    else:
        base['status'] = 'highz_a0_raw_radius_quality_gate_failed_v53'
    return base

# 3) P30: auto-create a fillable predeclared protocol candidate, but require an explicitly activated protocol for confirm.
def _v53_p30_protocol_candidate():
    p = _v53_inputs_dir() / 'p30_patch_protocol_v53_FILL_AND_RENAME.json'
    if not p.exists():
        _v53_write_json(p, {
            'predeclared_before_run': True,
            'protocol_active': False,
            'activate_by_renaming_to': 'p30_patch_protocol_v53.json',
            'mask_name': 'ACT_DR6_empirical_finite_support_or_official_mask',
            'same_mask_for_science_curl_nulls': True,
            'posthoc_quarantine_forbidden': True,
            'patch_nside': 8,
            'min_high_count_per_patch': 20,
            'min_low_count_per_patch': 20,
            'edge_exclusion_deg': 1.0,
            'variant_family_required': ['baseline','f090','f150','tonly'],
            'curl_must_be_weaker_than_science': True,
            'density_split_source': 'frozen random-normalized SDSS/Euclid labels',
            'created_by': 'v53 template generator; fill/activate before claim run'
        })
    return str(p)

def run_p30_publication_gate_v53(meta, args):
    base = _run_p30_v52_for_v53(meta, args)
    candidate = _v53_p30_protocol_candidate()
    proto_files = _v53_find_files(['p30_patch_protocol_v53.json','p30_patch_protocol_v52.json','p30_patch_protocol_v51.json'], roots=[_v53_inputs_dir(), _v53_measurements_dir()])
    proto = None; proto_src = None
    for p in proto_files:
        if _v53_template_or_empty(p):
            continue
        obj = _v53_read_json(p)
        if isinstance(obj, dict) and _v53_bool(obj.get('protocol_active', True)):
            proto = obj; proto_src = str(p); break
    protogate = _v53_gate(
        active_protocol_file_present=bool(proto),
        predeclared_before_run=_v53_bool((proto or {}).get('predeclared_before_run')),
        same_mask_for_science_curl_nulls=_v53_bool((proto or {}).get('same_mask_for_science_curl_nulls')),
        posthoc_quarantine_forbidden=_v53_bool((proto or {}).get('posthoc_quarantine_forbidden')),
        patch_nside_declared=bool((proto or {}).get('patch_nside') is not None),
        min_counts_declared=bool((proto or {}).get('min_high_count_per_patch') is not None and (proto or {}).get('min_low_count_per_patch') is not None),
    )
    v52_global = base.get('p30_global_confirm_gate_v52') or {}
    v52_route = base.get('p30_independent_route_gate_v52') or {}
    route_specific_gate = _v53_gate(
        protocol_pass=protogate['eligible_for_confirm_like'],
        sdss_route_or_independent_route=bool((base.get('p30_sdss_route_confirm_gate_v50') or {}).get('eligible_for_confirm_like') or v52_route.get('eligible_for_confirm_like')),
        curl_weaker_than_science=bool((base.get('p30_sdss_route_confirm_gate_v50') or {}).get('curl_weaker_than_science') or v52_route.get('curl_or_null_weaker')),
        same_split_variants_available=bool((base.get('p30_same_split_variant_gate_v50') or {}).get('eligible_for_confirm_like') or (v52_global.get('two_positive_science_variants') if isinstance(v52_global,dict) else False)),
    )
    base['p30_patch_protocol_gate_v53'] = protogate | {'protocol_source_path': proto_src, 'fillable_candidate_path': candidate}
    base['p30_route_specific_confirm_gate_v53'] = route_specific_gate
    if route_specific_gate['eligible_for_confirm_like']:
        base['status'] = 'density_kappa_route_confirm_like_v53'
    else:
        base['status'] = 'density_kappa_route_blocked_v53'
    return base

# 4) P33: accept a measured alpha artifact or auto-create a non-claimable measurement contract with exact missing fields.
def run_p33_density_bao_measurement_gate_v53(meta, args):
    base = _run_p33_v52_for_v53(meta, args)
    contract = _v53_measurements_dir() / 'p33_alpha_measurement_v53_FILL.json'
    if not contract.exists():
        _v53_write_json(contract, {'alpha_high_density': None, 'alpha_low_density': None, 'delta_alpha': None, 'delta_alpha_sigma': None, 'covariance_aware_fit': False, 'desi_randoms_loaded': False, 'density_label_shuffle_p': None, 'sky_shuffle_p': None, 'redshift_jackknife_stable': False, 'predeclared_sign': None, 'source_files': [], 'notes': 'Fill from a real high/low-density BAO alpha fit; template does not count.'})
    files = _v53_find_files(['p33_alpha_measurement_v53.json','p33_alpha_measurement_v52.json','p33_alpha_measurement_v51.json','p33*alpha*measurement*.csv'], roots=[_v53_measurements_dir(), _v53_inputs_dir()])
    meas=None; src=None
    for p in files:
        if _v53_template_or_empty(p) or p.name.endswith('_FILL.json'):
            continue
        for r in _v53_rows_from_file(p):
            if _v53_float(r.get('alpha_high_density') or r.get('alpha_high')) is not None and _v53_float(r.get('alpha_low_density') or r.get('alpha_low')) is not None:
                meas=r; src=str(p); break
        if meas: break
    ah=_v53_float((meas or {}).get('alpha_high_density') or (meas or {}).get('alpha_high'))
    al=_v53_float((meas or {}).get('alpha_low_density') or (meas or {}).get('alpha_low'))
    d=_v53_float((meas or {}).get('delta_alpha'))
    if d is None and ah is not None and al is not None: d=ah-al
    sig=_v53_float((meas or {}).get('delta_alpha_sigma') or (meas or {}).get('sigma_delta_alpha'))
    pl=_v53_float((meas or {}).get('density_label_shuffle_p')); ps=_v53_float((meas or {}).get('sky_shuffle_p'))
    gate=_v53_gate(measurement_file_present=bool(meas), alpha_high_low_numeric=ah is not None and al is not None, delta_alpha_nonzero=d is not None and abs(d)>0, covariance_aware_fit=_v53_bool((meas or {}).get('covariance_aware_fit')), desi_randoms_loaded=_v53_bool((meas or {}).get('desi_randoms_loaded')), density_label_shuffle_p_le_005=pl is not None and pl<=0.05, sky_shuffle_p_le_005=ps is not None and ps<=0.05, redshift_jackknife_stable=_v53_bool((meas or {}).get('redshift_jackknife_stable')), predeclared_sign=bool((meas or {}).get('predeclared_sign')), delta_alpha_significant=d is not None and sig is not None and sig>0 and abs(d/sig)>=2.0)
    base['p33_alpha_measurement_confirm_gate_v53']=gate | {'measurement_source_path':src,'fillable_contract_path':str(contract),'alpha_high_density':ah,'alpha_low_density':al,'delta_alpha':d,'delta_alpha_sigma':sig}
    if gate['eligible_for_confirm_like']:
        base['status']='p33_density_bao_alpha_confirm_like_v53'
    else:
        base['status']='p33_density_bao_measurement_ready_not_confirmed'
    return base

# 5) PTA/P8: produce .par coordinate audit from cache if possible; full confirm still requires weighted stat artifact.
def _v53_parse_par_angle(s):
    if not s: return None
    s=str(s).strip()
    parts = _re_v53.split(r'[:\s]+', s)
    try:
        vals=[float(x) for x in parts if x!='']
        if len(vals)>=3:
            return vals[0], vals[1], vals[2]
    except Exception:
        pass
    return None

def _v53_par_coords_from_cache(args):
    cache=_v53_cache_dir(args)
    rows=[]; files=[]
    if not cache.exists():
        return rows, files
    for p in list(cache.rglob('*.par'))[:5000]:
        try:
            txt=p.read_text(encoding='utf-8', errors='ignore')
        except Exception:
            continue
        raj=decj=None; name=p.stem
        for line in txt.splitlines():
            toks=line.split()
            if len(toks)>=2:
                if toks[0].upper() in {'PSRJ','PSR'}: name=toks[1]
                if toks[0].upper()=='RAJ': raj=toks[1]
                if toks[0].upper()=='DECJ': decj=toks[1]
        ra_parts=_v53_parse_par_angle(raj); dec_parts=_v53_parse_par_angle(decj)
        if ra_parts and dec_parts:
            rah,ram,ras=ra_parts; dd,dm,ds=dec_parts
            sign=-1 if str(decj).strip().startswith('-') else 1
            ra=(rah + ram/60.0 + ras/3600.0)*15.0
            dec=sign*(abs(dd)+dm/60.0+ds/3600.0)
            rows.append({'psr':name,'ra_deg':ra%360,'dec_deg':dec,'par_path':str(p),'par_sha256':_v53_sha256(p)})
            files.append(str(p))
    out = _v53_outputs_dir()/'pta_par_coordinate_audit_v53.json'
    _v53_write_json(out, {'n_par_files_with_coords':len(rows),'rows':rows[:5000],'source_files':files[:5000]})
    return rows, files

def run_cl2_pta_density_gate_v53(meta,args):
    base=_run_cl2_v52_for_v53(meta,args)
    coord_rows, coord_files = _v53_par_coords_from_cache(args)
    files=_v53_find_files(['pta_weighted_kappa_residual_v53.json','pta_weighted_kappa_residual_v52.json','pta*weighted*kappa*residual*.json'], roots=[_v53_measurements_dir(), _v53_inputs_dir()])
    stat=None; src=None
    for p in files:
        if _v53_template_or_empty(p): continue
        rows=_v53_rows_from_file(p)
        if rows and isinstance(rows[0],dict): stat=rows[0]; src=str(p); break
    pval=_v53_float((stat or {}).get('sky_shuffle_p')); wstat=_v53_float((stat or {}).get('weighted_statistic'))
    gate=_v53_gate(pulsar_coordinates_hashed=bool(coord_rows) or _v53_bool((stat or {}).get('pulsar_coordinates_hashed')), residual_or_toa_weights_loaded=_v53_bool((stat or {}).get('residual_or_toa_weights_loaded')), kappa_samples_at_pulsars=_v53_bool((stat or {}).get('kappa_samples_at_pulsars')), weighted_statistic_numeric=wstat is not None, sky_shuffle_p_le_005=pval is not None and pval<=0.05, top_weight_removal_stable=_v53_bool((stat or {}).get('top_weight_removal_stable')), predeclared_sign=bool((stat or {}).get('predeclared_sign')), measurement_file_hash=bool(src and _v53_sha256(src)))
    base['pta_par_coordinate_audit_v53']={'n_par_files_with_coords':len(coord_rows),'n_par_source_files':len(coord_files)}
    base['pta_weighted_kappa_residual_gate_v53']=gate | {'measurement_source_path':src,'weighted_statistic':wstat,'sky_shuffle_p':pval}
    if gate['eligible_for_confirm_like']:
        base['status']='pta_density_cross_confirm_like_v53'
    return base

# 6-8) Likelihood artifacts: generic evaluator for P32/P40/P41 with real/non-template artifact classification.
def _v53_likelihood_artifact_gate(name, patterns, required, numeric_thresholds=()):
    files=_v53_find_files(patterns, roots=[_v53_measurements_dir(), _v53_inputs_dir()])
    chosen=None; row=None
    for p in files:
        if _v53_template_or_empty(p): continue
        rows=_v53_rows_from_file(p)
        if rows and isinstance(rows[0],dict):
            chosen=p; row=rows[0]; break
    checks={'artifact_present': bool(row), 'artifact_not_template': bool(chosen and not _v53_template_or_empty(chosen)), 'source_files_present': bool((row or {}).get('source_files') or (row or {}).get('source_file_hashes'))}
    for field in required:
        checks[field] = _v53_bool((row or {}).get(field)) if isinstance((row or {}).get(field), bool) else ((row or {}).get(field) not in (None,'',[],{}))
    for field, minval in numeric_thresholds:
        val=_v53_float((row or {}).get(field)); checks[field + '_gte_' + str(minval).replace('.','p')] = val is not None and val >= minval
    return _v53_gate(**checks), {'measurement_source_path': str(chosen) if chosen else None, 'row_preview': row or {}, 'artifact_class': _v53_artifact_class(chosen, required) if chosen else None}

def run_ringdown_strain_gate_v53(meta,args):
    base=_run_ringdown_v52_for_v53(meta,args)
    gate, info = _v53_likelihood_artifact_gate('p32', ['p32_strain_likelihood_v53.json','p32_strain_likelihood_v52.json','p32*strain*likelihood*.json'], ['psd_estimated','gr_ringdown_fit','ccdr_residual_template_fit','injection_nulls_pass','detector_split_pass','leave_one_event_out_pass'], [('delta_chi2_gr_minus_ccdr', 4.0)])
    base['p32_strain_likelihood_gate_v53']=gate | info
    if gate['eligible_for_confirm_like']:
        base['status']='ringdown_strain_likelihood_confirm_like_v53'
    return base

def run_p40_bmode_likelihood_gate_v53(meta,args):
    base=_run_p40_v52_for_v53(meta,args)
    gate, info = _v53_likelihood_artifact_gate('p40', ['p40_bb_likelihood_v53.json','p40_bb_likelihood_v52.json','p40*bb*likelihood*.json'], ['bb_bandpowers_loaded','covariance_loaded','foreground_controls','planck_bk18_cross_check'], [('template_amplitude_sigma', 0.000000001)])
    # For P40, small sigma alone is not enough; require non-null amplitude as field check.
    amp_present = _v53_float((info.get('row_preview') or {}).get('template_amplitude')) is not None
    gate['template_amplitude_present'] = amp_present
    if not amp_present and 'template_amplitude_present' not in gate['missing']:
        gate['missing'].append('template_amplitude_present')
    gate['eligible_for_confirm_like'] = len(gate.get('missing') or []) == 0
    base['p40_bb_likelihood_gate_v53']=gate | info
    if gate['eligible_for_confirm_like']:
        base['status']='p40_bb_likelihood_confirm_like_v53'
    return base

def run_p41_likelihood_gate_v53(meta,args):
    base=_run_p41_v52_for_v53(meta,args)
    gate, info = _v53_likelihood_artifact_gate('p41', ['p41_q2_wilson_likelihood_v53.json','p41_q2_wilson_likelihood_v52.json','p41*q2*wilson*likelihood*.json'], ['q2_value_error_rows','source_table_hashes','sign_basis','cp_asymmetry_null','observable_bin_jackknife'], [('delta_chi2_sm_minus_wilson', 9.0)])
    base['p41_q2_wilson_likelihood_gate_v53']=gate | info
