# 10) Dashboard: strict template ignoring and filled-artifact counts.
def _v54_artifact_index():
    required={
        'p36_highz_raw':['source_group','object_id','z','vrot_km_s','radius_kpc','raw_source_file'],
        'p38_void':['void_catalogue_loaded','n_voids','source_file_hashes'],
        'p30_protocol':['predeclared_before_run','same_mask_for_science_curl_nulls','patch_nside'],
        'p30_route':['route','independent_route_positive','science_delta','sky_shuffle_p_high'],
        'p33_alpha':['alpha_high_density','alpha_low_density','delta_alpha','covariance_aware_fit'],
        'pta':['weighted_statistic','sky_shuffle_p','predeclared_sign'],
        'p32':['psd_estimated','gr_ringdown_fit','ccdr_residual_template_fit','delta_chi2_gr_minus_ccdr'],
        'p40':['bb_bandpowers_loaded','covariance_loaded','template_amplitude','template_amplitude_sigma'],
        'p41':['q2_value_error_rows','delta_chi2_sm_minus_wilson','cp_asymmetry_null'],
        'smd':['predicted_value','uncertainty_sigma','residual_sigma','no_target_fit'],
    }
    patterns={
        'p36_highz_raw':['p36_highz_object_rows_raw*'], 'p38_void':['p38_void_measurement*'], 'p30_protocol':['p30_patch_protocol*'], 'p30_route':['p30_independent_route*'], 'p33_alpha':['p33_alpha_measurement*'], 'pta':['pta_weighted_kappa_residual*'], 'p32':['p32_strain_likelihood*'], 'p40':['p40_bb_likelihood*'], 'p41':['p41_q2_wilson_likelihood*'], 'smd':['smd_derivation_predictions*']}
    idx=[]
    for key,pats in patterns.items():
        for p in _v54_find_files(pats, roots=[_v54_inputs_dir(), _v54_measurements_dir(), _v54_outputs_dir()]):
            rows=_v54_rows_from_file(p, max_rows=3)
            row=rows[0] if rows else {}
            missing=[]
            for f in required.get(key,[]):
                if row.get(f) in (None,'',[],{}) and (not isinstance(row.get(f), bool)):
                    missing.append(f)
            idx.append({'artifact_key':key,'path':str(p),'exists':p.exists(),'is_template':_v54_is_template_path(p),'size_bytes':p.stat().st_size if p.exists() else 0,'sha256':_v54_sha256(p),'missing_required_fields':missing,'filled_and_usable':p.exists() and not _v54_is_template_path(p) and not missing})
    return idx


def run_dashboard_v54(meta,args):
    base=_run_dashboard_v53_for_v54(meta,args)
    rows=[]
    for p in sorted(_v54_outputs_dir().glob('test*.json')):
        if p.name.startswith('test51'): continue
        obj=_v54_read_json(p)
        if isinstance(obj,dict): rows.append(obj)
    artifact_index=_v54_artifact_index()
    confirms=[]; sm=[]; coverage=[]; blocked=[]; ready=[]; failed=[]
    for r in rows:
        st=str(r.get('status','')); pid=str(r.get('prediction_id',''))
        item={'test_id':r.get('test_id'),'prediction_id':pid,'prediction_name':r.get('prediction_name'),'status':st}
        if 'coverage_confirmed' in st: coverage.append(item)
        elif 'smd_constant_consistency_confirm_like' in st: sm.append(item)
        elif 'confirm_like' in st and not pid.startswith('SM'): confirms.append(item)
        elif any(x in st for x in ['blocked','failed','data_limited','required','not_confirmed']): blocked.append(item)
        else: ready.append(item)
        for k,v in r.items():
            if isinstance(v,dict) and ('gate_v54' in k or 'gate_v53' in k) and not v.get('eligible_for_confirm_like', True):
                failed.append({'test_id':r.get('test_id'),'prediction_id':pid,'gate':k,'missing':v.get('missing')})
    priority=[]
    for tid,pid,artifact in [('R10-T13','P36 high-z','inputs/p36_highz_object_rows_raw.csv'),('R10-T10','P38','measurements/p38_void_measurement_v54_auto.json'),('R10-T04','P30','inputs/p30_patch_protocol_v54.json + measurements/p30_independent_route_v54.json'),('R10-T07','P33','measurements/p33_alpha_measurement_v54.json'),('R10-T17','PTA/CL2','measurements/pta_weighted_kappa_residual_v54.json'),('R10-T19','P32','measurements/p32_strain_likelihood_v54.json')]:
        row=next((r for r in rows if r.get('test_id')==tid),{})
        priority.append({'test_id':tid,'prediction':pid,'current_status':row.get('status'),'next_artifact':artifact})
    base['dashboard_v54']={'claim_policy':'v54 ignores all TEMPLATE/FILL artifacts for promotion. Confirm-like requires non-template measurement artifacts or already passed older publication gates with hashes.','artifact_index':artifact_index,'n_artifacts':len(artifact_index),'n_filled_usable_artifacts':sum(1 for a in artifact_index if a.get('filled_and_usable')),'nonSM_confirm_like':confirms,'SM_constant_consistency':sm,'coverage_confirmed':coverage,'ready_or_compatible':ready,'blocked_or_gate_failed':blocked,'failed_gates':failed[:300],'confirm_recovery_priority':priority,'n_nonSM_confirm_like':len(confirms),'n_SM_constant_consistency':len(sm),'n_coverage_confirmed':len(coverage),'n_blocked_or_gate_failed':len(blocked)}
    base['status']='dashboard_positive_current_only_v54'
    return base


