# -------------------------- Round-10 v55 confirm recovery --------------------------
_V55_VERSION = "v55"

def _v55_to_float(x):
    try:
        if x is None:
            return None
        s = str(x).strip().replace(",", "")
        if not s or s.lower() in {"nan", "none", "null", "na", "n/a"}:
            return None
        return float(s)
    except Exception:
        return None

def _v55_truthy(x):
    if isinstance(x, bool):
        return x
    if x is None:
        return False
    return str(x).strip().lower() in {"1", "true", "yes", "y", "ok", "pass", "passed"}

def _v55_first(row, aliases):
    lower = {str(k).strip().lower(): v for k, v in (row or {}).items()}
    for a in aliases:
        if a in row and row.get(a) not in (None, ""):
            return row.get(a)
        aa = str(a).strip().lower()
        if aa in lower and lower[aa] not in (None, ""):
            return lower[aa]
    return None

def _v55_not_template_path(p):
    return not _v54_is_template_path(p) and "AUTO_PREDECLARED_FOR_NEXT_RUN" not in str(p).upper() and "_FILL" not in str(p).upper()

def _v55_artifact_row(path):
    rows = _v54_rows_from_file(path, max_rows=200000)
    if not rows:
        return {}
    return rows[0] if isinstance(rows[0], dict) else {}

def _v55_write_json(path, obj):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(obj, indent=2, sort_keys=True, ensure_ascii=False), encoding="utf-8")
    return path

def _v55_write_csv(path, rows, fields):
    path = Path(path); path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=fields)
        w.writeheader()
        for r in rows:
            w.writerow({k: r.get(k, "") for k in fields})
    return path

def _v55_candidate_files(patterns, roots=None):
    roots = roots or [_v54_inputs_dir(), _v54_measurements_dir(), _v54_outputs_dir(), Path(".ccdr_round10_cache")]
    files = []
    for root in roots:
        root = Path(root)
        if not root.exists():
            continue
        for pat in patterns:
            try:
                files.extend(root.rglob(pat))
            except Exception:
                pass
    out = []
    seen = set()
    for p in files:
        try:
            key = str(p.resolve()).lower()
        except Exception:
            key = str(p).lower()
        if key not in seen and p.is_file():
            seen.add(key); out.append(p)
    return out

# 1-2) P36 high-z: build a strict raw-row normalized artifact, diagnostics, large-radius gate.
def _v55_normalize_highz_rows(max_files=80):
    patterns = [
        "p36_highz_object_rows_raw*.csv", "p36_highz_object_rows_raw*.json",
        "*KGES*.csv", "*KGES*.json", "*KROSS*.csv", "*KROSS*.json",
        "*KMOS3D*.csv", "*KMOS3D*.json", "*SAMI*.csv", "*SAMI*.json",
        "*highz*a0*.csv", "*highz*a0*.json", "*vrot*.csv", "*rotation*.csv",
    ]
    files = _v55_candidate_files(patterns, roots=[_v54_inputs_dir(), _v54_measurements_dir(), Path(".ccdr_round10_cache")])[:max_files]
    normalized, rejected = [], []
    for p in files:
        if _v54_is_template_path(p):
            continue
        rows = _v54_rows_from_file(p, max_rows=200000)
        source_hash = _v54_sha256(p)
        for i, row in enumerate(rows):
            if not isinstance(row, dict):
                rejected.append({"path": str(p), "row_index": i, "reason": "non_dict_row"})
                continue
            src = _v55_first(row, ["source_group", "source", "survey", "catalogue", "catalog", "dataset", "sample"])
            obj = _v55_first(row, ["object_id", "object", "id", "name", "galaxy", "target", "gal_id", "kid"])
            z = _v55_to_float(_v55_first(row, ["z", "redshift", "z_best", "zspec", "z_spec"]))
            v = _v55_to_float(_v55_first(row, ["vrot_km_s", "v_rot_km_s", "vrot", "v_rot", "vcirc", "v_circ", "vmax", "vmax_km_s", "velocity_km_s", "v_km_s"]))
            r = _v55_to_float(_v55_first(row, ["radius_kpc", "r_kpc", "r_d_kpc", "rd_kpc", "re_kpc", "r_eff_kpc", "radius", "R_kpc", "R"]))
            raw = _v55_first(row, ["raw_source_file", "source_file", "source_path", "file", "path", "__source_artifact", "source_url_or_path"])
            if not src:
                # infer source from filename
                name = p.name.lower()
                if "kges" in name: src = "KGES"
                elif "kross" in name: src = "KROSS"
                elif "kmos" in name: src = "KMOS3D"
                elif "sami" in name: src = "SAMI"
            if not obj:
                obj = f"{p.stem}:{i}"
            if not raw:
                raw = str(p)
            reasons = []
            if not src: reasons.append("missing_source_group")
            if z is None: reasons.append("missing_or_bad_z")
            if v is None or v <= 0: reasons.append("missing_or_bad_vrot_km_s")
            if r is None or r <= 0: reasons.append("missing_or_bad_radius_kpc")
            if "outputs" in str(raw).lower(): reasons.append("output_derived_source")
            if reasons:
                rejected.append({"path": str(p), "row_index": i, "object_id": obj, "source_group": src, "raw_source_file": str(raw), "reason": ";".join(reasons)})
                continue
            acc = (v * 1000.0) ** 2 / (r * 3.0856775814913673e19)
            row_hash = hashlib.sha256(json.dumps({"src":src,"obj":obj,"z":z,"v":v,"r":r,"raw":str(raw)}, sort_keys=True).encode()).hexdigest()
            normalized.append({
                "source_group": str(src),
                "object_id": str(obj),
                "z": z,
                "vrot_km_s": v,
                "radius_kpc": r,
                "accel_m_s2": acc,
                "raw_source_file": str(raw),
                "source_file_hash": source_hash,
                "row_hash": row_hash,
                "input_file": str(p),
                "large_radius": bool(r >= 0.5),
            })
    # Deduplicate by source+object+z+v+r
    dedup = []
    seen = set()
    for r in normalized:
        k = (r["source_group"], r["object_id"], round(float(r["z"]), 6), round(float(r["vrot_km_s"]), 6), round(float(r["radius_kpc"]), 6))
        if k in seen:
            continue
        seen.add(k); dedup.append(r)
    norm_path = _v54_outputs_dir() / "p36_highz_object_rows_normalized_v55.csv"
    if dedup:
        _v55_write_csv(norm_path, dedup, ["source_group","object_id","z","vrot_km_s","radius_kpc","accel_m_s2","raw_source_file","source_file_hash","row_hash","input_file","large_radius"])
    rej_path = _v54_outputs_dir() / "p36_highz_rejected_rows_v55.json"
    _v55_write_json(rej_path, {"version": _V55_VERSION, "n_candidate_files": len(files), "n_normalized_rows": len(dedup), "n_rejected_rows": len(rejected), "normalized_path": str(norm_path), "rejected": rejected[:2000]})
    return dedup, {"candidate_files": [str(p) for p in files], "normalized_path": str(norm_path), "rejected_path": str(rej_path), "n_rejected": len(rejected)}

def _v55_highz_gate_from_rows(rows, test_id=""):
    import statistics
    trusted = [r for r in rows if "outputs" not in str(r.get("raw_source_file","")).lower()]
    large = [r for r in trusted if _v55_truthy(r.get("large_radius")) or (_v55_to_float(r.get("radius_kpc")) or 0) >= 0.5]
    tiny = [r for r in trusted if (_v55_to_float(r.get("radius_kpc")) or 0) < 0.5]
    by_source = {}
    for r in large:
        by_source.setdefault(str(r.get("source_group")), 0)
        by_source[str(r.get("source_group"))] += 1
    two_sources_with20 = sum(1 for v in by_source.values() if v >= 20) >= 2
    accel = [float(r.get("accel_m_s2")) for r in large if _v55_to_float(r.get("accel_m_s2")) is not None]
    med = statistics.median(accel) if accel else None
    local_a0 = 9.55e-11
    missing = []
    if len(trusted) < 30: missing.append("n_trusted_rows_ge_30")
    if len(large) < 30: missing.append("n_large_radius_rows_ge_30")
    if len(by_source) < 2: missing.append("n_source_groups_ge_2")
    if not two_sources_with20: missing.append("two_sources_with_ge20_large_radius_rows")
    if trusted and len(tiny) / max(1, len(trusted)) > 0.20: missing.append("tiny_radius_fraction_le_20pct")
    if med is None or med <= local_a0: missing.append("large_radius_median_accel_gt_local_a0")
    gate = {
        "gate_version": _V55_VERSION,
        "n_trusted_rows": len(trusted),
        "n_large_radius_rows": len(large),
        "n_tiny_radius_rows": len(tiny),
        "tiny_radius_fraction": len(tiny) / max(1, len(trusted)),
        "n_source_groups_large_radius": len(by_source),
        "large_radius_rows_by_source": by_source,
        "large_radius_median_accel_m_s2": med,
        "local_a0_reference_m_s2": local_a0,
        "missing": missing,
        "eligible_for_confirm_like": not missing,
        "claim_policy": "v55 promotes high-z P36 only from non-output raw rows with large-radius support across independent sources.",
    }
    out = _v54_outputs_dir() / f"p36_highz_radius_quality_reanalysis_v55_{test_id or 'unknown'}.json"
    _v55_write_json(out, gate)
    gate["artifact_path"] = str(out)
    return gate

_run_highz_v54_for_v55 = run_highz_unit_field_table_v54
def run_highz_unit_field_table_v55(meta, args):
    base = _run_highz_v54_for_v55(meta, args)
    rows, build = _v55_normalize_highz_rows()
    gate = _v55_highz_gate_from_rows(rows, meta.get("test_id",""))
    gate["builder"] = build
    base["p36_highz_raw_builder_v55"] = build
    base["p36_highz_large_radius_gate_v55"] = gate
    if gate.get("eligible_for_confirm_like"):
        base["status"] = "highz_a0_raw_large_radius_confirm_like_v55"
        base["interpretation"] = "P36 high-z passed strict v55 raw-row + large-radius + multi-source gate."
    else:
        base["status"] = "highz_a0_raw_large_radius_gate_failed_v55"
        base["interpretation"] = "P36 high-z still lacks strict raw large-radius multi-source support."
    return base

# 3-5) P30: active predeclared protocol, same-mask route proof, independent route.
def _v55_active_p30_protocol():
    candidates = []
    for name in ["p30_patch_protocol_v55.json", "p30_patch_protocol_v54.json", "p30_patch_protocol_active.json"]:
        candidates += _v55_candidate_files([name], roots=[_v54_inputs_dir(), _v54_measurements_dir()])
    for p in candidates:
        if p.exists() and _v55_not_template_path(p):
            row = _v55_artifact_row(p)
            if row:
                return p, row
    # Write a fillable next-run active protocol, but do not count it in this run.
    fill = _v54_inputs_dir() / "p30_patch_protocol_v55_FILL_BEFORE_RUN.json"
    if not fill.exists():
        _v55_write_json(fill, {
            "version": _V55_VERSION,
            "fill_before_run": True,
            "predeclared_before_run": True,
            "patch_nside": 16,
            "min_high_count": 20,
            "min_low_count": 20,
            "edge_exclusion_deg": 1.0,
            "same_mask_for_science_curl_nulls": True,
            "same_density_labels_for_variants": True,
            "post_hoc_quarantine_allowed": False,
            "mask_identity_sha256": "FILL_WITH_MASK_HASH",
        })
    return None, {}

def _v55_p30_route_artifact_from_outputs():
    # Prefer explicit measurement artifact.
    for p in _v55_candidate_files(["p30_same_mask_route_v55*.json", "p30_same_mask_route*.json", "p30_independent_route_v55*.json", "p30_independent_route_v54*.json"], roots=[_v54_measurements_dir(), _v54_outputs_dir()]):
        if not _v55_not_template_path(p): 
            continue
        row = _v55_artifact_row(p)
        if row:
            return p, row
    return None, {}

_run_p30_v54_for_v55 = run_p30_publication_gate_v54
def run_p30_publication_gate_v55(meta,args):
    base = _run_p30_v54_for_v55(meta,args)
    proto_path, proto = _v55_active_p30_protocol()
    route_path, route = _v55_p30_route_artifact_from_outputs()
    missing = []
    if not proto_path: missing.append("active_predeclared_protocol_file")
    if not _v55_truthy(proto.get("predeclared_before_run")): missing.append("protocol_predeclared_before_run")
    if not _v55_truthy(proto.get("same_mask_for_science_curl_nulls")): missing.append("same_mask_for_science_curl_nulls")
    if not _v55_truthy(proto.get("same_density_labels_for_variants")): missing.append("same_density_labels_for_variants")
    if _v55_truthy(proto.get("post_hoc_quarantine_allowed")): missing.append("no_post_hoc_quarantine")
    if not route_path: missing.append("same_mask_or_independent_route_artifact")
    if route_path and not _v55_truthy(route.get("same_mask_for_science_curl_nulls")): missing.append("route_same_mask_for_science_curl_nulls")
    if route_path and not _v55_truthy(route.get("same_density_labels_for_variants")): missing.append("route_same_density_labels_for_variants")
    if route_path and not _v55_truthy(route.get("curl_weaker_than_science")): missing.append("route_curl_weaker_than_science")
    if route_path and not _v55_truthy(route.get("independent_route_positive")) and not _v55_truthy(route.get("sdss_route_positive")): missing.append("route_positive")
    gate = {
        "gate_version": _V55_VERSION,
        "protocol_path": str(proto_path) if proto_path else None,
        "route_path": str(route_path) if route_path else None,
        "protocol": proto,
        "route": route,
        "missing": missing,
        "eligible_for_route_confirm": len(missing) == 0,
        "claim_policy": "v55 requires an active protocol filled before the run plus a same-mask route proof; auto/FILL artifacts are never current-run evidence.",
    }
    base["p30_same_mask_route_gate_v55"] = gate
    if gate["eligible_for_route_confirm"]:
        base["status"] = "density_kappa_same_mask_route_confirm_like_v55"
    else:
        base["status"] = "density_kappa_same_mask_route_blocked_v55"
    return base

# 6) P33: convert legacy alpha artifacts only if actually measured, otherwise write a strict fill contract.
def _v55_find_p33_alpha_artifact():
    pats = ["p33_alpha_measurement_v55*.json", "p33_alpha_measurement_v54*.json", "p33_density_split_alpha_measurement_v*.json", "p33_*alpha*measurement*.json"]
    for p in _v55_candidate_files(pats, roots=[_v54_measurements_dir(), _v54_outputs_dir()]):
        if not _v55_not_template_path(p):
            continue
        row = _v55_artifact_row(p)
        if not row:
            continue
        # Normalize common legacy field names.
        if "alpha_high_density" not in row:
            for k in ["alpha_high", "high_alpha", "alpha_hi", "alpha_density_high"]:
                if k in row: row["alpha_high_density"] = row.get(k)
        if "alpha_low_density" not in row:
            for k in ["alpha_low", "low_alpha", "alpha_lo", "alpha_density_low"]:
                if k in row: row["alpha_low_density"] = row.get(k)
        ah = _v55_to_float(row.get("alpha_high_density"))
        al = _v55_to_float(row.get("alpha_low_density"))
        if ah is not None and al is not None:
            row["delta_alpha"] = row.get("delta_alpha", ah - al)
            return p, row
    fill = _v54_measurements_dir() / "p33_alpha_measurement_v55_FILL.json"
    if not fill.exists():
        _v55_write_json(fill, {"version":_V55_VERSION,"alpha_high_density":"FILL","alpha_low_density":"FILL","delta_alpha":"FILL","covariance_aware_fit":True,"desi_randoms_used":True,"density_label_shuffle_p":"FILL","sky_shuffle_p":"FILL","redshift_jackknife_stable":True,"predeclared_sign":"FILL"})
    return None, {}

_run_p33_v54_for_v55 = run_p33_density_bao_measurement_gate_v54
def run_p33_density_bao_measurement_gate_v55(meta,args):
    base = _run_p33_v54_for_v55(meta,args)
    p,row = _v55_find_p33_alpha_artifact()
    ah = _v55_to_float(row.get("alpha_high_density"))
    al = _v55_to_float(row.get("alpha_low_density"))
    da = _v55_to_float(row.get("delta_alpha"))
    missing=[]
    if p is None: missing.append("non_template_alpha_measurement_artifact")
    if ah is None: missing.append("alpha_high_density")
    if al is None: missing.append("alpha_low_density")
    if da is None or abs(da) <= 0: missing.append("nonzero_delta_alpha")
    for k in ["covariance_aware_fit","desi_randoms_used","redshift_jackknife_stable"]:
        if not _v55_truthy(row.get(k)): missing.append(k)
    for k in ["density_label_shuffle_p","sky_shuffle_p"]:
        val = _v55_to_float(row.get(k))
        if val is None: missing.append(k)
    gate={"gate_version":_V55_VERSION,"artifact_path":str(p) if p else None,"alpha_high_density":ah,"alpha_low_density":al,"delta_alpha":da,"missing":missing,"eligible_for_confirm_like":not missing}
    base["p33_alpha_measurement_gate_v55"]=gate
    if gate["eligible_for_confirm_like"]:
        base["status"]="p33_density_bao_alpha_confirm_like_v55"
    else:
        base["status"]="p33_density_bao_alpha_measurement_required_v55"
    return base

# 7) PTA/CL2: use .par audit but require real weighted statistic artifact.
def _v55_find_weighted_pta_artifact():
    for p in _v55_candidate_files(["pta_weighted_kappa_residual_v55*.json","pta_weighted_kappa_residual_v54*.json"], roots=[_v54_measurements_dir(), _v54_outputs_dir()]):
        if not _v55_not_template_path(p): continue
        row=_v55_artifact_row(p)
        if row: return p,row
    fill=_v54_measurements_dir()/"pta_weighted_kappa_residual_v55_FILL.json"
    if not fill.exists():
        _v55_write_json(fill, {"version":_V55_VERSION,"coordinate_hashes_present":True,"residual_or_toa_weights_present":True,"kappa_samples_present":True,"weighted_statistic":"FILL","sky_shuffle_p":"FILL","top_weight_removal_stable":True,"predeclared_sign":"FILL"})
    return None,{}

_run_cl2_v54_for_v55 = run_cl2_pta_density_gate_v54
def run_cl2_pta_density_gate_v55(meta,args):
    base=_run_cl2_v54_for_v55(meta,args)
    p,row=_v55_find_weighted_pta_artifact()
    missing=[]
    if p is None: missing.append("non_template_pta_weighted_artifact")
    for k in ["coordinate_hashes_present","residual_or_toa_weights_present","kappa_samples_present","top_weight_removal_stable"]:
        if not _v55_truthy(row.get(k)): missing.append(k)
    if _v55_to_float(row.get("weighted_statistic")) is None: missing.append("weighted_statistic")
    sp=_v55_to_float(row.get("sky_shuffle_p"))
    if sp is None or sp > 0.05: missing.append("sky_shuffle_p_le_0.05")
    if not row.get("predeclared_sign"): missing.append("predeclared_sign")
    gate={"gate_version":_V55_VERSION,"artifact_path":str(p) if p else None,"sky_shuffle_p":sp,"missing":missing,"eligible_for_confirm_like":not missing}
    base["pta_weighted_kappa_residual_gate_v55"]=gate
    if gate["eligible_for_confirm_like"]:
        base["status"]="pta_weighted_kappa_residual_confirm_like_v55"
    return base

# 8-9) Generic likelihood artifact gates for P32/P40/P41.
def _v55_generic_artifact_gate(patterns, required_bool, required_numeric, label):
    for p in _v55_candidate_files(patterns, roots=[_v54_measurements_dir(), _v54_outputs_dir()]):
        if not _v55_not_template_path(p): continue
        row=_v55_artifact_row(p)
        if not row: continue
        missing=[]
        for k in required_bool:
            if not _v55_truthy(row.get(k)): missing.append(k)
        for k in required_numeric:
            if _v55_to_float(row.get(k)) is None: missing.append(k)
        return {"gate_version":_V55_VERSION,"artifact_path":str(p),"missing":missing,"eligible_for_confirm_like":not missing,"artifact_label":label}
    return {"gate_version":_V55_VERSION,"artifact_path":None,"missing":["non_template_"+label+"_artifact"],"eligible_for_confirm_like":False,"artifact_label":label}

