def _v55_artifact_index():
    base = _v54_artifact_index()
    # Add v55 normalized/filled outputs.
    extra=[]
    for p in _v55_candidate_files(["*v55*.json","*v55*.csv"], roots=[_v54_inputs_dir(), _v54_measurements_dir(), _v54_outputs_dir()]):
        if p.name.startswith("test"): continue
        row=_v55_artifact_row(p)
        extra.append({"artifact_key":"v55_extra","path":str(p),"exists":p.exists(),"is_template":not _v55_not_template_path(p),"size_bytes":p.stat().st_size if p.exists() else 0,"sha256":_v54_sha256(p),"filled_and_usable":p.exists() and _v55_not_template_path(p) and bool(row)})
    return base + extra

def run_dashboard_v55(meta,args):
    base=_run_dashboard_v54_for_v55(meta,args)
    rows=[]
    for p in sorted(_v54_outputs_dir().glob('test*.json')):
        if p.name.startswith('test51'): continue
        obj=_v54_read_json(p)
        if isinstance(obj,dict): rows.append(obj)
    confirms=[]; sm=[]; coverage=[]; blocked=[]; ready=[]; failed=[]
    for r in rows:
        st=str(r.get('status','')); pid=str(r.get('prediction_id',''))
        item={'test_id':r.get('test_id'),'prediction_id':pid,'prediction_name':r.get('prediction_name'),'status':st}
        if 'coverage_confirmed' in st:
            coverage.append(item)
        elif 'smd_constant_consistency_confirm_like' in st:
            sm.append(item)
        elif 'confirm_like' in st and not pid.startswith('SM') and 'coverage' not in st:
            confirms.append(item)
        elif any(x in st for x in ['blocked','failed','data_limited','required','not_confirmed']):
            blocked.append(item)
        else:
            ready.append(item)
        for k,v in r.items():
            if isinstance(v,dict) and ('gate_v55' in k or 'gate_v54' in k) and not v.get('eligible_for_confirm_like', True):
                failed.append({'test_id':r.get('test_id'),'prediction_id':pid,'gate':k,'missing':v.get('missing')})
    priority=[
        {'test_id':'R10-T13','prediction':'P36 high-z','current_status':next((r.get('status') for r in rows if r.get('test_id')=='R10-T13'),None),'next_artifact':'inputs/p36_highz_object_rows_raw.csv'},
        {'test_id':'R10-T04','prediction':'P30','current_status':next((r.get('status') for r in rows if r.get('test_id')=='R10-T04'),None),'next_artifact':'inputs/p30_patch_protocol_v55.json + measurements/p30_same_mask_route_v55.json'},
        {'test_id':'R10-T07','prediction':'P33','current_status':next((r.get('status') for r in rows if r.get('test_id')=='R10-T07'),None),'next_artifact':'measurements/p33_alpha_measurement_v55.json'},
        {'test_id':'R10-T17','prediction':'PTA/CL2','current_status':next((r.get('status') for r in rows if r.get('test_id')=='R10-T17'),None),'next_artifact':'measurements/pta_weighted_kappa_residual_v55.json'},
        {'test_id':'R10-T19','prediction':'P32','current_status':next((r.get('status') for r in rows if r.get('test_id')=='R10-T19'),None),'next_artifact':'measurements/p32_strain_likelihood_v55.json'},
    ]
    artifact_index=_v55_artifact_index()
    base['dashboard_v55']={'claim_policy':'v55 only promotes non-template, non-FILL artifacts with required fields. Auto next-run protocol files are never used post hoc.','artifact_index':artifact_index,'n_artifacts':len(artifact_index),'n_filled_usable_artifacts':sum(1 for a in artifact_index if a.get('filled_and_usable')),'nonSM_confirm_like':confirms,'SM_constant_consistency':sm,'coverage_confirmed':coverage,'ready_or_compatible':ready,'blocked_or_gate_failed':blocked,'failed_gates':failed[:500],'confirm_recovery_priority':priority,'n_nonSM_confirm_like':len(confirms),'n_SM_constant_consistency':len(sm),'n_coverage_confirmed':len(coverage),'n_blocked_or_gate_failed':len(blocked)}
    base['status']='dashboard_positive_current_only_v55'
    return _v60_scrub_manual_fill_references(base)

