# -------------------------- Round-10 v56 confirm recovery + artifact builders --------------------------
_V56_VERSION = "v56"

# v56 principle: only promote when a non-template current artifact contains the exact
# measurement fields. Builders may generate diagnostic/helper artifacts, but helper
# artifacts never self-promote unless they pass the same strict gates.

def _v56_outputs_dir():
    return _v54_outputs_dir()

def _v56_inputs_dir():
    return _v54_inputs_dir()

def _v56_measurements_dir():
    return _v54_measurements_dir()

def _v56_now():
    import datetime
    return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

def _v56_current_run_id():
    import os
    return os.environ.get("CCDR_R10_CURRENT_RUN_ID_V56") or os.environ.get("CCDR_R10_CURRENT_RUN_ID") or "unknown"

def _v56_not_template_path(p):
    if not p:
        return False
    s = str(p).upper()
    bad = ["TEMPLATE", "FILL", "EXAMPLE", "SAMPLE", "PLACEHOLDER", "AUTO_PREDECLARED_FOR_NEXT_RUN"]
    return not any(x in s for x in bad)

def _v56_candidate_files(patterns, roots=None):
    return _v55_candidate_files(patterns, roots=roots)

def _v56_read_json(path):
    return _v54_read_json(path)

def _v56_write_json(path, obj):
    obj = dict(obj)
    obj.setdefault("version", _V56_VERSION)
    obj.setdefault("generated_utc", _v56_now())
    obj.setdefault("current_run_id_v56", _v56_current_run_id())
    return _v55_write_json(path, obj)

def _v56_write_csv(path, rows, fields):
    return _v55_write_csv(path, rows, fields)

def _v56_sha256(path):
    return _v54_sha256(path)

def _v56_to_float(x):
    return _v55_to_float(x)

def _v56_truthy(x):
    return _v55_truthy(x)

def _v56_first(row, aliases):
    return _v55_first(row, aliases)

def _v56_artifact_row(path):
    return _v55_artifact_row(path)

# 1-2) P36 high-z: broader raw-row recovery and strict large-radius gate.
def _v56_normalize_highz_rows(max_files=180):
    import csv, json, hashlib
    roots = [_v56_inputs_dir(), _v56_measurements_dir(), Path(".ccdr_round10_cache")]
    patterns = [
        "p36_highz_object_rows_raw*.csv", "p36_highz_object_rows_raw*.json",
        "*kges*.csv", "*kges*.json", "*kross*.csv", "*kross*.json",
        "*kmos3d*.csv", "*kmos3d*.json", "*sami*.csv", "*sami*.json",
        "*highz*rot*.csv", "*highz*rot*.json", "*vrot*.csv", "*vrot*.json",
    ]
    files = _v56_candidate_files(patterns, roots=roots)[:max_files]
    accepted, rejected = [], []

    def iter_rows(p):
        try:
            if p.suffix.lower() == ".json":
                obj = json.loads(p.read_text(encoding="utf-8", errors="replace"))
                if isinstance(obj, dict):
                    rows = obj.get("rows") or obj.get("objects") or obj.get("data") or obj.get("table") or []
                    if isinstance(rows, dict):
                        rows = list(rows.values())
                    if isinstance(rows, list):
                        for r in rows:
                            if isinstance(r, dict):
                                yield r
                elif isinstance(obj, list):
                    for r in obj:
                        if isinstance(r, dict):
                            yield r
            else:
                txt = p.read_text(encoding="utf-8", errors="replace")
                # try delimiter sniffing, then fall back to comma/tab
                sample = txt[:4096]
                try:
                    dialect = csv.Sniffer().sniff(sample, delimiters=",\t;|")
                    delim = dialect.delimiter
                except Exception:
                    delim = "\t" if "\t" in sample else ","
                for r in csv.DictReader(txt.splitlines(), delimiter=delim):
                    yield r
        except Exception as e:
            rejected.append({"input_file": str(p), "reason": "read_failed", "error": str(e)[:240]})

    src_aliases = ["source_group","source","survey","catalogue","catalog","dataset","sample","SOURCE","Survey","Catalogue"]
    obj_aliases = ["object_id","object","id","ID","name","galaxy","target","target_id","gal_id","kid","KID","KROSS_ID","KGES_ID"]
    z_aliases = ["z","Z","redshift","z_best","zspec","z_spec","zphot","z_phot"]
    v_aliases = ["vrot_km_s","Vrot","VROT","v_rot_km_s","vrot","v_rot","vcirc","v_circ","vmax","Vmax","vmax_km_s","velocity_km_s","v_km_s","V_2.2","V2.2","Vflat","v_flat"]
    r_aliases = ["radius_kpc","R_kpc","r_kpc","R","radius","r_d_kpc","rd_kpc","R_d","Rd","r_eff_kpc","Re_kpc","r_half_kpc","scale_radius_kpc"]
    raw_aliases = ["raw_source_file","source_file","source_path","file","path","source_url_or_path","reference","doi","url"]

    for p in files:
        pstr = str(p).lower().replace("\\", "/")
        # current/output/generated summaries are not raw high-z catalogues
        if "/outputs/" in pstr or "summary" in pstr or "reanalysis" in pstr or "normalized" in pstr or "rejected" in pstr:
            continue
        fhash = _v56_sha256(p)
        for row in iter_rows(p):
            src = _v56_first(row, src_aliases) or p.stem.split("_")[0]
            obj = _v56_first(row, obj_aliases) or ""
            z = _v56_to_float(_v56_first(row, z_aliases))
            v = _v56_to_float(_v56_first(row, v_aliases))
            r = _v56_to_float(_v56_first(row, r_aliases))
            raw = _v56_first(row, raw_aliases) or str(p)
            reason = []
            if not src: reason.append("missing_source_group")
            if not obj: reason.append("missing_object_id")
            if z is None: reason.append("missing_redshift")
            if v is None or v <= 0: reason.append("missing_positive_vrot_km_s")
            if r is None or r <= 0: reason.append("missing_positive_radius_kpc")
            raw_lower = str(raw).lower().replace("\\", "/")
            if "/outputs/" in raw_lower or "summary" in raw_lower or "reanalysis" in raw_lower:
                reason.append("raw_source_file_output_derived")
            if reason:
                if len(rejected) < 5000:
                    rejected.append({"input_file": str(p), "source_group": src, "object_id": obj, "reason": reason})
                continue
            # acceleration V^2/R with units km/s and kpc -> m/s^2
            accel = (v * 1000.0) ** 2 / (r * 3.0856775814913673e19)
            rhash = hashlib.sha256((str(src)+"|"+str(obj)+"|"+str(z)+"|"+str(v)+"|"+str(r)+"|"+fhash).encode("utf-8")).hexdigest()
            accepted.append({
                "source_group": str(src), "object_id": str(obj), "z": z, "vrot_km_s": v,
                "radius_kpc": r, "accel_m_s2": accel, "raw_source_file": str(raw),
                "source_file_hash": fhash, "row_hash": rhash, "input_file": str(p),
                "large_radius": bool(r >= 0.5), "trusted_raw_row_v56": True,
            })
    # dedupe by row_hash/object/source
    seen, dedup = set(), []
    for r in accepted:
        key = (r.get("source_group"), r.get("object_id"), round(float(r.get("z", 0)), 6), round(float(r.get("radius_kpc", 0)), 6))
        if key in seen:
            continue
        seen.add(key); dedup.append(r)
    norm_path = _v56_outputs_dir() / "p36_highz_object_rows_normalized_v56.csv"
    if dedup:
        _v56_write_csv(norm_path, dedup, ["source_group","object_id","z","vrot_km_s","radius_kpc","accel_m_s2","raw_source_file","source_file_hash","row_hash","input_file","large_radius","trusted_raw_row_v56"])
    rej_path = _v56_outputs_dir() / "p36_highz_rejected_rows_v56.json"
    _v56_write_json(rej_path, {"n_candidate_files": len(files), "n_normalized_rows": len(dedup), "n_rejected_rows": len(rejected), "normalized_path": str(norm_path), "rejected": rejected[:2000]})
    return dedup, {"builder_version": _V56_VERSION, "candidate_files": [str(x) for x in files[:120]], "n_rows": len(dedup), "normalized_path": str(norm_path), "rejected_path": str(rej_path)}

def _v56_highz_gate(rows, test_id=""):
    import statistics
    trusted = [r for r in rows if r.get("trusted_raw_row_v56")]
    large = [r for r in trusted if (_v56_to_float(r.get("radius_kpc")) or 0) >= 0.5]
    tiny = [r for r in trusted if (_v56_to_float(r.get("radius_kpc")) or 0) < 0.5]
    by_src = {}
    for r in large:
        by_src.setdefault(str(r.get("source_group")), []).append(r)
    accel = [float(r["accel_m_s2"]) for r in large if _v56_to_float(r.get("accel_m_s2")) is not None]
    med = statistics.median(accel) if accel else None
    local = 1.2e-10
    two_sources_20 = sum(1 for v in by_src.values() if len(v) >= 20) >= 2
    missing=[]
    if len(trusted) < 30: missing.append("trusted_raw_rows_ge_30")
    if len(large) < 30: missing.append("large_radius_rows_ge_30")
    if len(by_src) < 2: missing.append("source_groups_ge_2")
    if not two_sources_20: missing.append("two_sources_with_ge_20_large_radius_rows")
    if trusted and len(tiny)/max(1,len(trusted)) > 0.20: missing.append("tiny_radius_fraction_le_20pct")
    if med is None or med <= local: missing.append("large_radius_median_accel_above_local_a0")
    gate = {"gate_version": _V56_VERSION, "test_id": test_id, "n_trusted_rows": len(trusted), "n_large_radius_rows": len(large), "n_source_groups": len(by_src), "large_radius_rows_by_source": {k: len(v) for k,v in sorted(by_src.items())}, "tiny_radius_fraction": (len(tiny)/max(1,len(trusted))) if trusted else None, "median_large_radius_accel_m_s2": med, "local_a0_reference_m_s2": local, "missing": missing, "eligible_for_confirm_like": not missing, "claim_policy": "v56 promotes P36 high-z only from raw, non-output rows with large-radius multi-source support."}
    _v56_write_json(_v56_outputs_dir()/f"p36_highz_radius_quality_reanalysis_v56_{test_id or 'unknown'}.json", gate)
    return gate

_run_highz_v55_for_v56 = run_highz_unit_field_table_v55
def run_highz_unit_field_table_v56(meta,args):
    base = _run_highz_v55_for_v56(meta,args)
    rows, build = _v56_normalize_highz_rows()
    gate = _v56_highz_gate(rows, meta.get("test_id", ""))
    base["p36_highz_raw_builder_v56"] = build
    base["p36_highz_large_radius_gate_v56"] = gate
    if gate.get("eligible_for_confirm_like"):
        base["status"] = "highz_a0_raw_large_radius_confirm_like_v56"
        base["interpretation"] = "P36 high-z passed strict v56 raw-row + large-radius + multi-source gate."
    else:
        base["status"] = "highz_a0_raw_large_radius_gate_failed_v56"
    return base

# 3-5) P30: active protocol + same-mask proof + independent route verifier.
def _v56_active_p30_protocol():
    names=["p30_patch_protocol_v56.json","p30_patch_protocol_v55.json","p30_patch_protocol_active.json"]
    for p in _v56_candidate_files(names, roots=[_v56_inputs_dir(), _v56_measurements_dir()]):
        if not _v56_not_template_path(p):
            continue
        row=_v56_artifact_row(p)
        if row:
            return p,row
    fill=_v56_inputs_dir()/"p30_patch_protocol_v56_FILL_BEFORE_RUN.json"
    if not fill.exists():
        _v56_write_json(fill,{"version":_V56_VERSION,"predeclared_before_run":True,"same_mask_for_science_curl_nulls":True,"same_density_labels_for_variants":True,"post_hoc_quarantine_allowed":False,"patch_nside":"FILL","mask_id":"FILL","density_label_hash":"FILL","protocol_created_utc":"FILL before run"})
    return None,{}

def _v56_same_mask_route_artifact():
    pats=["p30_same_mask_route_v56*.json","p30_same_mask_route_v55*.json","p30_independent_route_v56*.json","p30_independent_route_v55*.json"]
    for p in _v56_candidate_files(pats, roots=[_v56_measurements_dir(), _v56_outputs_dir()]):
        if not _v56_not_template_path(p): continue
        row=_v56_artifact_row(p)
        if row: return p,row
    fill=_v56_measurements_dir()/"p30_same_mask_route_v56_FILL.json"
    if not fill.exists():
        _v56_write_json(fill,{"version":_V56_VERSION,"route_label":"sdss_or_planck_or_euclid","same_mask_for_science_curl_nulls":True,"same_density_labels_for_variants":True,"curl_weaker_than_science":True,"sky_shuffle_p":"FILL","density_shuffle_p":"FILL","jackknife_same_sign":True,"science_delta":"FILL","curl_delta":"FILL","sdss_route_positive":"FILL","independent_route_positive":"FILL","mask_id":"FILL","density_label_hash":"FILL","source_hashes_present":True})
    return None,{}

_run_p30_v55_for_v56 = run_p30_publication_gate_v55
def run_p30_publication_gate_v56(meta,args):
    base=_run_p30_v55_for_v56(meta,args)
    pp, proto = _v56_active_p30_protocol()
    rp, route = _v56_same_mask_route_artifact()
    missing=[]
    if not pp: missing.append("active_p30_patch_protocol_v56_or_v55")
    if not _v56_truthy(proto.get("predeclared_before_run")): missing.append("protocol_predeclared_before_run")
    if not _v56_truthy(proto.get("same_mask_for_science_curl_nulls")): missing.append("protocol_same_mask_for_science_curl_nulls")
    if not _v56_truthy(proto.get("same_density_labels_for_variants")): missing.append("protocol_same_density_labels_for_variants")
    if _v56_truthy(proto.get("post_hoc_quarantine_allowed")): missing.append("no_post_hoc_quarantine")
    if not proto.get("patch_nside"): missing.append("patch_nside_present")
    if not rp: missing.append("p30_same_mask_route_artifact")
    if not _v56_truthy(route.get("same_mask_for_science_curl_nulls")): missing.append("route_same_mask_for_science_curl_nulls")
    if not _v56_truthy(route.get("same_density_labels_for_variants")): missing.append("route_same_density_labels_for_variants")
    if not _v56_truthy(route.get("curl_weaker_than_science")): missing.append("route_curl_weaker_than_science")
    if not _v56_truthy(route.get("source_hashes_present")): missing.append("route_source_hashes_present")
    if not (_v56_truthy(route.get("sdss_route_positive")) or _v56_truthy(route.get("independent_route_positive"))): missing.append("route_positive")
    # Global confirm still requires an independent route, not just SDSS.
    if not _v56_truthy(route.get("independent_route_positive")): missing.append("second_independent_route_positive")
    gate={"gate_version":_V56_VERSION,"protocol_path":str(pp) if pp else None,"route_artifact_path":str(rp) if rp else None,"missing":missing,"eligible_for_route_confirm_like":not [m for m in missing if m != "second_independent_route_positive"],"eligible_for_global_confirm_like":not missing,"claim_policy":"v56 requires an active protocol before run, same-mask proof, weaker curl, source hashes, and independent route for global P30."}
    base["p30_same_mask_route_gate_v56"]=gate
    if gate["eligible_for_global_confirm_like"]:
        base["status"]="density_kappa_global_same_mask_confirm_like_v56"
    elif gate["eligible_for_route_confirm_like"]:
        base["status"]="density_kappa_route_confirm_like_v56"
    else:
        base["status"]="density_kappa_same_mask_route_blocked_v56"
    return base

# 6) P33: strict alpha artifact gate with significance.
def _v56_find_p33_alpha_artifact():
    pats=["p33_alpha_measurement_v56*.json","p33_alpha_measurement_v55*.json","p33_density_split_alpha_measurement*.json","p33_*alpha*measurement*.json"]
    for p in _v56_candidate_files(pats, roots=[_v56_measurements_dir(), _v56_outputs_dir()]):
        if not _v56_not_template_path(p): continue
        row=_v56_artifact_row(p)
        if row: return p,row
    fill=_v56_measurements_dir()/"p33_alpha_measurement_v56_FILL.json"
    if not fill.exists():
        _v56_write_json(fill,{"version":_V56_VERSION,"alpha_high_density":"FILL","alpha_low_density":"FILL","delta_alpha":"FILL","delta_alpha_sigma":"FILL","covariance_aware_fit":True,"desi_randoms_used":True,"density_label_shuffle_p":"FILL <=0.05","sky_shuffle_p":"FILL <=0.05","redshift_jackknife_stable":True,"predeclared_sign":"FILL","source_hashes_present":True})
    return None,{}

_run_p33_v55_for_v56 = run_p33_density_bao_measurement_gate_v55
def run_p33_density_bao_measurement_gate_v56(meta,args):
    base=_run_p33_v55_for_v56(meta,args)
    p,row=_v56_find_p33_alpha_artifact()
    ah=_v56_to_float(row.get("alpha_high_density")); al=_v56_to_float(row.get("alpha_low_density")); da=_v56_to_float(row.get("delta_alpha")); ds=_v56_to_float(row.get("delta_alpha_sigma"))
    missing=[]
    if p is None: missing.append("non_template_p33_alpha_measurement_artifact")
    for k in ["covariance_aware_fit","desi_randoms_used","redshift_jackknife_stable","source_hashes_present"]:
        if not _v56_truthy(row.get(k)): missing.append(k)
    for k,val in [("alpha_high_density",ah),("alpha_low_density",al),("delta_alpha",da)]:
        if val is None: missing.append(k)
    if ds is None or ds <= 0: missing.append("delta_alpha_sigma_positive")
    if da is not None and ds is not None and ds > 0 and abs(da/ds) < 2: missing.append("delta_alpha_ge_2sigma")
    for k in ["density_label_shuffle_p","sky_shuffle_p"]:
        val=_v56_to_float(row.get(k))
        if val is None or val > 0.05: missing.append(k+"_le_0.05")
    if not row.get("predeclared_sign"): missing.append("predeclared_sign")
    gate={"gate_version":_V56_VERSION,"artifact_path":str(p) if p else None,"alpha_high_density":ah,"alpha_low_density":al,"delta_alpha":da,"delta_alpha_sigma":ds,"missing":missing,"eligible_for_confirm_like":not missing,"claim_policy":"v56 requires a covariance-aware DESI density-split BAO alpha measurement with nulls and >=2σ delta-alpha."}
    base["p33_alpha_measurement_gate_v56"]=gate
    base["status"]="p33_density_bao_alpha_confirm_like_v56" if gate["eligible_for_confirm_like"] else "p33_density_bao_alpha_measurement_required_v56"
    return base

