_run_dashboard_v55_for_v56 = run_dashboard_v55
def _v56_artifact_index():
    base=_v55_artifact_index()
    extra=[]
    for p in _v56_candidate_files(["*v56*.json","*v56*.csv"], roots=[_v56_inputs_dir(), _v56_measurements_dir(), _v56_outputs_dir()]):
        if p.name.startswith("test"): continue
        row=_v56_artifact_row(p)
        extra.append({"artifact_key":"v56_extra","path":str(p),"exists":p.exists(),"is_template":not _v56_not_template_path(p),"size_bytes":p.stat().st_size if p.exists() else 0,"sha256":_v56_sha256(p),"filled_and_usable":p.exists() and _v56_not_template_path(p) and bool(row)})
    return base+extra

def run_dashboard_v56(meta,args):
    base=_run_dashboard_v55_for_v56(meta,args)
    rows=[]
    for p in sorted(_v56_outputs_dir().glob("test*.json")):
        if p.name.startswith("test51"): continue
        obj=_v56_read_json(p)
        if isinstance(obj,dict): rows.append(obj)
    confirms=[]; sm=[]; coverage=[]; blocked=[]; ready=[]; failed=[]
    for r in rows:
        st=str(r.get("status","")); pid=str(r.get("prediction_id",""))
        item={"test_id":r.get("test_id"),"prediction_id":pid,"prediction_name":r.get("prediction_name"),"status":st}
        if "coverage_confirmed" in st:
            coverage.append(item)
        elif "smd_constant_consistency_confirm_like" in st:
            sm.append(item)
        elif "confirm_like" in st and not pid.startswith("SM") and "coverage" not in st:
            confirms.append(item)
        elif any(x in st for x in ["blocked","failed","data_limited","required","not_confirmed"]):
            blocked.append(item)
        else:
            ready.append(item)
        for k,v in r.items():
            if isinstance(v,dict) and ("gate_v56" in k or "gate_v55" in k) and not v.get("eligible_for_confirm_like", True):
                failed.append({"test_id":r.get("test_id"),"prediction_id":pid,"gate":k,"missing":v.get("missing")})
    artifact_index=_v56_artifact_index()
    priority=[
        {"test_id":"R10-T13","prediction":"P36 high-z","next_artifact":"inputs/p36_highz_object_rows_raw.csv"},
        {"test_id":"R10-T04","prediction":"P30","next_artifact":"inputs/p30_patch_protocol_v56.json + measurements/p30_same_mask_route_v56.json"},
        {"test_id":"R10-T07","prediction":"P33","next_artifact":"measurements/p33_alpha_measurement_v56.json"},
        {"test_id":"R10-T17","prediction":"PTA/CL2","next_artifact":"measurements/pta_weighted_kappa_residual_v56.json"},
        {"test_id":"R10-T19","prediction":"P32","next_artifact":"measurements/p32_strain_likelihood_v56.json"},
        {"test_id":"R10-T21","prediction":"P40","next_artifact":"measurements/p40_bb_likelihood_v56.json"},
        {"test_id":"R10-T31","prediction":"P41","next_artifact":"measurements/p41_q2_wilson_likelihood_v56.json"},
    ]
    base["dashboard_v56"]={"claim_policy":"v56 promotes only non-template current measurement artifacts that pass strict gates. FILL/TEMPLATE/AUTO_PREDECLARED artifacts are ignored for promotion.","artifact_index":artifact_index,"n_artifacts":len(artifact_index),"n_filled_usable_artifacts":sum(1 for a in artifact_index if a.get("filled_and_usable")),"nonSM_confirm_like":confirms,"SM_constant_consistency":sm,"coverage_confirmed":coverage,"ready_or_compatible":ready,"blocked_or_gate_failed":blocked,"failed_gates":failed[:700],"confirm_recovery_priority":priority,"n_nonSM_confirm_like":len(confirms),"n_SM_constant_consistency":len(sm),"n_coverage_confirmed":len(coverage),"n_blocked_or_gate_failed":len(blocked)}
    base["status"]="dashboard_positive_current_only_v56"
    return _v60_scrub_manual_fill_references(base)

