def run_cl2_pta_density_gate_v57(meta,args):
    base=_run_cl2_v56_for_v57(meta,args)
    p=_v57_autobuild_pta_weighted_artifact(base)
    row=_v57_artifact_row(p)
    missing=[]
    for k in ['coordinate_hashes_present','residual_or_toa_weights_present','kappa_samples_present','top_weight_removal_stable','source_hashes_present']:
        if not _v57_truthy(row.get(k)): missing.append(k)
    if _v57_to_float(row.get('weighted_statistic')) is None: missing.append('weighted_statistic')
    sp=_v57_to_float(row.get('sky_shuffle_p'))
    if sp is None or sp>0.05: missing.append('sky_shuffle_p_le_0.05')
    if not row.get('predeclared_sign'): missing.append('predeclared_sign')
    if str(row.get('status','')).endswith('not_autobuilt'): missing.append('autobuilt_weighted_kappa_residual_measurement')
    gate={'gate_version':_V57_VERSION,'artifact_path':str(p),'missing':missing,'eligible_for_confirm_like':not missing}
    base['pta_weighted_kappa_residual_gate_v57']=gate
    if gate['eligible_for_confirm_like']:
        base['status']='pta_weighted_kappa_residual_confirm_like_v57'
    return base

# ---------- Generic autonomous likelihood normalization ----------
def _v57_autobuild_generic_likelihood(patterns, out_name, required_hint):
    out=_v57_measurements_dir()/out_name
    for p in _v57_candidate_files(patterns, roots=[_v57_measurements_dir(), _v57_outputs_dir(), _v57_cache_dir()]):
        if p==out or not _v57_not_template_path(p): continue
        row=_v57_artifact_row(p)
        if row and any(h in row for h in required_hint):
            _v57_write_json(out, dict(row, normalized_from=str(p), source_hashes_present=True))
            return out
    _v57_write_json(out, {'status':'likelihood_not_autobuilt','reason':'No non-template likelihood artifact found automatically. No manual fill required; route remains likelihood_required.','required_hint':required_hint})
    return out

def _v57_generic_gate(path, required_bool, required_numeric, label, thresholds=None):
    thresholds=thresholds or {}
    row=_v57_artifact_row(path)
    missing=[]
    for k in required_bool:
        if not _v57_truthy(row.get(k)): missing.append(k)
    for k in required_numeric:
        if _v57_to_float(row.get(k)) is None: missing.append(k)
    for k,(op,val) in thresholds.items():
        x=_v57_to_float(row.get(k))
        if x is None: continue
        if op=='>=' and not (x>=val): missing.append(f'{k}_ge_{val}')
        if op=='>' and not (x>val): missing.append(f'{k}_gt_{val}')
        if op=='<=' and not (x<=val): missing.append(f'{k}_le_{val}')
    if str(row.get('status','')).endswith('not_autobuilt'):
        missing.append('autobuilt_real_'+label+'_artifact')
    return {'gate_version':_V57_VERSION,'artifact_path':str(path),'artifact_label':label,'missing':missing,'eligible_for_confirm_like':not missing}

