def run_dashboard_v57(meta,args):
    base=_run_dashboard_v56_for_v57(meta,args)
    rows=[]
    for p in sorted(_v57_outputs_dir().glob('test*.json')):
        if p.name.startswith('test51'): continue
        obj=_v57_read_json(p)
        if isinstance(obj,dict): rows.append(obj)
    confirms=[]; sm=[]; coverage=[]; blocked=[]; ready=[]; failed=[]
    for r in rows:
        st=str(r.get('status','')); pid=str(r.get('prediction_id',''))
        item={'test_id':r.get('test_id'),'prediction_id':pid,'prediction_name':r.get('prediction_name'),'status':st}
        if 'coverage_confirmed' in st:
            coverage.append(item)
        elif 'smd_constant_consistency_confirm_like' in st:
            sm.append(item)
        elif 'confirm_like' in st and not pid.startswith('SM') and 'coverage' not in st:
            confirms.append(item)
        elif any(x in st for x in ['blocked','failed','data_limited','required','not_confirmed']):
            blocked.append(item)
        else:
            ready.append(item)
        for k,v in r.items():
            if isinstance(v,dict) and ('gate_v57' in k or 'gate_v56' in k or 'gate_v55' in k) and not v.get('eligible_for_confirm_like', True):
                failed.append({'test_id':r.get('test_id'),'prediction_id':pid,'gate':k,'missing':v.get('missing')})
    artifact_index=_v57_artifact_index()
    priority=[
        {'test_id':'R10-T13','prediction':'P36 high-z','autobuilder':'p36_highz_object_rows_raw_v57_AUTO.csv from cache/public raw tables'},
        {'test_id':'R10-T04','prediction':'P30','autobuilder':'p30_patch_protocol_v57.json + p30_same_mask_route_v57_AUTO.json from current ACT/SDSS stats'},
        {'test_id':'R10-T07','prediction':'P33','autobuilder':'p33_alpha_measurement_v57_AUTO.json from any cached DESI density-alpha artifact'},
        {'test_id':'R10-T17','prediction':'PTA/CL2','autobuilder':'pta_weighted_kappa_residual_v57_AUTO.json from cached weighted statistic if present'},
        {'test_id':'R10-T19','prediction':'P32','autobuilder':'p32_strain_likelihood_v57_AUTO.json from cached likelihood if present'},
        {'test_id':'R10-T21','prediction':'P40','autobuilder':'p40_bb_likelihood_v57_AUTO.json from cached BB likelihood if present'},
        {'test_id':'R10-T31','prediction':'P41','autobuilder':'p41_q2_wilson_likelihood_v57_AUTO.json from cached q2/Wilson likelihood if present'},
    ]
    base['dashboard_v57']={'claim_policy':'v57 requires no manual artifact filling. It auto-builds candidate artifacts from public/cached data, but promotes only if strict non-template measurement gates pass. If no raw/likelihood data are found, tests stay data_limited/required.','artifact_index':artifact_index,'n_artifacts':len(artifact_index),'n_filled_usable_artifacts':sum(1 for a in artifact_index if a.get('filled_and_usable')),'nonSM_confirm_like':confirms,'SM_constant_consistency':sm,'coverage_confirmed':coverage,'ready_or_compatible':ready,'blocked_or_gate_failed':blocked,'failed_gates':failed[:900],'confirm_recovery_priority':priority,'n_nonSM_confirm_like':len(confirms),'n_SM_constant_consistency':len(sm),'n_coverage_confirmed':len(coverage),'n_blocked_or_gate_failed':len(blocked)}
    base['status']='dashboard_positive_current_only_v57'
    return _v60_scrub_manual_fill_references(base)

