# -------------------------- Round-10 v58 no-manual confirm recovery --------------------------
_V58_VERSION = "v58"

# v58 goal: keep the v57 no-manual-fill policy, but make the automatic
# artifact builders more useful.  It adds richer public/cache parsers,
# sharper diagnostics that distinguish "no public rows" from a physics
# negative, and route-specific gates that avoid global over-promotion.

def _v58_outputs_dir():
    return Path('outputs')

def _v58_inputs_dir():
    p=Path('inputs'); p.mkdir(exist_ok=True); return p

def _v58_measurements_dir():
    p=Path('measurements'); p.mkdir(exist_ok=True); return p

def _v58_cache_dir():
    return Path('.ccdr_round10_cache')

def _v58_now():
    import datetime
    return datetime.datetime.utcnow().replace(microsecond=0).isoformat()+'Z'

def _v58_current_run_id():
    import os
    return os.environ.get('CCDR_R10_CURRENT_RUN_ID_V58') or os.environ.get('CCDR_R10_CURRENT_RUN_ID') or 'unknown'

def _v58_sha256(path):
    try:
        import hashlib
        h=hashlib.sha256()
        with open(path,'rb') as f:
            for chunk in iter(lambda:f.read(1024*1024), b''):
                h.update(chunk)
        return h.hexdigest()
    except Exception:
        return None

def _v58_write_json(path,obj):
    import json
    path=Path(path); path.parent.mkdir(parents=True, exist_ok=True)
    if isinstance(obj,dict):
        obj.setdefault('generated_utc', _v58_now())
        obj.setdefault('current_run_id_v58', _v58_current_run_id())
    path.write_text(json.dumps(obj, indent=2, sort_keys=True, ensure_ascii=False), encoding='utf-8')
    return str(path)

def _v58_write_csv(path, rows, fields):
    import csv
    path=Path(path); path.parent.mkdir(parents=True, exist_ok=True)
    with path.open('w', newline='', encoding='utf-8') as f:
        w=csv.DictWriter(f, fieldnames=fields); w.writeheader()
        for r in rows: w.writerow({k:r.get(k,'') for k in fields})
    return str(path)

def _v58_read_json(path):
    import json
    try: return json.loads(Path(path).read_text(encoding='utf-8'))
    except Exception: return None

def _v58_to_float(x):
    try:
        if x is None: return None
        s=str(x).strip().replace(',','')
        if s=='' or s.lower() in {'nan','none','null','--'}: return None
        return float(s)
    except Exception:
        return None

def _v58_truthy(x):
    if isinstance(x,bool): return x
    if isinstance(x,(int,float)): return bool(x)
    return str(x).strip().lower() in {'1','true','yes','y','passed','pass','ok'}

def _v58_not_template_path(path):
    s=str(path).lower()
    bad=['template','_fill','fill_and_rename','example','dummy','placeholder']
    return not any(b in s for b in bad)

def _v58_candidate_files(patterns, roots=None, max_files=1000):
    roots=roots or [_v58_inputs_dir(), _v58_measurements_dir(), _v58_outputs_dir(), _v58_cache_dir()]
    out=[]; seen=set()
    for root in roots:
        root=Path(root)
        if not root.exists(): continue
        for pat in patterns:
            for p in root.rglob(pat):
                try:
                    if not p.is_file(): continue
                    if p.stat().st_size <= 0: continue
                    key=str(p.resolve())
                    if key in seen: continue
                    seen.add(key); out.append(p)
                    if len(out)>=max_files: return out
                except Exception:
                    continue
    return out

def _v58_artifact_row(path):
    # Reuse mature v57 artifact flattener when available.
    try:
        return _v57_artifact_row(path)
    except Exception:
        obj=_v58_read_json(path)
        return obj if isinstance(obj,dict) else {}

# ---------- v58 P36 high-z: stronger public/cache row parser ----------
def _v58_norm_key(k):
    import re
    return re.sub(r'[^a-z0-9]+','',str(k).lower())

def _v58_first(row, aliases):
    norm={_v58_norm_key(k):v for k,v in row.items()}
    for a in aliases:
        ak=_v58_norm_key(a)
        if ak in norm and str(norm[ak]).strip() not in {'','nan','None','NULL','--'}:
            return norm[ak]
    return None

def _v58_iter_table_rows(path, max_rows=200000):
    """Yield dict rows from CSV/TSV/TXT/DAT/JSON/HTML-ish public tables."""
    import csv, json, re
    p=Path(path)
    try:
        raw=p.read_text(encoding='utf-8', errors='replace')
    except Exception:
        return
    if not raw.strip(): return
    suffix=p.suffix.lower()
    if suffix=='.json':
        try:
            obj=json.loads(raw)
        except Exception:
            return
        candidates=[]
        if isinstance(obj,list): candidates=obj
        elif isinstance(obj,dict):
            for k in ['rows','objects','data','table','catalog','catalogue','results']:
                v=obj.get(k)
                if isinstance(v,list): candidates=v; break
                if isinstance(v,dict): candidates=list(v.values()); break
            if not candidates:
                # Some JSON records are column-oriented.
                cols={k:v for k,v in obj.items() if isinstance(v,list)}
                if cols:
                    n=min(len(v) for v in cols.values())
                    for i in range(min(n,max_rows)):
                        yield {k:v[i] for k,v in cols.items()}
                    return
        for r in candidates[:max_rows]:
            if isinstance(r,dict): yield r
        return
    # Primitive HTML table extraction with pandas if present, otherwise strip tags.
    if '<table' in raw.lower() or suffix in {'.html','.htm'}:
        try:
            import pandas as pd
            for df in pd.read_html(raw):
                df.columns=[str(c) for c in df.columns]
                for _,rr in df.head(max_rows).iterrows():
                    yield {str(k):v for k,v in rr.to_dict().items()}
                return
        except Exception:
            raw=re.sub(r'<[^>]+>',' ',raw)
    lines=[ln for ln in raw.splitlines() if ln.strip() and not ln.lstrip().startswith(('#',';','//'))]
    if not lines: return
    # Find a likely header line with at least one semantic alias.
    alias_blob='vrot radius redshift z kpc v_circ vrot_km_s r_kpc object id name galaxy'
    header_i=0
    for i,ln in enumerate(lines[:80]):
        lo=ln.lower()
        if any(tok in lo for tok in alias_blob.split()) and len(re.split(r'[,\t;|\s]+',ln.strip()))>=3:
            header_i=i; break
    lines=lines[header_i:]
    sample='\n'.join(lines[:20])
    try:
        delim=csv.Sniffer().sniff(sample, delimiters=',\t;|').delimiter
    except Exception:
        delim='\t' if any('\t' in ln for ln in lines[:5]) else (',' if any(',' in ln for ln in lines[:5]) else None)
    if delim:
        try:
            for j,r in enumerate(csv.DictReader(lines, delimiter=delim)):
                if j>=max_rows: break
                yield r
        except Exception:
            return
    else:
        header=re.split(r'\s+', lines[0].strip())
        for j,ln in enumerate(lines[1:max_rows+1]):
            vals=re.split(r'\s+', ln.strip())
            if len(vals)>=len(header):
                yield dict(zip(header, vals))

def _v58_source_group_from_path(path, row):
    src=_v58_first(row, ['source_group','source','survey','catalogue','catalog','dataset','sample','paper','instrument'])
    if src: return str(src).strip()
    low=Path(path).name.lower()
    for key,val in [('kross','KROSS'),('kges','KGES'),('kmos3d','KMOS3D'),('kmos','KMOS3D'),('sami','SAMI'),('mosdef','MOSDEF'),('tacconi','PHIBSS'),('phibss','PHIBSS')]:
        if key in low: return val
    return Path(path).stem[:40]

def _v58_convert_radius_to_kpc(value, row):
    r=_v58_to_float(value)
    if r is None: return None, 'missing'
    # Unit hints in key names or separate unit columns.
    unit=str(_v58_first(row, ['radius_unit','r_unit','R_unit','units','unit']) or '').lower()
    keys=' '.join(str(k).lower() for k in row.keys())
    if 'pc' in unit and 'kpc' not in unit:
        return r/1000.0, 'pc_to_kpc'
    if 'kpc' in unit or 'kpc' in keys:
        return r, 'kpc'
    # Heuristic: high-z galaxy sizes in pc can be thousands; disk sizes in kpc are normally <200.
    if r>200 and r<200000:
        return r/1000.0, 'heuristic_pc_to_kpc'
    return r, 'assumed_kpc'

def _v58_autobuild_p36_highz_rows(max_files=1500):
    import hashlib, math
    out_csv=_v58_inputs_dir()/'p36_highz_object_rows_raw_v58_AUTO.csv'
    diag_path=_v58_outputs_dir()/'p36_highz_autobuild_v58.json'
    rejected_path=_v58_outputs_dir()/'p36_highz_rejected_rows_v58.json'
    patterns=['*kges*.*','*kross*.*','*kmos3d*.*','*kmos*.*','*sami*.*','*mosdef*.*','*phibss*.*','*tacconi*.*','*highz*.*','*vrot*.*','*rotation*.*','*galaxy*kinematic*.*']
    files=[]
    for p in _v58_candidate_files(patterns, roots=[_v58_inputs_dir(), _v58_measurements_dir(), _v58_cache_dir()], max_files=max_files):
        s=str(p).lower().replace('\\','/')
        if any(x in s for x in ['/outputs/','summary','template','fill','example','reanalysis','normalized','rejected','autobuild']): continue
        if p.suffix.lower() not in ['.csv','.tsv','.txt','.dat','.json','.html','.htm']: continue
        # Avoid very large binary-misnamed files.
        try:
            if p.stat().st_size > 200*1024*1024: continue
        except Exception: pass
        files.append(p)
    obj_alias=['object_id','object','id','ID','name','galaxy','target','target_id','gal_id','kid','KID','OBJID','objid','source_id']
    z_alias=['z','Z','redshift','z_best','zspec','z_spec','zphot','z_phot','REDSHIFT','zgal','z_gal']
    v_alias=['vrot_km_s','Vrot','VROT','v_rot_km_s','vrot','v_rot','vcirc','v_circ','vmax','Vmax','vmax_km_s','velocity_km_s','v_km_s','V_2.2','V2.2','Vflat','v_flat','vobs','v_obs','rot_vel','rotation_velocity']
    r_alias=['radius_kpc','R_kpc','r_kpc','R','radius','r_d_kpc','rd_kpc','R_d','Rd','r_eff_kpc','Re_kpc','r_half_kpc','scale_radius_kpc','R22','R_2.2','r22','r_22','size_kpc','re','r_e']
    accepted=[]; rejected=[]; files_with_rows=[]
    for p in files:
        fhash=_v58_sha256(p)
        n_file=0
        for ix,row in enumerate(_v58_iter_table_rows(p) or []):
            obj=_v58_first(row,obj_alias) or f'{p.stem}:{ix}'
            z=_v58_to_float(_v58_first(row,z_alias))
            v=_v58_to_float(_v58_first(row,v_alias))
            rad_raw=_v58_first(row,r_alias)
            rad,rad_unit=_v58_convert_radius_to_kpc(rad_raw,row)
            src=_v58_source_group_from_path(p,row)
            reason=[]
            if z is None or not (0.01 <= z <= 5.0): reason.append('missing_or_bad_z')
            if v is None or not (10 <= v <= 800): reason.append('missing_or_bad_vrot_km_s')
            if rad is None or not (0.05 <= rad <= 100): reason.append('missing_or_bad_radius_kpc')
            if reason:
                if len(rejected)<2000:
                    rejected.append({'input_file':str(p),'reason':reason,'columns':list(row.keys())[:60]})
                continue
            canonical='|'.join([str(src),str(obj),str(z),str(v),str(rad),str(p),str(fhash)])
            accepted.append({'source_group':src,'object_id':str(obj).strip(),'z':z,'vrot_km_s':v,'radius_kpc':rad,'radius_unit_inferred_v58':rad_unit,'raw_source_file':str(p),'raw_source_sha256':fhash,'row_sha256':hashlib.sha256(canonical.encode()).hexdigest()})
            n_file+=1
        if n_file: files_with_rows.append({'path':str(p),'n_rows':n_file,'sha256':fhash})
    # Dedup.
    dedup=[]; seen=set()
    for r in accepted:
        key=(r['source_group'],r['object_id'],round(float(r['z']),5),round(float(r['vrot_km_s']),2),round(float(r['radius_kpc']),3))
        if key in seen: continue
        seen.add(key); dedup.append(r)
    accepted=dedup
    fields=['source_group','object_id','z','vrot_km_s','radius_kpc','radius_unit_inferred_v58','raw_source_file','raw_source_sha256','row_sha256']
    if accepted:
        _v58_write_csv(out_csv, accepted, fields)
    _v58_write_json(rejected_path, {'n_rejected':len(rejected),'rejected_preview':rejected[:300]})
    large=[r for r in accepted if _v58_to_float(r.get('radius_kpc')) is not None and _v58_to_float(r.get('radius_kpc'))>=0.5]
    src_counts={}
    for r in large: src_counts[r['source_group']]=src_counts.get(r['source_group'],0)+1
    diag={'status':'built' if accepted else 'no_public_rows_found','candidate_files':[str(p) for p in files[:200]],'n_candidate_files':len(files),'files_with_rows':files_with_rows[:100],'n_rows':len(accepted),'n_large_radius_rows':len(large),'large_radius_source_counts':src_counts,'output_csv':str(out_csv) if accepted else None,'rejected_path':str(rejected_path),'diagnostic':'autobuilder_public_rows_absent' if not accepted else 'autobuilder_rows_available'}
    _v58_write_json(diag_path, diag)
    return out_csv if accepted else None, diag

