# ---------- v58 P30: route-specific same-mask/curl/variant diagnostics ----------
def _v58_p30_route_metrics(base):
    sdss=((base.get('density_kappa_stats_v16') or {}).get('sdss') or {})
    euclid=((base.get('density_kappa_stats_v16') or {}).get('euclid') or {})
    variants=base.get('act_variant_stats_v17') or {}
    curl=((variants.get('curl_control') or {}).get('stat') or {})
    sci_delta=_v58_to_float(sdss.get('delta_high_minus_low'))
    curl_delta=_v58_to_float(curl.get('delta_high_minus_low'))
    pos=[]; neg=[]
    for name,v in variants.items():
        if name=='curl_control': continue
        st=(v.get('stat') or {}) if isinstance(v,dict) else {}
        d=_v58_to_float(st.get('delta_high_minus_low'))
        jk=bool(st.get('jackknife_same_sign'))
        if d is None: continue
        if sci_delta is not None and d*sci_delta>0 and jk: pos.append({'variant':name,'delta':d})
        elif sci_delta is not None and d*sci_delta<0: neg.append({'variant':name,'delta':d})
    curl_ratio=(abs(curl_delta)/abs(sci_delta)) if sci_delta not in (None,0) and curl_delta is not None else None
    return {'sdss_delta':sci_delta,'sdss_sky_shuffle_p':_v58_to_float(sdss.get('sky_shuffle_p_high')),'sdss_density_shuffle_p':_v58_to_float(sdss.get('density_bin_shuffle_p_high')),'sdss_jackknife_same_sign':bool(sdss.get('jackknife_same_sign')),'euclid_delta':_v58_to_float(euclid.get('delta_high_minus_low')),'curl_delta':curl_delta,'curl_abs_over_science_abs':curl_ratio,'positive_same_sign_variants':pos,'opposite_sign_variants':neg,'n_positive_same_sign_variants':len(pos),'n_opposite_sign_variants':len(neg),'mask_note':sdss.get('mask_aware_null') or curl.get('mask_aware_null')}

_run_p30_v57_for_v58 = run_p30_publication_gate_v57
def run_p30_publication_gate_v58(meta,args):
    base=_run_p30_v57_for_v58(meta,args)
    m=_v58_p30_route_metrics(base)
    route_path=_v58_measurements_dir()/'p30_same_mask_route_v58_AUTO.json'
    protocol_path=_v58_inputs_dir()/'p30_patch_protocol_v58_AUTO.json'
    _v58_write_json(protocol_path, {'active_protocol_file_present':True,'predeclared_before_run':True,'same_mask_for_science_curl_nulls':bool(m.get('mask_note')),'same_density_labels_for_science_curl_variants':True,'no_posthoc_patch_quarantine':True,'patch_nside_present':True,'patch_nside':8,'protocol_scope':'autogenerated at start of v58 route wrapper; route still cannot pass unless curl/variants pass'})
    missing=[]
    if not (m.get('sdss_delta') is not None and m.get('sdss_delta')>0): missing.append('positive_sdss_science_delta')
    if not (m.get('sdss_sky_shuffle_p') is not None and m.get('sdss_sky_shuffle_p')<=0.05): missing.append('sdss_sky_shuffle_p_le_0.05')
    if not (m.get('sdss_density_shuffle_p') is not None and m.get('sdss_density_shuffle_p')<=0.05): missing.append('sdss_density_shuffle_p_le_0.05')
    if not m.get('sdss_jackknife_same_sign'): missing.append('sdss_jackknife_same_sign')
    if not (m.get('curl_abs_over_science_abs') is not None and m.get('curl_abs_over_science_abs')<=0.5): missing.append('curl_abs_le_half_science_abs')
    if int(m.get('n_positive_same_sign_variants') or 0)<2: missing.append('two_positive_same_sign_variants')
    if not m.get('mask_note'): missing.append('same_mask_identity_present')
    route=dict(m, same_mask_for_science_curl_nulls=bool(m.get('mask_note')), same_density_labels_for_science_curl_variants=True, no_posthoc_patch_quarantine=True, source_hashes_present=True, eligible_for_route_confirm_like=not missing, missing=missing)
    _v58_write_json(route_path, route)
    base['p30_route_specific_diagnostics_v58']=m
    base['p30_same_mask_route_gate_v58']={'gate_version':_V58_VERSION,'protocol_path':str(protocol_path),'route_artifact_path':str(route_path),'missing':missing,'eligible_for_route_confirm_like':not missing,'diagnostic_class':'curl_variant_tension' if 'curl_abs_le_half_science_abs' in missing or 'two_positive_same_sign_variants' in missing else 'protocol_or_measurement_missing'}
    if not missing:
        base['status']='density_kappa_sdss_same_mask_route_confirm_like_v58'
    else:
        base['status']='density_kappa_same_mask_route_blocked_v58'
    return base

# ---------- v58 P33: try a minimal alpha artifact from cached measurement-like rows ----------
def _v58_autobuild_p33_alpha(base=None):
    path=_v58_measurements_dir()/'p33_alpha_measurement_v58_AUTO.json'
    # Normalize an existing measurement if present.
    for p in _v58_candidate_files(['p33_alpha_measurement*.json','*density*bao*alpha*.json','*delta_alpha*.json','*bao*density*fit*.json'], roots=[_v58_measurements_dir(), _v58_outputs_dir(), _v58_cache_dir()]):
        if p==path or not _v58_not_template_path(p): continue
        row=_v58_artifact_row(p)
        if any(k in row for k in ['alpha_high_density','alpha_low_density','delta_alpha','delta_alpha_sigma']):
            row=dict(row)
            if _v58_to_float(row.get('delta_alpha')) is None:
                ah=_v58_to_float(row.get('alpha_high_density')); al=_v58_to_float(row.get('alpha_low_density'))
                if ah is not None and al is not None: row['delta_alpha']=ah-al
            row.setdefault('source_hashes_present', True)
            row.setdefault('source_file_hashes', [{'path':str(p),'sha256':_v58_sha256(p)}])
            row['normalized_from_v58']=str(p)
            _v58_write_json(path,row); return path
    # Report why auto-fit was not possible from available public cache.
    _v58_write_json(path, {'status':'alpha_measurement_not_autobuilt','diagnostic_class':'no_density_split_bao_alpha_fit_found','reason':'No existing density-split BAO alpha likelihood/fit artifact was found. v58 does not hand-fill or fake alpha_high/alpha_low.','autofit_requirements':['density split catalogue','DESI randoms','BAO covariance','alpha_high_density','alpha_low_density','sky and density-label shuffles','redshift jackknife']})
    return path

_run_p33_v57_for_v58 = run_p33_density_bao_measurement_gate_v57
def run_p33_density_bao_measurement_gate_v58(meta,args):
    base=_run_p33_v57_for_v58(meta,args)
    p=_v58_autobuild_p33_alpha(base)
    row=_v58_artifact_row(p)
    missing=[]
    for k in ['covariance_used','desi_randoms_used','redshift_jackknife_stable','source_hashes_present']:
        if not _v58_truthy(row.get(k)): missing.append(k)
    for k in ['alpha_high_density','alpha_low_density','delta_alpha','delta_alpha_sigma']:
        if _v58_to_float(row.get(k)) is None: missing.append(k)
    for k in ['density_label_shuffle_p','sky_shuffle_p']:
        x=_v58_to_float(row.get(k))
        if x is None or x>0.05: missing.append(k+'_le_0.05')
    if abs(_v58_to_float(row.get('delta_alpha_sigma')) or 0)<2: missing.append('delta_alpha_sigma_ge_2')
    if str(row.get('status','')).endswith('not_autobuilt'): missing.append('autobuilt_real_alpha_measurement')
    gate={'gate_version':_V58_VERSION,'artifact_path':str(p),'missing':missing,'eligible_for_confirm_like':not missing,'diagnostic_class':row.get('diagnostic_class','alpha_artifact_present')}
    base['p33_alpha_measurement_gate_v58']=gate
    base['p33_alpha_autobuild_v58']=row
    if gate['eligible_for_confirm_like']: base['status']='p33_density_bao_alpha_confirm_like_v58'
    else: base['status']='p33_density_bao_alpha_measurement_required_v58'
    return base

# ---------- v58 PTA/GW/BB/q2/SMD: stricter diagnostic wrappers ----------
def _v58_autobuild_generic(patterns, out_name, hints, missing_status):
    out=_v58_measurements_dir()/out_name
    for p in _v58_candidate_files(patterns, roots=[_v58_measurements_dir(), _v58_outputs_dir(), _v58_cache_dir()]):
        if p==out or not _v58_not_template_path(p): continue
        row=_v58_artifact_row(p)
        if row and any(h in row for h in hints):
            row=dict(row, normalized_from_v58=str(p))
            row.setdefault('source_hashes_present', True)
            row.setdefault('source_file_hashes',[{'path':str(p),'sha256':_v58_sha256(p)}])
            _v58_write_json(out,row); return out
    _v58_write_json(out, {'status':missing_status,'diagnostic_class':'no_public_or_cached_likelihood_artifact','required_hint':hints})
    return out

def _v58_gate(path, bools=(), nums=(), thresholds=None, label='artifact'):
    thresholds=thresholds or {}; row=_v58_artifact_row(path); missing=[]
    for k in bools:
        if not _v58_truthy(row.get(k)): missing.append(k)
    for k in nums:
        if _v58_to_float(row.get(k)) is None: missing.append(k)
    for k,(op,val) in thresholds.items():
        x=_v58_to_float(row.get(k))
        if x is None: continue
        if op=='>=' and x<val: missing.append(f'{k}_ge_{val}')
        if op=='<=' and x>val: missing.append(f'{k}_le_{val}')
    if str(row.get('status','')).endswith(('not_autobuilt','required','missing')) or str(row.get('status','')).startswith(('no_','likelihood_not')):
        missing.append('autobuilt_real_'+label)
    return {'gate_version':_V58_VERSION,'artifact_path':str(path),'missing':missing,'eligible_for_confirm_like':not missing,'diagnostic_class':row.get('diagnostic_class')}

