_run_dashboard_v57_for_v58 = run_dashboard_v57
def _v58_artifact_index():
    try: base=_v57_artifact_index()
    except Exception: base=[]
    extra=[]
    for p in _v58_candidate_files(['*v58*.json','*v58*.csv'], roots=[_v58_inputs_dir(), _v58_measurements_dir(), _v58_outputs_dir()]):
        if p.name.startswith('test'): continue
        row=_v58_artifact_row(p)
        st=str(row.get('status',''))
        extra.append({'artifact_key':'v58_extra','path':str(p),'exists':p.exists(),'is_template':not _v58_not_template_path(p),'size_bytes':p.stat().st_size if p.exists() else 0,'sha256':_v58_sha256(p),'filled_and_usable':p.exists() and _v58_not_template_path(p) and bool(row) and not st.endswith('not_autobuilt') and not st.startswith('no_'),'diagnostic_class':row.get('diagnostic_class')})
    return base+extra

def run_dashboard_v58(meta,args):
    base=_run_dashboard_v57_for_v58(meta,args)
    rows=[]
    for p in sorted(_v58_outputs_dir().glob('test*.json')):
        if p.name.startswith('test51'): continue
        obj=_v58_read_json(p)
        if isinstance(obj,dict): rows.append(obj)
    confirms=[]; sm=[]; coverage=[]; blocked=[]; ready=[]; failed=[]; diagnostics={}
    for r in rows:
        st=str(r.get('status','')); pid=str(r.get('prediction_id',''))
        item={'test_id':r.get('test_id'),'prediction_id':pid,'prediction_name':r.get('prediction_name'),'status':st}
        if 'coverage_confirmed' in st: coverage.append(item)
        elif 'smd_constant_consistency_confirm_like' in st: sm.append(item)
        elif 'confirm_like' in st and not pid.startswith('SM') and 'coverage' not in st: confirms.append(item)
        elif any(x in st for x in ['blocked','failed','data_limited','required','not_confirmed']): blocked.append(item)
        else: ready.append(item)
        for k,v in r.items():
            if isinstance(v,dict) and ('gate_v58' in k or 'gate_v57' in k) and not v.get('eligible_for_confirm_like', True) and not v.get('eligible_for_route_confirm_like', True):
                failed.append({'test_id':r.get('test_id'),'prediction_id':pid,'gate':k,'missing':v.get('missing'),'diagnostic_class':v.get('diagnostic_class')})
                dc=v.get('diagnostic_class') or 'unspecified'
                diagnostics[dc]=diagnostics.get(dc,0)+1
    artifact_index=_v58_artifact_index()
    base['dashboard_v58']={'claim_policy':'v58 keeps no-manual-fill behavior but distinguishes no-public-row/data-limited cases from actual negative/tension. Promotion still requires strict non-template artifacts and passing gates.','artifact_index':artifact_index,'n_artifacts':len(artifact_index),'n_filled_usable_artifacts':sum(1 for a in artifact_index if a.get('filled_and_usable')),'nonSM_confirm_like':confirms,'SM_constant_consistency':sm,'coverage_confirmed':coverage,'ready_or_compatible':ready,'blocked_or_gate_failed':blocked,'failed_gates':failed[:1200],'diagnostic_class_counts':diagnostics,'confirm_recovery_priority':[{'test_id':'R10-T13','prediction':'P36 high-z','next':'improve public KGES/KROSS/KMOS3D row parsers; current code requires real Vrot/R/z rows'},{'test_id':'R10-T04','prediction':'P30','next':'fix curl/variant tension under same mask; do not global-confirm until curl weaker and second route exists'},{'test_id':'R10-T07','prediction':'P33','next':'implement real DESI density-split BAO alpha fitter'},{'test_id':'R10-T17','prediction':'PTA/CL2','next':'connect residual/TOA weights to kappa samples'},{'test_id':'R10-T19','prediction':'P32','next':'build one-event GW150914 strain likelihood'}],'n_nonSM_confirm_like':len(confirms),'n_SM_constant_consistency':len(sm),'n_coverage_confirmed':len(coverage),'n_blocked_or_gate_failed':len(blocked)}
    base['status']='dashboard_positive_current_only_v58'
    return _v60_scrub_manual_fill_references(base)

