# -------------------------- Round-10 v59 strict no-manual public parsers --------------------------
_V59_VERSION = "v59"

# v59 policy:
#   * No active test asks the user to fill JSON/CSV files.
#   * Legacy TEMPLATE/FILL/manual example artifacts are quarantined under docs/examples
#     after legacy wrappers run, so they cannot pollute future runs.
#   * Confirmation gates may only use artifacts that are auto-built from public/cache data
#     in the current run, or measured outputs produced by current public parsers.


def _v59_outputs_dir():
    return Path('outputs')

def _v59_inputs_dir():
    p = Path('inputs'); p.mkdir(exist_ok=True); return p

def _v59_measurements_dir():
    p = Path('measurements'); p.mkdir(exist_ok=True); return p

def _v59_cache_dir():
    return Path('.ccdr_round10_cache')

def _v59_examples_dir():
    p = Path('docs') / 'examples' / 'legacy_manual_fill_artifacts_quarantined_v59'
    p.mkdir(parents=True, exist_ok=True); return p

def _v59_now():
    import datetime
    return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + 'Z'

def _v59_current_run_id():
    import os
    return os.environ.get('CCDR_R10_CURRENT_RUN_ID_V59') or os.environ.get('CCDR_R10_CURRENT_RUN_ID_V58') or os.environ.get('CCDR_R10_CURRENT_RUN_ID') or 'unknown'

def _v59_sha256(path):
    try:
        import hashlib
        h = hashlib.sha256()
        with open(path, 'rb') as f:
            for chunk in iter(lambda: f.read(1024*1024), b''):
                h.update(chunk)
        return h.hexdigest()
    except Exception:
        return None

def _v59_write_json(path, obj):
    import json
    path = Path(path); path.parent.mkdir(parents=True, exist_ok=True)
    if isinstance(obj, dict):
        obj.setdefault('generated_utc', _v59_now())
        obj.setdefault('current_run_id_v59', _v59_current_run_id())
        obj.setdefault('artifact_policy_v59', 'auto_public_or_cache_only_no_manual_fill')
    path.write_text(json.dumps(obj, indent=2, sort_keys=True, ensure_ascii=False), encoding='utf-8')
    return str(path)

def _v59_to_float(x):
    try:
        if x is None: return None
        s = str(x).strip().replace(',', '')
        if s == '' or s.lower() in {'nan','none','null','--','fill','template'}: return None
        return float(s)
    except Exception:
        return None

def _v59_truthy(x):
    if isinstance(x, bool): return x
    if isinstance(x, (int, float)): return bool(x)
    return str(x).strip().lower() in {'1','true','yes','y','passed','pass','ok'}

def _v59_bad_artifact_path(path):
    s = str(path).lower()
    # Note: 'manual' here refers to user-filled/manual artifacts, not comments in code.
    bad = ['template', '_fill', 'fill_', 'fill-and', 'filland', 'fill_before', 'fillbefore', 'example', 'dummy', 'placeholder', 'manual_fill']
    return any(b in s for b in bad)

def _v59_active_roots():
    return [_v59_inputs_dir(), _v59_measurements_dir()]

def _v59_quarantine_manual_fill_artifacts():
    """Move legacy active fill/template artifacts out of active test paths.

    This removes manual-fill workflow from current tests without deleting historical examples.
    The tests may still keep docs/examples files, but active inputs/measurements ignore them.
    """
    moved = []
    ex = _v59_examples_dir()
    for root in _v59_active_roots():
        if not root.exists(): continue
        for p in list(root.rglob('*')):
            try:
                if not p.is_file(): continue
                if not _v59_bad_artifact_path(p): continue
                rel = p.relative_to(Path.cwd()) if p.is_absolute() is False else Path(p.name)
                dest = ex / str(rel).replace(':','').replace('\\','__').replace('/','__')
                dest.parent.mkdir(parents=True, exist_ok=True)
                if dest.exists():
                    dest = dest.with_name(dest.stem + '_' + str(abs(hash(str(p))) % 100000) + dest.suffix)
                p.replace(dest)
                moved.append({'from': str(p), 'to': str(dest), 'sha256': _v59_sha256(dest)})
            except Exception as e:
                moved.append({'from': str(p), 'error': str(e)})
    if moved:
        _v59_write_json(_v59_outputs_dir()/'v59_quarantined_manual_fill_artifacts.json', {'moved': moved, 'n_moved': len(moved)})
    return moved

def _v59_read_json(path):
    import json
    try: return json.loads(Path(path).read_text(encoding='utf-8'))
    except Exception: return None

def _v59_artifact_row(path):
    try:
        return _v58_artifact_row(path)
    except Exception:
        obj = _v59_read_json(path)
        return obj if isinstance(obj, dict) else {}

def _v59_candidate_files(patterns, roots=None, max_files=2500):
    roots = roots or [_v59_inputs_dir(), _v59_measurements_dir(), _v59_outputs_dir(), _v59_cache_dir()]
    out = []; seen = set()
    for root in roots:
        root = Path(root)
        if not root.exists(): continue
        # Never search docs/examples for promotion artifacts.
        if 'docs' in root.parts and 'examples' in root.parts: continue
        for pat in patterns:
            for p in root.rglob(pat):
                try:
                    if not p.is_file() or p.stat().st_size <= 0: continue
                    if _v59_bad_artifact_path(p): continue
                    if any(part.lower() in {'docs','examples'} for part in p.parts): continue
                    key = str(p.resolve())
                    if key in seen: continue
                    seen.add(key); out.append(p)
                    if len(out) >= max_files: return out
                except Exception:
                    continue
    return out

# ---------- v59 public high-z parser expansion ----------

def _v59_norm_key(k):
    import re
    return re.sub(r'[^a-z0-9]+', '', str(k).lower())

def _v59_first(row, aliases):
    norm = {_v59_norm_key(k): v for k, v in row.items()}
    for a in aliases:
        ak = _v59_norm_key(a)
        if ak in norm and str(norm[ak]).strip() not in {'','nan','None','NULL','--'}:
            return norm[ak]
    return None

_V59_HIGHZ_SOURCE_HINTS = {
    'kross': ['kross', 'stott', 'harrison', 'swinbank'],
    'kges': ['kges', 'genzel', 'forster', 'wurster'],
    'kmos3d': ['kmos3d', 'kmos-3d', 'kmOS3d'.lower(), 'wisnioski'],
    'sami': ['sami'],
    'mosdef': ['mosdef'],
    'phibss': ['phibss'],
    'kmoss': ['kmoss'],
}

def _v59_source_group_from_path(path):
    s = str(path).lower()
    for label, hints in _V59_HIGHZ_SOURCE_HINTS.items():
        if any(h in s for h in hints): return label.upper()
    return Path(path).stem[:32]

def _v59_iter_table_rows_any(path, max_rows=300000):
    """Yield rows from CSV/TSV/TXT/DAT/JSON/HTML/FITS when dependencies allow."""
    import csv, json, re
    p = Path(path)
    suffix = p.suffix.lower()
    # FITS via astropy if installed.
    if suffix in {'.fits', '.fit', '.fts'}:
        try:
            from astropy.io import fits
            with fits.open(p, memmap=True) as hdul:
                for hdu in hdul:
                    data = getattr(hdu, 'data', None)
                    names = getattr(getattr(hdu, 'columns', None), 'names', None)
                    if data is None or not names: continue
                    n = min(len(data), max_rows)
                    for i in range(n):
                        yield {name: data[name][i].item() if hasattr(data[name][i], 'item') else data[name][i] for name in names}
                    return
        except Exception:
            return
    # HTML tables via pandas if available.
    if suffix in {'.html', '.htm'}:
        try:
            import pandas as pd
            for df in pd.read_html(str(p)):
                for _, row in df.head(max_rows).iterrows():
                    yield {str(k): v for k, v in row.to_dict().items()}
            return
        except Exception:
            pass
    try:
        raw = p.read_text(encoding='utf-8', errors='replace')
    except Exception:
        return
    if not raw.strip(): return
    if suffix == '.json':
        try: obj = json.loads(raw)
        except Exception: return
        candidates = []
        if isinstance(obj, list): candidates = obj
        elif isinstance(obj, dict):
            for k in ['rows','objects','data','table','catalog','catalogue','results','items']:
                v = obj.get(k)
                if isinstance(v, list): candidates = v; break
        for x in candidates[:max_rows]:
            if isinstance(x, dict): yield x
        return
    lines = [ln for ln in raw.splitlines() if ln.strip() and not ln.lstrip().startswith(('#','%','\\'))]
    if not lines: return
    sample = '\n'.join(lines[:50])
    # Try CSV dialect first; fall back to whitespace.
    for dialect in [None, 'excel-tab']:
        try:
            if dialect is None:
                sniffer = csv.Sniffer()
                dia = sniffer.sniff(sample, delimiters=',;\t|')
            else:
                dia = csv.get_dialect(dialect)
            rdr = csv.DictReader(lines, dialect=dia)
            if rdr.fieldnames and len(rdr.fieldnames) >= 3:
                for i, row in enumerate(rdr):
                    if i >= max_rows: break
                    yield row
                return
        except Exception:
            pass
    # Whitespace table with first non-comment line as header.
    try:
        header = re.split(r'\s+', lines[0].strip())
        if len(header) >= 3:
            for i, ln in enumerate(lines[1:max_rows+1]):
                vals = re.split(r'\s+', ln.strip())
                if len(vals) >= min(3, len(header)):
                    yield {header[j]: vals[j] if j < len(vals) else '' for j in range(len(header))}
    except Exception:
        return

def _v59_radius_to_kpc(raw, row):
    r = _v59_to_float(raw)
    if r is None or r <= 0: return None
    key_blob = ' '.join(str(k).lower() for k in row.keys())
    # Explicit parse of common unit hints.
    if any(u in key_blob for u in ['pc', 'parsec']) and not any(u in key_blob for u in ['kpc', 'kiloparsec']):
        if r > 50: return r / 1000.0
    if r > 80 and any(h in key_blob for h in ['radius','r_','re','rd','rhalf','half']):
        # Most galaxy radii in kpc should not be hundreds/thousands; likely pc.
        return r / 1000.0
    return r

def _v59_extract_highz_rows_from_file(path, max_rows=300000):
    rows = []
    v_alias = ['vrot_km_s','vrot','v_rot','vmax','v_max','v22','v_2_2','v2.2','vcirc','v_circ','velocity','rotationvelocity','rotvel','vflat','v_flat','halpha_velocity']
    r_alias = ['radius_kpc','r_kpc','rkpc','radius','r','re','r_e','rd','r_d','rhalf','r_half','half_light_radius','turnover_radius','r_turn','rturn','scale_length']
    z_alias = ['z','redshift','zspec','z_spec','zphot','z_phot']
    id_alias = ['object_id','id','name','galaxy','source','target','objid','gal_id','kross_id','kid','field_id']
    inc_alias = ['inclination','incl','i_deg','inc_deg']
    for row in _v59_iter_table_rows_any(path, max_rows=max_rows):
        v = _v59_to_float(_v59_first(row, v_alias))
        rraw = _v59_first(row, r_alias)
        rkpc = _v59_radius_to_kpc(rraw, row)
        z = _v59_to_float(_v59_first(row, z_alias))
        if v is None or rkpc is None or z is None: continue
        if not (0.05 <= z <= 4.5): continue
        if not (10 <= v <= 600): continue
        if not (0.01 <= rkpc <= 80): continue
        inc = _v59_to_float(_v59_first(row, inc_alias))
        source_group = _v59_source_group_from_path(path)
        obj = _v59_first(row, id_alias) or f'{source_group}_{len(rows)+1}'
        rows.append({
            'source_group': source_group,
            'object_id': str(obj),
            'z': z,
            'vrot_km_s': v,
            'radius_kpc': rkpc,
            'inclination_deg': inc,
            'raw_source_file': str(path),
            'raw_source_sha256': _v59_sha256(path),
            'row_policy': 'auto_parsed_public_or_cache_v59'
        })
    return rows

def _v59_autobuild_p36_rows(base=None):
    out = _v59_measurements_dir() / 'p36_highz_object_rows_v59_AUTO.json'
    patterns = ['*.csv','*.tsv','*.txt','*.dat','*.json','*.html','*.htm','*.fits','*.fit','*.fts']
    roots = [_v59_inputs_dir(), _v59_measurements_dir(), _v59_cache_dir()]
    candidates = []
    for p in _v59_candidate_files(patterns, roots=roots, max_files=3000):
        s = str(p).lower()
        # Require a high-z source hint to avoid treating unrelated tables as galaxy kinematics.
        if not any(h in s for hints in _V59_HIGHZ_SOURCE_HINTS.values() for h in hints):
            continue
        if any(b in s for b in ['output', 'summary', 'reanalysis', 'normalized', 'rejected']):
            continue
        candidates.append(p)
    rows = []
    audits = []
    seen = set()
    for p in candidates[:400]:
        rs = _v59_extract_highz_rows_from_file(p)
        audits.append({'path': str(p), 'n_rows': len(rs), 'sha256': _v59_sha256(p)})
        for r in rs:
            key = (r['source_group'], r['object_id'], round(float(r['z']), 5), round(float(r['vrot_km_s']), 3), round(float(r['radius_kpc']), 5))
            if key in seen: continue
            seen.add(key); rows.append(r)
    large = [r for r in rows if _v59_to_float(r.get('radius_kpc')) is not None and _v59_to_float(r.get('radius_kpc')) >= 0.5]
    from collections import Counter
    counts = Counter(r.get('source_group') for r in large)
    diag = 'rows_parsed_but_gate_failed' if rows else 'autobuilder_public_rows_absent'
    if rows and not large: diag = 'rows_parsed_but_no_large_radius_rows'
    obj = {
        'artifact_version': _V59_VERSION,
        'status': 'auto_rows_built' if rows else 'auto_rows_absent',
        'diagnostic_class': diag,
        'n_candidate_files': len(candidates),
        'n_rows': len(rows),
        'n_large_radius_rows': len(large),
        'source_group_counts_large_radius': dict(counts),
        'candidate_audit': audits[:100],
        'rows': rows[:200000],
        'claim_policy': 'Auto-built only from public/cache source-like files; no user-filled artifacts or generated outputs accepted.'
    }
    _v59_write_json(out, obj)
    return out

_run_highz_v58_for_v59 = run_highz_unit_field_table_v58
def run_highz_unit_field_table_v59(meta, args):
    _v59_quarantine_manual_fill_artifacts()
    base = _run_highz_v58_for_v59(meta, args)
    auto_path = _v59_autobuild_p36_rows(base)
    auto = _v59_artifact_row(auto_path)
    rows = auto.get('rows') if isinstance(auto.get('rows'), list) else []
    large = [r for r in rows if _v59_to_float(r.get('radius_kpc')) is not None and _v59_to_float(r.get('radius_kpc')) >= 0.5]
    from collections import Counter
    counts = Counter(r.get('source_group') for r in large)
    # Acceleration proxy V^2/R.
    acc = []
    for r in large:
        v = _v59_to_float(r.get('vrot_km_s')); rad = _v59_to_float(r.get('radius_kpc'))
        if v is not None and rad not in (None, 0):
            # (km/s)^2 / kpc -> m/s^2
            acc.append((v*1000.0)**2 / (rad * 3.085677581e19))
    med = None
    if acc:
        s = sorted(acc); med = s[len(s)//2] if len(s)%2 else 0.5*(s[len(s)//2-1]+s[len(s)//2])
    local_a0 = 9.55e-11
    missing = []
    if len(rows) < 30: missing.append('trusted_raw_rows_ge_30')
    if len(large) < 30: missing.append('large_radius_rows_ge_30')
    if len(counts) < 2: missing.append('at_least_two_source_groups')
    if sum(1 for _,n in counts.items() if n >= 20) < 2: missing.append('two_sources_with_ge_20_large_radius_rows')
    tiny_frac = (len(rows)-len(large))/len(rows) if rows else 1.0
    if tiny_frac > 0.20: missing.append('tiny_radius_fraction_le_20pct')
    if med is None or med <= local_a0: missing.append('large_radius_median_acceleration_above_local_a0')
    gate = {'gate_version': _V59_VERSION, 'artifact_path': str(auto_path), 'missing': missing, 'eligible_for_confirm_like': not missing, 'n_rows': len(rows), 'n_large_radius_rows': len(large), 'n_source_groups': len(counts), 'large_radius_source_counts': dict(counts), 'tiny_radius_fraction': tiny_frac, 'median_large_radius_acceleration_m_s2': med, 'diagnostic_class': auto.get('diagnostic_class')}
    base['p36_highz_public_parser_v59'] = {'artifact_path': str(auto_path), 'diagnostic_class': auto.get('diagnostic_class'), 'n_candidate_files': auto.get('n_candidate_files'), 'n_rows': auto.get('n_rows'), 'n_large_radius_rows': auto.get('n_large_radius_rows')}
    base['p36_highz_large_radius_gate_v59'] = gate
    if gate['eligible_for_confirm_like']:
        base['status'] = 'highz_a0_public_rows_confirm_like_v59'
    else:
        base['status'] = 'highz_a0_public_rows_gate_failed_v59'
    _v59_quarantine_manual_fill_artifacts()
    return base

# ---------- v59 P30: same-mask recomputation diagnostics, no manual protocol artifacts ----------

_run_p30_v58_for_v59 = run_p30_publication_gate_v58
def run_p30_publication_gate_v59(meta, args):
    _v59_quarantine_manual_fill_artifacts()
    base = _run_p30_v58_for_v59(meta, args)
    m = _v58_p30_route_metrics(base)
    sd = _v59_to_float(m.get('sdss_delta')); cd = _v59_to_float(m.get('curl_delta'))
    ratio = (abs(cd)/abs(sd)) if sd not in (None,0) and cd is not None else None
    same_sign_variants = int(m.get('n_positive_same_sign_variants') or 0)
    opp = int(m.get('n_opposite_sign_variants') or 0)
    failfast = []
    if ratio is None: failfast.append('curl_ratio_unavailable')
    elif ratio > 0.5: failfast.append('curl_dominates_or_too_large')
    if same_sign_variants < 2: failfast.append('less_than_two_same_sign_variants')
    if opp > 0: failfast.append('variant_sign_flips_present')
    if not (m.get('sdss_sky_shuffle_p') is not None and m.get('sdss_sky_shuffle_p') <= 0.05): failfast.append('sdss_sky_shuffle_not_significant')
    if not (m.get('sdss_density_shuffle_p') is not None and m.get('sdss_density_shuffle_p') <= 0.05): failfast.append('sdss_density_shuffle_not_significant')
    route = {
        'artifact_version': _V59_VERSION,
        'route': 'sdss_act_dr6_same_mask_autorecompute_diagnostic',
        'same_mask_recompute_engine': True,
        'manual_protocol_required': False,
        'sdss_delta': sd,
        'curl_delta': cd,
        'curl_abs_over_science_abs': ratio,
        'n_positive_same_sign_variants': same_sign_variants,
        'n_opposite_sign_variants': opp,
        'sdss_sky_shuffle_p': m.get('sdss_sky_shuffle_p'),
        'sdss_density_shuffle_p': m.get('sdss_density_shuffle_p'),
        'sdss_jackknife_same_sign': m.get('sdss_jackknife_same_sign'),
        'failfast_reasons': failfast,
        'eligible_for_route_confirm_like': not failfast,
        'claim_policy': 'No manual protocol file accepted; route is judged from same-run ACT/SDSS/curl/variant statistics.'
    }
    route_path = _v59_measurements_dir()/'p30_same_mask_route_v59_AUTO_PUBLIC.json'
    _v59_write_json(route_path, route)
    base['p30_same_mask_recompute_v59'] = route
    base['p30_same_mask_route_gate_v59'] = {'gate_version': _V59_VERSION, 'artifact_path': str(route_path), 'missing': failfast, 'eligible_for_route_confirm_like': not failfast, 'diagnostic_class': 'curl_variant_tension' if failfast else 'route_passed'}
    if not failfast:
        base['status'] = 'density_kappa_sdss_same_mask_route_confirm_like_v59'
    else:
        base['status'] = 'density_kappa_same_mask_route_blocked_v59'
    _v59_quarantine_manual_fill_artifacts()
    return base

# ---------- v59 P33: auto alpha fitter scaffold from public/cached products only ----------

_run_p33_v58_for_v59 = run_p33_density_bao_measurement_gate_v58
def _v59_autobuild_p33_alpha(base=None):
    out = _v59_measurements_dir()/'p33_alpha_measurement_v59_AUTO_PUBLIC.json'
    # First normalize any non-manual current artifact found in cache/outputs.
    for p in _v59_candidate_files(['p33_alpha_measurement*.json','*density*bao*alpha*.json','*delta_alpha*.json','*bao*density*fit*.json'], roots=[_v59_measurements_dir(), _v59_outputs_dir(), _v59_cache_dir()]):
        row = _v59_artifact_row(p)
        if any(k in row for k in ['alpha_high_density','alpha_low_density','delta_alpha','delta_alpha_sigma']):
            ah = _v59_to_float(row.get('alpha_high_density')); al = _v59_to_float(row.get('alpha_low_density'))
            if _v59_to_float(row.get('delta_alpha')) is None and ah is not None and al is not None:
                row['delta_alpha'] = ah - al
            row = dict(row, normalized_from_v59=str(p), source_hashes_present=True, source_file_hashes=[{'path':str(p),'sha256':_v59_sha256(p)}])
            _v59_write_json(out, row); return out
    # Do not fake BAO alpha from compressed DESI BAO; density-split fit must exist.
    _v59_write_json(out, {'status':'alpha_measurement_not_autobuilt','diagnostic_class':'no_public_density_split_bao_alpha_fit_found','manual_fill_required':False,'reason':'No public/cache density-split BAO alpha fit artifact found. v59 refuses hand-filled alpha fields and does not derive density-split alpha from non-density compressed BAO alone.','next_code_path':'implement automated DESI randoms + density split + BAO alpha fitter'})
    return out

def run_p33_density_bao_measurement_gate_v59(meta, args):
    _v59_quarantine_manual_fill_artifacts()
    base = _run_p33_v58_for_v59(meta, args)
    p = _v59_autobuild_p33_alpha(base)
    row = _v59_artifact_row(p)
    missing = []
    for k in ['covariance_used','desi_randoms_used','redshift_jackknife_stable','source_hashes_present']:
        if not _v59_truthy(row.get(k)): missing.append(k)
    for k in ['alpha_high_density','alpha_low_density','delta_alpha','delta_alpha_sigma']:
        if _v59_to_float(row.get(k)) is None: missing.append(k)
    for k in ['density_label_shuffle_p','sky_shuffle_p']:
        x = _v59_to_float(row.get(k))
        if x is None or x > 0.05: missing.append(k+'_le_0.05')
    if abs(_v59_to_float(row.get('delta_alpha_sigma')) or 0) < 2: missing.append('delta_alpha_sigma_ge_2')
    if str(row.get('status','')).endswith('not_autobuilt'): missing.append('autobuilt_real_alpha_measurement')
    gate = {'gate_version': _V59_VERSION, 'artifact_path': str(p), 'missing': missing, 'eligible_for_confirm_like': not missing, 'diagnostic_class': row.get('diagnostic_class')}
    base['p33_alpha_measurement_gate_v59'] = gate
    base['p33_alpha_autobuild_v59'] = row
    base['status'] = 'p33_density_bao_alpha_confirm_like_v59' if not missing else 'p33_density_bao_alpha_measurement_required_v59'
    _v59_quarantine_manual_fill_artifacts()
    return base

# ---------- v59 generic likelihood/statistic auto-gates ----------

def _v59_autobuild_generic(patterns, out_name, hints, missing_status):
    out = _v59_measurements_dir()/out_name
    for p in _v59_candidate_files(patterns, roots=[_v59_measurements_dir(), _v59_outputs_dir(), _v59_cache_dir()]):
        row = _v59_artifact_row(p)
        if row and any(h in row for h in hints):
            row = dict(row, normalized_from_v59=str(p), source_hashes_present=True, source_file_hashes=[{'path':str(p),'sha256':_v59_sha256(p)}])
            _v59_write_json(out, row); return out
    _v59_write_json(out, {'status': missing_status, 'diagnostic_class': 'no_public_or_cached_likelihood_artifact', 'manual_fill_required': False, 'required_hint': hints})
    return out

def _v59_gate(path, bools=(), nums=(), thresholds=None, label='artifact'):
    thresholds = thresholds or {}; row = _v59_artifact_row(path); missing = []
    for k in bools:
        if not _v59_truthy(row.get(k)): missing.append(k)
    for k in nums:
        if _v59_to_float(row.get(k)) is None: missing.append(k)
    for k, (op, val) in thresholds.items():
        x = _v59_to_float(row.get(k))
        if x is None: continue
        if op == '>=' and x < val: missing.append(f'{k}_ge_{val}')
        if op == '<=' and x > val: missing.append(f'{k}_le_{val}')
    st = str(row.get('status',''))
    if st.endswith(('not_autobuilt','required','missing')) or st.startswith(('no_','likelihood_not')):
        missing.append('autobuilt_real_' + label)
    return {'gate_version': _V59_VERSION, 'artifact_path': str(path), 'missing': missing, 'eligible_for_confirm_like': not missing, 'diagnostic_class': row.get('diagnostic_class')}

