def run_dashboard_v59(meta,args):
    _v59_quarantine_manual_fill_artifacts()
    base = _run_dashboard_v58_for_v59(meta,args)
    rows = []
    for p in sorted(_v59_outputs_dir().glob('test*.json')):
        if p.name.startswith('test51'): continue
        obj = _v59_read_json(p)
        if isinstance(obj,dict): rows.append(obj)
    confirms=[]; sm=[]; coverage=[]; blocked=[]; ready=[]; failed=[]; diagnostics={}
    for r in rows:
        st = str(r.get('status','')); pid = str(r.get('prediction_id',''))
        item={'test_id':r.get('test_id'),'prediction_id':pid,'prediction_name':r.get('prediction_name'),'status':st}
        if 'coverage_confirmed' in st: coverage.append(item)
        elif 'smd_constant_consistency_confirm_like' in st: sm.append(item)
        elif 'confirm_like' in st and not pid.startswith('SM') and 'coverage' not in st: confirms.append(item)
        elif any(x in st for x in ['blocked','failed','data_limited','required','not_confirmed']): blocked.append(item)
        else: ready.append(item)
        for k,v in r.items():
            if isinstance(v,dict) and ('gate_v59' in k or 'gate_v58' in k) and not v.get('eligible_for_confirm_like', True) and not v.get('eligible_for_route_confirm_like', True):
                failed.append({'test_id':r.get('test_id'),'prediction_id':pid,'gate':k,'missing':v.get('missing'),'diagnostic_class':v.get('diagnostic_class')})
                dc = v.get('diagnostic_class') or 'unspecified'; diagnostics[dc] = diagnostics.get(dc,0)+1
    artifact_index = _v59_artifact_index()
    base['dashboard_v59'] = {'claim_policy':'v59 removes manual-fill artifacts from active paths. Tests use auto public/cache parsers only; if public data are insufficient, status remains blocked/data-limited instead of asking the user to fill files.','no_manual_fill_policy':True,'manual_fill_artifacts_quarantined':True,'artifact_index':artifact_index,'n_artifacts':len(artifact_index),'n_filled_usable_artifacts':sum(1 for a in artifact_index if a.get('filled_and_usable')),'nonSM_confirm_like':confirms,'SM_constant_consistency':sm,'coverage_confirmed':coverage,'ready_or_compatible':ready,'blocked_or_gate_failed':blocked,'failed_gates':failed[:1200],'diagnostic_class_counts':diagnostics,'confirm_recovery_priority':[{'test_id':'R10-T13','prediction':'P36 high-z','next':'deeper automatic public KGES/KROSS/KMOS3D/SAMI/MOSDEF/PHIBSS parsers'},{'test_id':'R10-T04','prediction':'P30','next':'same-mask recomputation plus curl/variant tension tests; no manual protocol files'},{'test_id':'R10-T07','prediction':'P33','next':'automated DESI density-split BAO alpha fitter'},{'test_id':'R10-T17','prediction':'PTA/CL2','next':'auto residual/TOA weights + kappa samples'},{'test_id':'R10-T19','prediction':'P32','next':'auto one-event strain likelihood builder'}],'n_nonSM_confirm_like':len(confirms),'n_SM_constant_consistency':len(sm),'n_coverage_confirmed':len(coverage),'n_blocked_or_gate_failed':len(blocked)}
    base['status']='dashboard_positive_current_only_v59'
    _v59_quarantine_manual_fill_artifacts()
    return _v60_scrub_manual_fill_references(base)

