# ==================== v60 no-manual public parser / confirm-recovery layer ====================
# v60 implements the requested "no manual data filling" policy more strictly:
# - no active FILL/TEMPLATE/manual artifacts are used for promotion;
# - tests try source-targeted public/cache parsers first;
# - blocked routes report explicit classes: parser_blocked, public_data_absent,
#   control_tension, likelihood_missing, statistic_not_significant.

_V60_VERSION = 'v60'

from pathlib import Path as _V60Path


def _v60_outputs_dir():
    p = _V60Path('outputs'); p.mkdir(exist_ok=True); return p

def _v60_inputs_dir():
    p = _V60Path('inputs'); p.mkdir(exist_ok=True); return p

def _v60_measurements_dir():
    p = _V60Path('measurements'); p.mkdir(exist_ok=True); return p

def _v60_cache_dir():
    p = _V60Path('.ccdr_round10_cache'); p.mkdir(exist_ok=True); return p

def _v60_public_dir():
    p = _v60_cache_dir() / 'v60_public_fetches'; p.mkdir(parents=True, exist_ok=True); return p

def _v60_examples_dir():
    p = _V60Path('docs') / 'examples' / 'legacy_manual_fill_artifacts_quarantined_v60'; p.mkdir(parents=True, exist_ok=True); return p

def _v60_now():
    import datetime
    return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + 'Z'

def _v60_current_run_id():
    import os
    return os.environ.get('CCDR_R10_CURRENT_RUN_ID_V60') or os.environ.get('CCDR_R10_CURRENT_RUN_ID_V59') or os.environ.get('CCDR_R10_CURRENT_RUN_ID') or 'unknown'

def _v60_sha256(path):
    try:
        import hashlib
        h = hashlib.sha256()
        with open(path, 'rb') as f:
            for chunk in iter(lambda: f.read(1024*1024), b''):
                h.update(chunk)
        return h.hexdigest()
    except Exception:
        return None

def _v60_write_json(path, obj):
    import json
    path = _V60Path(path); path.parent.mkdir(parents=True, exist_ok=True)
    if isinstance(obj, dict):
        obj.setdefault('generated_utc', _v60_now())
        obj.setdefault('current_run_id_v60', _v60_current_run_id())
        obj.setdefault('artifact_policy_v60', 'auto_public_or_cache_only_no_manual_fill')
    path.write_text(json.dumps(obj, indent=2, sort_keys=True, ensure_ascii=False), encoding='utf-8')
    return str(path)

def _v60_read_json(path):
    import json
    try:
        return json.loads(_V60Path(path).read_text(encoding='utf-8'))
    except Exception:
        return None

def _v60_to_float(x):
    try:
        if x is None: return None
        s = str(x).strip().replace(',', '')
        if s == '' or s.lower() in {'nan','none','null','--','fill','template','example','manual'}: return None
        # tolerate values like "123 +/- 4" or "1.23e-4*"
        import re
        m = re.search(r'[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?', s)
        return float(m.group(0)) if m else None
    except Exception:
        return None

def _v60_truthy(x):
    if isinstance(x, bool): return x
    if isinstance(x, (int, float)): return bool(x)
    return str(x).strip().lower() in {'1','true','yes','y','passed','pass','ok','usable'}

def _v60_bad_artifact_path(path):
    s = str(path).lower()
    bad = ['template', '_fill', 'fill_', 'fill-before', 'fill_before', 'fillbefore', 'example', 'dummy', 'placeholder', 'manual_fill', 'manual-fill']
    return any(b in s for b in bad)

def _v60_quarantine_manual_fill_artifacts():
    moved=[]; ex=_v60_examples_dir()
    for root in [_v60_inputs_dir(), _v60_measurements_dir()]:
        if not root.exists(): continue
        for p in list(root.rglob('*')):
            try:
                if not p.is_file(): continue
                if not _v60_bad_artifact_path(p): continue
                dest = ex / str(p).replace(':','').replace('\\','__').replace('/','__')
                dest.parent.mkdir(parents=True, exist_ok=True)
                if dest.exists(): dest = dest.with_name(dest.stem + '_' + str(abs(hash(str(p))) % 100000) + dest.suffix)
                p.replace(dest)
                moved.append({'from': str(p), 'to': str(dest), 'sha256': _v60_sha256(dest)})
            except Exception as e:
                moved.append({'from': str(p), 'error': str(e)})
    if moved:
        _v60_write_json(_v60_outputs_dir()/'v60_quarantined_manual_fill_artifacts.json', {'n_moved': len(moved), 'moved': moved})
    return moved



def _v60_scrub_manual_fill_references(obj):
    """Remove legacy active fill/template guidance from returned JSON.

    Historical v52-v56 keys may still be produced by lower wrappers. v60 keeps old
    computations for compatibility but removes user-facing manual-fill/template
    instructions from current test outputs.
    """
    bad_key_terms = {'artifact_templates','future_protocol','fill_contract','template_path','fillable_template','manual_fill','is_template'}
    def bad_string(x):
        lx=str(x).lower()
        return any(tok in lx for tok in ['_template', '_fill.', '_fill_', 'fill_and_rename', 'fill-before', 'fill_before', 'manual_fill'])
    def rec(x):
        if isinstance(x, dict):
            out={}
            for k,v in x.items():
                lk=str(k).lower()
                if any(term in lk for term in bad_key_terms):
                    continue
                if isinstance(v, str) and bad_string(v):
                    continue
                out[k]=rec(v)
            return out
        if isinstance(x, list):
            new=[]
            for v in x:
                if isinstance(v, str) and bad_string(v):
                    continue
                rv=rec(v)
                if rv not in ({}, [], None): new.append(rv)
            return new
        return x
    y=rec(obj)
    if isinstance(y, dict):
        y['no_manual_artifact_references_active_v60']=True
    return y

def _v60_candidate_files(patterns, roots=None, max_files=5000):
    roots = roots or [_v60_inputs_dir(), _v60_measurements_dir(), _v60_outputs_dir(), _v60_cache_dir(), _v60_public_dir()]
    out=[]; seen=set()
    for root in roots:
        root = _V60Path(root)
        if not root.exists(): continue
        if any(part.lower() in {'docs','examples'} for part in root.parts): continue
        for pat in patterns:
            for p in root.rglob(pat):
                try:
                    if not p.is_file() or p.stat().st_size <= 0: continue
                    if _v60_bad_artifact_path(p): continue
                    if any(part.lower() in {'docs','examples'} for part in p.parts): continue
                    k=str(p.resolve())
                    if k in seen: continue
                    seen.add(k); out.append(p)
                    if len(out) >= max_files: return out
                except Exception:
                    continue
    return out

# ---------- v60 public fetch helpers ----------

def _v60_url_to_cache_path(url, source_hint='public'):
    import hashlib, re
    h = hashlib.sha256(url.encode('utf-8')).hexdigest()[:16]
    name = re.sub(r'[^A-Za-z0-9_.-]+', '_', url.split('/')[-1] or source_hint)[:80]
    if '.' not in name: name += '.dat'
    return _v60_public_dir() / f'{source_hint}_{h}_{name}'

def _v60_try_download(url, source_hint='public', timeout=12):
    """Best-effort public downloader. Failure is data_limited, not fatal."""
    import urllib.request
    out = _v60_url_to_cache_path(url, source_hint)
    if out.exists() and out.stat().st_size > 0:
        return {'url': url, 'path': str(out), 'cached': True, 'ok': True, 'size_bytes': out.stat().st_size}
    try:
        req = urllib.request.Request(url, headers={'User-Agent':'CCDR-round10-v60-public-parser/1.0'})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            data = r.read(20*1024*1024)  # hard cap: 20 MB per file
        out.write_bytes(data)
        return {'url': url, 'path': str(out), 'cached': False, 'ok': True, 'size_bytes': len(data)}
    except Exception as e:
        return {'url': url, 'path': str(out), 'cached': False, 'ok': False, 'error': str(e)[:400]}

# ---------- v60 P36 high-z targeted public/cache parser ----------

_V60_HIGHZ_PUBLIC_URLS = [
    # These are intentionally best-effort candidate landing/data URLs. The parser
    # also scans all local cache files, so failed downloads do not block offline runs.
    ('KROSS', 'https://cdsarc.cds.unistra.fr/ftp/J/MNRAS/452/3578/table1.dat'),
    ('KROSS', 'https://cdsarc.cds.unistra.fr/viz-bin/cat/J/MNRAS/452/3578'),
    ('KGES', 'https://cdsarc.cds.unistra.fr/viz-bin/cat/J/ApJ/785/75'),
    ('KMOS3D', 'https://cdsarc.cds.unistra.fr/viz-bin/cat/J/ApJ/799/209'),
    ('KMOS3D', 'https://cdsarc.cds.unistra.fr/viz-bin/cat/J/ApJ/842/111'),
    ('SAMI', 'https://cdsarc.cds.unistra.fr/viz-bin/cat/J/MNRAS/447/2857'),
    ('MOSDEF', 'https://cdsarc.cds.unistra.fr/viz-bin/cat/J/ApJ/824/1'),
    ('PHIBSS', 'https://cdsarc.cds.unistra.fr/viz-bin/cat/J/ApJ/833/206'),
]

_V60_HIGHZ_COLUMN_MAPS = {
    'velocity': ['vrot_km_s','vrot','v_rot','vmax','v_max','v2.2','v_2_2','v22','vcirc','v_circ','vflat','v_flat','rotvel','rotationvelocity','vel','velocity','vobs','v_c'],
    'radius': ['radius_kpc','r_kpc','rkpc','radius','r','re','r_e','reff','r_eff','rd','r_d','rhalf','r_half','half_light_radius','turnover_radius','r_turn','rturn','scale_length','disk_radius'],
    'redshift': ['z','redshift','zspec','z_spec','zphot','z_phot','zbest'],
    'object_id': ['object_id','id','name','galaxy','source','target','objid','gal_id','field_id','kid','kross_id','kgid','kmos3d_id'],
    'inclination': ['inclination','incl','inc','i_deg','inc_deg'],
}

_V60_SOURCE_HINTS = {
    'KROSS': ['kross','stott','harrison','swinbank'],
    'KGES': ['kges','genzel','forster','wurster'],
    'KMOS3D': ['kmos3d','kmos-3d','wisnioski'],
    'SAMI': ['sami'],
    'MOSDEF': ['mosdef'],
    'PHIBSS': ['phibss'],
    'SINS': ['sins','sinfoni'],
}

def _v60_norm_key(k):
    import re
    return re.sub(r'[^a-z0-9]+', '', str(k).lower())

def _v60_first(row, aliases):
    norm = {_v60_norm_key(k): v for k, v in row.items()}
    for a in aliases:
        ak = _v60_norm_key(a)
        if ak in norm and str(norm[ak]).strip() not in {'','nan','None','NULL','--'}:
            return norm[ak]
    return None

def _v60_source_group_from_path(path):
    s = str(path).lower()
    for label,hints in _V60_SOURCE_HINTS.items():
        if any(h in s for h in hints): return label
    return _V60Path(path).stem[:32].upper()

def _v60_iter_rows_any(path, max_rows=500000):
    # Prefer the mature v59 reader if present, then add fixed-width fallback.
    try:
        yielded = False
        for r in _v59_iter_table_rows_any(path, max_rows=max_rows):
            yielded = True; yield r
        if yielded: return
    except Exception:
        pass
    import csv, re, json
    p=_V60Path(path)
    try:
        txt = p.read_text(encoding='utf-8', errors='replace')
    except Exception:
        return
    lines=[ln for ln in txt.splitlines() if ln.strip() and not ln.lstrip().startswith(('#','%','|---'))]
    if not lines: return
    # CDS ReadMe-style data can be fixed width. Try whitespace headers and numeric rows.
    header=None
    for ln in lines[:80]:
        toks=re.split(r'\s+', ln.strip())
        if len(toks)>=3 and any(_v60_norm_key(t) in {_v60_norm_key(a) for a in sum(_V60_HIGHZ_COLUMN_MAPS.values(), [])} for t in toks):
            header=toks; break
    if header:
        for ln in lines[lines.index(' '.join(header)) + 1:max_rows+1] if ' '.join(header) in lines else lines[1:max_rows+1]:
            vals=re.split(r'\s+', ln.strip())
            if len(vals)>=min(3,len(header)):
                yield {header[i]: vals[i] if i < len(vals) else '' for i in range(len(header))}

def _v60_radius_to_kpc(raw, row):
    r=_v60_to_float(raw)
    if r is None or r <= 0: return None, 'missing_or_nonpositive'
    key_blob=' '.join(str(k).lower() for k in row.keys())
    val_blob=' '.join(str(v).lower() for v in row.values())[:500]
    if any(u in key_blob for u in ['kpc','kiloparsec']) or 'kpc' in val_blob:
        return r, 'explicit_kpc'
    if any(u in key_blob for u in ['pc','parsec']) and 'kpc' not in key_blob:
        return r/1000.0, 'explicit_pc_to_kpc'
    if r > 80:
        return r/1000.0, 'large_value_assumed_pc_to_kpc'
    if 0.01 <= r <= 80:
        return r, 'assumed_kpc_safe_range'
    return None, 'ambiguous_radius_unit'

def _v60_extract_highz_rows_from_file(path, max_rows=500000):
    rows=[]
    for row in _v60_iter_rows_any(path, max_rows=max_rows):
        v=_v60_to_float(_v60_first(row, _V60_HIGHZ_COLUMN_MAPS['velocity']))
        z=_v60_to_float(_v60_first(row, _V60_HIGHZ_COLUMN_MAPS['redshift']))
        rraw=_v60_first(row, _V60_HIGHZ_COLUMN_MAPS['radius'])
        rkpc, rpol = _v60_radius_to_kpc(rraw, row)
        if v is None or z is None or rkpc is None: continue
        if not (0.05 <= z <= 5.0 and 10 <= v <= 700 and 0.01 <= rkpc <= 100): continue
        source_group=_v60_source_group_from_path(path)
        obj=_v60_first(row, _V60_HIGHZ_COLUMN_MAPS['object_id']) or f'{source_group}_{len(rows)+1}'
        inc=_v60_to_float(_v60_first(row, _V60_HIGHZ_COLUMN_MAPS['inclination']))
        rows.append({'source_group':source_group,'object_id':str(obj),'z':z,'vrot_km_s':v,'radius_kpc':rkpc,'radius_unit_policy':rpol,'inclination_deg':inc,'raw_source_file':str(path),'raw_source_sha256':_v60_sha256(path),'row_policy':'auto_public_or_cache_parsed_v60'})
    return rows

def _v60_fetch_highz_public_sources(args=None):
    attempts=[]
    timeout = int(getattr(args, 'timeout', 8) or 8) if args is not None else 8
    # Keep quick runs fast.
    if getattr(args, 'quick', False):
        return [{'skipped':'quick_mode'}]
    for label,url in _V60_HIGHZ_PUBLIC_URLS[:8]:
        attempts.append(_v60_try_download(url, 'p36_'+label.lower(), timeout=min(timeout, 12)))
    _v60_write_json(_v60_outputs_dir()/'p36_highz_public_fetch_audit_v60.json', {'attempts': attempts, 'n_ok': sum(1 for a in attempts if a.get('ok'))})
    return attempts

def _v60_autobuild_p36_rows(args=None):
    _v60_fetch_highz_public_sources(args)
    patterns=['*.csv','*.tsv','*.txt','*.dat','*.json','*.html','*.htm','*.fits','*.fit','*.fts']
    candidates=[]
    for p in _v60_candidate_files(patterns, roots=[_v60_inputs_dir(), _v60_measurements_dir(), _v60_cache_dir(), _v60_public_dir()], max_files=8000):
        s=str(p).lower()
        if any(b in s for b in ['output','summary','reanalysis','normalized','rejected','dashboard']): continue
        if not any(h in s for hints in _V60_SOURCE_HINTS.values() for h in hints): continue
        candidates.append(p)
    rows=[]; audits=[]; seen=set()
    for p in candidates[:1000]:
        rs=_v60_extract_highz_rows_from_file(p)
        audits.append({'path':str(p),'source_group':_v60_source_group_from_path(p),'n_rows':len(rs),'sha256':_v60_sha256(p)})
        for r in rs:
            key=(r['source_group'], r['object_id'], round(float(r['z']),5), round(float(r['vrot_km_s']),3), round(float(r['radius_kpc']),5))
            if key in seen: continue
            seen.add(key); rows.append(r)
    large=[r for r in rows if _v60_to_float(r.get('radius_kpc')) is not None and _v60_to_float(r.get('radius_kpc')) >= 0.5]
    from collections import Counter
    counts=Counter(r.get('source_group') for r in large)
    diag='public_rows_absent' if not rows else ('rows_parsed_but_no_large_radius_rows' if not large else 'rows_parsed_gate_evaluable')
    out=_v60_measurements_dir()/'p36_highz_object_rows_v60_AUTO_PUBLIC.json'
    _v60_write_json(out, {'artifact_version':_V60_VERSION,'status':'auto_rows_built' if rows else 'auto_rows_absent','diagnostic_class':diag,'n_candidate_files':len(candidates),'n_rows':len(rows),'n_large_radius_rows':len(large),'large_radius_source_counts':dict(counts),'candidate_audit':audits[:250],'rows':rows[:250000]})
    return out

_run_highz_v59_for_v60 = run_highz_unit_field_table_v59

def run_highz_unit_field_table_v60(meta,args):
    _v60_quarantine_manual_fill_artifacts()
    base=_run_highz_v59_for_v60(meta,args)
    p=_v60_autobuild_p36_rows(args)
    art=_v60_read_json(p) or {}
    rows=art.get('rows') if isinstance(art.get('rows'), list) else []
    large=[r for r in rows if (_v60_to_float(r.get('radius_kpc')) or 0) >= 0.5]
    from collections import Counter
    counts=Counter(r.get('source_group') for r in large)
    acc=[]
    for r in large:
        v=_v60_to_float(r.get('vrot_km_s')); rad=_v60_to_float(r.get('radius_kpc'))
        if v is not None and rad not in (None,0): acc.append((v*1000.0)**2/(rad*3.085677581e19))
    med=None
    if acc:
        acc=sorted(acc); med=acc[len(acc)//2] if len(acc)%2 else 0.5*(acc[len(acc)//2-1]+acc[len(acc)//2])
    missing=[]; local_a0=9.55e-11
    if len(rows)<30: missing.append('trusted_raw_rows_ge_30')
    if len(large)<30: missing.append('large_radius_rows_ge_30')
    if len(counts)<2: missing.append('at_least_two_source_groups')
    if sum(1 for n in counts.values() if n>=20)<2: missing.append('two_sources_with_ge_20_large_radius_rows')
    tiny_frac=(len(rows)-len(large))/len(rows) if rows else 1.0
    if tiny_frac>0.20: missing.append('tiny_radius_fraction_le_20pct')
    if med is None or med<=local_a0: missing.append('large_radius_median_acceleration_above_local_a0')
    gate={'gate_version':_V60_VERSION,'artifact_path':str(p),'missing':missing,'eligible_for_confirm_like':not missing,'n_rows':len(rows),'n_large_radius_rows':len(large),'n_source_groups':len(counts),'large_radius_source_counts':dict(counts),'tiny_radius_fraction':tiny_frac,'median_large_radius_acceleration_m_s2':med,'diagnostic_class':art.get('diagnostic_class') or ('parser_blocked' if not rows else 'statistic_not_significant')}
    base['p36_highz_public_parser_v60']={'artifact_path':str(p),'n_candidate_files':art.get('n_candidate_files'),'n_rows':art.get('n_rows'),'n_large_radius_rows':art.get('n_large_radius_rows'),'diagnostic_class':art.get('diagnostic_class')}
    base['p36_highz_large_radius_gate_v60']=gate
    base['why_not_confirm_v60']='' if gate['eligible_for_confirm_like'] else gate['diagnostic_class']
    base['status']='highz_a0_public_rows_confirm_like_v60' if gate['eligible_for_confirm_like'] else 'highz_a0_public_rows_gate_failed_v60'
    _v60_quarantine_manual_fill_artifacts(); return _v60_scrub_manual_fill_references(base)

# ---------- v60 P30 same-mask recomputation/fail-fast ----------

_run_p30_v59_for_v60 = run_p30_publication_gate_v59

def _v60_p30_route_metrics(base):
    try: return _v58_p30_route_metrics(base)
    except Exception:
        return {}

def run_p30_publication_gate_v60(meta,args):
    _v60_quarantine_manual_fill_artifacts()
    base=_run_p30_v59_for_v60(meta,args)
    m=_v60_p30_route_metrics(base)
    sd=_v60_to_float(m.get('sdss_delta')); cd=_v60_to_float(m.get('curl_delta'))
    ratio=(abs(cd)/abs(sd)) if sd not in (None,0) and cd is not None else None
    same=int(m.get('n_positive_same_sign_variants') or 0); opp=int(m.get('n_opposite_sign_variants') or 0)
    missing=[]
    if sd is None: missing.append('science_delta_available')
    if ratio is None: missing.append('curl_ratio_available')
    elif ratio > 0.5: missing.append('curl_abs_le_half_science_abs')
    if same < 2: missing.append('two_same_sign_positive_science_variants')
    if opp > 0: missing.append('no_opposite_sign_variants')
    if not (m.get('sdss_sky_shuffle_p') is not None and m.get('sdss_sky_shuffle_p') <= 0.05): missing.append('sky_shuffle_p_le_0p05')
    if not (m.get('sdss_density_shuffle_p') is not None and m.get('sdss_density_shuffle_p') <= 0.05): missing.append('density_shuffle_p_le_0p05')
    tension=[]
    if ratio is not None and ratio>0.5: tension.append('curl_dominance')
    if opp>0: tension.append('variant_sign_flip')
    # Reuse existing field/patch diagnostics if available.
    if isinstance(base.get('field_or_region_jackknife_v17'), dict) and not base['field_or_region_jackknife_v17'].get('all_positive', False): tension.append('field_jackknife_sign_instability')
    route={'gate_version':_V60_VERSION,'metric_source':'same_run_current_outputs_no_manual_protocol','missing':missing,'eligible_for_route_confirm_like':not missing,'sdss_delta':sd,'curl_delta':cd,'curl_abs_over_science_abs':ratio,'n_positive_same_sign_variants':same,'n_opposite_sign_variants':opp,'tension_classes':tension,'diagnostic_class':'control_tension' if tension else ('statistic_not_significant' if missing else 'route_passed')}
    base['p30_same_mask_recompute_gate_v60']=route
    base['why_not_confirm_v60']='' if route['eligible_for_route_confirm_like'] else route['diagnostic_class']
    base['status']='density_kappa_same_mask_route_confirm_like_v60' if route['eligible_for_route_confirm_like'] else 'density_kappa_same_mask_route_blocked_v60'
    return _v60_scrub_manual_fill_references(base)

# ---------- v60 P33 automated alpha artifact finder/fitter scaffold ----------

_run_p33_v59_for_v60 = run_p33_density_bao_measurement_gate_v59

def _v60_autobuild_p33_alpha(base=None):
    # Search for real alpha tables in public/cache outputs. No FILL/TEMPLATE accepted.
    candidates=_v60_candidate_files(['*p33*alpha*.json','*density*bao*alpha*.json','*bao*alpha*.csv','*bao*alpha*.tsv','*bao*alpha*.txt'], roots=[_v60_outputs_dir(),_v60_measurements_dir(),_v60_cache_dir()], max_files=1000)
    best=None; audits=[]
    for p in candidates:
        if _v60_bad_artifact_path(p): continue
        row=_v60_read_json(p) if p.suffix.lower()=='.json' else None
        if not isinstance(row, dict):
            # Parse simple key/value-ish CSV headers via v60 row reader.
            vals=list(_v60_iter_rows_any(p, max_rows=10))
            row=vals[0] if vals else {}
        ah=_v60_to_float(row.get('alpha_high_density') or row.get('alpha_high') or row.get('alpha_hi'))
        al=_v60_to_float(row.get('alpha_low_density') or row.get('alpha_low') or row.get('alpha_lo'))
        da=_v60_to_float(row.get('delta_alpha'))
        if da is None and ah is not None and al is not None: da=ah-al
        sig=_v60_to_float(row.get('delta_alpha_sigma') or row.get('significance_sigma'))
        normalized={'source_path':str(p),'source_sha256':_v60_sha256(p),'alpha_high_density':ah,'alpha_low_density':al,'delta_alpha':da,'delta_alpha_sigma':sig,'covariance_used':_v60_truthy(row.get('covariance_used')),'desi_randoms_used':_v60_truthy(row.get('desi_randoms_used')),'density_label_shuffle_p':_v60_to_float(row.get('density_label_shuffle_p')),'sky_shuffle_p':_v60_to_float(row.get('sky_shuffle_p')),'redshift_jackknife_stable':_v60_truthy(row.get('redshift_jackknife_stable')),'source_hashes_present':bool(row.get('source_file_hashes') or row.get('source_hashes_present'))}
        audits.append(normalized)
        if ah is not None and al is not None: best=normalized; break
    out=_v60_measurements_dir()/'p33_alpha_measurement_v60_AUTO_PUBLIC.json'
    if best is None:
        best={'status':'alpha_fit_not_found','diagnostic_class':'likelihood_missing','candidate_count':len(candidates),'candidate_audit':audits[:50]}
    else:
        best.update({'status':'alpha_fit_found','diagnostic_class':'fit_found_gate_evaluable'})
    _v60_write_json(out,best); return out

def run_p33_density_bao_measurement_gate_v60(meta,args):
    _v60_quarantine_manual_fill_artifacts()
    base=_run_p33_v59_for_v60(meta,args)
    p=_v60_autobuild_p33_alpha(base); art=_v60_read_json(p) or {}
    missing=[]
    for k in ['alpha_high_density','alpha_low_density','delta_alpha']:
        if _v60_to_float(art.get(k)) is None: missing.append(k)
    if _v60_to_float(art.get('delta_alpha_sigma')) is None or _v60_to_float(art.get('delta_alpha_sigma')) < 2.0: missing.append('delta_alpha_sigma_ge_2')
    if not _v60_truthy(art.get('covariance_used')): missing.append('covariance_used')
    if not _v60_truthy(art.get('desi_randoms_used')): missing.append('desi_randoms_used')
    if _v60_to_float(art.get('density_label_shuffle_p')) is None or _v60_to_float(art.get('density_label_shuffle_p')) > 0.05: missing.append('density_label_shuffle_p_le_0p05')
    if _v60_to_float(art.get('sky_shuffle_p')) is None or _v60_to_float(art.get('sky_shuffle_p')) > 0.05: missing.append('sky_shuffle_p_le_0p05')
    if not _v60_truthy(art.get('redshift_jackknife_stable')): missing.append('redshift_jackknife_stable')
    if not _v60_truthy(art.get('source_hashes_present')): missing.append('source_hashes_present')
    gate={'gate_version':_V60_VERSION,'artifact_path':str(p),'missing':missing,'eligible_for_confirm_like':not missing,'diagnostic_class':'fit_missing_or_incomplete' if missing else 'alpha_fit_passed'}
    base['p33_alpha_measurement_gate_v60']=gate
    base['status']='p33_density_bao_alpha_confirm_like_v60' if gate['eligible_for_confirm_like'] else 'p33_density_bao_alpha_measurement_required_v60'
    return _v60_scrub_manual_fill_references(base)

# ---------- v60 generic likelihood/statistic gates ----------

def _v60_gate_real_artifact(patterns, out_name, required_bool=(), required_num=(), thresholds=None, label='artifact'):
    thresholds=thresholds or {}
    # Use v59 generic normalizer first if present.
    try:
        p=_v59_autobuild_generic(patterns, out_name, list(required_bool)+list(required_num), f'{label}_not_autobuilt')
    except Exception:
        p=_v60_measurements_dir()/out_name; _v60_write_json(p, {'status':f'{label}_not_autobuilt','diagnostic_class':'likelihood_missing'})
    row=_v60_read_json(p) or {}
    missing=[]
    st=str(row.get('status',''))
    if st.endswith('not_autobuilt') or st.startswith('no_'): missing.append('autobuilt_real_'+label)
    for k in required_bool:
        if not _v60_truthy(row.get(k)): missing.append(k)
    for k in required_num:
        if _v60_to_float(row.get(k)) is None: missing.append(k)
    for k,(op,val) in thresholds.items():
        x=_v60_to_float(row.get(k))
        if x is None: missing.append(k); continue
        if op=='>=' and not (x>=val): missing.append(f'{k}_ge_{val}')
        if op=='<=' and not (x<=val): missing.append(f'{k}_le_{val}')
    return {'gate_version':_V60_VERSION,'artifact_path':str(p),'missing':missing,'eligible_for_confirm_like':not missing,'diagnostic_class':'likelihood_missing' if missing else 'likelihood_passed'}

