# ---------- v60 dashboard ----------

_run_dashboard_v59_for_v60 = run_dashboard_v59

def _v60_why_not_confirm_class(row):
    st=str(row.get('status',''))
    if 'public_rows' in st or 'parser' in st or 'endpoint_data_limited' in st: return 'parser_blocked_or_public_rows_absent'
    if 'p33' in st or 'likelihood_required' in st or 'strain_analysis_required' in st: return 'likelihood_or_fit_missing'
    if 'density_kappa' in st: return 'control_tension'
    if 'not_detection' in st or 'positive_ready' in st: return 'readiness_not_signal'
    if 'data_limited' in st: return 'public_data_absent_or_limited'
    return 'not_claim_grade'

def _v60_artifact_index():
    try: base=_v59_artifact_index()
    except Exception: base=[]
    extra=[]
    for p in _v60_candidate_files(['*v60*.json','*v60*.csv'], roots=[_v60_inputs_dir(),_v60_measurements_dir(),_v60_outputs_dir(),_v60_public_dir()]):
        if p.name.startswith('test'): continue
        row=_v60_read_json(p) or {}
        st=str(row.get('status',''))
        usable=p.exists() and not _v60_bad_artifact_path(p) and bool(row) and not st.endswith('not_autobuilt') and not st.startswith('no_') and 'absent' not in st
        extra.append({'artifact_key':'v60_extra','path':str(p),'exists':p.exists(),'size_bytes':p.stat().st_size if p.exists() else 0,'sha256':_v60_sha256(p),'filled_and_usable':usable,'diagnostic_class':row.get('diagnostic_class')})
    return [a for a in base+extra if not _v60_bad_artifact_path(a.get('path',''))]

def run_dashboard_v60(meta,args):
    _v60_quarantine_manual_fill_artifacts()
    base=_run_dashboard_v59_for_v60(meta,args)
    rows=[]
    for p in sorted(_v60_outputs_dir().glob('test*.json')):
        if p.name.startswith('test51'): continue
        obj=_v60_read_json(p)
        if isinstance(obj,dict): rows.append(obj)
    confirms=[]; sm=[]; coverage=[]; blocked=[]; ready=[]; why={}
    failed=[]
    for r in rows:
        st=str(r.get('status','')); pid=str(r.get('prediction_id',''))
        item={'test_id':r.get('test_id'),'prediction_id':pid,'prediction_name':r.get('prediction_name'),'status':st,'why_not_confirm':_v60_why_not_confirm_class(r)}
        if 'coverage_confirmed' in st: coverage.append(item)
        elif 'smd_constant_consistency_confirm_like' in st: sm.append(item)
        elif 'confirm_like' in st and not pid.startswith('SM') and 'coverage' not in st: confirms.append(item)
        elif any(x in st for x in ['blocked','failed','data_limited','required','not_confirmed']): blocked.append(item)
        else: ready.append(item)
        why[item['why_not_confirm']]=why.get(item['why_not_confirm'],0)+1
        for k,v in r.items():
            if isinstance(v,dict) and ('gate_v60' in k or 'gate_v59' in k) and not v.get('eligible_for_confirm_like', True) and not v.get('eligible_for_route_confirm_like', True):
                failed.append({'test_id':r.get('test_id'),'prediction_id':pid,'gate':k,'missing':v.get('missing'),'diagnostic_class':v.get('diagnostic_class')})
    art=_v60_artifact_index()
    # Remove legacy dashboard sections that still contained old manual/example artifact descriptions.
    for _k in list(base.keys()):
        if str(_k).startswith('dashboard_v') and _k != 'dashboard_v60':
            base.pop(_k, None)
        if 'artifact_template' in str(_k).lower() or 'template' in str(_k).lower():
            base.pop(_k, None)
    base['dashboard_v60']={'claim_policy':'v60 no-manual public parser policy: tests must auto-download/auto-parse public or cached data. Legacy manual/example artifacts are quarantined and ignored.','no_manual_fill_policy':True,'artifact_index':art,'n_artifacts':len(art),'n_filled_usable_artifacts':sum(1 for a in art if a.get('filled_and_usable')),'nonSM_confirm_like':confirms,'SM_constant_consistency':sm,'coverage_confirmed':coverage,'ready_or_compatible':ready,'blocked_or_gate_failed':blocked,'failed_gates':failed[:1500],'why_not_confirm_class_counts':why,'confirm_recovery_priority':[{'test_id':'R10-T13','prediction':'P36 high-z','next':'source-targeted public downloads + column maps + unit provenance'},{'test_id':'R10-T04','prediction':'P30','next':'same-mask recomputation and curl/variant tension repair'},{'test_id':'R10-T07','prediction':'P33','next':'automated DESI density-split BAO alpha fitter'},{'test_id':'R10-T17','prediction':'PTA/CL2','next':'automatic residual/TOA weights and kappa sampling'},{'test_id':'R10-T19','prediction':'P32','next':'one-event GW strain likelihood builder'}],'n_nonSM_confirm_like':len(confirms),'n_SM_constant_consistency':len(sm),'n_coverage_confirmed':len(coverage),'n_blocked_or_gate_failed':len(blocked)}
    base['status']='dashboard_positive_current_only_v60'
    return _v60_scrub_manual_fill_references(base)

