_V61_VERSION = 'v61'

def _v61_run_id():
    return os.environ.get('CCDR_R10_CURRENT_RUN_ID_V61') or os.environ.get('CCDR_R10_CURRENT_RUN_ID') or 'unknown'

def _v61_paths():
    root = Path(__file__).resolve().parent
    return {'root': root, 'cache': root / os.environ.get('CCDR_R10_CACHE', '.ccdr_round10_cache'), 'outputs': root / 'outputs', 'measurements': root / 'measurements', 'public': root / 'public_data', 'inputs': root / 'inputs'}

def _v61_dir(name):
    d = _v61_paths()[name]; d.mkdir(parents=True, exist_ok=True); return d

def _v61_write_json(path, obj):
    path = Path(path); path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + '.tmp')
    tmp.write_text(json.dumps(obj, indent=2, sort_keys=True), encoding='utf-8')
    tmp.replace(path); return path

def _v61_read_json(path):
    try: return json.loads(Path(path).read_text(encoding='utf-8'))
    except Exception: return None

def _v61_sha256(path):
    try:
        import hashlib
        h=hashlib.sha256()
        with open(path,'rb') as f:
            for b in iter(lambda:f.read(1024*1024), b''):
                h.update(b)
        return h.hexdigest()
    except Exception:
        return None

def _v61_float(x): return _v60_to_float(x)
def _v61_truthy(x): return _v60_truthy(x)

def _v61_bad_path(path):
    s = str(path).lower()
    return any(b in s for b in ['template','fill','manual','example','reanalysis','rejected','summary','round10_summary','dashboard'])

def _v61_text(path, max_bytes=5_000_000):
    try: return read_text_any(Path(path), max_bytes=max_bytes)
    except Exception:
        try: return Path(path).read_text(encoding='utf-8', errors='replace')[:max_bytes]
        except Exception: return ''

def _v61_download(urls, label, args, max_mb=None):
    old_max = getattr(args, 'max_mb', None)
    if max_mb is not None:
        try: args.max_mb = max(getattr(args, 'max_mb', 0) or 0, max_mb)
        except Exception: pass
    paths=[]; attempts=[]
    for u in urls:
        try:
            p, at = download_candidates([u], Path(args.cache_dir), label + '_' + cache_name(u)[:32], args)
            attempts += at or []
            if p and Path(p).exists() and Path(p).stat().st_size > 0: paths.append(Path(p))
        except Exception as e:
            attempts.append({'url':u,'error':str(e)})
    if old_max is not None:
        try: args.max_mb = old_max
        except Exception: pass
    return paths, attempts

# ---------- v61 P36 high-z: source-targeted fetchers, column maps, provenance ----------

_V61_HIGHZ_SOURCE_REGISTRY = {
    'KROSS': {'pages': ['https://astro.dur.ac.uk/KROSS/data.html', 'https://cdsarc.cds.unistra.fr/viz-bin/cat/J/MNRAS/474/5076'], 'direct': ['https://vizier.cds.unistra.fr/viz-bin/asu-tsv?-source=J/MNRAS/474/5076&-out.max=unlimited'], 'hints': ['kross','474/5076','mnras/474/5076'], 'aliases': {'id':['source','name','id','kid','object','galaxy','kross'], 'z':['z','z_ha','zha','redshift','ha_redshift'], 'v':['vrot','v_rot','vc','v_c','v22','v_2.2','v2p2','vmax','v_max','vflat','velocity'], 'r':['re','r_e','rd','r_d','rturn','r_turn','r_2.2','radius','size','hlr','r50','continuum_size'], 'inc':['inc','inclination','i','i_deg','inc_deg']}},
    'KGES': {'pages': ['https://astro.dur.ac.uk/kmos/kges/', 'https://cdsarc.cds.unistra.fr/viz-bin/cat/J/MNRAS/506/323'], 'direct': ['https://vizier.cds.unistra.fr/viz-bin/asu-tsv?-source=J/MNRAS/506/323&-out.max=unlimited'], 'hints': ['kges','506/323','tiley'], 'aliases': {'id':['source','name','id','object','galaxy','kges'], 'z':['z','redshift','z_ha','zha'], 'v':['vrot','v_rot','vmax','v_max','v22','v_2.2','vc','v_c','velocity'], 'r':['re','r_e','rd','r_d','rturn','r_turn','radius','size','r50'], 'inc':['inc','inclination','i','i_deg','inc_deg']}},
    'KMOS3D': {'pages': ['https://www.mpe.mpg.de/ir/KMOS3D/data', 'https://www.mpe.mpg.de/resources/IR/KMOS3D/data/README'], 'direct': ['https://www.mpe.mpg.de/resources/IR/KMOS3D/data/k3d_fnlsp_table_hafits_v3.fits','https://www.mpe.mpg.de/resources/IR/KMOS3D/data/README'], 'hints': ['kmos3d','k3d','fnlsp','hafits'], 'aliases': {'id':['id','name','object','galaxy','k3d','source'], 'z':['z','redshift','z_ha','zspec'], 'v':['vrot','v_rot','vmax','vmax_re','vcirc','v_circ','v22','v_2.2','vout','velocity'], 'r':['re','r_e','rd','r_d','r_eff','reff','radius','rturn','r_turn'], 'inc':['inc','inclination','i','i_deg','inc_deg']}},
    'SAMI': {'pages': ['https://sami-survey.org/', 'https://datacentral.org.au/services/schema/'], 'direct': [], 'hints': ['sami'], 'aliases': {'id':['catid','id','name','object','galaxy'], 'z':['z','redshift','z_spec'], 'v':['vrot','v_rot','vmax','v_max','vcirc','velocity'], 'r':['re','r_e','r_eff','reff','radius','size'], 'inc':['inc','inclination','i_deg']}},
    'MOSDEF': {'pages': ['https://mosdef.astro.berkeley.edu/for-scientists/data-releases/'], 'direct': [], 'hints': ['mosdef'], 'aliases': {'id':['id','name','object','galaxy'], 'z':['z','redshift','z_spec','zspec'], 'v':['vrot','v_rot','vmax','velocity'], 'r':['re','r_e','reff','r_eff','radius','size'], 'inc':['inc','inclination','i_deg']}},
    'PHIBSS': {'pages': ['https://www.iram.fr/~phibss2/Data_Release.html'], 'direct': ['https://www.iram.fr/~phibss2/Data_Release.html'], 'hints': ['phibss'], 'aliases': {'id':['id','name','object','galaxy'], 'z':['z','redshift','z_spec'], 'v':['vrot','v_rot','vmax','vcirc','velocity','linewidth'], 'r':['re','r_e','reff','r_eff','radius','size'], 'inc':['inc','inclination','i_deg']}},
}

def _v61_absolute_url(base, href):
    try:
        import urllib.parse
        return urllib.parse.urljoin(base, href)
    except Exception: return href

def _v61_links_from_html(path, base_url):
    txt = _v61_text(path, max_bytes=3_000_000); links=[]
    for m in re.finditer("href=[\"']([^\"']+)[\"']", txt, flags=re.I):
        u = _v61_absolute_url(base_url, m.group(1))
        if re.search(r'(?i)(\.csv|\.tsv|\.txt|\.dat|\.fits|\.fit|\.fts|\.gz|\.zip|\.tar|asu-tsv|viz-bin|download)', u): links.append(u)
    return sorted(set(links))

def _v61_fetch_highz_sources(args):
    paths=[]; attempts=[]; by_source={}
    for source, cfg in _V61_HIGHZ_SOURCE_REGISTRY.items():
        if getattr(args, 'quick', False):
            continue
        urls=list(cfg.get('direct', []))
        page_paths, at = _v61_download(cfg.get('pages', []), f'v61_highz_{source}_page', args, max_mb=25)
        attempts += at
        for pp, page_url in zip(page_paths, cfg.get('pages', [])):
            urls.extend(_v61_links_from_html(pp, page_url)); paths.append(pp); by_source[str(pp)] = source
        data_paths, at = _v61_download(sorted(set(urls))[:30], f'v61_highz_{source}_data', args, max_mb=200)
        attempts += at
        for dp in data_paths:
            paths.append(dp); by_source[str(dp)] = source
    for p in _v60_candidate_files(['*.csv','*.tsv','*.txt','*.dat','*.json','*.html','*.htm','*.fits','*.fit','*.fts','*.gz'], roots=[_v60_cache_dir(), _v60_public_dir(), _v60_outputs_dir()], max_files=6000):
        if _v61_bad_path(p): continue
        ss=str(p).lower()
        for src,cfg in _V61_HIGHZ_SOURCE_REGISTRY.items():
            if any(h.lower() in ss for h in cfg.get('hints', [])):
                paths.append(Path(p)); by_source[str(p)] = src; break
    out=[]; seen=set()
    for p in paths:
        try: key=str(Path(p).resolve())
        except Exception: key=str(p)
        if key not in seen and Path(p).exists() and Path(p).stat().st_size>0:
            seen.add(key); out.append(Path(p))
    return out, attempts, by_source

def _v61_norm_col(c): return re.sub(r'[^a-z0-9]+','',str(c).lower())

def _v61_pick(row, aliases):
    norm={_v61_norm_col(k):k for k in row.keys()}
    for a in aliases:
        an=_v61_norm_col(a)
        if an in norm: return norm[an], row.get(norm[an])
    for a in aliases:
        an=_v61_norm_col(a)
        for nk,orig in norm.items():
            if an and (an == nk or an in nk or nk in an): return orig, row.get(orig)
    return None, None

def _v61_radius_to_kpc(value, colname, row, source):
    x=_v61_float(value)
    if x is None: return None, 'missing'
    lc=(colname or '').lower()
    if any(u in lc for u in ['arcsec','asec','as_']): return None, 'angular_radius_rejected_no_cosmology_conversion'
    if any(u in lc for u in ['pc']) and 'kpc' not in lc: return x/1000.0, 'pc_to_kpc_from_column_name'
    if 'kpc' in lc: return x, 'kpc_from_column_name'
    if any(k in lc for k in ['re','reff','r_e','rd','r_d','rturn','radius','size','r50','hlr']):
        if x > 200: return x/1000.0, 'pc_to_kpc_by_value_gt_200'
        return x, 'assumed_kpc_safe_range'
    return None, 'ambiguous_radius_column'

def _v61_velocity_to_kms(value, colname, row):
    x=_v61_float(value)
    if x is None: return None, 'missing'
    lc=(colname or '').lower()
    if 'm/s' in lc and 'km' not in lc: return x/1000.0, 'm_s_to_km_s_from_column_name'
    if 10 <= abs(x) <= 800: return abs(x), 'km_s_safe_range'
    return None, 'velocity_out_of_safe_range'

def _v61_iter_rows(path):
    path=Path(path)
    try:
        if path.suffix.lower() in ['.gz']:
            import gzip
            txt=gzip.open(path,'rt',errors='replace').read(5_000_000)
            return sniff_table(txt)[:300000]
    except Exception: pass
    try: return list(_v59_iter_table_rows_any(path, max_rows=300000))
    except Exception: pass
    try: return sniff_table(_v61_text(path, max_bytes=10_000_000))[:300000]
    except Exception: return []

def _v61_extract_p36_rows_from_file(path, source_hint=None):
    path=Path(path); source=source_hint
    if source is None:
        ss=str(path).lower()
        for src,cfg in _V61_HIGHZ_SOURCE_REGISTRY.items():
            if any(h.lower() in ss for h in cfg.get('hints', [])): source=src; break
    source=source or 'UNKNOWN_HIGHZ'; cfg=_V61_HIGHZ_SOURCE_REGISTRY.get(source, {}); aliases=cfg.get('aliases', {})
    rows=[]; rejected=[]; sha=_v61_sha256(path)
    for idx,row in enumerate(_v61_iter_rows(path)):
        if not isinstance(row, dict): continue
        z_col,z_val=_v61_pick(row, aliases.get('z', ['z','redshift']))
        v_col,v_val=_v61_pick(row, aliases.get('v', ['vrot','vmax','velocity']))
        r_col,r_val=_v61_pick(row, aliases.get('r', ['re','radius','size']))
        id_col,id_val=_v61_pick(row, aliases.get('id', ['id','name','object']))
        inc_col,inc_val=_v61_pick(row, aliases.get('inc', ['inc','inclination']))
        z=_v61_float(z_val); v,v_method=_v61_velocity_to_kms(v_val, v_col, row); rkpc,r_method=_v61_radius_to_kpc(r_val, r_col, row, source)
        reason=[]
        if z is None or not (0.2 <= z <= 4.5): reason.append('redshift_missing_or_outside_highz_range')
        if v is None or not (20 <= v <= 700): reason.append('velocity_missing_or_outside_safe_range')
        if rkpc is None or not (0.05 <= rkpc <= 80): reason.append('radius_missing_or_outside_safe_range')
        obj=str(id_val).strip() if id_val not in (None,'') else f'{source}_{idx+1}'
        prov={'source_group':source,'raw_source_file':str(path),'source_file_hash':sha,'row_index':idx,'original_columns':{'object_id':id_col,'z':z_col,'vrot':v_col,'radius':r_col,'inclination':inc_col},'unit_conversion':{'velocity':v_method,'radius':r_method}}
        if reason:
            if len(rejected)<200: rejected.append(dict(prov, object_id=obj, reject_reasons=reason))
            continue
        rows.append({'source_group':source,'object_id':obj,'z':z,'vrot_km_s':v,'radius_kpc':rkpc,'inclination_deg':_v61_float(inc_val),'raw_source_file':str(path),'source_file_hash':sha,'row_index':idx,'original_columns':prov['original_columns'],'unit_conversion':prov['unit_conversion'],'row_policy':'v61_source_targeted_public_or_cached_parser'})
    return rows, rejected

def _v61_build_p36_public_rows(args):
    out=_v61_dir('measurements')/'p36_highz_object_rows_v61_AUTO_PUBLIC.json'
    paths, attempts, source_by_path = _v61_fetch_highz_sources(args)
    all_rows=[]; rejects=[]; audit=[]; seen=set()
    for p in paths[:1000]:
        rows,rejected=_v61_extract_p36_rows_from_file(p, source_by_path.get(str(p)))
        audit.append({'path':str(p),'source_group':source_by_path.get(str(p)),'sha256':_v61_sha256(p),'n_rows':len(rows),'n_rejected_sample':len(rejected)})
        for r in rows:
            key=(r['source_group'],r['object_id'],round(float(r['z']),5),round(float(r['vrot_km_s']),3),round(float(r['radius_kpc']),4))
            if key in seen: continue
            seen.add(key); all_rows.append(r)
        rejects.extend(rejected[:100])
    large=[r for r in all_rows if _v61_float(r.get('radius_kpc')) is not None and _v61_float(r.get('radius_kpc'))>=0.5]
    from collections import Counter
    counts=Counter(r.get('source_group') for r in large)
    acc=[]
    for r in large:
        v=_v61_float(r.get('vrot_km_s')); rad=_v61_float(r.get('radius_kpc'))
        if v and rad: acc.append((v*1000.0)**2/(rad*3.085677581e19))
    med=None
    if acc:
        ss=sorted(acc); med=ss[len(ss)//2] if len(ss)%2 else 0.5*(ss[len(ss)//2-1]+ss[len(ss)//2])
    obj={'artifact_version':_V61_VERSION,'status':'auto_rows_built' if all_rows else 'auto_rows_absent','diagnostic_class':'rows_parsed_but_gate_failed' if all_rows else 'source_targeted_public_rows_absent','manual_fill_required':False,'source_registry':{k:{'pages':v.get('pages'),'direct':v.get('direct')} for k,v in _V61_HIGHZ_SOURCE_REGISTRY.items()},'download_attempts':attempts[:200],'candidate_audit':audit[:300],'n_candidate_files':len(paths),'n_rows':len(all_rows),'n_large_radius_rows':len(large),'source_group_counts_large_radius':dict(counts),'median_large_radius_acceleration_m_s2':med,'rejected_rows_sample':rejects[:500],'rows':all_rows[:300000]}
    _v61_write_json(out,obj); return out

_run_highz_v60_for_v61 = run_highz_unit_field_table_v60

def run_highz_unit_field_table_v61(meta,args):
    base=_run_highz_v60_for_v61(meta,args); auto_path=_v61_build_p36_public_rows(args); auto=_v61_read_json(auto_path) or {}
    rows=auto.get('rows') or []; large=[r for r in rows if _v61_float(r.get('radius_kpc')) is not None and _v61_float(r.get('radius_kpc'))>=0.5]
    from collections import Counter
    counts=Counter(r.get('source_group') for r in large); tiny=(len(rows)-len(large))/len(rows) if rows else 1.0; med=auto.get('median_large_radius_acceleration_m_s2')
    missing=[]
    if len(rows)<30: missing.append('trusted_public_rows_ge_30')
    if len(large)<30: missing.append('large_radius_rows_ge_30')
    if len(counts)<2: missing.append('at_least_two_source_groups')
    if sum(1 for n in counts.values() if n>=20)<2: missing.append('two_sources_with_ge_20_large_radius_rows')
    if tiny>0.20: missing.append('tiny_radius_fraction_le_20pct')
    if med is None or med <= 9.55e-11: missing.append('large_radius_median_acceleration_above_local_a0')
    prov_ok=all(r.get('source_file_hash') and r.get('original_columns') and r.get('unit_conversion') for r in large[:max(1,min(len(large),50))]) if large else False
    if not prov_ok: missing.append('row_level_provenance_present')
    gate={'gate_version':_V61_VERSION,'artifact_path':str(auto_path),'missing':missing,'eligible_for_confirm_like':not missing,'n_rows':len(rows),'n_large_radius_rows':len(large),'n_source_groups':len(counts),'large_radius_source_counts':dict(counts),'tiny_radius_fraction':tiny,'median_large_radius_acceleration_m_s2':med,'diagnostic_class':auto.get('diagnostic_class')}
    base['p36_highz_public_parser_v61']={k:auto.get(k) for k in ['status','diagnostic_class','n_candidate_files','n_rows','n_large_radius_rows','source_group_counts_large_radius','median_large_radius_acceleration_m_s2']}
    base['p36_highz_large_radius_gate_v61']=gate
    base['status']='highz_a0_public_rows_confirm_like_v61' if not missing else 'highz_a0_public_rows_gate_failed_v61'
    return base

# ---------- v61 P30 actual same-mask recompute diagnostics and control resolver ----------

_run_p30_v60_for_v61 = run_p30_publication_gate_v60

def _v61_p30_variant_stats(base):
    stats=[]
    for name,obj in (base.get('act_variant_stats_v17') or {}).items():
        st=(obj or {}).get('stat') if isinstance(obj,dict) else None
        if isinstance(st,dict) and st.get('delta_high_minus_low') is not None:
            stats.append({'name':name,'delta':_v61_float(st.get('delta_high_minus_low')),'sky_p':_v61_float(st.get('sky_shuffle_p_high')),'density_p':_v61_float(st.get('density_bin_shuffle_p_high')),'jackknife_same_sign':st.get('jackknife_same_sign'),'n':st.get('n')})
    return stats

def _v61_p30_control_resolver(base):
    sdss=(base.get('density_kappa_stats_v16') or {}).get('sdss') or {}; euclid=(base.get('density_kappa_stats_v16') or {}).get('euclid') or {}
    variants=_v61_p30_variant_stats(base); curl=next((v for v in variants if 'curl' in v['name'].lower()), None); science=[v for v in variants if 'curl' not in v['name'].lower()]
    sd=_v61_float(sdss.get('delta_high_minus_low')); cd=_v61_float(curl.get('delta') if curl else None); ratio=(abs(cd)/abs(sd)) if sd not in (None,0) and cd is not None else None
    same_sign=[v for v in science if v.get('delta') is not None and sd is not None and (v['delta']>0)==(sd>0)]; opposite=[v for v in science if v.get('delta') is not None and sd is not None and (v['delta']>0)!=(sd>0)]
    jk=base.get('field_or_region_jackknife_v17') or {}; jk_deltas=[_v61_float(x.get('delta')) for x in (jk.get('jackknife') or []) if _v61_float(x.get('delta')) is not None]
    tension=[]
    if ratio is None: tension.append('curl_ratio_unavailable')
    elif ratio > 0.5: tension.append('curl_dominates_or_too_large')
    if len(same_sign)<2: tension.append('less_than_two_same_sign_science_variants')
    if opposite: tension.append('variant_sign_flips_present')
    if sd is None or sd<=0: tension.append('route_sign_policy_failed')
    if not (sdss.get('sky_shuffle_p_high') is not None and sdss.get('sky_shuffle_p_high') <= 0.05): tension.append('sky_shuffle_not_significant')
    if not (sdss.get('density_bin_shuffle_p_high') is not None and sdss.get('density_bin_shuffle_p_high') <= 0.05): tension.append('density_label_shuffle_not_significant')
    if jk_deltas and not all((x>0)==(sd>0) for x in jk_deltas): tension.append('field_jackknife_sign_instability')
    bad=base.get('p30_bad_patch_followup_table_v45') or {}; n_bad=bad.get('n_bad_or_low_quality_patches')
    if n_bad and n_bad>0: tension.append('patch_imbalance_or_bad_patch_followup_required')
    edge_proxy=any('finite-map-pixel' in str((v.get('stat') or {}).get('mask_aware_null','')).lower() for v in (base.get('act_variant_stats_v17') or {}).values() if isinstance(v,dict))
    if edge_proxy: tension.append('explicit_official_mask_missing_edge_proxy_only')
    return {'gate_version':_V61_VERSION,'same_run_shared_mask_engine':True,'manual_protocol_required':False,'route_sign_policy':'positive_high_minus_low_for_sdss','sdss_delta':sd,'euclid_delta':_v61_float(euclid.get('delta_high_minus_low')),'curl_delta':cd,'curl_abs_over_science_abs':ratio,'science_variants':science,'n_positive_same_sign_variants':len(same_sign),'n_opposite_sign_variants':len(opposite),'field_jackknife_deltas':jk_deltas,'control_tension_classes':sorted(set(tension)),'edge_proximity_proxy':edge_proxy,'bad_patch_count':n_bad,'eligible_for_route_confirm_like':not tension,'missing':sorted(set(tension)),'diagnostic_class':'control_tension' if tension else 'route_passed'}

def run_p30_publication_gate_v61(meta,args):
    base=_run_p30_v60_for_v61(meta,args); gate=_v61_p30_control_resolver(base); out=_v61_dir('measurements')/'p30_same_mask_recompute_v61_AUTO_PUBLIC.json'; _v61_write_json(out, gate)
    base['p30_same_mask_recompute_gate_v61']=gate; base['p30_control_tension_resolver_v61']={'artifact_path':str(out),'control_tension_classes':gate.get('control_tension_classes'),'diagnostic_class':gate.get('diagnostic_class'),'route_sign_policy':gate.get('route_sign_policy')}
    base['status']='density_kappa_sdss_same_mask_route_confirm_like_v61' if gate['eligible_for_route_confirm_like'] else 'density_kappa_same_mask_route_blocked_v61'
    return base

