_run_p33_v60_for_v61 = run_p33_density_bao_measurement_gate_v60

def _v61_table_rows_from_any(path, max_rows=200000):
    try: return list(_v59_iter_table_rows_any(Path(path), max_rows=max_rows))
    except Exception: return []

def _v61_find_desi_catalogues():
    pats=['*desi*catalog*.fits','*desi*catalog*.csv','*desi*catalog*.dat','*desi*lrg*.fits','*desi*elg*.fits','*desi*qso*.fits','*random*.fits','*random*.csv','*random*.dat']
    files=[]
    for p in _v60_candidate_files(pats, roots=[_v60_cache_dir(), _v60_public_dir(), _v60_outputs_dir()], max_files=3000):
        if not _v61_bad_path(p): files.append(Path(p))
    return files

def _v61_extract_ra_dec_z(rows, limit=20000):
    out=[]
    for row in rows[:limit]:
        if not isinstance(row,dict): continue
        _,ra=_v61_pick(row,['ra','ra_deg','right_ascension','alpha']); _,dec=_v61_pick(row,['dec','dec_deg','declination','delta']); _,z=_v61_pick(row,['z','zred','redshift','z_not4clus','zspec'])
        ra=_v61_float(ra); dec=_v61_float(dec); z=_v61_float(z)
        if ra is not None and dec is not None and z is not None and 0<=ra<=360 and -90<=dec<=90 and 0.05<=z<=3.5: out.append({'ra':ra,'dec':dec,'z':z})
    return out

def _v61_pair_alpha_proxy(sample, seed=123, maxn=2500):
    try: import numpy as np
    except Exception as e: return {'error':str(e)}
    if len(sample)<500: return {'error':'too_few_objects_for_density_split_alpha_proxy','n':len(sample)}
    rng=np.random.default_rng(seed)
    if len(sample)>maxn: sample=[sample[i] for i in rng.choice(len(sample), size=maxn, replace=False)]
    ra=np.array([r['ra'] for r in sample]); dec=np.array([r['dec'] for r in sample]); z=np.array([r['z'] for r in sample])
    key=np.floor(ra/5).astype(int)*100+np.floor((dec+90)/5).astype(int); uniq,counts=np.unique(key, return_counts=True); dens=dict(zip(uniq,counts)); d=np.array([dens[k] for k in key])
    lo=d<=np.quantile(d,0.25); hi=d>=np.quantile(d,0.75)
    def peak_alpha(mask):
        idx=np.where(mask)[0]
        if len(idx)<150: return None
        pairs=[]
        for _ in range(min(60000, len(idx)*40)):
            a,b=rng.choice(idx,2,replace=False); dz=abs(z[a]-z[b]); dang=np.hypot((ra[a]-ra[b])*np.cos(np.deg2rad((dec[a]+dec[b])/2)), dec[a]-dec[b]); sep=np.sqrt((3000*dz)**2 + (25*dang*((z[a]+z[b])/2))**2)
            if 40<sep<180: pairs.append(sep)
        if len(pairs)<100: return None
        hist,edges=np.histogram(pairs,bins=np.linspace(60,160,41)); centers=(edges[:-1]+edges[1:])/2; win=(centers>85)&(centers<125)
        if not np.any(win): return None
        return float(centers[win][np.argmax(hist[win])])/105.0
    ah=peak_alpha(hi); al=peak_alpha(lo)
    if ah is None or al is None: return {'error':'alpha_proxy_peak_not_measurable','n':len(sample),'n_high':int(hi.sum()),'n_low':int(lo.sum())}
    return {'alpha_high_density':ah,'alpha_low_density':al,'delta_alpha':ah-al,'delta_alpha_sigma':None,'covariance_used':False,'desi_randoms_used':False,'density_label_shuffle_p':None,'sky_shuffle_p':None,'redshift_jackknife_stable':False,'n_objects':len(sample),'n_high_density':int(hi.sum()),'n_low_density':int(lo.sum()),'estimator':'v61_pair_separation_bao_proxy_requires_public_catalogues'}

def _v61_build_p33_alpha(args):
    out=_v61_dir('measurements')/'p33_alpha_measurement_v61_AUTO_PUBLIC.json'; files=_v61_find_desi_catalogues(); best=None; audit=[]
    for p in files[:100]:
        rows=_v61_table_rows_from_any(p, max_rows=50000); sample=_v61_extract_ra_dec_z(rows, limit=30000); audit.append({'path':str(p),'sha256':_v61_sha256(p),'n_rows':len(rows),'n_usable_ra_dec_z':len(sample)})
        if len(sample)>=500:
            res=_v61_pair_alpha_proxy(sample)
            if not res.get('error'):
                res.update({'status':'alpha_proxy_built_from_public_catalogue','source_file_hashes':[{'path':str(p),'sha256':_v61_sha256(p)}],'source_hashes_present':True,'manual_fill_required':False}); best=res; break
    if best is None: best={'status':'alpha_measurement_not_autobuilt','diagnostic_class':'no_public_desi_density_catalogue_with_ra_dec_z_found','manual_fill_required':False,'candidate_audit':audit[:100],'required_code_path':'download/parse DESI clustering catalogues + randoms, then run density split BAO alpha fitter'}
    _v61_write_json(out,best); return out

def run_p33_density_bao_measurement_gate_v61(meta,args):
    base=_run_p33_v60_for_v61(meta,args); p=_v61_build_p33_alpha(args); row=_v61_read_json(p) or {}; missing=[]
    for k in ['alpha_high_density','alpha_low_density','delta_alpha']:
        if _v61_float(row.get(k)) is None: missing.append(k)
    if not _v61_truthy(row.get('covariance_used')): missing.append('covariance_aware_fit')
    if not _v61_truthy(row.get('desi_randoms_used')): missing.append('desi_randoms_used')
    if _v61_float(row.get('delta_alpha_sigma')) is None or abs(_v61_float(row.get('delta_alpha_sigma')) or 0)<2: missing.append('delta_alpha_sigma_ge_2')
    if _v61_float(row.get('density_label_shuffle_p')) is None or (_v61_float(row.get('density_label_shuffle_p')) or 1)>0.05: missing.append('density_label_shuffle_p_le_0p05')
    if _v61_float(row.get('sky_shuffle_p')) is None or (_v61_float(row.get('sky_shuffle_p')) or 1)>0.05: missing.append('sky_shuffle_p_le_0p05')
    if not _v61_truthy(row.get('redshift_jackknife_stable')): missing.append('redshift_jackknife_stable')
    if not _v61_truthy(row.get('source_hashes_present')): missing.append('source_hashes_present')
    gate={'gate_version':_V61_VERSION,'artifact_path':str(p),'missing':missing,'eligible_for_confirm_like':not missing,'diagnostic_class':row.get('diagnostic_class') or ('alpha_proxy_not_claim_grade' if row.get('alpha_high_density') is not None else 'fit_missing')}
    base['p33_alpha_measurement_gate_v61']=gate; base['p33_alpha_autofit_v61']=row; base['status']='p33_density_bao_alpha_confirm_like_v61' if not missing else 'p33_density_bao_alpha_measurement_required_v61'
    return base

# ---------- v61 PTA weighted statistic and likelihood builders ----------

_run_cl2_v60_for_v61 = run_cl2_pta_density_gate_v60

def _v61_parse_par_coords():
    pars=[]
    for p in _v60_candidate_files(['*.par','*nanograv*.txt','*pulsar*.par'], roots=[_v60_cache_dir(), _v60_public_dir(), _v60_outputs_dir()], max_files=2000):
        if _v61_bad_path(p): continue
        txt=_v61_text(p, max_bytes=200000)
        if 'RAJ' not in txt and 'DECJ' not in txt: continue
        name=None; raj=None; decj=None
        for ln in txt.splitlines():
            parts=ln.split()
            if not parts: continue
            key=parts[0].upper()
            if key in ['PSRJ','PSR'] and len(parts)>1: name=parts[1]
            if key=='RAJ' and len(parts)>1: raj=parts[1]
            if key=='DECJ' and len(parts)>1: decj=parts[1]
        try:
            from astropy.coordinates import Angle
            import astropy.units as u
            pars.append({'name':name or p.stem,'ra':float(Angle(raj, unit=u.hourangle).degree),'dec':float(Angle(decj, unit=u.deg).degree),'path':str(p),'sha256':_v61_sha256(p)})
        except Exception: pass
    return pars

def _v61_build_pta_stat(args):
    out=_v61_dir('measurements')/'pta_weighted_kappa_residual_v61_AUTO_PUBLIC.json'; coords=_v61_parse_par_coords()
    if len(coords)<20: _v61_write_json(out, {'status':'pta_stat_not_autobuilt','diagnostic_class':'pulsar_coordinates_absent_or_too_few','n_coords':len(coords),'manual_fill_required':False}); return out
    residual_rows=[]
    for p in _v60_candidate_files(['*resid*.csv','*resid*.txt','*toa*.tim','*nanograv*.csv','*nanograv*.txt'], roots=[_v60_cache_dir(), _v60_public_dir()], max_files=1000):
        if _v61_bad_path(p): continue
        for row in _v61_table_rows_from_any(p, max_rows=100000):
            if not isinstance(row,dict): continue
            _,nval=_v61_pick(row,['psr','psrj','name','pulsar']); _,rval=_v61_pick(row,['residual','resid','postfit','toa_resid'])
            if nval and _v61_float(rval) is not None: residual_rows.append({'name':str(nval),'residual':_v61_float(rval),'path':str(p),'sha256':_v61_sha256(p)})
    if len(residual_rows)<20: _v61_write_json(out, {'status':'pta_stat_not_autobuilt','diagnostic_class':'public_residual_or_toa_weights_absent','n_coords':len(coords),'n_residual_rows':len(residual_rows),'coordinate_hashes_present':True,'manual_fill_required':False}); return out
    _v61_write_json(out, {'status':'pta_stat_not_autobuilt','diagnostic_class':'kappa_map_sampling_not_available_in_pta_builder','n_coords':len(coords),'n_residual_rows':len(residual_rows),'coordinate_hashes_present':True,'residual_or_toa_weights_present':True,'manual_fill_required':False}); return out

def run_cl2_pta_density_gate_v61(meta,args):
    base=_run_cl2_v60_for_v61(meta,args); p=_v61_build_pta_stat(args); row=_v61_read_json(p) or {}; missing=[]
    for k in ['coordinate_hashes_present','residual_or_toa_weights_present','kappa_samples_present','top_weight_removal_stable','source_hashes_present']:
        if not _v61_truthy(row.get(k)): missing.append(k)
    if _v61_float(row.get('weighted_statistic')) is None: missing.append('weighted_statistic')
    if _v61_float(row.get('sky_shuffle_p')) is None or (_v61_float(row.get('sky_shuffle_p')) or 1)>0.05: missing.append('sky_shuffle_p_le_0p05')
    base['pta_weighted_kappa_residual_gate_v61']={'gate_version':_V61_VERSION,'artifact_path':str(p),'missing':missing,'eligible_for_confirm_like':not missing,'diagnostic_class':row.get('diagnostic_class')}
    if not missing: base['status']='pta_weighted_kappa_residual_confirm_like_v61'
    return base

