def _v61_why(row):
    st=str(row.get('status','')); pid=str(row.get('prediction_id','')).lower()
    if 'p36' in pid and 'highz' in st: return 'parser_blocked_public_rows_absent'
    if 'density_kappa' in st: return 'control_tension'
    if 'p33' in st: return 'fit_missing'
    if 'likelihood_required' in st or 'strain_analysis_required' in st: return 'likelihood_missing'
    if 'positive_ready' in st or 'compatible' in st: return 'readiness_not_signal'
    if 'data_limited' in st: return 'public_data_limited'
    if 'smd_constant' in st: return 'consistency_not_derivation'
    return 'not_claim_grade'

def run_dashboard_v61(meta,args):
    base=_run_dashboard_v60_for_v61(meta,args); rows=[]
    for p in sorted(_v61_dir('outputs').glob('test*.json')):
        if p.name.startswith('test51'): continue
        obj=_v61_read_json(p)
        if isinstance(obj,dict): rows.append(obj)
    confirms=[]; sm=[]; coverage=[]; blocked=[]; ready=[]; why={}; failed=[]
    for r in rows:
        st=str(r.get('status','')); pid=str(r.get('prediction_id','')); item={'test_id':r.get('test_id'),'prediction_id':pid,'prediction_name':r.get('prediction_name'),'status':st,'why_not_confirm':_v61_why(r)}
        if 'coverage_confirmed' in st: coverage.append(item)
        elif 'smd_constant_consistency_confirm_like' in st: sm.append(item)
        elif 'confirm_like' in st and not pid.startswith('SM') and 'coverage' not in st: confirms.append(item)
        elif any(x in st for x in ['blocked','failed','data_limited','required','not_confirmed']): blocked.append(item)
        else: ready.append(item)
        why[item['why_not_confirm']]=why.get(item['why_not_confirm'],0)+1
        for k,v in r.items():
            if isinstance(v,dict) and ('gate_v61' in k or 'gate_v60' in k) and not v.get('eligible_for_confirm_like', True) and not v.get('eligible_for_route_confirm_like', True): failed.append({'test_id':r.get('test_id'),'prediction_id':pid,'gate':k,'missing':v.get('missing'),'diagnostic_class':v.get('diagnostic_class')})
    art=[]
    for p in _v60_candidate_files(['*v61*.json','*v61*.csv','*v60*.json'], roots=[_v61_dir('measurements'),_v61_dir('outputs'),_v61_dir('inputs'),_v61_dir('public')], max_files=1000):
        if _v61_bad_path(p) or p.name.startswith('test'): continue
        row=_v61_read_json(p) or {}; st=str(row.get('status','')); usable=bool(row) and not st.endswith('not_autobuilt') and 'absent' not in st and 'missing' not in st
        art.append({'artifact_key':p.stem,'path':str(p),'exists':p.exists(),'sha256':_v61_sha256(p),'size_bytes':p.stat().st_size if p.exists() else 0,'filled_and_usable':usable,'diagnostic_class':row.get('diagnostic_class')})
    base['dashboard_v61']={'claim_policy':'v61 concrete no-manual implementation policy: source-targeted public fetchers and real estimators run automatically; if public data are insufficient the test reports parser_blocked/control_tension/fit_missing/likelihood_missing.','no_manual_fill_policy':True,'nonSM_confirm_like':confirms,'SM_constant_consistency':sm,'coverage_confirmed':coverage,'ready_or_compatible':ready,'blocked_or_gate_failed':blocked,'failed_gates':failed[:2000],'why_not_confirm_class_counts':why,'artifact_index':art,'n_artifacts':len(art),'n_filled_usable_artifacts':sum(1 for a in art if a.get('filled_and_usable')),'confirm_recovery_priority':[{'rank':1,'test_id':'R10-T13','prediction':'P36 high-z','implemented_v61':'source-targeted registry fetchers + source column maps + row provenance','next_if_blocked':'add missing public source URL/schema to registry, not manual files'},{'rank':2,'test_id':'R10-T04','prediction':'P30','implemented_v61':'same-run control resolver from baseline/curl/variant/null/jackknife stats','next_if_blocked':'fix curl/variant physical control tension'},{'rank':3,'test_id':'R10-T07','prediction':'P33','implemented_v61':'automatic catalogue search + density split BAO proxy fitter','next_if_blocked':'add public DESI clustering/random catalogue URL parser'},{'rank':4,'test_id':'R10-T17','prediction':'PTA/CL2','implemented_v61':'automatic par/residual discovery and statistic gate','next_if_blocked':'public residual/TOA products or kappa sampling unavailable'},{'rank':5,'test_id':'R10-T19','prediction':'P32','implemented_v61':'GWOSC HDF5 downloader + minimal ringdown grid fit when h5py/strain available'}],'n_nonSM_confirm_like':len(confirms),'n_SM_constant_consistency':len(sm),'n_coverage_confirmed':len(coverage),'n_blocked_or_gate_failed':len(blocked)}
    base['status']='dashboard_positive_current_only_v61'; return base

