    base['pta_weighted_kappa_residual_gate_v62']={'gate_version':_V62_VERSION,'artifact_path':str(p),'eligible_for_confirm_like':not missing,'missing':missing,'diagnostic_class':row.get('diagnostic_class')}
    if not missing: base['status']='pta_weighted_kappa_residual_confirm_like_v62'
