_run_dashboard_v61_for_v62 = run_dashboard_v61

def _v62_why(row):
    st=str(row.get('status','')); pid=str(row.get('prediction_id','')).lower()
    if 'highz' in st: return 'parser_partial_needs_second_source_or_quality'
    if 'density_kappa' in st: return 'control_tension'
    if 'p33' in st: return 'alpha_fit_missing_or_proxy_not_claim_grade'
    if 'likelihood_required' in st or 'strain_analysis_required' in st: return 'likelihood_missing'
    if 'positive_ready' in st or 'compatible' in st: return 'readiness_not_signal'
    if 'data_limited' in st: return 'public_data_limited'
    if 'smd_constant' in st: return 'consistency_not_derivation'
    return 'not_claim_grade'

def run_dashboard_v62(meta,args):
    base=_run_dashboard_v61_for_v62(meta,args)
    rows=[]
    for p in sorted(_v62_dir('outputs').glob('test*.json')):
        if p.name.startswith('test51'): continue
        obj=_v62_read_json(p)
        if isinstance(obj,dict): rows.append(obj)
    confirms=[]; sm=[]; coverage=[]; blocked=[]; ready=[]; why={}; failed=[]
    for r in rows:
        st=str(r.get('status','')); pid=str(r.get('prediction_id','')); item={'test_id':r.get('test_id'),'prediction_id':pid,'prediction_name':r.get('prediction_name'),'status':st,'why_not_confirm':_v62_why(r)}
        if 'coverage_confirmed' in st: coverage.append(item)
        elif 'smd_constant_consistency_confirm_like' in st: sm.append(item)
        elif 'confirm_like' in st and not pid.startswith('SM') and 'coverage' not in st: confirms.append(item)
        elif any(x in st for x in ['blocked','failed','data_limited','required','not_confirmed','broken']): blocked.append(item)
        else: ready.append(item)
        why[item['why_not_confirm']]=why.get(item['why_not_confirm'],0)+1
        for k,v in r.items():
            if isinstance(v,dict) and ('gate_v62' in k or 'gate_v61' in k) and not v.get('eligible_for_confirm_like', True) and not v.get('eligible_for_route_confirm_like', True):
                failed.append({'test_id':r.get('test_id'),'prediction_id':pid,'gate':k,'missing':v.get('missing'),'diagnostic_class':v.get('diagnostic_class')})
    art=[]
    for p in _v60_candidate_files(['*v62*.json','*v62*.csv','*v62*.jsonl','*v61*.json','*v61*.csv'], roots=[_v62_dir('measurements'),_v62_dir('outputs'),_v62_dir('inputs')], max_files=1200):
        if _v62_bad_path(p) or Path(p).name.startswith('test'): continue
        obj=_v62_read_json(p) if str(p).endswith('.json') else {}
        usable=Path(p).exists() and Path(p).stat().st_size>0 and not (isinstance(obj,dict) and str(obj.get('status','')).endswith('not_autobuilt'))
        art.append({'artifact_key':Path(p).stem,'path':str(p),'exists':Path(p).exists(),'size_bytes':Path(p).stat().st_size if Path(p).exists() else 0,'sha256':_v62_sha256(p),'filled_and_usable':usable,'diagnostic_class':obj.get('diagnostic_class') if isinstance(obj,dict) else None})
    base['dashboard_v62']={'claim_policy':'v62 behavior-changing patch: P36 rows stream to jsonl/csv, source-2 harvest attempts normalized prior public/cache rows, P30 resolver computes patch/curl/edge diagnostics, P33 runs an alpha proxy if RA/DEC/Z catalogue exists.','no_manual_fill_policy':True,'interface_only':False,'nonSM_confirm_like':confirms,'SM_constant_consistency':sm,'coverage_confirmed':coverage,'ready_or_compatible':ready,'blocked_or_gate_failed':blocked,'failed_gates':failed[:2000],'why_not_confirm_class_counts':why,'artifact_index':art,'n_artifacts':len(art),'n_filled_usable_artifacts':sum(1 for a in art if a.get('filled_and_usable')),'confirm_recovery_priority':[{'rank':1,'test_id':'R10-T14','prediction':'P36 cross-catalogue','next':'streaming fixed; add/repair KGES/KMOS3D/SAMI parser until second source has >=20 large-radius rows'},{'rank':2,'test_id':'R10-T13','prediction':'P36 high-z','next':'reduce tiny-radius fraction with stricter radius maps and add source bootstrap'},{'rank':3,'test_id':'R10-T07','prediction':'P33','next':'exact DESI LSS/random endpoint parser for RA/DEC/Z + covariance'},{'rank':4,'test_id':'R10-T04','prediction':'P30','next':'same-mask engine must resolve curl/variant control tension'},{'rank':5,'test_id':'R10-T17','prediction':'PTA/CL2','next':'add residual/TOA weights and kappa sampling'}],'n_nonSM_confirm_like':len(confirms),'n_SM_constant_consistency':len(sm),'n_coverage_confirmed':len(coverage),'n_blocked_or_gate_failed':len(blocked)}
    base['status']='dashboard_positive_current_only_v62'; return base

