# ============================================================================
# ROUND-10 v65 deep incremental behavior patch
# Goal: no interface-only changes.  Focus on decisive blockers:
#   1) P36 source-2: KGES + KMOS3D public parsers, with KROSS retained.
#   2) P36 radius claim audit and strict whitelist.
#   3) P36 fallback hierarchy and source bootstrap.
#   4) P30 single empirical mask object + pre-sign patch rejection.
#   5) P30 redshift/density residualization proxy.
#   6) P33 exact DESI LSS/random endpoint parsing + pair alpha proxy.
#   7) PTA residual/TOA join.
#   8) P32 detector split / injection-null gate focus.
# ============================================================================

_V65_VERSION = 'v65'

import os as _v65_os, re as _v65_re, json as _v65_json, math as _v65_math, csv as _v65_csv, hashlib as _v65_hashlib, urllib.request as _v65_ureq, urllib.parse as _v65_uparse, tarfile as _v65_tarfile, gzip as _v65_gzip, io as _v65_io, random as _v65_random
from pathlib import Path as _V65Path
from collections import Counter as _V65Counter, defaultdict as _V65DefaultDict


def _v65_dir(kind='outputs'):
    d = _V65Path.cwd() / kind
    d.mkdir(parents=True, exist_ok=True)
    return d


def _v65_float(x):
    try:
        if x is None: return None
        if isinstance(x, (int, float)): return float(x) if _v65_math.isfinite(float(x)) else None
        s = str(x).strip().replace(',', '')
        if not s or s.lower() in ('nan','none','null','--','...'):
            return None
        # strip units or latex-ish junk while preserving exponent signs
        m = _v65_re.search(r'[-+]?\d+(?:\.\d+)?(?:[eE][-+]?\d+)?', s)
        return float(m.group(0)) if m else None
    except Exception:
        return None


def _v65_truthy(x):
    if isinstance(x, bool): return x
    if isinstance(x, (int,float)): return x != 0
    return str(x).strip().lower() in ('true','1','yes','y','ok','passed','pass')


def _v65_write_json(path, obj):
    p = _V65Path(path); p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(_v65_json.dumps(obj, indent=2, sort_keys=True, default=str), encoding='utf-8')
    return str(p)


def _v65_read_json(path):
    try:
        p = _V65Path(path)
        if not p.exists(): return None
        return _v65_json.loads(p.read_text(encoding='utf-8', errors='replace'))
    except Exception:
        return None


def _v65_sha256(path, limit=None):
    try:
        h=_v65_hashlib.sha256(); n=0
        with open(path,'rb') as f:
            while True:
                b=f.read(1024*1024)
                if not b: break
                if limit is not None and n+len(b)>limit:
                    b=b[:max(0,limit-n)]
                h.update(b); n+=len(b)
                if limit is not None and n>=limit: break
        return h.hexdigest()
    except Exception:
        return None


def _v65_fetch(url, name=None, max_bytes=80_000_000):
    cache=_v65_dir('.ccdr_round10_cache') if False else (_V65Path.cwd()/'.ccdr_round10_cache')
    cache.mkdir(parents=True, exist_ok=True)
    if name is None:
        name='v65__'+_v65_hashlib.sha1(url.encode('utf-8')).hexdigest()[:14]+'__'+_v65_re.sub(r'[^A-Za-z0-9_.-]+','_',url.split('/')[-1] or 'download')[:120]
    p=cache/name
    audit={'url':url,'path':str(p),'cached':p.exists(),'max_bytes':max_bytes}
    if p.exists() and p.stat().st_size>0:
        audit.update({'ok':True,'size_bytes':p.stat().st_size,'sha256':_v65_sha256(p)})
        return p,audit
    try:
        req=_v65_ureq.Request(url, headers={'User-Agent':'CCDR-Round10-v65/1.0 no-manual public parser'})
        with _v65_ureq.urlopen(req, timeout=10) as r:
            clen=r.headers.get('Content-Length')
            if clen and int(clen)>max_bytes:
                audit.update({'ok':False,'skipped':'content_length_exceeds_limit','content_length_bytes':int(clen)})
                return None,audit
            data=r.read(max_bytes+1)
            if len(data)>max_bytes:
                audit.update({'ok':False,'skipped':'download_exceeds_limit','downloaded_prefix_bytes':len(data)})
                return None,audit
        p.write_bytes(data)
        audit.update({'ok':True,'size_bytes':p.stat().st_size,'sha256':_v65_sha256(p)})
        return p,audit
    except Exception as e:
        audit.update({'ok':False,'error':repr(e)[:500]})
        return None,audit


