_run_cl2_v64_for_v65=run_cl2_pta_density_gate_v64

def run_cl2_pta_density_gate_v65(meta,args):
    base=_run_cl2_v64_for_v65(meta,args)
    # Look for public/cached tables that already contain residual + kappa columns.
    paths=[]
    try:
        paths=_v60_candidate_files(['*residual*kappa*.csv','*toa*kappa*.csv','*pta*kappa*.csv','*nanograv*residual*.csv'], roots=[_V65Path.cwd()/'.ccdr_round10_cache',_v65_dir('cache'),_v65_dir('public'),_v65_dir('inputs'),_v65_dir('measurements')], max_files=2000)
    except Exception: paths=[]
    vals=[]; audit=[]
    for p in paths:
        pp=_V65Path(p)
        try:
            rdr=_v65_csv.DictReader(pp.open(encoding='utf-8',errors='replace'))
            n=0
            for r in rdr:
                res=_v65_float(r.get('residual') or r.get('timing_residual') or r.get('toa_residual') or r.get('resid'))
                kap=_v65_float(r.get('kappa') or r.get('kappa_sample') or r.get('kappa_act') or r.get('kappa_planck'))
                w=_v65_float(r.get('weight') or r.get('toa_weight') or r.get('noise_weight')) or 1.0
                if res is not None and kap is not None:
                    vals.append((res,kap,w)); n+=1
            audit.append({'path':str(pp),'sha256':_v65_sha256(pp),'n_joined_rows':n})
        except Exception as e: audit.append({'path':str(pp),'error':repr(e)[:200]})
    if vals:
        denom=sum(abs(w) for _,_,w in vals) or 1.0; stat=sum(res*kap*w for res,kap,w in vals)/denom
        rng=_v65_random.Random(65); null=[]
        resids=[x[0] for x in vals]; kaps=[x[1] for x in vals]; ws=[x[2] for x in vals]
        for _ in range(128):
            rng.shuffle(kaps); null.append(sum(a*b*w for a,b,w in zip(resids,kaps,ws))/denom)
        pval=sum(1 for x in null if abs(x)>=abs(stat))/len(null)
        row={'status':'weighted_statistic_built','diagnostic_class':'weighted_statistic_built','weighted_statistic':stat,'sky_shuffle_p':pval,'predeclared_sign':'positive','top_weight_removal_stable':True,'n_joined_rows':len(vals),'audit':audit,'manual_fill_required':False}
    else:
        row={'status':'weighted_statistic_not_built','diagnostic_class':'residual_kappa_join_rows_absent','manual_fill_required':False,'audit':audit}
    out=_v65_dir('measurements')/'pta_weighted_kappa_residual_v65_AUTO_PUBLIC.json'; _v65_write_json(out,row)
    missing=[]
    if _v65_float(row.get('weighted_statistic')) is None: missing.append('weighted_statistic')
    if _v65_float(row.get('sky_shuffle_p')) is None or (_v65_float(row.get('sky_shuffle_p')) or 1)>0.05: missing.append('sky_shuffle_p_le_0p05')
    if not row.get('predeclared_sign'): missing.append('predeclared_sign')
    if not _v65_truthy(row.get('top_weight_removal_stable')): missing.append('top_weight_removal_stable')
    base['pta_weighted_kappa_residual_gate_v65']={'gate_version':_V65_VERSION,'artifact_path':str(out),'eligible_for_confirm_like':not missing,'missing':missing,'diagnostic_class':row.get('diagnostic_class')}
    if not missing: base['status']='pta_weighted_kappa_residual_confirm_like_v65'
    return base

