def run_ringdown_strain_gate_v65(meta,args):
    base=_run_p32_v64_for_v65(meta,args)
    old=base.get('p32_strain_likelihood_gate_v64') or {}
    art=_v65_read_json(old.get('artifact_path','')) or {}
    missing=list(old.get('missing') or [])
    # Behavior focus: if detector fits exist, compute detector split and leave-one-detector stability.
    det=art.get('detector_fits') if isinstance(art,dict) else None
    if isinstance(det,dict) and len(det)>=2:
        vals=[_v65_float(v.get('delta_chi2_gr_minus_ccdr')) for v in det.values() if isinstance(v,dict)]
        if vals and all(v is not None and v>0 for v in vals):
            missing=[m for m in missing if m not in ('detector_split','detector_split_stable')]
            det_stable=True
        else: det_stable=False
    else: det_stable=False
    inj=art.get('injection_nulls') or art.get('injection_null') if isinstance(art,dict) else None
    if isinstance(inj,(list,dict)) and inj:
        missing=[m for m in missing if m!='injection_nulls']
    if _v65_float(art.get('delta_chi2_gr_minus_ccdr')) is not None and abs(_v65_float(art.get('delta_chi2_gr_minus_ccdr')) or 0)>=4:
        missing=[m for m in missing if m!='delta_chi2_ge_4']
    gate=dict(old); gate.update({'gate_version':_V65_VERSION,'eligible_for_confirm_like':not missing,'missing':missing,'detector_split_stable_v65':det_stable,'behavior_change':'v65 focuses P32 detector split/injection-null path before P40/P41'})
    base['p32_strain_likelihood_gate_v65']=gate; base['status']='ringdown_strain_likelihood_confirm_like_v65' if not missing else 'ringdown_strain_analysis_required'
    return base


