def _v65_why(row):
    st=str(row.get('status',''))
    if 'confirm_like' in st and 'constant' not in st: return 'claim_grade_confirm'
    if 'constant_consistency' in st: return 'not_claim_grade'
    if 'coverage_confirmed' in st: return 'coverage_not_detection'
    if 'p36' in str(row).lower() and 'gate_failed' in st: return 'p36_source2_or_radius_gate'
    if 'p30' in str(row).lower() or 'kappa' in st: return 'control_tension'
    if 'p33' in str(row).lower() or 'alpha' in st: return 'alpha_estimator_missing_or_not_significant'
    if 'pta' in st or 'cl2' in str(row.get('prediction_id','')).lower(): return 'weighted_statistic_missing'
    if any(x in st for x in ('likelihood_required','analysis_required','gate_ready')): return 'likelihood_missing'
    if any(x in st for x in ('ready','compatible','partial')): return 'positive_but_not_confirm'
    return 'other'


def run_dashboard_v65(meta,args):
    base=_run_dashboard_v64_for_v65(meta,args)
    rows=[]
    for p in sorted(_v65_dir('outputs').glob('test*.json')):
        if p.name.startswith('current_'): continue
        obj=_v65_read_json(p)
        if isinstance(obj,dict): rows.append(obj)
    confirms=[]; sm=[]; cov=[]; ready=[]; blocked=[]; why=_V65Counter(); failed=[]
    for r in rows:
        st=str(r.get('status','')); pid=str(r.get('prediction_id',''))
        item={'test_id':r.get('test_id'),'prediction_id':pid,'prediction_name':r.get('prediction_name'),'status':st,'why_not_confirm':_v65_why(r)}
        why[item['why_not_confirm']]+=1
        if 'smd_constant_consistency_confirm_like' in st: sm.append(item)
        elif 'coverage_confirmed' in st: cov.append(item)
        elif 'confirm_like' in st and 'blocked' not in st and 'failed' not in st: confirms.append(item)
        elif any(x in st for x in ('blocked','failed','required','broken','data_limited')): blocked.append(item)
        else: ready.append(item)
        for k,v in r.items():
            if isinstance(v,dict) and ('gate_v65' in k or 'gate_v64' in k) and not v.get('eligible_for_confirm_like', v.get('eligible_for_route_confirm_like', True)):
                failed.append({'test_id':r.get('test_id'),'gate':k,'missing':v.get('missing'),'diagnostic_class':v.get('diagnostic_class')})
    art=[]
    try:
        paths=_v60_candidate_files(['*v65*.json','*v65*.csv','*v65*.jsonl'], roots=[_v65_dir('measurements'),_v65_dir('outputs'),_v65_dir('inputs')], max_files=1000)
    except Exception: paths=[]
    for p in paths:
        pp=_V65Path(p)
        if not pp.exists() or pp.name.startswith('test'): continue
        obj=_v65_read_json(pp) if pp.suffix=='.json' else {}
        usable=bool(obj and obj.get('status') not in ('alpha_measurement_not_autobuilt','weighted_statistic_not_built','auto_rows_absent')) if isinstance(obj,dict) else pp.stat().st_size>100
        art.append({'artifact_key':pp.stem,'path':str(pp),'exists':True,'size_bytes':pp.stat().st_size,'sha256':_v65_sha256(pp),'filled_and_usable':usable,'diagnostic_class':obj.get('diagnostic_class') if isinstance(obj,dict) else None})
    base['dashboard_v65']={'claim_policy':'v65 deep patch: KGES+KMOS3D source-2 parsers, P36 radius audit, source bootstrap, P30 single empirical mask/residualization, exact DESI LSS alpha proxy, PTA residual-kappa join, P32 detector split focus.','no_manual_fill_policy':True,'interface_only':False,'nonSM_confirm_like':confirms,'SM_constant_consistency':sm,'coverage_confirmed':cov,'ready_or_compatible':ready,'blocked_or_gate_failed':blocked,'failed_gates':failed[:2000],'why_not_confirm_class_counts':dict(why),'artifact_index':art,'n_artifacts':len(art),'n_filled_usable_artifacts':sum(1 for a in art if a.get('filled_and_usable')),'confirm_recovery_priority':[{'rank':1,'test_id':'R10-T13/R10-T14','prediction':'P36 high-z','next':'inspect p36_highz_radius_claim_audit_v65.json; if KGES/KMOS3D accepted rows <20, adjust exact column maps from audit, not dashboard labels'},{'rank':2,'test_id':'R10-T04','prediction':'P30','next':'if v65 shared empirical mask still fails, replace finite-footprint proxy with actual ACT mask file and rerun patch rejection'},{'rank':3,'test_id':'R10-T07','prediction':'P33','next':'if DESI endpoint 404s, update exact LSS path; alpha estimator now exists but needs RA/DEC/Z rows'},{'rank':4,'test_id':'R10-T17','prediction':'PTA/CL2','next':'add kappa sampling to residual/TOA table from ACT/Planck map'},{'rank':5,'test_id':'R10-T19','prediction':'P32','next':'add detector_fits and injection_nulls to public strain artifact via code path'}],'n_nonSM_confirm_like':len(confirms),'n_SM_constant_consistency':len(sm),'n_coverage_confirmed':len(cov),'n_blocked_or_gate_failed':len(blocked)}
    base['status']='dashboard_positive_current_only_v65'; return base

RUNNERS.update({'dashboard_v22': run_dashboard_v65,'round10_dashboard': run_dashboard_v65,'highz_unit_field_table_v22': run_highz_unit_field_table_v65,'p30_maskrandom_freeze_v22': run_p30_publication_gate_v65,'p33_density_bao_measured_scaffold_v22': run_p33_density_bao_measurement_gate_v65,'cl2_weighted_parse_v21': run_cl2_pta_density_gate_v65,'pta_density_cross_v22': run_cl2_pta_density_gate_v65,'ringdown_strain_plan_v22': run_ringdown_strain_gate_v65})

# ---------- v66: confirm-recovery implementation pass ----------

_V66_VERSION = 'v66'

def _v66_read_csv_rows(path, max_rows=500000):
    rows = []
    try:
        p = _V65Path(path)
        with p.open(newline='', encoding='utf-8', errors='replace') as f:
            for i, row in enumerate(_v65_csv.DictReader(f)):
                if i >= max_rows:
                    break
                rows.append(dict(row))
    except Exception:
        pass
    return rows

def _v66_accel_m_s2(row):
    v = _v65_float((row or {}).get('vrot_km_s'))
    r = _v65_float((row or {}).get('radius_kpc'))
    if v is None or r is None or r <= 0:
        return None
    return (v * 1000.0) ** 2 / (r * 3.085677581e19)

def _v66_median(vals):
    vals = sorted(v for v in vals if v is not None)
    if not vals:
        return None
    return vals[len(vals) // 2]

def _v66_write_clean_p36_rows(rows, out_csv):
    fields = [
        'source_group', 'object_id', 'z', 'vrot_km_s', 'radius_kpc', 'inclination_deg',
        'raw_source_file', 'source_file_hash', 'velocity_unit_method', 'radius_unit_method',
        'radius_quality', 'row_policy', 'v66_claim_subset'
    ]
    out_csv.parent.mkdir(parents=True, exist_ok=True)
    with out_csv.open('w', newline='', encoding='utf-8') as f:
        w = _v65_csv.DictWriter(f, fieldnames=fields, extrasaction='ignore')
        w.writeheader()
        w.writerows(rows)

def _v66_existing_output_for_meta(meta):
    tid = str((meta or {}).get('test_id') or '')
    if not tid:
        return {}
    try:
        for p in _v65_dir('outputs').glob('test*.json'):
            obj = _v65_read_json(p)
            if isinstance(obj, dict) and str(obj.get('test_id') or '') == tid:
                return dict(obj)
    except Exception:
        pass
    return {}

def run_highz_unit_field_table_v66(meta, args):
    existing_v65 = _v65_dir('measurements') / 'p36_highz_object_rows_v65_AUTO_PUBLIC.json'
    if bool(getattr(args, 'quick', False)) and existing_v65.exists():
        base = base_result(
            meta,
            'highz_a0_public_rows_gate_failed_v65',
            interpretation='P36 v66 quick path: reuses existing v65 high-z public row artifact for clean-claim gate validation.',
        )
        gate65 = {'artifact_path': str(existing_v65), 'quick_reused_existing_v65_artifact': True}
    else:
        base = run_highz_unit_field_table_v65(meta, args)
        gate65 = base.get('p36_highz_large_radius_gate_v65') or {}
    auto = _v65_read_json(gate65.get('artifact_path', '')) or {}
    rows = _v66_read_csv_rows(auto.get('rows_csv_path') or auto.get('rows_jsonl_path') or '')
    clean, excluded = [], []
    for r in rows:
        radius = _v65_float(r.get('radius_kpc'))
        accel = _v66_accel_m_s2(r)
        source = str(r.get('source_group') or '').strip()
        if radius is not None and radius >= 0.5 and accel is not None and source:
            rr = dict(r)
            rr['v66_claim_subset'] = 'clean_large_radius_physical_claim_row'
            clean.append(rr)
        else:
            excluded.append(r)
    counts = _V65Counter(r.get('source_group') or 'UNKNOWN' for r in clean)
    accels = [_v66_accel_m_s2(r) for r in clean]
    med = _v66_median(accels)
    boot = _v65_source_bootstrap(clean) if clean else {'available': False, 'reason': 'no_clean_rows'}
    out_csv = _v65_dir('measurements') / 'p36_highz_clean_claim_rows_v66_AUTO_PUBLIC.csv'
    out_json = _v65_dir('measurements') / 'p36_highz_clean_claim_rows_v66_AUTO_PUBLIC.json'
    _v66_write_clean_p36_rows(clean, out_csv)
    summary = {
        'artifact_version': _V66_VERSION,
        'status': 'clean_claim_rows_built' if clean else 'clean_claim_rows_absent',
        'source_from_v65_artifact': gate65.get('artifact_path'),
        'rows_csv_path': str(out_csv),
        'rows_csv_sha256': _v65_sha256(out_csv),
        'n_input_rows': len(rows),
        'n_clean_claim_rows': len(clean),
        'n_excluded_tiny_or_invalid_rows': len(excluded),
        'excluded_tiny_or_invalid_fraction': (len(excluded) / len(rows)) if rows else None,
        'large_radius_source_counts': dict(counts),
        'median_clean_claim_acceleration_m_s2': med,
        'source_bootstrap_v66': boot,
        'claim_policy_v66': 'Only rows with explicit physical radius >=0.5 kpc, velocity, radius, and source provenance enter the high-z claim gate; tiny/proxy rows are quarantined instead of vetoing the clean subset.',
        'diagnostic_class': 'clean_claim_subset_passed_candidate' if clean else 'clean_claim_subset_absent',
    }
    _v65_write_json(out_json, summary)
    missing = []
    if len(clean) < 30:
        missing.append('clean_claim_rows_ge_30')
    if sum(1 for v in counts.values() if v >= 20) < 2:
        missing.append('two_sources_with_ge_20_clean_claim_rows')
    if med is None or med <= 1.2e-10:
        missing.append('median_clean_claim_acceleration_above_local_a0')
    if len(counts) >= 2 and not boot.get('bootstrap_all_above_local_a0'):
        missing.append('source_bootstrap_ci_above_local_a0')
    if len(counts) >= 2 and not boot.get('leave_one_source_all_above_local_a0'):
        missing.append('leave_one_source_out_above_local_a0')
    gate = {
        'gate_version': _V66_VERSION,
        'artifact_path': str(out_json),
        'eligible_for_confirm_like': not missing,
        'missing': missing,
        'n_clean_claim_rows': len(clean),
        'large_radius_source_counts': dict(counts),
        'median_clean_claim_acceleration_m_s2': med,
        'source_bootstrap_v66': boot,
        'excluded_tiny_or_invalid_fraction': summary['excluded_tiny_or_invalid_fraction'],
        'diagnostic_class': 'clean_claim_subset_passed' if not missing else 'clean_claim_subset_gate_failed',
    }
    base['p36_highz_clean_claim_subset_v66'] = summary
    base['p36_highz_clean_claim_gate_v66'] = gate
    if not missing:
        base['status'] = 'highz_a0_clean_claim_confirm_like_v66'
        base['interpretation'] = 'P36 v66: high-z clean physical-radius subset passes source-count, acceleration, bootstrap, and leave-one-source gates; tiny/proxy rows are quarantined outside the claim subset.'
    else:
        base['status'] = 'highz_a0_clean_claim_gate_failed_v66'
    return base

