def _v66_scan_numeric_table(path, max_rows=20000):
    rows = []
    p = _V65Path(path)
    try:
        text = p.read_text(encoding='utf-8', errors='replace')[:20_000_000]
    except Exception:
        return rows
    for line in text.splitlines():
        nums = [_v65_float(x) for x in _v65_re.findall(r'[-+]?(?:\d+\.\d*|\.\d+|\d+)(?:[eE][-+]?\d+)?', line)]
        nums = [x for x in nums if x is not None]
        if len(nums) >= 3:
            rows.append(nums[:8])
            if len(rows) >= max_rows:
                break
    return rows

def run_p40_bmode_likelihood_gate_v66(meta, args):
    if bool(getattr(args, 'quick', False)):
        base = _v66_existing_output_for_meta(meta) or run_p40_bmode_likelihood_gate_v64(meta, args)
    else:
        base = run_p40_bmode_likelihood_gate_v64(meta, args)
    gate64 = base.get('p40_bb_likelihood_gate_v64') or {}
    candidates = []
    try:
        candidates = _v60_candidate_files(
            ['*bk18*', '*bicep*', '*keck*', '*bandpower*', '*bb*likelihood*', '*bb*cov*'],
            roots=[_V65Path.cwd()/'.ccdr_round10_cache', _v65_dir('inputs'), _v65_dir('measurements'), _v65_dir('outputs')],
            max_files=2000,
        )
    except Exception:
        candidates = []
    reports = []
    best_rows = []
    for p in candidates[:200]:
        pp = _V65Path(p)
        if pp.is_dir() or pp.suffix.lower() in ('.png', '.jpg', '.jpeg', '.pdf', '.zip', '.gz', '.fits'):
            continue
        rows = _v66_scan_numeric_table(pp)
        if rows:
            reports.append({'path': str(pp), 'sha256': _v65_sha256(pp), 'n_numeric_rows': len(rows)})
            if len(rows) > len(best_rows):
                best_rows = rows
    amp = None
    sig = None
    if best_rows:
        vals = [r[1] for r in best_rows if len(r) > 1]
        errs = [abs(r[2]) for r in best_rows if len(r) > 2 and r[2] != 0]
        amp = sum(vals) / len(vals) if vals else None
        sig = (sum(e * e for e in errs) ** 0.5 / len(errs)) if errs else None
    row = {
        'artifact_version': _V66_VERSION,
        'status': 'bb_numeric_rows_scanned' if best_rows else 'bb_likelihood_not_autobuilt',
        'n_bandpowers': len(best_rows),
        'bb_bandpowers_loaded': bool(best_rows),
        'covariance_loaded': False,
        'template_amplitude': amp,
        'template_amplitude_sigma': sig,
        'audit': reports[:50],
        'manual_fill_required': False,
    }
    out = _v65_dir('measurements') / 'p40_bb_likelihood_v66_AUTO_PUBLIC.json'
    _v65_write_json(out, row)
    missing = []
    if not row['bb_bandpowers_loaded']:
        missing.append('bb_bandpowers_loaded')
    if not row['covariance_loaded']:
        missing.append('covariance_loaded')
    if row['template_amplitude'] is None:
        missing.append('template_amplitude')
    if row['template_amplitude_sigma'] is None:
        missing.append('template_amplitude_sigma')
    base['p40_bb_likelihood_gate_v66'] = {
        'gate_version': _V66_VERSION,
        'artifact_path': str(out),
        'eligible_for_confirm_like': not missing,
        'missing': missing,
        'diagnostic_class': 'bb_rows_loaded_covariance_missing' if best_rows else 'bb_bandpower_rows_absent',
    }
    base['status'] = 'p40_bb_likelihood_confirm_like_v66' if not missing else 'p40_bb_likelihood_required'
    return base

def run_p41_likelihood_gate_v66(meta, args):
    if bool(getattr(args, 'quick', False)):
        base = _v66_existing_output_for_meta(meta) or run_p41_likelihood_gate_v64(meta, args)
