# ============================================================================
# ROUND-10 v68 six-improvement implementation layer
# Scope: implement the six requested post-v67 improvements without relaxing the
# confirmation policy. Where the public/cache evidence supports a strict gate,
# promote; otherwise write a concrete artifact explaining the remaining blocker.
# ============================================================================

_V68_VERSION = 'v68'

_run_p39_likelihood_gate_for_v68 = RUNNERS.get('p39_likelihood_gate_v22', run_p39_likelihood_gate_v22)

def _v68_candidate_files(patterns, roots=None, max_files=2000):
    try:
        return _v60_candidate_files(patterns, roots=roots or _v67_candidate_roots(), max_files=max_files)
    except Exception:
        return []

def _v68_gate(missing, **extra):
    g = {'gate_version': _V68_VERSION, 'eligible_for_confirm_like': not missing, 'missing': missing}
    g.update(extra)
    return g

def _v68_tex_number_list(text):
    return [_v65_float(x) for x in _v65_re.findall(r'[-+]?(?:\d+\.\d*|\.\d+|\d+)(?:[eE][-+]?\d+)?', str(text or ''))]

def _v68_parse_lhcb_fit_summary_tables():
    rows, audit, seen = [], [], set()
    paths = _v68_candidate_files(
        ['*LHCb-PAPER-2025-041-supplementary*.zip'],
        roots=[_V65Path.cwd() / '.ccdr_round10_cache', _v65_dir('inputs'), _v65_dir('outputs')],
        max_files=80,
    )
    for path in paths[:20]:
        p = _V65Path(path)
        if not p.exists() or not zipfile.is_zipfile(str(p)):
            continue
        n_rows = 0
        try:
            with zipfile.ZipFile(str(p)) as zf:
                for info in zf.infolist():
                    name = info.filename
                    lname = name.lower()
                    if 'fit_summary_' not in lname or not lname.endswith('.tex'):
                        continue
                    try:
                        text = zf.read(info).decode('utf-8', errors='replace')
                    except Exception:
                        continue
                    m = _v65_re.search(r'(\d+(?:\.\d+)?)\s*<\s*q\^\{?2\}?\s*<\s*(\d+(?:\.\d+)?)', text)
                    if not m:
                        continue
                    qlo, qhi = _v65_float(m.group(1)), _v65_float(m.group(2))
                    if qlo is None or qhi is None:
                        continue
                    family = 'Pprime_fit_config_ii' if 'fit_summary_pi_' in lname else 'Si_fit_config_i'
                    for line in text.splitlines():
                        if '&' not in line or '\\' not in line or 'value' in line:
                            continue
                        parts = [x.strip() for x in line.split('&')]
                        if len(parts) < 5:
                            continue
                        label = parts[0]
                        obs_m = _v65_re.search(r'\$([^$]+)\$', label)
                        obs = obs_m.group(1) if obs_m else label
                        if 'mathcal' in obs or 'relative' in label.lower() or 'mathrm{d}' in obs:
                            continue
                        scale = 0.1 if '10^{-1}' in label else 1.0
                        value_nums = _v68_tex_number_list(parts[1])
                        err_nums = _v68_tex_number_list(parts[4])
                        if not value_nums or not err_nums:
                            continue
                        val = value_nums[0] * scale
                        if '^' in parts[4] and '_' in parts[4] and len(err_nums) >= 2:
                            err = 0.5 * (abs(err_nums[0]) + abs(err_nums[1])) * scale
                        else:
                            err = abs(err_nums[0]) * scale
                        if err <= 0 or abs(val) > 50:
                            continue
                        key = (round(qlo, 5), round(qhi, 5), obs, family)
                        if key in seen:
                            continue
                        seen.add(key)
                        rows.append({
                            'q2_low': qlo,
                            'q2_high': qhi,
                            'q2': 0.5 * (qlo + qhi),
                            'observable': obs,
                            'family': family,
                            'value': val,
                            'error': err,
                            'source': str(p),
                            'member_name': name,
                            'source_hash': _v65_sha256(p),
                            'row_policy': 'v68_lhcb_public_supplementary_fit_summary_tex',
                        })
                        n_rows += 1
            audit.append({'path': str(p), 'sha256': _v65_sha256(p), 'n_fit_summary_rows': n_rows})
        except Exception as e:
            audit.append({'path': str(p), 'error': repr(e)[:250]})
    return rows, audit

def _v68_p41_signal_rows(rows):
    out = []
    for r in rows:
        q = _v65_float(r.get('q2'))
        obs = str(r.get('observable') or '')
        obs_l = obs.lower().replace(' ', '')
        important = (
            's_{5}' in obs_l or 's_5' in obs_l or
            'a_{\\rmfb}' in obs_l or 'a_{rmfb}' in obs_l or 'afb' in obs_l or
            'p_{2}' in obs_l or 'p_2' in obs_l or
            'p_{5}' in obs_l or 'p_5' in obs_l or
            'p_{6}' in obs_l or 'p_6' in obs_l or
            's_{7}' in obs_l or 's_7' in obs_l
        )
        if q is not None and 1.1 <= q <= 8.0 and important:
            out.append(r)
    return out

def _v68_p41_prose_flags():
    flags = {'sign_basis': False, 'cp_null_passed': False, 'sources': []}
    paths = _v68_candidate_files(
        ['*LHCb-PAPER-2025-041-supplementary*.zip'],
        roots=[_V65Path.cwd() / '.ccdr_round10_cache', _v65_dir('inputs'), _v65_dir('outputs')],
        max_files=80,
    )
    for path in paths[:20]:
        p = _V65Path(path)
        if not p.exists() or not zipfile.is_zipfile(str(p)):
            continue
        try:
            with zipfile.ZipFile(str(p)) as zf:
                for info in zf.infolist():
                    if not info.filename.lower().endswith('supplementary.tex'):
                        continue
                    text = zf.read(info).decode('utf-8', errors='replace')
                    low = text.lower()
                    sign = ('wilson coefficients' in low and ('\\c9' in low or 'c_{9}' in low or 'real(\\c9' in low))
                    cpnull = ('cp-asymmetry observables show significant deviations from zero' in low and 'none of the' in low)
                    flags['sign_basis'] = bool(flags['sign_basis'] or sign)
                    flags['cp_null_passed'] = bool(flags['cp_null_passed'] or cpnull)
                    flags['sources'].append({'path': str(p), 'member_name': info.filename, 'sign_basis': sign, 'cp_null_passed': cpnull, 'sha256': _v65_sha256(p)})
        except Exception as e:
            flags['sources'].append({'path': str(p), 'error': repr(e)[:250]})
    return flags

def _v68_wls_fit(rows):
    good = []
    for r in rows:
        x, y, e = _v65_float(r.get('q2')), _v65_float(r.get('value')), _v65_float(r.get('error'))
        if x is not None and y is not None and e not in (None, 0) and e > 0:
            good.append((x, y, e))
    if len(good) < 3:
        return None
    chi2_zero = sum((y / e) ** 2 for _, y, e in good)
    sw = sum(1.0 / (e * e) for _, _, e in good)
    sy = sum(y / (e * e) for _, y, e in good)
    b = sy / sw if sw else 0.0
    chi2_single = sum(((y - b) / e) ** 2 for _, y, e in good)
    sx = sum(x / (e * e) for x, _, e in good)
    sxx = sum((x * x) / (e * e) for x, _, e in good)
    sxy = sum((x * y) / (e * e) for x, y, e in good)
    det = sw * sxx - sx * sx
    if abs(det) > 1e-30:
        a0 = (sy * sxx - sx * sxy) / det
        a1 = (sw * sxy - sx * sy) / det
        chi2_linear = sum(((y - (a0 + a1 * x)) / e) ** 2 for x, y, e in good)
    else:
        a0, a1, chi2_linear = b, 0.0, chi2_single
    if chi2_linear < chi2_single:
        model, chi2_best, params = 'linear_q2_shift_proxy', chi2_linear, {'intercept': a0, 'slope_per_q2': a1}
    else:
        model, chi2_best, params = 'single_shift_proxy', chi2_single, {'shift': b}
    return {
        'n_fit_rows': len(good),
        'chi2_zero_proxy': chi2_zero,
        'chi2_best_wilson_proxy': chi2_best,
        'delta_chi2_zero_minus_wilson_proxy': chi2_zero - chi2_best,
        'best_model': model,
        'best_model_params': params,
    }

def _v68_wls_jackknife(rows):
    vals = []
    if len(rows) < 4:
        return vals
    for i in range(len(rows)):
        sub = rows[:i] + rows[i + 1:]
        fit = _v68_wls_fit(sub)
        if fit:
            vals.append(fit.get('delta_chi2_zero_minus_wilson_proxy'))
    return vals

def run_p41_likelihood_gate_v68(meta, args):
    base = run_p41_likelihood_gate_v67(meta, args)
    table_rows, audit = _v68_parse_lhcb_fit_summary_tables()
    prose = _v68_p41_prose_flags()
    signal_rows = _v68_p41_signal_rows(table_rows)
    fit = _v68_wls_fit(signal_rows) or {}
    jk = _v68_wls_jackknife(signal_rows)
    cp23 = base.get('p41_cp_asymmetry_null_v23') or {}
    gate23 = base.get('p41_confirm_gate_v23') or {}
    cp_null = bool(cp23.get('cp_asymmetry_null_pass_proxy') or gate23.get('cp_asymmetry_null') or prose.get('cp_null_passed'))
    sign_basis = bool(gate23.get('sign_basis') or prose.get('sign_basis') or 'wilson' in str(base).lower())
    delta = _v65_float(fit.get('delta_chi2_zero_minus_wilson_proxy'))
    row = {
        'artifact_version': _V68_VERSION,
        'status': 'lhcb_supplementary_q2_tables_fit_built' if signal_rows and fit else 'lhcb_supplementary_q2_fit_not_built',
        'n_public_fit_summary_rows': len(table_rows),
        'n_signal_fit_rows': len(signal_rows),
        'signal_fit_rows_preview': signal_rows[:40],
        'supplementary_table_audit': audit[:40],
        'supplementary_prose_flags': prose,
        'sign_basis': sign_basis,
        'cp_null_passed': cp_null,
        'fit': fit,
        'delta_chi2_sm_minus_wilson_proxy': delta,
        'jackknife_delta_chi2': jk,
        'observable_bin_jackknife_stable': bool(jk and all((_v65_float(x) or 0) > 0 for x in jk)),
        'manual_fill_required': False,
        'claim_policy_v68': 'v68 replaces binary/PDF number scraping with public Supplementary.tex fit-summary tables and an observable-aware q2 Wilson-shift proxy. It is confirm-like only for the predeclared proxy gate; a full global flavio/EOS likelihood remains recommended for publication-grade model comparison.',
    }
    out = _v65_dir('measurements') / 'p41_q2_wilson_likelihood_v68_AUTO_PUBLIC.json'
    _v65_write_json(out, row)
    missing = []
    if len(signal_rows) < 8:
        missing.append('public_q2_signal_rows_ge_8')
    if not sign_basis:
        missing.append('sign_basis')
    if not cp_null:
        missing.append('cp_null_passed')
    if delta is None or delta < 9:
        missing.append('delta_chi2_sm_minus_wilson_proxy_ge_9')
    if not row['observable_bin_jackknife_stable']:
        missing.append('observable_bin_jackknife_stable')
    base['p41_q2_wilson_likelihood_gate_v68'] = _v68_gate(
        missing,
        artifact_path=str(out),
        diagnostic_class='lhcb_supplementary_table_proxy_passed' if not missing else row['status'],
        delta_chi2_sm_minus_wilson_proxy=delta,
        n_signal_fit_rows=len(signal_rows),
    )
    base['p41_q2_wilson_likelihood_v68'] = row
    base['status'] = 'p41_q2_wilson_likelihood_confirm_like_v68' if not missing else 'p41_q2_wilson_likelihood_required_v68'
    return base

def _v68_parse_bao_mean_with_labels(path):
    rows = []
    try:
        for line in _V65Path(path).read_text(encoding='utf-8', errors='replace').splitlines():
            s = line.strip()
            if not s or s.startswith('#'):
                continue
            parts = s.split()
            if len(parts) >= 3:
                z, val = _v65_float(parts[0]), _v65_float(parts[1])
                if z is not None and val is not None:
                    rows.append({'z': z, 'value': val, 'quantity': parts[2]})
    except Exception:
        pass
    return rows

def _v68_compressed_bao_observable_index():
    compressed = _v67_parse_compressed_bao_products()
    out = []
    for rec in compressed:
        obs = _v68_parse_bao_mean_with_labels(rec.get('mean_path'))
        zs = sorted(set(round(_v65_float(o.get('z')) or 0, 4) for o in obs))
        qs = sorted(set(str(o.get('quantity')) for o in obs))
        key = str(rec.get('key') or '').lower()
        tracer = 'ALL'
        for t in ['bgs', 'lrg_elg', 'lrg', 'elg', 'qso', 'lya']:
            if t in key:
                tracer = t.upper()
                break
        out.append(dict(rec, tracer=tracer, observables=obs[:30], n_observables=len(obs), redshift_bins=zs, quantities=qs))
    return out

