def _v68_why(row):
    st = str(row.get('status', ''))
    if 'confirm_like_v68' in st:
        return 'claim_grade_confirm'
    if any(k.endswith('_gate_v68') for k in row):
        return 'v68_gate_strict_or_recovered'
    return _v67_why(row)

def run_dashboard_v68(meta, args):
    base = run_dashboard_v67(meta, args)
    rows = []
    for p in sorted(_v65_dir('outputs').glob('test*.json')):
        obj = _v65_read_json(p)
        if isinstance(obj, dict):
            rows.append(obj)
    confirms, sm, cov, ready, blocked, failed = [], [], [], [], [], []
    why = _V65Counter()
    for r in rows:
        st = str(r.get('status', ''))
        item = {'test_id': r.get('test_id'), 'prediction_id': r.get('prediction_id'), 'prediction_name': r.get('prediction_name'), 'status': st, 'why_not_confirm': _v68_why(r)}
        why[item['why_not_confirm']] += 1
        if 'smd_constant_consistency_confirm_like' in st:
            sm.append(item)
        elif 'coverage_confirmed' in st:
            cov.append(item)
        elif 'confirm_like' in st and 'blocked' not in st and 'failed' not in st:
            confirms.append(item)
        elif any(x in st for x in ('blocked', 'failed', 'required', 'broken', 'data_limited')):
            blocked.append(item)
        else:
            ready.append(item)
        for k, v in r.items():
            if isinstance(v, dict) and ('gate_v68' in k or 'gate_v67' in k or 'gate_v66' in k or 'gate_v65' in k or 'gate_v64' in k):
                ok = v.get('eligible_for_confirm_like', v.get('eligible_for_route_confirm_like', True))
                if not ok:
                    failed.append({'test_id': r.get('test_id'), 'gate': k, 'missing': v.get('missing'), 'diagnostic_class': v.get('diagnostic_class')})
    art = []
    for p in _v68_candidate_files(['*v68*.json', '*v68*.csv', '*v68*.jsonl'], roots=[_v65_dir('measurements'), _v65_dir('outputs')], max_files=1000):
        pp = _V65Path(p)
        if not pp.exists() or pp.name.startswith('test'):
            continue
        obj = _v65_read_json(pp) if pp.suffix.lower() == '.json' else {}
        art.append({'artifact_key': pp.stem, 'path': str(pp), 'exists': True, 'size_bytes': pp.stat().st_size, 'sha256': _v65_sha256(pp), 'status': obj.get('status') if isinstance(obj, dict) else None})
    base['dashboard_v68'] = {
        'claim_policy': 'v68 implements the six requested improvements: P41 table-based Wilson proxy, P33 labeled compressed/exact split audit, P32 H1/L1 text-strain fits, PTA coordinate/residual-kappa join audit, P30 mask/control-subtraction resolver, and P39 covariance/model-penalty audit.',
        'no_manual_fill_policy': True,
        'interface_only': False,
        'nonSM_confirm_like': confirms,
        'SM_constant_consistency': sm,
        'coverage_confirmed': cov,
        'ready_or_compatible': ready,
        'blocked_or_gate_failed': blocked,
        'failed_gates': failed[:2500],
        'why_not_confirm_class_counts': dict(why),
        'artifact_index': art,
        'n_artifacts': len(art),
        'n_nonSM_confirm_like': len(confirms),
        'n_SM_constant_consistency': len(sm),
        'n_coverage_confirmed': len(cov),
        'n_blocked_or_gate_failed': len(blocked),
        'implemented_improvements_v68': [
            'P41 public Supplementary.tex q2 table parser plus observable-aware Wilson proxy fit',
            'P33 DESI compressed BAO observable-label index plus exact LSS/random catalogue gate',
            'P32 H1/L1 GWOSC text-strain likelihood rebuild with pre-peak null',
            'PTA residual-kappa join scan with coordinate and ACT-kappa availability audit',
            'P30 mask acceptance/control-subtracted patch resolver',
            'P39/P1 Pantheon+DESI covariance, systematics, AIC/BIC gate artifact',
        ],
    }
    base['status'] = 'dashboard_positive_current_only_v68'
    return base

