def _v70_p3_endpoint_candidates():
    rows, audit = [], []
    try:
        paths = _v60_candidate_files(
            ['*filament*.csv', '*filament*.tsv', '*filament*.dat', '*filament*.txt', '*endpoint*.csv', '*node*.csv', '*cosmicweb*', '*tempel*'],
            roots=[_V65Path.cwd() / '.ccdr_round10_cache', _v65_dir('inputs'), _v65_dir('measurements'), _v65_dir('outputs')],
            max_files=800,
        )
    except Exception:
        paths = []
    endpoint_tokens = ['ra1', 'dec1', 'ra2', 'dec2', 'node1', 'node2', 'endpoint', 'endpoint_ra', 'endpoint_dec']
    for p in paths[:160]:
        pp = _V65Path(p)
        if not pp.exists() or not pp.is_file() or pp.stat().st_size > 120_000_000:
            continue
        text = _v69_read_text_maybe_gzip(pp, max_bytes=1_000_000)
        low = text[:20000].lower()
        hit = any(t in low for t in endpoint_tokens)
        audit.append({'path': str(pp), 'sha256': _v65_sha256(pp), 'size_bytes': pp.stat().st_size, 'endpoint_token_hit': hit})
        if not hit:
            continue
        for line in text.splitlines()[:5000]:
            nums = [_v65_float(x) for x in _v65_re.findall(r'[-+]?(?:\d+\.\d*|\.\d+|\d+)(?:[eE][-+]?\d+)?', line)]
            nums = [x for x in nums if x is not None]
            if len(nums) >= 4:
                rows.append({'source_path': str(pp), 'values': nums[:8]})
                if len(rows) >= 200:
                    break
    return rows, audit

def run_p3_exact_metadata_v70(meta, args):
    base = _run_p3_for_v70(meta, args) if _run_p3_for_v70 else base_result(meta, 'endpoint_data_limited')
    rows, audit = _v70_p3_endpoint_candidates()
    row = {
        'artifact_version': _V70_VERSION,
        'status': 'endpoint_semantic_candidates_found' if rows else 'endpoint_semantic_catalogue_absent',
        'n_endpoint_candidate_rows': len(rows),
        'endpoint_rows_preview': rows[:40],
        'audit': audit[:80],
        'claim_policy_v70': 'v70 searches only metadata/header/token-positive files and avoids giant non-endpoint downloads. Confirmation still requires explicit endpoint semantics plus redshift/orientation nulls.',
        'manual_fill_required': False,
    }
    out = _v65_dir('outputs') / 'p3_endpoint_recovery_v70.json'
    _v65_write_json(out, row)
    base['p3_endpoint_recovery_v70'] = row
    missing = []
    if not rows:
        missing.append('explicit_endpoint_or_node_pair_rows')
    missing.extend(['endpoint_redshift_null', 'orientation_shuffle_null'])
    base['p3_endpoint_recovery_gate_v70'] = _v70_gate(missing, artifact_path=str(out), diagnostic_class=row['status'])
    if rows and str(base.get('status')) == 'endpoint_data_limited':
        base['status'] = 'filament_endpoint_semantic_candidates_ready_v70'
    return base

def _v70_why(row):
    st = str(row.get('status', ''))
    if 'confirm_like_v70' in st:
        return 'claim_grade_confirm'
    if any(k.endswith('_gate_v70') for k in row):
        return 'v70_gate_strict_or_recovered'
    return _v69_why(row)

def run_dashboard_v70(meta, args):
    base = run_dashboard_v69(meta, args)
    rows = []
    for p in sorted(_v65_dir('outputs').glob('test*.json')):
        obj = _v65_read_json(p)
        if isinstance(obj, dict):
            rows.append(obj)
    confirms, sm, cov, ready, blocked, failed = [], [], [], [], [], []
    why = _V65Counter()
    for r in rows:
        st = str(r.get('status', ''))
        item = {'test_id': r.get('test_id'), 'prediction_id': r.get('prediction_id'), 'prediction_name': r.get('prediction_name'), 'status': st, 'why_not_confirm': _v70_why(r)}
        why[item['why_not_confirm']] += 1
        if 'smd_constant_consistency_confirm_like' in st:
            sm.append(item)
        elif 'coverage_confirmed' in st:
            cov.append(item)
        elif 'confirm_like' in st and 'blocked' not in st and 'failed' not in st:
            confirms.append(item)
        elif any(x in st for x in ('blocked', 'failed', 'required', 'broken', 'data_limited')):
            blocked.append(item)
        else:
            ready.append(item)
        for k, v in r.items():
            if isinstance(v, dict) and any(tok in k for tok in ('gate_v70', 'gate_v69', 'gate_v68', 'gate_v67', 'gate_v66', 'gate_v65', 'gate_v64')):
                ok = v.get('eligible_for_confirm_like', v.get('eligible_for_route_confirm_like', True))
                if not ok:
                    failed.append({'test_id': r.get('test_id'), 'gate': k, 'missing': v.get('missing'), 'diagnostic_class': v.get('diagnostic_class')})
    art = []
    for p in _v68_candidate_files(['*v70*.json', '*v70*.csv', '*v70*.jsonl'], roots=[_v65_dir('measurements'), _v65_dir('outputs')], max_files=1000):
        pp = _V65Path(p)
        if not pp.exists() or pp.name.startswith('test'):
            continue
        obj = _v65_read_json(pp) if pp.suffix.lower() == '.json' else {}
        art.append({'artifact_key': pp.stem, 'path': str(pp), 'exists': True, 'size_bytes': pp.stat().st_size, 'sha256': _v65_sha256(pp), 'status': obj.get('status') if isinstance(obj, dict) else None})
    base['dashboard_v70'] = {
        'claim_policy': 'v70 implements all seven requested improvements: P36 memory-safe clean-row reuse, PTA signed residual-kappa gate, DESI exact-input manifest, P30 SDSS route confirmation, P32 multi-event manifest, P39 full-covariance audit, and P3 endpoint semantic search.',
        'no_manual_fill_policy': True,
        'interface_only': False,
        'nonSM_confirm_like': confirms,
        'SM_constant_consistency': sm,
        'coverage_confirmed': cov,
        'ready_or_compatible': ready,
        'blocked_or_gate_failed': blocked,
        'failed_gates': failed[:2500],
        'why_not_confirm_class_counts': dict(why),
        'artifact_index': art,
        'n_artifacts': len(art),
        'n_nonSM_confirm_like': len(confirms),
        'n_SM_constant_consistency': len(sm),
        'n_coverage_confirmed': len(cov),
        'n_blocked_or_gate_failed': len(blocked),
        'implemented_improvements_v70': [
            'R10-T14 P36 memory-safe clean-claim gate avoiding v64 MemoryError',
            'PTA/CL2 predeclared positive signed residual-kappa gate',
            'P33 source-targeted DESI DR2 LSScats clustering/random manifest',
            'P30 SDSS same-mask route confirm separated from global P30 claim',
            'P32 multi-event strain manifest and strict no-overclaim gate',
            'P39/P1 covariance/model-penalty v70 audit',
            'P3 endpoint semantic catalogue search with giant-download guard',
        ],
    }
    base['status'] = 'dashboard_positive_current_only_v70'
    return base

