def _v73_parse_par_coords(text):
    c = _v69_parse_par_coords(text)
    if c:
        c['coordinate_system'] = 'equatorial_ra_dec'
        return c
    name = elong = elat = None
    for line in str(text or '').splitlines():
        s = line.strip()
        if not s or s.startswith('#'):
            continue
        parts = s.split()
        if not parts:
            continue
        key = parts[0].upper()
        if key in ('PSRJ', 'PSRB', 'PSR', 'NAME') and len(parts) > 1:
            name = parts[1]
        elif key == 'ELONG' and len(parts) > 1:
            elong = _v65_float(parts[1])
        elif key == 'ELAT' and len(parts) > 1:
            elat = _v65_float(parts[1])
    if elong is not None and elat is not None:
        return {'pulsar_id': name, 'ra': elong % 360.0, 'dec': elat, 'ecliptic_lon': elong, 'ecliptic_lat': elat, 'coordinate_system': 'ecliptic_lon_lat'}
    return None

def _v73_pta_public_source_scan():
    paths = _v73_public_candidate_files(['*.par', '*.tim', '*.tar*', '*.tgz', '*.zip', '*tar__content*', '*ng_full*', '*resid*', '*residual*', '*toa*', '*nanograv*', '*NANOGrav*', '*15yr*', '*kappa*'], max_files=5000)
    coords, pair_rows, audit = [], [], []
    residual_like_numeric_rows = 0
    kappa_like_numeric_rows = 0
    seen_coord = set()
    for p in paths[:1200]:
        pp = _V65Path(p)
        if not pp.exists() or not pp.is_file():
            continue
        if pp.stat().st_size > 300_000_000 and not any(tok in pp.name.lower() for tok in ('.par', '.tim', 'resid', 'toa', 'ng_full', 'nanograv', '15yr', 'tar__content')):
            continue
        ncoord = npair = nres = nkap = 0
        try:
            items = _v69_pta_file_texts(pp)
        except Exception:
            items = []
        items = sorted(
            items,
            key=lambda it: (
                0 if '.par' in str(it.get('member_name') or '').lower() else
                1 if any(tok in str(it.get('member_name') or '').lower() for tok in ('resid', 'residual', 'kappa')) else
                2
            ),
        )
        for item in items[:600]:
            lname = str(item.get('member_name') or '').lower()
            text = item.get('text') or ''
            if '.par' in lname:
                c = _v73_parse_par_coords(text)
                if c:
                    key = (round(c['ra'], 6), round(c['dec'], 6), c.get('pulsar_id'))
                    if key not in seen_coord:
                        seen_coord.add(key)
                        c = dict(c, source_path=str(pp), member_name=item.get('member_name'))
                        coords.append(c)
                        ncoord += 1
            if any(tok in lname for tok in ['resid', 'residual', 'toa', 'kappa']):
                for line in text.splitlines()[:120000]:
                    nums = [_v65_float(x) for x in _v65_re.findall(r'[-+]?(?:\d+\.\d*|\.\d+|\d+)(?:[eE][-+]?\d+)?', line)]
                    nums = [x for x in nums if x is not None]
                    if len(nums) >= 2 and any(tok in line.lower() for tok in ('resid', 'toa')):
                        nres += 1
                    if len(nums) >= 2 and 'kappa' in line.lower():
                        nkap += 1
                        pair_rows.append({'residual_or_toa_weight': nums[0], 'kappa_sample': nums[-1], 'source_path': str(pp), 'member_name': item.get('member_name')})
                        npair += 1
        residual_like_numeric_rows += nres
        kappa_like_numeric_rows += nkap
        if ncoord or npair or nres or nkap:
            audit.append(_v73_file_digest_record(pp, {'n_coordinates': ncoord, 'n_residual_like_numeric_rows': nres, 'n_residual_kappa_pair_rows': npair, 'n_kappa_like_numeric_rows': nkap}))
    vals = [
        (_v65_float(r.get('residual_or_toa_weight')), _v65_float(r.get('kappa_sample')))
        for r in pair_rows
        if _v65_float(r.get('residual_or_toa_weight')) is not None and _v65_float(r.get('kappa_sample')) is not None
    ]
    weighted = signed_p = two_sided_p = None
    top_stable = False
    if vals:
        weighted = sum(a * b for a, b in vals) / len(vals)
        res = [a for a, _ in vals]
        kap = [b for _, b in vals]
        rng = _v65_random.Random(73017)
        null = []
        n_perm = 4096 if len(vals) >= 20 else 1024
        for _ in range(n_perm):
            kk = list(kap)
            rng.shuffle(kk)
            null.append(sum(a * b for a, b in zip(res, kk)) / len(vals))
        two_sided_p = sum(1 for x in null if abs(x) >= abs(weighted)) / len(null)
        signed_p = sum(1 for x in null if x >= weighted) / len(null) if weighted is not None and weighted > 0 else None
        ranked = sorted(vals, key=lambda x: abs(x[0] * x[1]), reverse=True)
        trimmed = ranked[max(1, len(ranked)//10):] if len(ranked) >= 10 else ranked[1:]
        if trimmed:
            trimmed_stat = sum(a * b for a, b in trimmed) / len(trimmed)
            top_stable = bool(weighted == 0 or (weighted * trimmed_stat > 0 and abs(trimmed_stat) >= 0.25 * abs(weighted)))
    v72 = _v65_read_json(_v65_dir('measurements') / 'pta_residual_kappa_public_only_v72_AUTO_PUBLIC.json') or {}
    row = {
        'artifact_version': _V73_VERSION,
        'status': 'pta_public_residual_kappa_pairs_ready_v73' if len(vals) >= 20 else 'pta_public_residual_kappa_pairs_still_absent_v73',
        'n_public_par_coordinates': len(coords),
        'n_public_residual_like_numeric_rows': residual_like_numeric_rows,
        'n_public_kappa_like_numeric_rows': kappa_like_numeric_rows,
        'n_public_residual_kappa_pairs': len(vals),
        'public_weighted_statistic': weighted,
        'public_two_sided_sky_shuffle_p': two_sided_p,
        'public_one_sided_signed_sky_shuffle_p': signed_p,
        'public_top_weight_removal_stable': top_stable,
        'coordinate_rows_preview': coords[:40],
        'source_audit': audit[:160],
        'v72_public_only_status': v72.get('status'),
        'v72_excluded_echo_rows': v72.get('n_excluded_measurement_or_output_echo_rows'),
        'manual_fill_required': False,
        'claim_policy_v73': 'v73 scans only cache/input public PTA sources for .par/.tim/residual/TOA/kappa content. Coordinates alone do not promote; confirm-like requires >=20 public residual-kappa pairs and the signed shuffle/top-weight gates.',
    }
    return row

def run_cl2_pta_density_gate_v73(meta, args):
    existing = _v72_output_by_test_id('R10-T17')
    if isinstance(existing, dict) and existing:
        base = dict(existing)
