def _v73_exact_lss_random_source_scan():
    paths = _v73_public_candidate_files(
        ['*clustering*.dat*', '*clustering*.fits*', '*LSScats*', '*full*.ran*', '*random*.dat*', '*random*.fits*', '*LRG*', '*ELG*', '*QSO*', '*BGS*', '*eBOSS*', '*BOSS*'],
        max_files=2500,
    )
    catalog_audit, random_audit, excluded_audit = [], [], []
    best_catalog_rows, best_fit = [], None
    catalog_rows_total = 0
    random_rows_total = 0
    for p in paths[:220]:
        lname = str(p).lower()
        is_lss = any(tok in lname for tok in ('desi', 'lsscat', 'lss', 'clustering', 'sdss', 'boss', 'eboss', 'lrg', 'elg', 'qso', 'bgs'))
        is_random = any(tok in lname for tok in ('random', 'full.ran', '_ran', '.ran'))
        if any(tok in lname for tok in ('p30', 'act_dr6', 'lensing', 'kappa')) and not any(tok in lname for tok in ('desi', 'sdss', 'boss', 'eboss')):
            excluded_audit.append(_v73_file_digest_record(p, {'reason': 'non_lss_or_p30_control_random'}))
            continue
        rows, inf = _v69_load_rdz_any(p, max_rows=120000)
        rec = _v73_file_digest_record(p, {'n_rdz_rows': len(rows), 'columns': inf.get('columns') or inf.get('header'), 'parser_error': inf.get('error') or inf.get('fits_error'), 'lss_scoped': is_lss})
        if is_random:
            random_rows_total += len(rows)
            random_audit.append(rec)
        elif is_lss:
            catalog_rows_total += len(rows)
            catalog_audit.append(rec)
            if len(rows) > len(best_catalog_rows):
                best_catalog_rows = rows
        else:
            excluded_audit.append(dict(rec, reason='not_lss_scoped'))
    if best_catalog_rows and len(best_catalog_rows) >= 800 and random_rows_total >= 800:
        best_fit = _v65_pair_alpha(best_catalog_rows)
        if best_fit:
            best_fit['random_rows_available_for_split'] = random_rows_total
            best_fit['source_policy'] = 'v73_exact_lss_catalog_plus_public_random_rows'
    compressed = _v68_compressed_bao_observable_index()
    row = {
        'artifact_version': _V73_VERSION,
        'status': 'p33_exact_lss_random_density_split_ready_v73' if best_fit else 'p33_exact_lss_random_inputs_still_absent_v73',
        'n_exact_catalog_files': len(catalog_audit),
        'n_exact_random_files': len(random_audit),
        'n_exact_catalog_rows': catalog_rows_total,
        'n_exact_random_rows': random_rows_total,
        'exact_density_split_alpha': best_fit,
        'exact_catalog_audit': catalog_audit[:120],
        'exact_random_audit': random_audit[:120],
        'excluded_or_non_lss_audit': excluded_audit[:80],
        'n_compressed_bao_products': len(compressed),
        'compressed_bao_control_preview': compressed[:20],
        'manual_fill_required': False,
        'claim_policy_v73': 'v73 performs a source-scoped exact LSS/random scan and excludes P30/lensing random controls. Compressed BAO remains a control, not a substitute for RA/Dec/z clustering plus random catalogues.',
    }
    return row

