    if not fit.get('redshift_jackknife_stable'):
        missing.append('redshift_jackknife_stable')
    base['p33_exact_lss_random_source_scan_v73'] = row
    base['p33_exact_lss_random_source_gate_v73'] = _v73_gate(missing, artifact_path=str(out), diagnostic_class=row['status'])
