def _v73_lss_pk_xi_source_scan():
    compressed = _v68_compressed_bao_observable_index()
    paths = _v73_public_candidate_files(
        ['*pk*.txt', '*pk*.dat*', '*pofk*', '*power*spectrum*', '*PowerSpect*', '*xi*.txt', '*xi*.dat*', '*corr*.txt', '*correlation*.dat*'],
        max_files=1200,
    )
    audits, best = [], None
    for p in paths[:180]:
        lss = _v71_is_lss_power_candidate(p) or any(tok in str(p).lower() for tok in ('correlation', 'xi', 'boss', 'eboss', 'desi', 'sdss'))
        if not lss:
            audits.append(_v73_file_digest_record(p, {'lss_scoped': False, 'n_numeric_rows': 0, 'score': None}))
            continue
        rows = _v71_parse_power_rows(p, max_rows=30000)
        score = _v71_harmonic_score(rows)
        rec = _v73_file_digest_record(p, {'lss_scoped': True, 'n_numeric_rows': len(rows), 'score': score})
        audits.append(rec)
        if score and score.get('phase_randomized_p') is not None:
            if best is None or (score.get('n_peaks', 0), len(rows)) > (((best.get('score') or {}).get('n_peaks', 0)), best.get('n_numeric_rows', 0)):
                best = rec
    control = _v72_compressed_bao_harmonic_control(compressed)
    row = {
        'artifact_version': _V73_VERSION,
        'status': 'p35_lss_pk_xi_harmonic_candidate_built_v73' if best else 'p35_lss_pk_or_xi_table_absent_v73',
        'lss_power_or_xi_audit': audits[:160],
        'best_lss_power_or_xi_candidate': best,
        'compressed_bao_harmonic_control': control,
        'n_compressed_bao_products': len(compressed),
        'manual_fill_required': False,
        'claim_policy_v73': 'v73 expands the P(k)/xi source scan but only claim-grades public LSS-scoped power-spectrum/correlation tables with >=4 harmonic peaks and a phase-randomized p<=0.05.',
    }
    return row

