def _v73_p3_endpoint_source_scan():
    patterns = ['*filament*', '*endpoint*', '*node*', '*tempel*', '*cosmicweb*', '*catalog*', '*tully*']
    paths = _v73_public_candidate_files(patterns, max_files=1500)
    header_tokens = [
        'ra1', 'dec1', 'ra2', 'dec2', 'ra_1', 'dec_1', 'ra_2', 'dec_2',
        'node1', 'node2', 'node_1', 'node_2', 'endpoint', 'end_ra', 'end_dec',
        'endpoint_ra', 'endpoint_dec', 'ra_start', 'dec_start', 'ra_end', 'dec_end',
        'x1', 'y1', 'z1', 'x2', 'y2', 'z2',
    ]
    rows, audit = [], []
    for p in paths[:220]:
        pp = _V65Path(p)
        if not pp.exists() or not pp.is_file():
            continue
        if pp.stat().st_size > 180_000_000:
            audit.append(_v73_file_digest_record(pp, {'skipped': 'giant_download_guard'}))
            continue
        text = _v69_read_text_maybe_gzip(pp, max_bytes=3_000_000)
        low = text[:80000].lower()
        hits = [t for t in header_tokens if t in low]
        semantic = len(hits) >= 2 and any(t in low for t in ('endpoint', 'node', 'filament'))
        rec = _v73_file_digest_record(pp, {'endpoint_header_hits': hits, 'semantic_endpoint_candidate': semantic})
        nrows = 0
        if semantic:
            for line in text.splitlines()[:14000]:
                nums = [_v65_float(x) for x in _v65_re.findall(r'[-+]?(?:\d+\.\d*|\.\d+|\d+)(?:[eE][-+]?\d+)?', line)]
                nums = [x for x in nums if x is not None]
                if len(nums) >= 4 and all(-360 <= x <= 360 for x in nums[:4]):
                    rows.append({'source_path': str(pp), 'values': nums[:8], 'header_hits': hits[:8]})
                    nrows += 1
                    if nrows >= 120 or len(rows) >= 500:
                        break
        rec['n_strict_endpoint_rows'] = nrows
        audit.append(rec)
    row = {
        'artifact_version': _V73_VERSION,
        'status': 'p3_endpoint_semantic_rows_ready_v73' if rows else 'p3_endpoint_semantics_still_absent_v73',
        'n_strict_endpoint_rows': len(rows),
        'endpoint_rows_preview': rows[:80],
        'audit': audit[:160],
        'giant_download_guard': True,
        'manual_fill_required': False,
        'claim_policy_v73': 'v73 deepens endpoint/node-pair header detection but keeps promotion limited to explicit endpoint semantics plus redshift and orientation-shuffle nulls.',
    }
    return row

def run_p3_exact_metadata_v73(meta, args):
    base = _v73_base(meta, args, _run_p3_for_v73, 'endpoint_data_limited')
    row = _v73_p3_endpoint_source_scan()
