def _v74_p33_exact_lss_artifact():
    scan73 = _v65_read_json(_v65_dir('measurements') / 'p33_exact_lss_random_source_scan_v73_AUTO_PUBLIC.json') or {}
    candidates = _v73_public_candidate_files(['*LSScats*', '*clustering*', '*full.ran*', '*random*', '*LRG*', '*ELG*', '*QSO*', '*BOSS*', '*eBOSS*'], max_files=1200)
    exact_audit = []
    for p in candidates[:120]:
        low = str(p).lower()
        if any(tok in low for tok in ('bao', 'gaussian_bao', '_cov', '_mean')) and not any(tok in low for tok in ('clustering', 'lsscat', 'random', 'full.ran')):
            exact_audit.append(_v73_file_digest_record(p, {'lss_exact_candidate': False, 'reason': 'compressed_bao_not_exact_lss'}))
            continue
        rows, inf = _v69_load_rdz_any(p, max_rows=120000)
        exact_audit.append(_v73_file_digest_record(p, {'lss_exact_candidate': bool(rows), 'n_rdz_rows': len(rows), 'columns': inf.get('columns') or inf.get('header'), 'parser_error': inf.get('error') or inf.get('fits_error')}))
    row = {
        'artifact_version': _V74_VERSION,
        'status': 'p33_exact_lss_random_inputs_still_absent_v74',
        'n_exact_catalog_rows': int(scan73.get('n_exact_catalog_rows') or 0),
        'n_exact_random_rows': int(scan73.get('n_exact_random_rows') or 0),
        'n_compressed_bao_products': int(scan73.get('n_compressed_bao_products') or 0),
        'exact_candidate_audit': exact_audit[:120],
        'manual_fill_required': False,
        'claim_policy_v74': 'v74 separates exact LSS/random catalogues from compressed BAO mean/cov products. Confirm-like requires real RA/Dec/z clustering and random rows, not only BAO summary vectors.',
    }
    return row

