def _v74_p35_pkxi_artifact():
    scan73 = _v65_read_json(_v65_dir('measurements') / 'p35_lss_pk_xi_source_scan_v73_AUTO_PUBLIC.json') or {}
    compressed = _v68_compressed_bao_observable_index()
    control = _v72_compressed_bao_harmonic_control(compressed)
    candidates = _v73_public_candidate_files(['*pk*.txt', '*pk*.dat*', '*pofk*', '*power*spectrum*', '*xi*.txt', '*xi*.dat*', '*corr*.txt', '*correlation*.dat*'], max_files=800)
    audits = []
    best = None
    for p in candidates[:140]:
        low = str(p).lower()
        lss = _v71_is_lss_power_candidate(p) or any(tok in low for tok in ('boss', 'eboss', 'desi', 'sdss', 'xi', 'correlation'))
        rows = _v71_parse_power_rows(p, max_rows=30000) if lss else []
        score = _v71_harmonic_score(rows) if rows else None
        rec = _v73_file_digest_record(p, {'lss_scoped': lss, 'n_numeric_rows': len(rows), 'score': score})
        audits.append(rec)
        if score and score.get('phase_randomized_p') is not None and (best is None or score.get('n_peaks', 0) > ((best.get('score') or {}).get('n_peaks', 0))):
            best = rec
    row = {
        'artifact_version': _V74_VERSION,
        'status': 'p35_lss_pk_xi_table_absent_v74' if not best else 'p35_lss_pk_xi_candidate_built_v74',
        'best_lss_power_or_xi_candidate': best,
        'candidate_audit': audits[:140],
        'compressed_bao_harmonic_control': control,
        'v73_status': scan73.get('status'),
        'manual_fill_required': False,
        'claim_policy_v74': 'v74 adds a broader source audit for P(k)/xi products but keeps compressed BAO as a non-claim-grade control.',
    }
    return row

