def _v74_p3_endpoint_artifact():
    scan73 = _v65_read_json(_v65_dir('outputs') / 'p3_endpoint_semantic_source_scan_v73.json') or {}
    paths = _v73_public_candidate_files(['*filament*', '*endpoint*', '*node*', '*tempel*', '*cosmicweb*', '*catalog*', '*void*'], max_files=1200)
    audit = []
    rows = []
    tokens = ('ra1', 'dec1', 'ra2', 'dec2', 'node1', 'node2', 'endpoint', 'ra_start', 'dec_start', 'ra_end', 'dec_end')
    for p in paths[:180]:
        pp = _V65Path(p)
        if not pp.exists() or pp.stat().st_size > 180_000_000:
            audit.append(_v73_file_digest_record(pp, {'skipped': 'giant_or_missing'}))
            continue
        text = _v69_read_text_maybe_gzip(pp, max_bytes=3_000_000)
        low = text[:120000].lower()
        hits = [t for t in tokens if t in low]
        nrows = 0
        if len(hits) >= 2:
            for line in text.splitlines()[:16000]:
                nums = [_v65_float(x) for x in _v65_re.findall(r'[-+]?(?:\d+\.\d*|\.\d+|\d+)(?:[eE][-+]?\d+)?', line)]
                nums = [x for x in nums if x is not None]
                if len(nums) >= 4 and all(-360 <= x <= 360 for x in nums[:4]):
                    rows.append({'source_path': str(pp), 'values': nums[:8], 'header_hits': hits[:8]})
                    nrows += 1
                    if nrows >= 120:
                        break
        audit.append(_v73_file_digest_record(pp, {'endpoint_header_hits': hits, 'n_endpoint_like_rows': nrows}))
    row = {
        'artifact_version': _V74_VERSION,
        'status': 'p3_endpoint_semantics_still_absent_v74' if not rows else 'p3_endpoint_rows_recovered_v74',
        'n_strict_endpoint_rows': len(rows),
        'endpoint_rows_preview': rows[:80],
        'source_audit': audit[:180],
        'v73_n_strict_endpoint_rows': scan73.get('n_strict_endpoint_rows'),
        'manual_fill_required': False,
        'claim_policy_v74': 'v74 expands endpoint discovery but keeps confirmation tied to explicit endpoint/node-pair rows plus redshift and orientation-shuffle nulls.',
    }
    return row

def run_p3_exact_metadata_v74(meta, args):
    base = _v74_base_from_existing('R10-T09', meta, args, _run_p3_for_v74, 'endpoint_data_limited')
    row = _v74_p3_endpoint_artifact()
    out = _v74_write_output('p3_endpoint_catalogue_recovery_v74.json', row)
    missing = []
    if (row.get('n_strict_endpoint_rows') or 0) <= 0:
        missing.append('explicit_endpoint_or_node_pair_rows')
    missing.extend(['endpoint_redshift_null', 'orientation_shuffle_null'])
    base['p3_endpoint_catalogue_recovery_v74'] = row
    base['p3_endpoint_catalogue_gate_v74'] = _v74_gate(missing, artifact_path=str(out), diagnostic_class=row['status'])
    base['status'] = 'p3_endpoint_orientation_confirm_like_v74' if not missing else ('filament_endpoint_semantic_candidates_ready_v74' if row.get('n_strict_endpoint_rows') else 'endpoint_data_limited')
    return base

def _v74_p32_multievent_artifact():
    scan73 = _v65_read_json(_v65_dir('measurements') / 'p32_multi_event_strain_source_scan_v73_AUTO_PUBLIC.json') or {}
    paths = _v73_public_candidate_files(['*GW*', '*gw*', '*eventapi*', '*GWOSC*', '*strain*', '*.hdf5', '*.gwf', '*.txt.gz'], max_files=2000)
    catalog_ids = set(scan73.get('event_ids_seen') or [])
    strain_ids = set()
    audit = []
    for p in paths[:320]:
        rec = _v73_file_digest_record(p)
        ids = set(m.upper() for m in _v65_re.findall(r'GW\d{6}', str(p), _v65_re.I))
        try:
            if _V65Path(p).stat().st_size < 5_000_000 or 'eventapi' in str(p).lower():
                text = _v69_read_text_maybe_gzip(p, max_bytes=5_000_000)
                ids.update(m.upper() for m in _v65_re.findall(r'GW\d{6}', text, _v65_re.I))
        except Exception:
            pass
        rec['event_ids_in_path_or_text'] = sorted(ids)
        if any(tok in str(p).lower() for tok in ('gwosc', 'strain', '.hdf5', '.gwf', '.txt.gz')):
            strain_ids.update(ids)
        catalog_ids.update(ids)
        audit.append(rec)
    row = {
        'artifact_version': _V74_VERSION,
        'status': 'p32_multi_event_strain_inputs_ready_v74' if len(strain_ids) >= 2 else 'p32_single_event_strain_only_v74',
        'event_catalog_ids_seen': sorted(catalog_ids),
        'strain_event_ids_seen': sorted(strain_ids),
        'n_distinct_strain_events': len(strain_ids),
        'source_audit': audit[:180],
        'v73_status': scan73.get('status'),
        'v71_min_detector_delta_chi2': scan73.get('v71_min_detector_delta_chi2'),
        'v71_max_time_slide_p': scan73.get('v71_max_time_slide_p'),
        'manual_fill_required': False,
        'claim_policy_v74': 'v74 scans event API payload text as well as filenames. Confirm-like still requires at least two distinct public strain events and passing detector/time-slide/LOO gates.',
    }
    return row

