def _v75_p35_pkxi_artifact():
    row74 = _v65_read_json(_v65_dir('measurements') / 'p35_lss_pk_xi_harmonic_v74_AUTO_PUBLIC.json') or {}
    paths = _v73_public_candidate_files(['*pk*.txt', '*pk*.dat*', '*pofk*', '*power*spectrum*', '*xi*.txt', '*xi*.dat*', '*corr*.txt', '*correlation*.dat*'], max_files=500)
    audits = []
    best = None
    for p in paths[:90]:
        pp = _V65Path(p)
        if not pp.exists() or pp.stat().st_size > 25_000_000:
            audits.append(_v73_file_digest_record(pp, {'skipped': 'missing_or_too_large_for_pkxi_text_scan'}))
            continue
        low = str(pp).lower()
        lss = _v71_is_lss_power_candidate(pp) or any(tok in low for tok in ('boss', 'eboss', 'desi', 'sdss', 'xi', 'correlation'))
        rows = _v71_parse_power_rows(pp, max_rows=50000) if lss else []
        score = _v71_harmonic_score(rows) if rows else None
        rec = _v73_file_digest_record(pp, {'lss_scoped': lss, 'n_numeric_rows': len(rows), 'score': score})
        audits.append(rec)
        if score and score.get('phase_randomized_p') is not None and (best is None or score.get('n_peaks', 0) > ((best.get('score') or {}).get('n_peaks', 0))):
            best = rec
    row = {
        'artifact_version': _V75_VERSION,
        'status': 'p35_lss_pk_xi_table_absent_v75' if not best else 'p35_lss_pk_xi_candidate_built_v75',
        'best_lss_power_or_xi_candidate': best,
        'candidate_audit': audits[:140],
        'v74_status': row74.get('status'),
        'manual_fill_required': False,
        'claim_policy_v75': 'v75 extends the P(k)/xi search to correlation-table names while keeping compressed BAO products and broad archives out of the confirm gate.',
    }
    return row

def run_harmonic_comb_proxy_v75(meta, args):
    base = _v75_base_from_existing('R10-T08', meta, args, _run_p35_for_v75, 'harmonic_proxy_positive_ready')
    row = _v75_p35_pkxi_artifact()
    out = _v75_write_measurement('p35_extended_pk_xi_harmonic_v75_AUTO_PUBLIC.json', row)
    score = ((row.get('best_lss_power_or_xi_candidate') or {}).get('score') or {})
    missing = []
    if not row.get('best_lss_power_or_xi_candidate'):
        missing.append('public_lss_pk_or_xi_table')
    if (score.get('n_peaks') or 0) < 4:
        missing.append('harmonic_peaks_ge_4')
    if _v65_float(score.get('phase_randomized_p')) is None or (_v65_float(score.get('phase_randomized_p')) or 1) > 0.05:
        missing.append('phase_randomized_p_le_0p05')
    base['p35_extended_pk_xi_harmonic_v75'] = row
    base['p35_extended_pk_xi_harmonic_gate_v75'] = _v75_gate(missing, artifact_path=str(out), diagnostic_class=row['status'])
    base['status'] = 'p35_harmonic_pk_confirm_like_v75' if not missing else 'harmonic_proxy_positive_ready'
    return base

def _v75_endpoint_rows_from_text(path, text, max_rows=500):
    rows = []
    lines = [ln for ln in str(text or '').splitlines() if ln.strip() and not ln.lstrip().startswith('#')]
    header = lines[0].lower() if lines else ''
    header_hits = [t for t in ('ra1', 'dec1', 'ra2', 'dec2', 'node1', 'node2', 'endpoint', 'ra_start', 'dec_start', 'ra_end', 'dec_end', 'source_ra', 'target_ra') if t in header or t in str(text[:50000]).lower()]
    for ln in lines[1 if _v65_re.search(r'[A-Za-z]', header) else 0:]:
        nums = [_v65_float(x) for x in _v65_re.findall(r'[-+]?(?:\d+\.\d*|\.\d+|\d+)(?:[eE][-+]?\d+)?', ln)]
        nums = [x for x in nums if x is not None]
        if len(nums) >= 4 and 0 <= nums[0] <= 360 and -90 <= nums[1] <= 90 and 0 <= nums[2] <= 360 and -90 <= nums[3] <= 90:
            rows.append({'source_path': str(path), 'values': nums[:8], 'header_hits': header_hits[:12]})
            if len(rows) >= max_rows:
                break
    return rows, header_hits

def _v75_p3_endpoint_artifact():
    row74 = _v65_read_json(_v65_dir('outputs') / 'p3_endpoint_catalogue_recovery_v74.json') or {}
    paths = _v73_public_candidate_files(['*filament*', '*endpoint*', '*node*', '*edge*', '*tempel*', '*cosmicweb*', '*catalog*', '*void*'], max_files=1400)
    found = []
    audit = []
    for p in paths[:220]:
        pp = _V65Path(p)
        if not pp.exists() or pp.stat().st_size > 180_000_000:
            audit.append(_v73_file_digest_record(pp, {'skipped': 'giant_or_missing'}))
            continue
        if zipfile.is_zipfile(str(pp)) or _v65_tarfile.is_tarfile(str(pp)):
            audit.append(_v73_file_digest_record(pp, {'archive_present': True, 'endpoint_rows_recovered': 0}))
            continue
        text = _v69_read_text_maybe_gzip(pp, max_bytes=5_000_000)
        rows, hits = _v75_endpoint_rows_from_text(pp, text, max_rows=120)
        found.extend(rows)
        audit.append(_v73_file_digest_record(pp, {'endpoint_header_hits': hits, 'n_endpoint_like_rows': len(rows)}))
    row = {
        'artifact_version': _V75_VERSION,
        'status': 'p3_endpoint_semantics_still_absent_v75' if not found else 'p3_endpoint_rows_recovered_v75',
        'n_strict_endpoint_rows': len(found),
        'endpoint_rows_preview': found[:100],
        'source_audit': audit[:220],
        'v74_n_strict_endpoint_rows': row74.get('n_strict_endpoint_rows'),
        'manual_fill_required': False,
        'claim_policy_v75': 'v75 parses endpoint/node/edge-style RA-Dec pairs using alternate graph column names. Confirmation still requires redshift and orientation-shuffle nulls.',
    }
    return row

def run_p3_exact_metadata_v75(meta, args):
    base = _v75_base_from_existing('R10-T09', meta, args, _run_p3_for_v75, 'endpoint_data_limited')
    row = _v75_p3_endpoint_artifact()
    out = _v75_write_output('p3_endpoint_edge_parser_v75.json', row)
    missing = []
    if (row.get('n_strict_endpoint_rows') or 0) <= 0:
        missing.append('explicit_endpoint_or_node_pair_rows')
    missing.extend(['endpoint_redshift_null', 'orientation_shuffle_null'])
    base['p3_endpoint_edge_parser_v75'] = row
    base['p3_endpoint_edge_parser_gate_v75'] = _v75_gate(missing, artifact_path=str(out), diagnostic_class=row['status'])
    base['status'] = 'p3_endpoint_orientation_confirm_like_v75' if not missing else ('filament_endpoint_semantic_candidates_ready_v75' if row.get('n_strict_endpoint_rows') else 'endpoint_data_limited')
    return base

def _v75_p32_eventapi_strain_index():
    cached = _v65_read_json(_v65_dir('measurements') / 'p32_eventapi_strain_index_v75_AUTO_PUBLIC.json') or {}
    if cached.get('artifact_version') == _V75_VERSION and cached.get('status'):
        cached['reused_cached_v75_artifact'] = True
        return cached
    paths = _v73_public_candidate_files(['*eventapi*', '*GWOSC*', '*strain*', '*GW*.hdf5', '*GW*.gwf', '*GW*.txt.gz'], max_files=2500)
    local_strain_ids = set()
    eventapi_events = {}
    audit = []
    for p in paths[:500]:
        pp = _V65Path(p)
        low = str(pp).lower()
        ids = set(m.upper() for m in _v65_re.findall(r'GW\d{6}', str(pp), _v65_re.I))
        if any(tok in low for tok in ('strain', '.hdf5', '.gwf', '.txt.gz')):
            local_strain_ids.update(ids)
        rec = _v73_file_digest_record(pp, {'event_ids_in_name': sorted(ids)})
        if 'eventapi' in low and pp.exists() and pp.stat().st_size < 80_000_000:
            try:
                obj = _v65_json.loads(pp.read_text(encoding='utf-8', errors='replace'))
                events = obj.get('events') if isinstance(obj, dict) else {}
                if isinstance(events, dict):
                    for _, ev in events.items():
                        cname = str(ev.get('commonName') or '')
                        if not _v65_re.match(r'GW\d{6}', cname):
                            continue
                        strain = ev.get('strain') or []
                        eventapi_events[cname.upper()] = {
                            'n_strain_urls': len(strain) if isinstance(strain, list) else 0,
                            'detectors': sorted(set(str(x.get('detector')) for x in strain if isinstance(x, dict) and x.get('detector'))),
                            'urls_preview': [x.get('url') for x in strain[:8] if isinstance(x, dict) and x.get('url')],
                        }
                rec['n_eventapi_events'] = len(events) if isinstance(events, dict) else 0
            except Exception as e:
                rec['eventapi_parse_error'] = repr(e)[:250]
        audit.append(rec)
    eventapi_with_strain = sorted([k for k, v in eventapi_events.items() if (v.get('n_strain_urls') or 0) > 0])
    return {
        'artifact_version': _V75_VERSION,
        'status': 'p32_eventapi_multi_event_strain_urls_ready_v75' if len(eventapi_with_strain) >= 2 else ('p32_single_event_strain_only_v75' if len(local_strain_ids) < 2 else 'p32_multi_event_local_strain_ready_v75'),
        'local_strain_event_ids': sorted(local_strain_ids),
        'n_local_strain_events': len(local_strain_ids),
        'eventapi_strain_event_ids': eventapi_with_strain,
        'n_eventapi_strain_events': len(eventapi_with_strain),
        'eventapi_strain_index_preview': {k: eventapi_events[k] for k in eventapi_with_strain[:12]},
        'source_audit': audit[:160],
        'manual_fill_required': False,
        'claim_policy_v75': 'v75 indexes local strain files and event API strain URLs separately. Confirm-like requires local strain for at least two events plus detector, time-slide, and leave-one-event-out gates.',
    }

def run_ringdown_strain_gate_v75(meta, args):
    base = _v75_base_from_existing('R10-T19', meta, args, _run_p32_for_v75, 'ringdown_strain_analysis_required_v74')
    row = _v75_p32_eventapi_strain_index()
    out = _v75_write_measurement('p32_eventapi_strain_index_v75_AUTO_PUBLIC.json', row)
    old = _v65_read_json(_v65_dir('measurements') / 'p32_multi_event_strain_likelihood_v74_AUTO_PUBLIC.json') or {}
    min_delta = _v65_float(old.get('v71_min_detector_delta_chi2'))
    max_p = _v65_float(old.get('v71_max_time_slide_p'))
    missing = []
    if (row.get('n_local_strain_events') or 0) < 2:
        missing.append('two_distinct_local_public_strain_events')
    if min_delta is None or min_delta < 4:
        missing.append('min_detector_delta_chi2_ge_4')
    if max_p is None or max_p > 0.05:
        missing.append('time_slide_p_le_0p05')
    if (row.get('n_local_strain_events') or 0) < 2:
        missing.append('leave_one_event_out_stable')
    base['p32_eventapi_strain_index_v75'] = row
    base['p32_eventapi_strain_index_gate_v75'] = _v75_gate(missing, artifact_path=str(out), diagnostic_class=row['status'])
    base['status'] = 'ringdown_strain_likelihood_confirm_like_v75' if not missing else 'ringdown_strain_analysis_required_v75'
    return base

def _v75_p39_covariance_systematics_artifact(base=None):
    base = base or {}
    row74 = _v65_read_json(_v65_dir('measurements') / 'p39_publication_likelihood_chain_v74_AUTO_PUBLIC.json') or {}
    paths = _v73_public_candidate_files(['*Pantheon*', '*SH0ES*', '*pantheon*', '*cov*', '*sys*', '*systematic*'], max_files=1000)
    audit = []
    pantheon_full = []
    pantheon_diag = []
    systematics = []
    for p in paths[:220]:
        pp = _V65Path(p)
        low = str(pp).lower()
        rec = _v74_numeric_shape(pp, max_rows=15000)
        rec['pantheon_scoped'] = bool('pantheon' in low or 'sh0es' in low)
        rec['systematics_scoped'] = bool(any(tok in low for tok in ('sys', 'systematic')))
        rec['bao_scoped'] = bool('desi_gaussian_bao' in low or 'bao' in low)
        rec['full_covariance_candidate'] = bool(rec.get('pantheon_scoped') and ('cov' in low or rec.get('systematics_scoped')) and (rec.get('max_numeric_cols') or 0) > 3 and (rec.get('n_numeric_rows') or 0) > 100)
        if rec['full_covariance_candidate']:
            pantheon_full.append(rec)
        if rec['pantheon_scoped'] and (rec.get('n_numeric_rows') or 0) > 100:
            pantheon_diag.append(rec)
        if rec['pantheon_scoped'] and rec['systematics_scoped']:
            systematics.append(rec)
        audit.append(rec)
    delta = _v65_float(row74.get('delta_chi2_lcdm_minus_best') or base.get('delta_chi2_lcdm_minus_best'))
    diag_rows = max([int(r.get('n_numeric_rows') or 0) for r in pantheon_diag], default=int(row74.get('pantheon_diag_rows') or 0))
    n_obs = max(1, diag_rows + 8)
    delta_aic = 2 - (delta or 0)
    delta_bic = _v65_math.log(n_obs) - (delta or 0)
    row = {
        'artifact_version': _V75_VERSION,
        'status': 'p39_full_covariance_still_absent_v75' if not pantheon_full else 'p39_full_covariance_candidates_ready_v75',
        'pantheon_diag_rows': diag_rows,
        'pantheon_full_covariance_used': bool(pantheon_full),
        'pantheon_systematics_candidates': systematics[:20],
        'pantheon_covariance_candidates': pantheon_full[:20],
        'bao_full_covariance_used': bool(row74.get('bao_full_covariance_used')),
        'delta_chi2_lcdm_minus_best': delta,
        'delta_AIC_new_minus_LCDM': delta_aic,
        'delta_BIC_new_minus_LCDM': delta_bic,
        'model_penalty_supports_new_model': bool(delta is not None and delta >= 9 and delta_aic < 0 and delta_bic < 0),
        'systematics_splits_done': bool(pantheon_full and systematics and delta is not None and delta >= 9),
        'source_audit': audit[:220],
        'manual_fill_required': False,
        'claim_policy_v75': 'v75 separately classifies Pantheon diagonal, covariance, and systematics candidates. BAO covariance is not allowed to stand in for Pantheon covariance.',
    }
    return row

def run_p39_likelihood_gate_v75(meta, args):
    base = _v75_base_from_existing(str(meta.get('test_id') or ''), meta, args, _run_p39_for_v75, 'positive_compatible')
    row = _v75_p39_covariance_systematics_artifact(base)
    out = _v75_write_measurement('p39_covariance_systematics_chain_v75_AUTO_PUBLIC.json', row)
    missing = []
    if _v65_float(row.get('delta_chi2_lcdm_minus_best')) is None or (_v65_float(row.get('delta_chi2_lcdm_minus_best')) or 0) < 9:
        missing.append('delta_chi2_lcdm_minus_best_ge_9')
    if not row.get('pantheon_full_covariance_used'):
        missing.append('pantheon_full_covariance_used')
    if not row.get('bao_full_covariance_used'):
        missing.append('bao_full_covariance_used')
    if not row.get('systematics_splits_done'):
        missing.append('systematics_splits_done')
    if not row.get('model_penalty_supports_new_model'):
        missing.append('model_penalty_supports_new_model')
    base['p39_covariance_systematics_chain_v75'] = row
    base['p39_covariance_systematics_gate_v75'] = _v75_gate(missing, artifact_path=str(out), diagnostic_class=row['status'])
    base['status'] = 'p39_likelihood_confirm_like_v75' if not missing else 'positive_compatible'
    return base

def _v75_why(row):
    st = str(row.get('status', ''))
    if 'confirm_like_v75' in st:
        return 'claim_grade_confirm'
    if any(k.endswith('_gate_v75') for k in row):
        return 'v75_gate_strict_or_recovered'
    return _v74_why(row)

def run_dashboard_v75(meta, args):
    base = run_dashboard_v74(meta, args)
    rows = []
    for p in sorted(_v65_dir('outputs').glob('test*.json')):
        obj = _v65_read_json(p)
        if isinstance(obj, dict):
            rows.append(obj)
    confirms, sm, cov, ready, blocked, failed = [], [], [], [], [], []
    why = _V65Counter()
    for r in rows:
        st = str(r.get('status', ''))
        item = {'test_id': r.get('test_id'), 'prediction_id': r.get('prediction_id'), 'prediction_name': r.get('prediction_name'), 'status': st, 'why_not_confirm': _v75_why(r)}
        why[item['why_not_confirm']] += 1
        if 'smd_constant_consistency_confirm_like' in st:
            sm.append(item)
        elif 'coverage_confirmed' in st:
            cov.append(item)
        elif 'confirm_like' in st and 'blocked' not in st and 'failed' not in st:
            confirms.append(item)
        elif any(x in st for x in ('blocked', 'failed', 'required', 'broken', 'data_limited')):
            blocked.append(item)
        else:
            ready.append(item)
        for k, v in r.items():
            if isinstance(v, dict) and any(tok in k for tok in ('gate_v75', 'gate_v74', 'gate_v73', 'gate_v72', 'gate_v71', 'gate_v70', 'gate_v69', 'gate_v68', 'gate_v67', 'gate_v66', 'gate_v65')):
                ok = v.get('eligible_for_confirm_like', v.get('eligible_for_route_confirm_like', True))
                if not ok:
                    failed.append({'test_id': r.get('test_id'), 'gate': k, 'missing': v.get('missing'), 'diagnostic_class': v.get('diagnostic_class')})
    art = []
    for p in _v68_candidate_files(['*v75*.json', '*v75*.csv', '*v75*.jsonl'], roots=[_v65_dir('measurements'), _v65_dir('outputs')], max_files=1000):
        pp = _V65Path(p)
        if not pp.exists() or pp.name.startswith('test'):
            continue
        obj = _v65_read_json(pp) if pp.suffix.lower() == '.json' else {}
        art.append({'artifact_key': pp.stem, 'path': str(pp), 'exists': True, 'size_bytes': pp.stat().st_size, 'sha256': _v65_sha256(pp), 'status': obj.get('status') if isinstance(obj, dict) else None})
    base['dashboard_v75'] = {
        'claim_policy': 'v75 implements the seven requested confirm-recovery improvements as concrete local source parsers/statistics, with strict no-manual-fill promotion gates.',
        'no_manual_fill_policy': True,
        'interface_only': False,
        'nonSM_confirm_like': confirms,
        'SM_constant_consistency': sm,
        'coverage_confirmed': cov,
        'ready_or_compatible': ready,
        'blocked_or_gate_failed': blocked,
        'failed_gates': failed[:5000],
        'why_not_confirm_class_counts': dict(why),
        'artifact_index': art,
        'n_artifacts': len(art),
        'n_nonSM_confirm_like': len(confirms),
        'n_SM_constant_consistency': len(sm),
        'n_coverage_confirmed': len(cov),
        'n_blocked_or_gate_failed': len(blocked),
        'implemented_improvements_v75': [
            'P30 Euclid sample-random same-mask geometry statistic',
            'P30 Planck map-level product classifier',
            'PTA public .tim TOA-weight parser and residual-kappa gate',
            'P33 archive-aware exact LSS/random discovery',
            'P35 extended public P(k)/xi harmonic parser',
            'P3 endpoint/node/edge parser with alternate column names',
            'P32 GWOSC event API strain URL/local strain index',
            'P39/P1 Pantheon covariance/systematics classifier',
        ],
    }
    base['status'] = 'dashboard_positive_current_only_v75'
    return base

