# ROUND-10 v76 confirm-recovery implementation layer
# Scope: implement the eight v75 report improvements with strict filters and
# explicit source gates.  v76 intentionally rejects loose numeric candidates
# that do not satisfy the claim-specific source contract.
# ============================================================================

_V76_VERSION = 'v76'

_run_cl2_for_v76 = RUNNERS.get('cl2_weighted_parse_v21', run_cl2_pta_density_gate_v75)
_run_p33_for_v76 = RUNNERS.get('p33_density_bao_measured_scaffold_v22', run_p33_density_bao_measurement_gate_v75)
_run_p30_for_v76 = RUNNERS.get('p30_maskrandom_freeze_v22', run_p30_publication_gate_v75)
_run_planck_for_v76 = RUNNERS.get('planck_route_guard_v20', run_planck_route_guard_v75)
_run_euclid_for_v76 = RUNNERS.get('euclid_mer_catalogue_only_v13', run_euclid_route_guard_v75)
_run_p35_for_v76 = RUNNERS.get('harmonic_comb_proxy', run_harmonic_comb_proxy_v75)
_run_p3_for_v76 = RUNNERS.get('p3_exact_metadata_v21', run_p3_exact_metadata_v75)
_run_p32_for_v76 = RUNNERS.get('ringdown_strain_plan_v22', run_ringdown_strain_gate_v75)
_run_p39_for_v76 = RUNNERS.get('p39_likelihood_gate_v22', run_p39_likelihood_gate_v75)

def _v76_gate(missing, **extra):
    g = {'gate_version': _V76_VERSION, 'eligible_for_confirm_like': not missing, 'missing': missing}
    g.update(extra)
    return g

def _v76_write_measurement(name, obj):
    out = _v65_dir('measurements') / name
    _v65_write_json(out, obj)
    return out

def _v76_write_output(name, obj):
    out = _v65_dir('outputs') / name
    _v65_write_json(out, obj)
    return out

def _v76_base_from_existing(test_id, meta, args, runner, fallback_status):
    existing = _v72_output_by_test_id(test_id)
    if isinstance(existing, dict) and existing:
        return dict(existing)
    try:
        return runner(meta, args)
    except Exception as e:
        b = base_result(meta, fallback_status)
        b['v76_base_runner_error'] = repr(e)[:500]
        return b

def _v76_angle_deg(vals):
    if len(vals) < 4:
        return None
    ra1, dec1, ra2, dec2 = vals[:4]
    if not (0 <= ra1 <= 360 and -90 <= dec1 <= 90 and 0 <= ra2 <= 360 and -90 <= dec2 <= 90):
        return None
    dra = (ra2 - ra1) * _v65_math.cos(_v65_math.radians((dec1 + dec2) / 2.0))
    ddec = dec2 - dec1
    if abs(dra) + abs(ddec) <= 1e-12:
        return None
    return (_v65_math.degrees(_v65_math.atan2(ddec, dra)) + 180.0) % 180.0

def _v76_orientation_score(angles):
    if len(angles) < 20:
        return {'n_angles': len(angles), 'anisotropy_score': None, 'orientation_shuffle_p': None}
    obs_x = sum(_v65_math.cos(2.0 * _v65_math.radians(a)) for a in angles) / len(angles)
    obs_y = sum(_v65_math.sin(2.0 * _v65_math.radians(a)) for a in angles) / len(angles)
    obs = (obs_x * obs_x + obs_y * obs_y) ** 0.5
    rng = _v65_random.Random(76)
    null = []
    for _ in range(256):
        aa = [rng.random() * 180.0 for _ in angles]
        nx = sum(_v65_math.cos(2.0 * _v65_math.radians(a)) for a in aa) / len(aa)
        ny = sum(_v65_math.sin(2.0 * _v65_math.radians(a)) for a in aa) / len(aa)
        null.append((nx * nx + ny * ny) ** 0.5)
    return {'n_angles': len(angles), 'anisotropy_score': obs, 'orientation_shuffle_p': sum(1 for x in null if x >= obs) / len(null)}

def _v76_p3_endpoint_orientation_artifact():
    row75 = _v65_read_json(_v65_dir('outputs') / 'p3_endpoint_edge_parser_v75.json') or {}
    raw = row75.get('endpoint_rows_preview') or []
    strict = []
    rejects = []
    for r in raw:
        vals = [_v65_float(x) for x in (r.get('values') or [])]
        vals = [x for x in vals if x is not None]
        source = str(r.get('source_path') or '')
        low = source.lower()
        hits = [str(x).lower() for x in (r.get('header_hits') or [])]
        source_scoped = bool(any(tok in low for tok in ('filament', 'endpoint', 'node', 'edge', 'tempel', 'cosmicweb')) and not any(tok in low for tok in ('p30_', 'random_catalogue', 'random_catalog')))
        header_scoped = bool(any(tok in ' '.join(hits) for tok in ('endpoint', 'node', 'edge', 'ra1', 'dec1', 'ra2', 'dec2', 'ra_start', 'ra_end')))
        angle = _v76_angle_deg(vals)
        zvals = [x for x in vals[4:] if 0.0 < x < 5.0]
        if angle is not None and (source_scoped or header_scoped):
            strict.append({'source_path': source, 'values': vals[:8], 'angle_deg': angle, 'redshift': zvals[0] if zvals else None, 'header_hits': hits[:8]})
        else:
            rejects.append({'source_path': source, 'reason': 'not_endpoint_scoped_or_not_pair_coordinates', 'values': vals[:6], 'header_hits': hits[:8]})
    angles = [r['angle_deg'] for r in strict if r.get('angle_deg') is not None]
    zrows = [r for r in strict if r.get('redshift') is not None]
    orient = _v76_orientation_score(angles)
    row = {
        'artifact_version': _V76_VERSION,
        'status': 'p3_endpoint_strict_rows_absent_v76' if not strict else 'p3_endpoint_orientation_statistic_built_v76',
        'n_v75_endpoint_like_rows': len(raw),
        'n_strict_endpoint_rows': len(strict),
        'n_rejected_loose_numeric_rows': len(rejects),
        'n_endpoint_rows_with_redshift': len(zrows),
        'orientation_statistic': orient,
        'strict_rows_preview': strict[:80],
        'reject_preview': rejects[:80],
        'manual_fill_required': False,
        'claim_policy_v76': 'v76 requires endpoint/node/edge-scoped sources or explicit endpoint headers before computing orientation. Loose coordinate rows from unrelated random catalogues are rejected.',
    }
    return row

def run_p3_exact_metadata_v76(meta, args):
    base = _v76_base_from_existing('R10-T09', meta, args, _run_p3_for_v76, 'endpoint_data_limited')
    row = _v76_p3_endpoint_orientation_artifact()
    out = _v76_write_output('p3_endpoint_orientation_strict_v76.json', row)
    p = _v65_float((row.get('orientation_statistic') or {}).get('orientation_shuffle_p'))
    missing = []
    if (row.get('n_strict_endpoint_rows') or 0) < 20:
        missing.append('strict_endpoint_or_node_pair_rows_ge_20')
    if (row.get('n_endpoint_rows_with_redshift') or 0) < 20:
        missing.append('endpoint_redshift_rows_ge_20')
    if p is None or p > 0.05:
        missing.append('orientation_shuffle_p_le_0p05')
    base['p3_endpoint_orientation_strict_v76'] = row
    base['p3_endpoint_orientation_gate_v76'] = _v76_gate(missing, artifact_path=str(out), diagnostic_class=row['status'])
    base['status'] = 'p3_endpoint_orientation_confirm_like_v76' if not missing else ('p3_endpoint_strict_rows_required_v76' if row.get('n_strict_endpoint_rows') else 'endpoint_data_limited')
    return base

def _v76_scan_residual_kappa_tables():
    roots = [_V65Path.cwd() / '.ccdr_round10_cache', _v65_dir('measurements'), _v65_dir('outputs'), _v65_dir('inputs')]
    paths = _v68_candidate_files(['*resid*.csv', '*residual*.csv', '*toa*.csv', '*kappa*.csv', '*pta*.csv'], roots=roots, max_files=700)
    pairs = []
    audit = []
    for p in paths[:120]:
        pp = _V65Path(p)
        if not pp.exists() or pp.suffix.lower() != '.csv' or pp.stat().st_size > 40_000_000:
            continue
        n = 0
        try:
            with pp.open(encoding='utf-8', errors='replace') as f:
                rdr = _v65_csv.DictReader(f)
                for r in rdr:
                    norm = {_v65_norm(k): v for k, v in r.items()}
                    pid = norm.get('pulsar_id') or norm.get('psr') or norm.get('psrj') or norm.get('name')
                    res = _v65_float(norm.get('residual') or norm.get('timing_residual') or norm.get('toa_residual') or norm.get('resid'))
                    kap = _v65_float(norm.get('kappa') or norm.get('kappa_sample') or norm.get('kappa_act') or norm.get('kappa_planck'))
                    w = _v65_float(norm.get('weight') or norm.get('toa_weight') or norm.get('noise_weight')) or 1.0
                    if pid and res is not None and kap is not None:
                        pairs.append({'pulsar_id': str(pid), 'residual': res, 'kappa': kap, 'weight': w, 'source_path': str(pp)})
                        n += 1
                        if len(pairs) >= 20000:
                            break
                audit.append({'path': str(pp), 'sha256': _v65_sha256(pp), 'n_residual_kappa_pairs': n})
        except Exception as e:
            audit.append({'path': str(pp), 'error': repr(e)[:250]})
        if len(pairs) >= 20000:
            break
    return pairs, audit

def _v76_pta_residual_kappa_artifact():
    row75 = _v65_read_json(_v65_dir('measurements') / 'pta_toa_weighted_residual_recovery_v75_AUTO_PUBLIC.json') or {}
    pairs, audit = _v76_scan_residual_kappa_tables()
    stat = None
    pval = None
    stable = False
    if pairs:
        denom = sum(abs(x.get('weight') or 1.0) for x in pairs) or 1.0
        stat = sum(x['residual'] * x['kappa'] * (x.get('weight') or 1.0) for x in pairs) / denom
        rng = _v65_random.Random(76)
        resids = [x['residual'] for x in pairs]
        kappas = [x['kappa'] for x in pairs]
        weights = [x.get('weight') or 1.0 for x in pairs]
        null = []
        for _ in range(256):
            rng.shuffle(kappas)
            null.append(sum(a * b * w for a, b, w in zip(resids, kappas, weights)) / denom)
        pval = sum(1 for x in null if x >= stat) / len(null)
        top = sorted(pairs, key=lambda x: abs((x.get('residual') or 0) * (x.get('kappa') or 0) * (x.get('weight') or 1)), reverse=True)
        keep = top[1:] if len(top) > 3 else top
        if keep:
            den2 = sum(abs(x.get('weight') or 1.0) for x in keep) or 1.0
            stat2 = sum(x['residual'] * x['kappa'] * (x.get('weight') or 1.0) for x in keep) / den2
            stable = bool(stat * stat2 > 0 and abs(stat2) >= 0.25 * abs(stat))
    row = {
        'artifact_version': _V76_VERSION,
        'status': 'pta_residual_kappa_pairs_recovered_v76' if len(pairs) >= 20 else 'pta_residual_kappa_pairs_still_absent_v76',
        'n_toa_weighted_pulsars_v75': row75.get('n_toa_weighted_pulsars'),
        'n_residual_kappa_pairs': len(pairs),
        'weighted_statistic': stat,
        'public_one_sided_signed_sky_shuffle_p': pval,
        'top_weight_removal_stable': stable,
        'scan_audit': audit[:100],
        'pairs_preview': pairs[:40],
        'manual_fill_required': False,
        'claim_policy_v76': 'v76 scans local public/cache tables for real residual+kappa columns. TOA weights alone are not treated as residuals.',
    }
    return row

def run_cl2_pta_density_gate_v76(meta, args):
    base = _v76_base_from_existing('R10-T17', meta, args, _run_cl2_for_v76, 'pta_weighted_kappa_residual_required_v75')
    row = _v76_pta_residual_kappa_artifact()
    out = _v76_write_measurement('pta_residual_kappa_pair_recovery_v76_AUTO_PUBLIC.json', row)
    missing = []
    if (row.get('n_residual_kappa_pairs') or 0) < 20:
        missing.append('public_residual_kappa_pairs_ge_20')
    if _v65_float(row.get('weighted_statistic')) is None or (_v65_float(row.get('weighted_statistic')) or 0) <= 0:
        missing.append('positive_public_weighted_statistic')
    if _v65_float(row.get('public_one_sided_signed_sky_shuffle_p')) is None or (_v65_float(row.get('public_one_sided_signed_sky_shuffle_p')) or 1) > 0.05:
        missing.append('public_one_sided_signed_sky_shuffle_p_le_0p05')
    if not row.get('top_weight_removal_stable'):
        missing.append('public_top_weight_removal_stable')
    base['pta_residual_kappa_pair_recovery_v76'] = row
    base['pta_residual_kappa_pair_recovery_gate_v76'] = _v76_gate(missing, artifact_path=str(out), diagnostic_class=row['status'])
    base['status'] = 'pta_weighted_kappa_residual_confirm_like_v76' if not missing else 'pta_weighted_kappa_residual_required_v76'
    return base

def _v76_p30_second_route_artifact():
    row75 = _v65_read_json(_v65_dir('measurements') / 'p30_second_route_statistic_v75_AUTO_PUBLIC.json') or {}
    euclid75 = (((row75.get('route_matrix') or {}).get('euclid') or {}).get('v75_same_mask_geometry') or {})
    planck75 = (((row75.get('route_matrix') or {}).get('planck') or {}).get('v75_map_product_audit') or {})
    kappa_paths = _v68_candidate_files(['*euclid*kappa*.csv', '*kappa*cell*.csv', '*density*kappa*.csv', '*act*kappa*.csv', '*planck*kappa*.csv'], roots=[_V65Path.cwd()/'.ccdr_round10_cache', _v65_dir('measurements'), _v65_dir('outputs'), _v65_dir('inputs')], max_files=600)
    kappa_rows = []
    kappa_audit = []
    for p in kappa_paths[:80]:
        pp = _V65Path(p)
        if not pp.exists() or pp.suffix.lower() != '.csv' or pp.stat().st_size > 80_000_000:
            continue
        n = 0
        try:
            with pp.open(encoding='utf-8', errors='replace') as f:
                rdr = _v65_csv.DictReader(f)
                for r in rdr:
                    norm = {_v65_norm(k): v for k, v in r.items()}
                    kap = _v65_float(norm.get('kappa') or norm.get('kappa_sample') or norm.get('kappa_act') or norm.get('convergence'))
                    ra = _v65_float(norm.get('ra') or norm.get('ra_deg'))
                    dec = _v65_float(norm.get('dec') or norm.get('dec_deg'))
                    if kap is not None and ra is not None and dec is not None:
                        kappa_rows.append({'ra': ra, 'dec': dec, 'kappa': kap, 'source_path': str(pp)})
                        n += 1
                        if len(kappa_rows) >= 50000:
                            break
            kappa_audit.append({'path': str(pp), 'sha256': _v65_sha256(pp), 'n_ra_dec_kappa_rows': n})
        except Exception as e:
            kappa_audit.append({'path': str(pp), 'error': repr(e)[:250]})
    planck_numeric = [r for r in (planck75.get('map_level_candidates') or []) if ((r.get('numeric_shape') or {}).get('n_numeric_rows') or 0) > 100]
    euclid_delta = _v65_float(row75.get('euclid_delta_after_residualization'))
    planck_stat_ready = bool(planck_numeric and False)
    euclid_stat_ready = bool(len(kappa_rows) >= 800 and euclid_delta is not None and euclid_delta > 0)
    second = bool(planck_stat_ready or euclid_stat_ready)
    row = {
        'artifact_version': _V76_VERSION,
        'status': 'p30_global_second_route_confirmed_v76' if second and row75.get('sdss_scoped_confirm_like') else 'p30_second_route_still_not_confirmed_v76',
        'sdss_scoped_confirm_like': bool(row75.get('sdss_scoped_confirm_like')),
        'second_independent_route_confirm_like': second,
        'n_routes_confirm_like': int(bool(row75.get('sdss_scoped_confirm_like'))) + int(second),
        'planck_map_level_candidates': planck75.get('n_map_level_candidates'),
        'planck_numeric_map_candidates': len(planck_numeric),
        'planck_same_mask_statistic_available': planck_stat_ready,
        'euclid_sample_rows': euclid75.get('n_sample_rows'),
        'euclid_random_rows': euclid75.get('n_random_rows'),
        'euclid_kappa_cell_rows': len(kappa_rows),
        'euclid_delta_after_residualization': euclid_delta,
        'euclid_same_mask_geometry_status': euclid75.get('status'),
        'kappa_cell_audit': kappa_audit[:60],
        'manual_fill_required': False,
        'claim_policy_v76': 'v76 searches for RA/Dec/kappa cell tables and numeric Planck map candidates. It does not promote from map filenames or density geometry alone.',
    }
    return row

