def _v76_p33_exact_alpha_artifact():
    row75 = _v65_read_json(_v65_dir('measurements') / 'p33_archive_exact_lss_random_v75_AUTO_PUBLIC.json') or {}
    paths = _v73_public_candidate_files(['*clustering*.dat*', '*clustering*.fits*', '*LSScats*', '*full*.ran*', '*random*.dat*', '*random*.fits*', '*LRG*clustering*', '*ELG*clustering*', '*QSO*clustering*'], max_files=1400)
    cat_rows = []
    ran_rows = []
    audit = []
    for p in paths[:120]:
        low = str(p).lower()
        rows, inf = _v69_load_rdz_any(p, max_rows=50000)
        is_random = any(tok in low for tok in ('random', 'full.ran', '_ran', '.ran'))
        audit.append({'path': str(p), 'sha256': _v65_sha256(p), 'n_rdz_rows': len(rows), 'is_random_like': is_random, 'columns': inf.get('columns') or inf.get('header'), 'error': inf.get('error') or inf.get('fits_error')})
        if is_random:
            ran_rows.extend(rows[:50000 - len(ran_rows)])
        else:
            cat_rows.extend(rows[:50000 - len(cat_rows)])
    fit = _v65_pair_alpha(cat_rows[:4000]) if len(cat_rows) >= 800 else None
    if fit:
        fit['desi_randoms_used'] = bool(len(ran_rows) >= 800)
    row = {
        'artifact_version': _V76_VERSION,
        'status': 'p33_exact_alpha_fit_built_v76' if fit else 'p33_exact_lss_random_inputs_still_absent_v76',
        'n_exact_catalog_rows': len(cat_rows),
        'n_exact_random_rows': len(ran_rows),
        'exact_alpha_fit': fit,
        'v75_n_exact_catalog_rows': row75.get('n_exact_catalog_rows'),
        'v75_n_exact_random_rows': row75.get('n_exact_random_rows'),
        'source_audit': audit[:120],
        'manual_fill_required': False,
        'claim_policy_v76': 'v76 attempts a real RA/Dec/z parse and lightweight density-split alpha fit. Compressed BAO vectors are not substitutes for exact catalog/random rows.',
    }
    return row

