    row = _v77_p30_route_manifest()
    out = _v77_write_measurement('p30_claim_grade_map_manifest_v77_AUTO_PUBLIC.json', row)
    missing = []
    if not row.get('sdss_scoped_confirm_like'):
        missing.append('sdss_route_confirm_like')
    missing.append('second_independent_route_confirm_like_with_public_kappa_or_map_values')
    base['p30_claim_grade_map_manifest_v77'] = row
    base['p30_global_second_route_gate_v77'] = _v77_gate(missing, artifact_path=str(out), diagnostic_class=row['status'])
    base['status'] = 'density_kappa_global_route_confirm_like_v77' if not missing else ('density_kappa_sdss_route_confirm_like_v77' if row.get('sdss_scoped_confirm_like') else 'density_kappa_global_route_blocked_v77')
    return base

