def _v77_p32_second_event_manifest():
    v76 = _v65_read_json(_v65_dir('measurements') / 'p32_second_strain_event_v76_AUTO_PUBLIC.json') or {}
    paths = _v73_public_candidate_files(['*GW*.hdf5', '*GW*.gwf', '*GW*.txt.gz', '*strain*', '*eventapi*'], max_files=2500)
    local_ids, api_ids, audit = set(), set(), []
    for p in paths[:360]:
        pp = _V65Path(p)
        ids = set(m.upper() for m in _v65_re.findall(r'GW\d{6}', str(pp), _v65_re.I))
        low = str(pp).lower()
        if any(tok in low for tok in ('.hdf5', '.gwf', '.txt.gz', 'strain')):
            local_ids.update(ids)
        if 'eventapi' in low:
            text = _v77_read_small_text(pp, max_bytes=20_000_000)
            api_ids.update(m.upper() for m in _v65_re.findall(r'GW\d{6}', text, _v65_re.I))
        audit.append(_v73_file_digest_record(pp, {'event_ids_in_name': sorted(ids)}))
    row = {
        'artifact_version': _V77_VERSION,
        'status': 'p32_second_local_strain_still_absent_v77' if len(local_ids) < 2 else 'p32_multi_event_local_strain_ready_v77',
        'local_strain_event_ids': sorted(local_ids),
        'eventapi_event_ids_seen': sorted(api_ids)[:80],
        'n_local_strain_events': len(local_ids),
        'n_eventapi_event_ids_seen': len(api_ids),
        'v76_n_local_strain_events': v76.get('n_local_strain_events'),
        'source_audit': audit[:120],
        'manual_fill_required': False,
        'claim_policy_v77': 'v77 distinguishes event metadata from local strain. Only local strain files for distinct events count toward confirm.',
    }
    return row

