def _v77_p39_covariance_source_manifest(base=None):
    base = base or {}
    v76 = _v65_read_json(_v65_dir('measurements') / 'p39_full_covariance_likelihood_v76_AUTO_PUBLIC.json') or {}
    paths = _v73_public_candidate_files(['*Pantheon*cov*', '*Pantheon*sys*', '*SH0ES*cov*', '*SH0ES*sys*', '*pantheon*cov*', '*pantheon*sys*'], max_files=500)
    audit = []
    full = []
    for p in paths[:100]:
        rec = _v74_numeric_shape(p, max_rows=12000)
        low = str(p).lower()
        rec['pantheon_scoped'] = bool('pantheon' in low or 'sh0es' in low)
        rec['full_covariance_candidate'] = bool(rec.get('pantheon_scoped') and (rec.get('n_numeric_rows') or 0) > 100 and (rec.get('max_numeric_cols') or 0) > 3)
        if rec['full_covariance_candidate']:
            full.append(rec)
        audit.append(rec)
    delta = _v65_float(v76.get('delta_chi2_lcdm_minus_best') or base.get('delta_chi2_lcdm_minus_best'))
    row = {
        'artifact_version': _V77_VERSION,
        'status': 'p39_full_covariance_sources_absent_v77' if not full else 'p39_full_covariance_sources_ready_v77',
        'pantheon_diag_rows': v76.get('pantheon_diag_rows'),
        'pantheon_full_covariance_used': bool(full),
        'bao_full_covariance_used': bool(v76.get('bao_full_covariance_used')),
        'delta_chi2_lcdm_minus_best': delta,
        'covariance_source_audit': audit[:100],
        'manual_fill_required': False,
        'claim_policy_v77': 'v77 searches only Pantheon/Pantheon+SH0ES-scoped covariance/systematics sources; DESI BAO covariance cannot substitute.',
    }
    return row

def run_p39_likelihood_gate_v77(meta, args):
    base = _v77_base_from_existing(str(meta.get('test_id') or ''), meta, args, _run_p39_for_v77, 'positive_compatible')
    row = _v77_p39_covariance_source_manifest(base)
    out = _v77_write_measurement('p39_covariance_source_manifest_v77_AUTO_PUBLIC.json', row)
    missing = []
    if _v65_float(row.get('delta_chi2_lcdm_minus_best')) is None or (_v65_float(row.get('delta_chi2_lcdm_minus_best')) or 0) < 9:
        missing.append('delta_chi2_lcdm_minus_best_ge_9')
    if not row.get('pantheon_full_covariance_used'):
        missing.append('pantheon_full_covariance_used')
    if not row.get('bao_full_covariance_used'):
        missing.append('bao_full_covariance_used')
    missing.extend(['systematics_splits_done', 'model_penalty_supports_new_model'])
    base['p39_covariance_source_manifest_v77'] = row
    base['p39_covariance_source_gate_v77'] = _v77_gate(missing, artifact_path=str(out), diagnostic_class=row['status'])
    base['status'] = 'p39_likelihood_confirm_like_v77' if not missing else 'positive_compatible'
    return base

def _v77_p35_pkxi_source_manifest():
    v76 = _v65_read_json(_v65_dir('measurements') / 'p35_exact_pkxi_harmonic_v76_AUTO_PUBLIC.json') or {}
    paths = _v73_public_candidate_files(['*pofk*', '*pk*.txt', '*pk*.dat*', '*xi*.txt', '*xi*.dat*', '*correlation*.txt', '*corr*.dat*'], max_files=700)
    audit = []
    best = None
    for p in paths[:100]:
        pp = _V65Path(p)
        if not pp.exists() or pp.stat().st_size > 25_000_000:
            continue
        low = str(pp).lower()
        exact = bool(any(tok in low for tok in ('boss', 'eboss', 'desi', 'sdss', 'pofk', 'xi', 'correlation')) and not any(tok in low for tok in ('gaussian_bao', '_cov', '_mean')))
        rows = _v71_parse_power_rows(pp, max_rows=50000) if exact else []
        score = _v71_harmonic_score(rows) if rows else None
        rec = _v73_file_digest_record(pp, {'exact_lss_pkxi_candidate': exact, 'n_numeric_rows': len(rows), 'score': score})
        audit.append(rec)
        if score and score.get('phase_randomized_p') is not None and (best is None or score.get('n_peaks', 0) > ((best.get('score') or {}).get('n_peaks', 0))):
            best = rec
    row = {
        'artifact_version': _V77_VERSION,
        'status': 'p35_exact_pkxi_source_absent_v77' if not best else 'p35_exact_pkxi_source_candidate_v77',
        'best_lss_power_or_xi_candidate': best,
        'v76_status': v76.get('status'),
        'source_audit': audit[:100],
        'manual_fill_required': False,
        'claim_policy_v77': 'v77 keeps P35 confirm tied to exact public P(k)/xi/correlation data and phase-randomized harmonic nulls.',
    }
    return row

def run_harmonic_comb_proxy_v77(meta, args):
    base = _v77_base_from_existing('R10-T08', meta, args, _run_p35_for_v77, 'harmonic_proxy_positive_ready')
    row = _v77_p35_pkxi_source_manifest()
    out = _v77_write_measurement('p35_pkxi_source_manifest_v77_AUTO_PUBLIC.json', row)
    score = ((row.get('best_lss_power_or_xi_candidate') or {}).get('score') or {})
    missing = []
    if not row.get('best_lss_power_or_xi_candidate'):
        missing.append('public_lss_pk_or_xi_table')
    if (score.get('n_peaks') or 0) < 4:
        missing.append('harmonic_peaks_ge_4')
    if _v65_float(score.get('phase_randomized_p')) is None or (_v65_float(score.get('phase_randomized_p')) or 1) > 0.05:
        missing.append('phase_randomized_p_le_0p05')
    base['p35_pkxi_source_manifest_v77'] = row
    base['p35_pkxi_source_gate_v77'] = _v77_gate(missing, artifact_path=str(out), diagnostic_class=row['status'])
    base['status'] = 'p35_harmonic_pk_confirm_like_v77' if not missing else 'harmonic_proxy_positive_ready'
    return base

def _v77_why(row):
    st = str(row.get('status', ''))
    if 'confirm_like_v77' in st:
        return 'claim_grade_confirm'
    if any(k.endswith('_gate_v77') for k in row):
        return 'v77_gate_strict_or_recovered'
    return _v76_why(row)

def run_dashboard_v77(meta, args):
    base = run_dashboard_v76(meta, args)
    rows = []
    for p in sorted(_v65_dir('outputs').glob('test*.json')):
        obj = _v65_read_json(p)
        if isinstance(obj, dict):
            rows.append(obj)
    confirms, sm, cov, ready, blocked, failed = [], [], [], [], [], []
    why = _V65Counter()
    for r in rows:
        st = str(r.get('status', ''))
        item = {'test_id': r.get('test_id'), 'prediction_id': r.get('prediction_id'), 'prediction_name': r.get('prediction_name'), 'status': st, 'why_not_confirm': _v77_why(r)}
        why[item['why_not_confirm']] += 1
        if 'smd_constant_consistency_confirm_like' in st:
            sm.append(item)
        elif 'coverage_confirmed' in st:
            cov.append(item)
        elif 'confirm_like' in st and 'blocked' not in st and 'failed' not in st:
            confirms.append(item)
        elif any(x in st for x in ('blocked', 'failed', 'required', 'broken', 'data_limited')):
            blocked.append(item)
        else:
            ready.append(item)
        for k, v in r.items():
            if isinstance(v, dict) and any(tok in k for tok in ('gate_v77', 'gate_v76', 'gate_v75', 'gate_v74', 'gate_v73', 'gate_v72', 'gate_v71', 'gate_v70', 'gate_v69', 'gate_v68', 'gate_v67', 'gate_v66', 'gate_v65')):
                ok = v.get('eligible_for_confirm_like', v.get('eligible_for_route_confirm_like', True))
                if not ok:
                    failed.append({'test_id': r.get('test_id'), 'gate': k, 'missing': v.get('missing'), 'diagnostic_class': v.get('diagnostic_class')})
    art = []
    for p in _v68_candidate_files(['*v77*.json', '*v77*.csv', '*v77*.jsonl'], roots=[_v65_dir('measurements'), _v65_dir('outputs')], max_files=1000):
        pp = _V65Path(p)
        if not pp.exists() or pp.name.startswith('test'):
            continue
        obj = _v65_read_json(pp) if pp.suffix.lower() == '.json' else {}
        art.append({'artifact_key': pp.stem, 'path': str(pp), 'exists': True, 'size_bytes': pp.stat().st_size, 'sha256': _v65_sha256(pp), 'status': obj.get('status') if isinstance(obj, dict) else None})
    base['dashboard_v77'] = {
        'claim_policy': 'v77 implements all eight requested improvements as deeper source-recovery manifests with strict no-proxy promotion gates.',
        'no_manual_fill_policy': True,
        'interface_only': False,
        'nonSM_confirm_like': confirms,
        'SM_constant_consistency': sm,
        'coverage_confirmed': cov,
        'ready_or_compatible': ready,
        'blocked_or_gate_failed': blocked,
        'failed_gates': failed[:5400],
        'why_not_confirm_class_counts': dict(why),
        'artifact_index': art,
        'n_artifacts': len(art),
        'n_nonSM_confirm_like': len(confirms),
        'n_SM_constant_consistency': len(sm),
        'n_coverage_confirmed': len(cov),
        'n_blocked_or_gate_failed': len(blocked),
        'implemented_improvements_v77': [
            'P3 real endpoint source recovery',
            'PTA residual/postfit source manifest',
            'P30 Planck kappa-map sampler manifest',
            'P30 Euclid kappa-cell source manifest',
            'P32 second local strain event manifest',
            'P33 exact LSS/random source manifest',
            'P39/P1 Pantheon covariance source manifest',
            'P35 exact P(k)/xi source manifest',
        ],
    }
    base['status'] = 'dashboard_positive_current_only_v77'
    return base

RUNNERS.update({
    'dashboard_v22': run_dashboard_v77,
    'round10_dashboard': run_dashboard_v77,
    'p39_likelihood_gate_v22': run_p39_likelihood_gate_v77,
    'p30_maskrandom_freeze_v22': run_p30_publication_gate_v77,
    'planck_route_guard_v20': run_planck_route_guard_v77,
    'euclid_mer_catalogue_only_v13': run_euclid_route_guard_v77,
    'p33_density_bao_measured_scaffold_v22': run_p33_density_bao_measurement_gate_v77,
    'harmonic_comb_proxy': run_harmonic_comb_proxy_v77,
    'p3_exact_metadata_v21': run_p3_exact_metadata_v77,
    'ringdown_strain_plan_v22': run_ringdown_strain_gate_v77,
    'cl2_weighted_parse_v21': run_cl2_pta_density_gate_v77,
    'pta_density_cross_v22': run_cl2_pta_density_gate_v77,
})

# ============================================================================
# ROUND-10 v78 archive-aware confirm-recovery implementation layer
# Scope: implement the eight requested follow-up improvements with deeper
# archive/member parsers while preserving strict no-proxy promotion gates.
# ============================================================================

_V78_VERSION = 'v78'

_run_cl2_for_v78 = RUNNERS.get('cl2_weighted_parse_v21', run_cl2_pta_density_gate_v77)
_run_p33_for_v78 = RUNNERS.get('p33_density_bao_measured_scaffold_v22', run_p33_density_bao_measurement_gate_v77)
_run_p30_for_v78 = RUNNERS.get('p30_maskrandom_freeze_v22', run_p30_publication_gate_v77)
_run_planck_for_v78 = RUNNERS.get('planck_route_guard_v20', run_planck_route_guard_v77)
_run_euclid_for_v78 = RUNNERS.get('euclid_mer_catalogue_only_v13', run_euclid_route_guard_v77)
_run_p35_for_v78 = RUNNERS.get('harmonic_comb_proxy', run_harmonic_comb_proxy_v77)
_run_p3_for_v78 = RUNNERS.get('p3_exact_metadata_v21', run_p3_exact_metadata_v77)
_run_p32_for_v78 = RUNNERS.get('ringdown_strain_plan_v22', run_ringdown_strain_gate_v77)
_run_p39_for_v78 = RUNNERS.get('p39_likelihood_gate_v22', run_p39_likelihood_gate_v77)

def _v78_norm(x):
    return _v65_norm_col(x)

def _v78_gate(missing, **extra):
    g = {'gate_version': _V78_VERSION, 'eligible_for_confirm_like': not missing, 'missing': missing}
    g.update(extra)
    return g

def _v78_write_measurement(name, obj):
    out = _v65_dir('measurements') / name
    _v65_write_json(out, obj)
    return out

def _v78_write_output(name, obj):
    out = _v65_dir('outputs') / name
    _v65_write_json(out, obj)
    return out

def _v78_base_from_existing(test_id, meta, args, runner, fallback_status):
    existing = _v72_output_by_test_id(test_id)
    if isinstance(existing, dict) and existing:
        return dict(existing)
    try:
        return runner(meta, args)
    except Exception as e:
        b = base_result(meta, fallback_status)
        b['v78_base_runner_error'] = repr(e)[:500]
        return b

def _v78_tmp_member_path(archive_path, member_name, data):
    name = _V65Path(str(member_name).replace('\\', '/')).name or 'member.dat'
    safe = _v65_re.sub(r'[^A-Za-z0-9_.-]+', '_', name)[:120]
    h = _v65_hashlib.sha1((str(archive_path) + '|' + str(member_name)).encode('utf-8', 'replace')).hexdigest()[:16]
    out = _V65Path.cwd() / '.ccdr_round10_cache' / ('v78_member_' + h + '_' + safe)
    out.parent.mkdir(parents=True, exist_ok=True)
    if not out.exists() or out.stat().st_size != len(data):
        out.write_bytes(data)
    return out

def _v78_member_token_match(name, tokens):
    low = str(name).lower()
    return any(str(t).lower() in low for t in tokens)

def _v78_iter_archive_members(path, tokens, max_members=1200, max_bytes=80_000_000, suffixes=None):
    p = _V65Path(path)
    suffixes = suffixes or ('.fits', '.fit', '.fits.gz', '.fit.gz', '.csv', '.tsv', '.txt', '.dat', '.dat.gz', '.txt.gz', '.json')
    out = []
    try:
        if zipfile.is_zipfile(str(p)):
            with zipfile.ZipFile(str(p)) as zf:
                for info in zf.infolist()[:max_members]:
                    nm = info.filename
                    low = nm.lower()
                    if info.is_dir() or info.file_size <= 0 or info.file_size > max_bytes:
                        continue
                    if not low.endswith(tuple(suffixes)):
                        continue
                    if not _v78_member_token_match(nm, tokens):
                        continue
                    data = zf.read(info)
                    tmp = _v78_tmp_member_path(p, nm, data)
                    out.append({'archive_path': str(p), 'member_name': nm, 'member_size': info.file_size, 'path': tmp})
        elif _v65_tarfile.is_tarfile(str(p)):
            with _v65_tarfile.open(str(p), 'r:*') as tf:
                for m in tf.getmembers()[:max_members]:
                    nm = m.name
                    low = nm.lower()
                    if not m.isfile() or m.size <= 0 or m.size > max_bytes:
                        continue
                    if not low.endswith(tuple(suffixes)):
                        continue
                    if not _v78_member_token_match(nm, tokens):
                        continue
                    fh = tf.extractfile(m)
                    if not fh:
                        continue
                    data = fh.read()
                    tmp = _v78_tmp_member_path(p, nm, data)
                    out.append({'archive_path': str(p), 'member_name': nm, 'member_size': m.size, 'path': tmp})
    except Exception as e:
        out.append({'archive_path': str(p), 'archive_error': repr(e)[:300]})
    return out

def _v78_read_text(path, max_bytes=12_000_000):
    p = _V65Path(path)
    try:
        if str(p).lower().endswith('.gz'):
            with _v65_gzip.open(p, 'rt', encoding='utf-8', errors='replace') as fh:
                return fh.read(max_bytes)
        with p.open('r', encoding='utf-8', errors='replace') as fh:
            return fh.read(max_bytes)
    except Exception:
        return ''

def _v78_parse_delimited_text(text, source, raw_path, max_rows=100000):
    lines = []
    for ln in str(text or '').splitlines():
        s = ln.strip()
        if not s or s.startswith('#') or s.startswith('---'):
            continue
        lines.append(ln)
    if not lines:
        return [], {'source': source, 'path': str(raw_path), 'n_rows': 0, 'reason': 'no_data_lines'}
    header_idx = None
    for i, ln in enumerate(lines[:80]):
        toks = [t for t in _v65_re.split(r'[,;\t ]+', ln.strip()) if t]
        if len(toks) >= 2 and sum(bool(_v65_re.search(r'[A-Za-z]', t)) for t in toks) >= 2:
            header_idx = i
            break
    if header_idx is None:
        return [], {'source': source, 'path': str(raw_path), 'n_rows': 0, 'reason': 'header_not_found'}
    header_line = lines[header_idx]
    if '\t' in header_line:
        delim = '\t'
    elif ',' in header_line:
        delim = ','
    elif ';' in header_line:
        delim = ';'
    else:
        delim = None
    rows = []
    try:
        if delim:
            rdr = _v65_csv.DictReader(_v65_io.StringIO('\n'.join(lines[header_idx:])), delimiter=delim)
            for j, d in enumerate(rdr):
                if j >= max_rows:
                    break
                if d:
                    rows.append(dict(d))
        else:
            header = _v65_re.split(r'\s+', header_line.strip())
            for ln in lines[header_idx + 1:header_idx + 1 + max_rows]:
                vals = _v65_re.split(r'\s+', ln.strip())
                if len(vals) < max(2, len(header) // 2):
                    continue
                rows.append({header[j]: vals[j] if j < len(vals) else '' for j in range(len(header))})
    except Exception as e:
        return [], {'source': source, 'path': str(raw_path), 'n_rows': 0, 'error': repr(e)[:250]}
    return rows, {'source': source, 'path': str(raw_path), 'n_rows': len(rows), 'sha256': _v65_sha256(raw_path) if raw_path else None}

def _v78_parse_table_any(path, source, max_rows=100000):
    p = _V65Path(path)
    low = str(p).lower()
    if low.endswith(('.fits', '.fit', '.fits.gz', '.fit.gz')):
        return _v65_parse_fits_table(p, source, max_rows=max_rows)
    text = _v78_read_text(p, max_bytes=30_000_000)
    rows, info = _v78_parse_delimited_text(text, source, p, max_rows=max_rows)
    if not rows:
        rows, info2 = _v65_parse_tsv_text(text, source, p, max_rows=max_rows)
        if rows:
            info = info2
    return rows, info

def _v78_table_sources(paths, tokens, max_files=160, max_members=1200, max_rows=100000, max_member_bytes=80_000_000):
    for p in paths[:max_files]:
        pp = _V65Path(p)
        low = str(pp).lower()
        if not pp.exists() or not pp.is_file():
            yield [], {'path': str(pp), 'exists': pp.exists(), 'error': 'missing_or_not_file'}
            continue
        if zipfile.is_zipfile(str(pp)) or _v65_tarfile.is_tarfile(str(pp)):
            members = _v78_iter_archive_members(pp, tokens, max_members=max_members, max_bytes=max_member_bytes)
            if not members:
                yield [], _v73_file_digest_record(pp, {'archive_scanned': True, 'n_matching_members': 0})
            for m in members:
                if m.get('archive_error'):
                    yield [], m
                    continue
                rows, info = _v78_parse_table_any(m['path'], str(m.get('member_name')), max_rows=max_rows)
                info.update({'archive_path': m.get('archive_path'), 'archive_member': m.get('member_name'), 'member_size': m.get('member_size')})
                yield rows, info
        elif _v78_member_token_match(low, tokens):
            rows, info = _v78_parse_table_any(pp, str(pp.name), max_rows=max_rows)
            yield rows, info

def _v78_pick(norm, candidates):
    for c in candidates:
        cc = _v78_norm(c)
        if cc in norm:
            return norm[cc]
    for key, val in norm.items():
        if any(_v78_norm(c) in key for c in candidates):
            return val
    return None

def _v78_residual_kappa_stat(pairs):
    if not pairs:
        return {'n_pairs': 0, 'weighted_statistic': None, 'public_one_sided_signed_sky_shuffle_p': None, 'top_weight_removal_stable': False}
    denom = sum(abs(x.get('weight') or 1.0) for x in pairs) or 1.0
    stat = sum((x.get('residual') or 0.0) * (x.get('kappa') or 0.0) * (x.get('weight') or 1.0) for x in pairs) / denom
    rng = _v65_random.Random(78)
    resids = [x.get('residual') or 0.0 for x in pairs]
    kappas0 = [x.get('kappa') or 0.0 for x in pairs]
    weights = [x.get('weight') or 1.0 for x in pairs]
    null = []
    for _ in range(256):
        kappas = list(kappas0)
        rng.shuffle(kappas)
        null.append(sum(a * b * w for a, b, w in zip(resids, kappas, weights)) / denom)
    pval = sum(1 for x in null if x >= stat) / len(null)
    ranked = sorted(pairs, key=lambda x: abs((x.get('residual') or 0) * (x.get('kappa') or 0) * (x.get('weight') or 1.0)), reverse=True)
    keep = ranked[1:] if len(ranked) > 3 else ranked
    stable = False
    if keep:
        den2 = sum(abs(x.get('weight') or 1.0) for x in keep) or 1.0
        stat2 = sum((x.get('residual') or 0.0) * (x.get('kappa') or 0.0) * (x.get('weight') or 1.0) for x in keep) / den2
        stable = bool(stat * stat2 > 0 and abs(stat2) >= 0.25 * abs(stat))
    return {'n_pairs': len(pairs), 'weighted_statistic': stat, 'public_one_sided_signed_sky_shuffle_p': pval, 'top_weight_removal_stable': stable}

def _v78_pta_residual_kappa_join_artifact():
    v77 = _v65_read_json(_v65_dir('measurements') / 'pta_residual_source_manifest_v77_AUTO_PUBLIC.json') or {}
    paths = _v73_public_candidate_files(['*resid*', '*residual*', '*postfit*', '*prefit*', '*kappa*', '*nanograv*', '*15yr*', '*pta*'], max_files=1800)
    residuals, kappas, pairs, audit = {}, {}, [], []
    for rows, info in _v78_table_sources(paths, ['resid', 'residual', 'postfit', 'prefit', 'kappa', 'pta', 'nanograv'], max_files=170, max_members=2200, max_rows=50000, max_member_bytes=60_000_000):
        n_res = n_kap = n_pair = 0
        for r in rows[:50000]:
            if not isinstance(r, dict):
                continue
            norm = {_v78_norm(k): k for k in r.keys()}
            idc = _v78_pick(norm, ['pulsar_id', 'pulsar', 'psrj', 'psr', 'name', 'jname'])
            resc = _v78_pick(norm, ['residual', 'timing_residual', 'toa_residual', 'postfit', 'post_fit', 'prefit', 'resid'])
            kapc = _v78_pick(norm, ['kappa', 'kappa_sample', 'kappa_act', 'kappa_planck', 'convergence'])
            wc = _v78_pick(norm, ['weight', 'toa_weight', 'noise_weight', 'w'])
            pid = str(r.get(idc) or '').strip() if idc else ''
            pid_norm = _v78_norm(pid)
            res = _v65_float(r.get(resc)) if resc else None
            kap = _v65_float(r.get(kapc)) if kapc else None
            w = _v65_float(r.get(wc)) if wc else 1.0
            if pid_norm and res is not None:
                residuals.setdefault(pid_norm, []).append({'pulsar_id': pid, 'residual': res, 'weight': w or 1.0, 'source_path': info.get('path'), 'archive_member': info.get('archive_member')})
                n_res += 1
            if pid_norm and kap is not None:
                kappas.setdefault(pid_norm, []).append({'pulsar_id': pid, 'kappa': kap, 'source_path': info.get('path'), 'archive_member': info.get('archive_member')})
                n_kap += 1
            if pid_norm and res is not None and kap is not None:
                pairs.append({'pulsar_id': pid, 'residual': res, 'kappa': kap, 'weight': w or 1.0, 'source_path': info.get('path'), 'archive_member': info.get('archive_member')})
                n_pair += 1
        audit.append({k: info.get(k) for k in ('path', 'archive_path', 'archive_member', 'n_rows', 'reason', 'error', 'sha256')} | {'n_residual_rows': n_res, 'n_kappa_rows': n_kap, 'n_direct_pairs': n_pair})
    if not pairs:
        for pid in sorted(set(residuals) & set(kappas)):
            for rr in residuals[pid][:3]:
                for kk in kappas[pid][:3]:
                    pairs.append({'pulsar_id': rr.get('pulsar_id'), 'residual': rr.get('residual'), 'kappa': kk.get('kappa'), 'weight': rr.get('weight') or 1.0, 'residual_source': rr.get('source_path'), 'kappa_source': kk.get('source_path'), 'join_mode': 'pulsar_id_cross_table_v78'})
                    if len(pairs) >= 20000:
                        break
                if len(pairs) >= 20000:
                    break
            if len(pairs) >= 20000:
                break
    stat = _v78_residual_kappa_stat(pairs)
    if len(pairs) >= 20:
        status = 'pta_residual_kappa_pairs_joined_v78'
    elif residuals or kappas:
        status = 'pta_residual_and_kappa_sources_unpaired_v78'
    elif (v77.get('n_residual_named_members') or 0) > 0:
        status = 'pta_residual_named_members_unparsed_v78'
    else:
        status = 'pta_residual_kappa_sources_absent_v78'
    row = {
        'artifact_version': _V78_VERSION,
        'status': status,
        'n_residual_rows': sum(len(v) for v in residuals.values()),
        'n_kappa_rows': sum(len(v) for v in kappas.values()),
        'n_residual_pulsars': len(residuals),
        'n_kappa_pulsars': len(kappas),
        'n_joined_residual_kappa_pairs': len(pairs),
        'n_residual_named_members_v77': v77.get('n_residual_named_members'),
        'statistic': stat,
        'pairs_preview': pairs[:60],
        'source_audit': audit[:180],
        'manual_fill_required': False,
        'claim_policy_v78': 'v78 parses residual/postfit archive members and joins residual rows to kappa rows by normalized pulsar id. TOA rows or residual filenames alone cannot confirm.',
    }
    return row

def run_cl2_pta_density_gate_v78(meta, args):
    base = _v78_base_from_existing('R10-T17', meta, args, _run_cl2_for_v78, 'pta_weighted_kappa_residual_required_v77')
    row = _v78_pta_residual_kappa_join_artifact()
    out = _v78_write_measurement('pta_residual_kappa_join_v78_AUTO_PUBLIC.json', row)
    stat = row.get('statistic') or {}
    missing = []
    if (row.get('n_joined_residual_kappa_pairs') or 0) < 20:
        missing.append('public_residual_kappa_pairs_ge_20')
    if _v65_float(stat.get('weighted_statistic')) is None or (_v65_float(stat.get('weighted_statistic')) or 0) <= 0:
        missing.append('positive_public_weighted_statistic')
    p_signed = _v65_float(stat.get('public_one_sided_signed_sky_shuffle_p'))
    if p_signed is None or p_signed > 0.05:
        missing.append('public_one_sided_signed_sky_shuffle_p_le_0p05')
    if not stat.get('top_weight_removal_stable'):
        missing.append('public_top_weight_removal_stable')
    base['pta_residual_kappa_join_v78'] = row
    base['pta_residual_kappa_join_gate_v78'] = _v78_gate(missing, artifact_path=str(out), diagnostic_class=row['status'])
    base['status'] = 'pta_weighted_kappa_residual_confirm_like_v78' if not missing else 'pta_weighted_kappa_residual_required_v78'
    return base

def _v78_fits_probe(path):
    p = _V65Path(path)
    rec = _v73_file_digest_record(p)
    try:
        head = b''
        if str(p).lower().endswith('.gz'):
            with _v65_gzip.open(p, 'rb') as fh:
                head = fh.read(80)
        else:
            with p.open('rb') as fh:
                head = fh.read(80)
        rec['fits_magic'] = head.startswith(b'SIMPLE')
    except Exception as e:
        rec['head_error'] = repr(e)[:200]
    try:
        from astropy.io import fits
        import numpy as np
        with fits.open(p, memmap=True) as hdul:
            hdu_recs = []
            n_pix = 0
            for i, h in enumerate(hdul[:8]):
                hr = {'hdu': i, 'name': getattr(h, 'name', ''), 'class': h.__class__.__name__}
                data = getattr(h, 'data', None)
                try:
                    if data is not None and hasattr(data, 'shape'):
                        hr['shape'] = list(data.shape)
                        if len(data.shape) >= 1:
                            n_pix = max(n_pix, int(data.shape[0]))
                    if getattr(h, 'columns', None) is not None:
                        hr['columns'] = [str(c) for c in h.columns.names[:80]]
                        try:
                            n_pix = max(n_pix, int(len(data)))
                        except Exception:
                            pass
                except Exception as e:
                    hr['probe_error'] = repr(e)[:160]
                hdu_recs.append(hr)
            rec['fits_opened'] = True
            rec['fits_hdus'] = hdu_recs
            rec['n_image_or_table_rows'] = n_pix
            rec['healpix_like'] = bool(n_pix > 0 and any(n_pix == 12 * n * n for n in (64, 128, 256, 512, 1024, 2048)))
    except Exception as e:
        rec['fits_opened'] = False
        rec['fits_error'] = repr(e)[:300]
    return rec

def _v78_planck_map_sampler_artifact():
    v77 = _v65_read_json(_v65_dir('measurements') / 'p30_planck_map_sampler_manifest_v77_AUTO_PUBLIC.json') or {}
    paths = _v73_public_candidate_files(['*COM_Lensing*', '*planck*lensing*', '*lensing*map*', '*kappa*map*', '*kappa*.fits*', '*alm*'], max_files=1100)
    audit = []
    usable = []
    for p in paths[:160]:
        pp = _V65Path(p)
        low = str(pp).lower()
        if zipfile.is_zipfile(str(pp)) or _v65_tarfile.is_tarfile(str(pp)):
            members = _v78_iter_archive_members(pp, ['lensing', 'kappa', 'alm', 'map', 'COM_Lensing'], max_members=2500, max_bytes=120_000_000, suffixes=('.fits', '.fit', '.fits.gz', '.fit.gz'))
            if not members:
                audit.append(_v73_file_digest_record(pp, {'archive_scanned': True, 'n_fits_members': 0}))
            for m in members[:60]:
                if m.get('archive_error'):
                    audit.append(m)
                    continue
                rec = _v78_fits_probe(m['path'])
                rec.update({'archive_path': m.get('archive_path'), 'archive_member': m.get('member_name'), 'member_size': m.get('member_size')})
                rec['planck_lensing_scoped'] = bool(_v78_member_token_match(str(m.get('member_name')), ['planck', 'COM_Lensing', 'kappa', 'lensing', 'alm']))
                if rec.get('fits_opened') and rec.get('planck_lensing_scoped'):
                    usable.append(rec)
                audit.append(rec)
        elif any(tok in low for tok in ('planck', 'com_lensing', 'lensing', 'kappa', 'alm')) and low.endswith(('.fits', '.fit', '.fits.gz', '.fit.gz')):
            rec = _v78_fits_probe(pp)
            rec['planck_lensing_scoped'] = True
            if rec.get('fits_opened'):
                usable.append(rec)
            audit.append(rec)
    row = {
        'artifact_version': _V78_VERSION,
        'status': 'p30_planck_fits_map_or_alm_sources_ready_v78' if usable else 'p30_planck_claim_grade_map_sources_absent_v78',
        'n_usable_planck_fits_or_alm_sources': len(usable),
        'usable_planck_sources_preview': usable[:20],
        'v77_usable_fits_map_candidates': v77.get('usable_fits_map_candidates'),
        'v77_planck_map_level_candidates': v77.get('v76_planck_map_level_candidates'),
        'source_audit': audit[:180],
        'same_mask_density_kappa_statistic_available': False,
        'manual_fill_required': False,
        'claim_policy_v78': 'v78 detects FITS/ALM maps inside archives and gzip members. Confirmation still requires a same-mask density-kappa statistic and nulls, not just a readable map.',
    }
    return row

def _v78_extract_kappa_rows_from_rows(rows, info, max_out=100000):
    out = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        norm = {_v78_norm(k): k for k in r.keys()}
        rac = _v78_pick(norm, ['ra', 'ra_deg', 'raj2000', 'alpha'])
        decc = _v78_pick(norm, ['dec', 'dec_deg', 'dej2000', 'delta'])
        kapc = _v78_pick(norm, ['kappa', 'kappa_cell', 'kappa_sample', 'convergence', 'lens_kappa'])
        denc = _v78_pick(norm, ['density', 'overdensity', 'delta_g', 'n_gal', 'count'])
        if not kapc:
            continue
        ra = _v65_float(r.get(rac)) if rac else None
        dec = _v65_float(r.get(decc)) if decc else None
        kap = _v65_float(r.get(kapc))
        den = _v65_float(r.get(denc)) if denc else None
        if kap is not None and (ra is None or 0 <= ra <= 360) and (dec is None or -90 <= dec <= 90):
            out.append({'ra': ra, 'dec': dec, 'kappa': kap, 'density_proxy': den, 'source_path': info.get('path'), 'archive_member': info.get('archive_member')})
            if len(out) >= max_out:
                break
    return out

def _v78_density_kappa_split_stat(rows):
    usable = [r for r in rows if _v65_float(r.get('kappa')) is not None and _v65_float(r.get('density_proxy')) is not None]
    if len(usable) < 20:
        return {'n_rows_with_density_and_kappa': len(usable), 'delta_high_minus_low': None, 'density_shuffle_p_high': None}
    dens = sorted(_v65_float(r.get('density_proxy')) for r in usable)
    med = dens[len(dens) // 2]
    high = [_v65_float(r.get('kappa')) for r in usable if (_v65_float(r.get('density_proxy')) or 0) >= med]
    low = [_v65_float(r.get('kappa')) for r in usable if (_v65_float(r.get('density_proxy')) or 0) < med]
    if not high or not low:
        return {'n_rows_with_density_and_kappa': len(usable), 'delta_high_minus_low': None, 'density_shuffle_p_high': None}
    obs = sum(high) / len(high) - sum(low) / len(low)
    rng = _v65_random.Random(78)
    kappas = [_v65_float(r.get('kappa')) for r in usable]
    null = []
    nh = len(high)
    for _ in range(256):
        kk = list(kappas)
        rng.shuffle(kk)
        null.append(sum(kk[:nh]) / nh - sum(kk[nh:]) / max(1, len(kk) - nh))
    return {'n_rows_with_density_and_kappa': len(usable), 'density_median': med, 'delta_high_minus_low': obs, 'density_shuffle_p_high': sum(1 for x in null if x >= obs) / len(null)}

def _v78_euclid_kappa_cell_artifact():
    v77 = _v65_read_json(_v65_dir('measurements') / 'p30_euclid_kappa_sampler_manifest_v77_AUTO_PUBLIC.json') or {}
    paths = _v73_public_candidate_files(['*euclid*kappa*', '*kappa*cell*', '*density*kappa*', '*convergence*cell*', '*MER*kappa*', '*mer*kappa*'], max_files=1000)
    rows_all = []
    audit = []
    for rows, info in _v78_table_sources(paths, ['euclid', 'kappa', 'convergence', 'cell', 'density', 'MER', 'mer'], max_files=140, max_members=1800, max_rows=120000, max_member_bytes=80_000_000):
        krows = _v78_extract_kappa_rows_from_rows(rows, info, max_out=120000 - len(rows_all))
        rows_all.extend(krows)
        audit.append({k: info.get(k) for k in ('path', 'archive_path', 'archive_member', 'n_rows', 'reason', 'error', 'sha256')} | {'n_kappa_rows': len(krows)})
        if len(rows_all) >= 120000:
            break
    stat = _v78_density_kappa_split_stat(rows_all)
    row = {
        'artifact_version': _V78_VERSION,
        'status': 'p30_euclid_kappa_cells_ready_v78' if len(rows_all) >= 800 else 'p30_euclid_kappa_cells_absent_v78',
        'n_euclid_kappa_cell_rows': len(rows_all),
        'density_kappa_split_stat': stat,
        'rows_preview': rows_all[:60],
        'v77_euclid_kappa_cell_rows': v77.get('v76_euclid_kappa_cell_rows'),
        'source_audit': audit[:160],
        'manual_fill_required': False,
        'claim_policy_v78': 'v78 parses Euclid/MER kappa-cell tables from files and archive members. Confirmation requires kappa cells plus positive residualized density split and shuffle nulls.',
    }
    return row

def _v78_p30_route_artifact():
    v76 = _v65_read_json(_v65_dir('measurements') / 'p30_second_route_kappa_join_v76_AUTO_PUBLIC.json') or {}
    planck = _v78_planck_map_sampler_artifact()
    euclid = _v78_euclid_kappa_cell_artifact()
    stat = euclid.get('density_kappa_split_stat') or {}
    planck_confirm = False
    euclid_confirm = bool(
        (euclid.get('n_euclid_kappa_cell_rows') or 0) >= 800
        and (_v65_float(stat.get('delta_high_minus_low')) or 0) > 0
        and _v65_float(stat.get('density_shuffle_p_high')) is not None
        and (_v65_float(stat.get('density_shuffle_p_high')) or 1) <= 0.05
    )
    sdss = bool(v76.get('sdss_scoped_confirm_like'))
    row = {
        'artifact_version': _V78_VERSION,
        'status': 'p30_global_second_route_confirmed_v78' if sdss and (planck_confirm or euclid_confirm) else 'p30_second_route_still_not_confirmed_v78',
        'sdss_scoped_confirm_like': sdss,
        'planck_route_confirm_like': planck_confirm,
        'euclid_route_confirm_like': euclid_confirm,
        'second_independent_route_confirm_like': bool(planck_confirm or euclid_confirm),
        'n_routes_confirm_like': int(sdss) + int(planck_confirm or euclid_confirm),
        'planck_map_sampler_v78': {k: planck.get(k) for k in ('status', 'n_usable_planck_fits_or_alm_sources', 'same_mask_density_kappa_statistic_available')},
        'euclid_kappa_cell_v78': {k: euclid.get(k) for k in ('status', 'n_euclid_kappa_cell_rows', 'density_kappa_split_stat')},
        'manual_fill_required': False,
        'claim_policy_v78': 'v78 global P30 requires the existing SDSS route plus an independent Planck or Euclid route with same-mask/null evidence.',
    }
    return row, planck, euclid

