def _v78_json_walk(obj):
    stack = [obj]
    while stack:
        cur = stack.pop()
        if isinstance(cur, dict):
            yield cur
            stack.extend(cur.values())
        elif isinstance(cur, list):
            stack.extend(cur)

def _v78_p32_second_event_resolver_artifact():
    v77 = _v65_read_json(_v65_dir('measurements') / 'p32_second_event_source_manifest_v77_AUTO_PUBLIC.json') or {}
    paths = _v73_public_candidate_files(['*eventapi*', '*GWOSC*', '*strain*', '*GW*.hdf5', '*GW*.gwf', '*GW*.txt.gz', '*GW*.json'], max_files=2600)
    local = set()
    eventapi = {}
    resolved_from_url = set()
    audit = []
    all_local_paths = []
    for p in paths[:520]:
        pp = _V65Path(p)
        low = str(pp).lower()
        ids = set(m.upper() for m in _v65_re.findall(r'GW\d{6}', str(pp), _v65_re.I))
        if any(tok in low for tok in ('.hdf5', '.gwf', '.txt.gz', 'strain')) and ids:
            local.update(ids)
            all_local_paths.append(str(pp))
        rec = _v73_file_digest_record(pp, {'event_ids_in_name': sorted(ids)})
        if pp.exists() and ('eventapi' in low or low.endswith('.json')) and pp.stat().st_size < 100_000_000:
            try:
                obj = _v65_json.loads(pp.read_text(encoding='utf-8', errors='replace'))
                for d in _v78_json_walk(obj):
                    cname = str(d.get('commonName') or d.get('event') or d.get('id') or '')
                    m = _v65_re.search(r'GW\d{6}', cname, _v65_re.I)
                    eid = m.group(0).upper() if m else None
                    urls = []
                    for val in d.values():
                        if isinstance(val, str) and ('http' in val or 'GWOSC' in val or 'gwosc' in val):
                            urls.extend(_v65_re.findall(r'https?://[^\\s"\']+', val))
                        elif isinstance(val, list):
                            for item in val:
                                if isinstance(item, str):
                                    urls.extend(_v65_re.findall(r'https?://[^\\s"\']+', item))
                                elif isinstance(item, dict):
                                    u = item.get('url') or item.get('download_url') or item.get('href')
                                    if u:
                                        urls.append(str(u))
                    strain_urls = [u for u in urls if _v65_re.search(r'(?i)(strain|gwosc|\\.hdf5|\\.gwf|\\.txt\\.gz)', u)]
                    if eid and strain_urls:
                        eventapi.setdefault(eid, {'urls': [], 'detectors': set()})
                        eventapi[eid]['urls'].extend(strain_urls[:20])
                        for u in strain_urls:
                            if 'H1' in u:
                                eventapi[eid]['detectors'].add('H1')
                            if 'L1' in u:
                                eventapi[eid]['detectors'].add('L1')
                rec['eventapi_events_with_urls'] = len(eventapi)
            except Exception as e:
                rec['eventapi_parse_error'] = repr(e)[:250]
        audit.append(rec)
    local_names = [str(x).lower() for x in all_local_paths]
    for eid, v in eventapi.items():
        for u in v.get('urls', [])[:30]:
            tail = _V65Path(str(u).split('?')[0].rstrip('/')).name.lower()
            if tail and any(tail in name for name in local_names):
                resolved_from_url.add(eid)
    eventapi_norm = {k: {'n_strain_urls': len(v.get('urls') or []), 'detectors': sorted(v.get('detectors') or []), 'urls_preview': (v.get('urls') or [])[:8], 'locally_resolved_from_url': k in resolved_from_url} for k, v in eventapi.items()}
    local_effective = sorted(local | resolved_from_url)
    row = {
        'artifact_version': _V78_VERSION,
        'status': 'p32_multi_event_local_strain_ready_v78' if len(local_effective) >= 2 else ('p32_eventapi_second_event_urls_ready_not_local_v78' if len(eventapi) >= 2 else 'p32_second_local_strain_still_absent_v78'),
        'local_strain_event_ids': sorted(local),
        'eventapi_strain_event_ids': sorted(eventapi),
        'url_resolved_local_event_ids': sorted(resolved_from_url),
        'effective_local_strain_event_ids': local_effective,
        'n_local_strain_events': len(local_effective),
        'n_eventapi_strain_events': len(eventapi),
        'eventapi_strain_index_preview': {k: eventapi_norm[k] for k in sorted(eventapi_norm)[:20]},
        'v77_local_strain_event_ids': v77.get('local_strain_event_ids'),
        'source_audit': audit[:180],
        'manual_fill_required': False,
        'claim_policy_v78': 'v78 extracts nested GWOSC/eventapi strain URLs and resolves them against local cache names. URLs alone are readiness; confirm requires local strain and likelihood/null gates.',
    }
    return row

def run_ringdown_strain_gate_v78(meta, args):
    base = _v78_base_from_existing('R10-T19', meta, args, _run_p32_for_v78, 'ringdown_strain_analysis_required_v77')
