def _v78_numeric_total(path, max_lines=200000):
    p = _V65Path(path)
    text = _v78_read_text(p, max_bytes=60_000_000)
    total = 0
    nlines = 0
    max_cols = 0
    for ln in text.splitlines():
        nums = _v65_re.findall(r'[-+]?(?:\d+\.\d*|\.\d+|\d+)(?:[eE][-+]?\d+)?', ln)
        if nums:
            total += len(nums)
            nlines += 1
            max_cols = max(max_cols, len(nums))
        if nlines >= max_lines:
            break
    return {'sample_numeric_values': total, 'sample_numeric_rows': nlines, 'sample_max_numeric_cols': max_cols}

def _v78_p39_covariance_vector_artifact(base=None):
    base = base or {}
    v77 = _v65_read_json(_v65_dir('measurements') / 'p39_covariance_source_manifest_v77_AUTO_PUBLIC.json') or {}
    diag_rows = int(v77.get('pantheon_diag_rows') or 0)
    paths = _v73_public_candidate_files(['*Pantheon*cov*', '*Pantheon*sys*', '*Pantheon*systematic*', '*SH0ES*cov*', '*SH0ES*sys*', '*pantheon*cov*', '*pantheon*sys*'], max_files=900)
    audit = []
    full = []
    systematics = []
    for p in paths[:160]:
        pp = _V65Path(p)
        low = str(pp).lower()
        rec = _v74_numeric_shape(pp, max_rows=25000)
        rec.update(_v78_numeric_total(pp, max_lines=250000))
        rec['pantheon_scoped'] = bool('pantheon' in low or 'sh0es' in low)
        rec['systematics_scoped'] = bool('sys' in low or 'systematic' in low)
        tri = diag_rows * (diag_rows + 1) // 2 if diag_rows else None
        sq = diag_rows * diag_rows if diag_rows else None
        sample_total = rec.get('sample_numeric_values') or 0
        matrix_like = bool((rec.get('max_numeric_cols') or 0) >= 20 and (rec.get('n_numeric_rows') or 0) >= 20)
        vector_like = bool(diag_rows and sample_total in {tri, sq})
        rec['flattened_covariance_vector_candidate'] = vector_like
        rec['matrix_covariance_candidate'] = matrix_like
        rec['full_covariance_candidate'] = bool(rec['pantheon_scoped'] and (vector_like or matrix_like) and ('cov' in low or rec['systematics_scoped']))
        if rec['full_covariance_candidate']:
            full.append(rec)
        if rec['pantheon_scoped'] and rec['systematics_scoped']:
            systematics.append(rec)
        audit.append(rec)
    delta = _v65_float(v77.get('delta_chi2_lcdm_minus_best') or base.get('delta_chi2_lcdm_minus_best'))
    n_obs = max(1, diag_rows + 8)
    delta_aic = 2 - (delta or 0)
    delta_bic = _v65_math.log(n_obs) - (delta or 0)
    row = {
        'artifact_version': _V78_VERSION,
        'status': 'p39_pantheon_covariance_vector_ready_v78' if full else 'p39_pantheon_covariance_vector_absent_v78',
        'pantheon_diag_rows': diag_rows,
        'pantheon_full_covariance_used': bool(full),
        'pantheon_covariance_candidates': full[:30],
        'pantheon_systematics_candidates': systematics[:30],
        'bao_full_covariance_used': bool(v77.get('bao_full_covariance_used')),
        'delta_chi2_lcdm_minus_best': delta,
        'delta_AIC_new_minus_LCDM': delta_aic,
        'delta_BIC_new_minus_LCDM': delta_bic,
        'model_penalty_supports_new_model': bool(delta is not None and delta >= 9 and delta_aic < 0 and delta_bic < 0),
        'systematics_splits_done': bool(full and systematics and delta is not None and delta >= 9),
        'source_audit': audit[:160],
        'manual_fill_required': False,
        'claim_policy_v78': 'v78 recognizes Pantheon covariance as either a matrix or flattened N*N / N(N+1)/2 vector. DESI/BAO covariance cannot substitute for Pantheon covariance.',
    }
    return row

def run_p39_likelihood_gate_v78(meta, args):
    base = _v78_base_from_existing(str(meta.get('test_id') or ''), meta, args, _run_p39_for_v78, 'positive_compatible')
    row = _v78_p39_covariance_vector_artifact(base)
    out = _v78_write_measurement('p39_pantheon_covariance_vector_v78_AUTO_PUBLIC.json', row)
