# ============================================================================
# ROUND-10 v79 measurement-recovery implementation layer
# Scope: implement the eight requested improvements after v78, with special
# attention to turning recovered map/table sources into measured diagnostics
# while keeping route independence and confirm gates strict.
# ============================================================================

_V79_VERSION = 'v79'

_run_cl2_for_v79 = RUNNERS.get('cl2_weighted_parse_v21', run_cl2_pta_density_gate_v78)
_run_p33_for_v79 = RUNNERS.get('p33_density_bao_measured_scaffold_v22', run_p33_density_bao_measurement_gate_v78)
_run_p30_for_v79 = RUNNERS.get('p30_maskrandom_freeze_v22', run_p30_publication_gate_v78)
_run_planck_for_v79 = RUNNERS.get('planck_route_guard_v20', run_planck_route_guard_v78)
_run_euclid_for_v79 = RUNNERS.get('euclid_mer_catalogue_only_v13', run_euclid_route_guard_v78)
_run_p35_for_v79 = RUNNERS.get('harmonic_comb_proxy', run_harmonic_comb_proxy_v78)
_run_p3_for_v79 = RUNNERS.get('p3_exact_metadata_v21', run_p3_exact_metadata_v78)
_run_p32_for_v79 = RUNNERS.get('ringdown_strain_plan_v22', run_ringdown_strain_gate_v78)
_run_p39_for_v79 = RUNNERS.get('p39_likelihood_gate_v22', run_p39_likelihood_gate_v78)

def _v79_gate(missing, **extra):
    g = {'gate_version': _V79_VERSION, 'eligible_for_confirm_like': not missing, 'missing': missing}
    g.update(extra)
    return g

def _v79_p_le(value, threshold=0.05):
    p = _v65_float(value)
    return p is not None and p <= threshold

def _v79_write_measurement(name, obj):
    out = _v65_dir('measurements') / name
    _v65_write_json(out, obj)
    return out

def _v79_write_output(name, obj):
    out = _v65_dir('outputs') / name
    _v65_write_json(out, obj)
    return out

def _v79_base_from_existing(test_id, meta, args, runner, fallback_status):
    existing = _v72_output_by_test_id(test_id)
    if isinstance(existing, dict) and existing:
        return dict(existing)
    try:
        return runner(meta, args)
    except Exception as e:
        b = base_result(meta, fallback_status)
        b['v79_base_runner_error'] = repr(e)[:500]
        return b

def _v79_source_scope(path):
    s = str(path or '').lower()
    if 'planck' in s or 'com_lensing' in s:
        return 'planck'
    if 'act' in s or 'dr6' in s:
        return 'act'
    if 'euclid' in s or 'mer_catalogue' in s:
        return 'euclid'
    return 'unknown'

def _v79_cached_sdss_coords(max_rows=2000):
    paths = list((_V65Path.cwd() / '.ccdr_round10_cache').glob('R10-T04_sdss_coords*'))
    rows = []
    chosen = None
    for p in sorted(paths, key=lambda x: x.stat().st_size if x.exists() else 0, reverse=True):
        try:
            rows = _v13_parse_csv_coords(p, max_rows=max_rows)
            if rows:
                chosen = p
                break
        except Exception:
            pass
    return rows[:max_rows], str(chosen) if chosen else None

def _v79_euclid_coords(max_rows=2000):
    t06 = _v72_output_by_test_id('R10-T06')
    path = (((t06 or {}).get('mer_catalogue_selected_v13') or {}).get('sample_path'))
    if path:
        p = _V65Path(path)
        if not p.is_absolute():
            p = _V65Path.cwd() / p
        try:
            rows = _v13_parse_csv_coords(p, max_rows=max_rows)
            if rows:
                return rows[:max_rows], str(p)
        except Exception:
            pass
    rows = []
    for r in (t06.get('mer_catalogue_sample_preview_v13') or []) if isinstance(t06, dict) else []:
        ra, dec = _v65_float(r.get('ra')), _v65_float(r.get('dec'))
        if ra is not None and dec is not None:
            rows.append({'ra': ra, 'dec': dec})
    return rows[:max_rows], 'outputs/test06_preview'

def _v79_load_map_from_fits_or_alm(path, args, nside=64):
    p = _V65Path(path)
    info = {'path': str(p), 'source_scope': _v79_source_scope(p)}
    try:
        m, inf = _v15_act_alm_to_map_all_modes(str(p), args, nside=nside)
        info.update(inf or {})
        info['load_mode'] = 'alm_to_map_or_healpy_read_alm'
        if m is not None:
            info['map_sanity'] = _v13_map_sanity(m)
            return m, info
    except Exception as e:
        info.setdefault('attempts', []).append({'mode': 'alm_to_map', 'error': repr(e)[:260]})
    try:
        import healpy as hp
        m = hp.read_map(str(p), verbose=False)
        info['load_mode'] = 'healpy_read_map'
        info['map_sanity'] = _v13_map_sanity(m)
        return m, info
    except Exception as e:
        info['read_map_error'] = repr(e)[:260]
    return None, info

def _v79_planck_same_mask_sampler_artifact(args):
    v78 = _v65_read_json(_v65_dir('measurements') / 'p30_planck_archive_map_sampler_v78_AUTO_PUBLIC.json') or {}
    sources = v78.get('usable_planck_sources_preview') or []
    source_records = []
    stat = None
    chosen = None
    catalogue, cat_path = _v79_cached_sdss_coords(max_rows=2000)
    for rec in sources[:8]:
        path = rec.get('path')
        if not path or not _V65Path(path).exists():
            source_records.append({'path': path, 'error': 'missing'})
            continue
        m, info = _v79_load_map_from_fits_or_alm(path, args, nside=64)
        if m is None:
            source_records.append(info)
            continue
        if catalogue:
            st = _v13_density_stat_with_footprint(m, catalogue, args, density_nside=32)
            info['sdss_same_mask_statistic'] = st
            if stat is None or ((st.get('delta_high_minus_low') or -999) > (stat.get('delta_high_minus_low') or -999)):
                stat = st
                chosen = info
        source_records.append(info)
        # One successful low-nside map is enough for deterministic v79 diagnostics.
        if stat and stat.get('n', 0) >= 20:
            break
    scope = (chosen or {}).get('source_scope')
    stat_confirm = bool(
        stat
        and (stat.get('delta_high_minus_low') or 0) > 0
        and _v65_float(stat.get('sky_shuffle_p_high')) is not None
        and _v79_p_le(stat.get('sky_shuffle_p_high'))
        and _v65_float(stat.get('density_bin_shuffle_p_high')) is not None
        and _v79_p_le(stat.get('density_bin_shuffle_p_high'))
        and stat.get('jackknife_same_sign')
        and 'random finite' not in str(stat.get('footprint_note', ''))
    )
    planck_scoped = sum(1 for r in sources if _v79_source_scope(r.get('path') or r.get('archive_member')) == 'planck')
    act_scoped = sum(1 for r in sources if _v79_source_scope(r.get('path') or r.get('archive_member')) == 'act')
    row = {
        'artifact_version': _V79_VERSION,
        'status': 'p30_planck_same_mask_confirm_like_v79' if stat_confirm and scope == 'planck' else ('p30_act_map_same_mask_statistic_built_v79' if stat_confirm else 'p30_planck_same_mask_statistic_not_confirmed_v79'),
        'n_usable_map_sources_v78': len(sources),
        'n_planck_scoped_sources': planck_scoped,
        'n_act_scoped_sources': act_scoped,
        'catalogue_source': cat_path,
        'catalogue_n': len(catalogue),
        'chosen_map_source': chosen,
        'same_mask_density_kappa_statistic': stat,
        'same_mask_statistic_confirm_like': stat_confirm,
        'planck_route_confirm_like': bool(stat_confirm and scope == 'planck'),
        'act_route_statistic_ready': bool(stat_confirm and scope == 'act'),
        'source_audit': source_records[:20],
        'manual_fill_required': False,
        'claim_policy_v79': 'v79 actually reconstructs a low-nside map and samples cached SDSS coordinates. ACT-map statistics are reported as measured readiness, not as a Planck-independent route.',
    }
    return row

def _v79_sample_map_at_coords(map_row, coords, label, args):
    src = (((map_row or {}).get('chosen_map_source') or {}).get('path'))
    if not src:
        # Fall back to first ACT/Planck source when the chosen source was not persisted.
        v78 = _v65_read_json(_v65_dir('measurements') / 'p30_planck_archive_map_sampler_v78_AUTO_PUBLIC.json') or {}
        for rec in v78.get('usable_planck_sources_preview') or []:
            if rec.get('path'):
                src = rec.get('path')
                break
    if not src:
        return [], {'error': 'missing_map_source'}
    m, info = _v79_load_map_from_fits_or_alm(src, args, nside=64)
    if m is None:
        return [], info
    try:
        import healpy as hp
        import numpy as np
        ra = np.asarray([c['ra'] for c in coords], dtype=float)
        dec = np.asarray([c['dec'] for c in coords], dtype=float)
        th, ph = _v11_ra_dec_to_theta_phi(ra, dec)
        pix = hp.ang2pix(hp.get_nside(m), th, ph)
        arr = np.asarray(m, dtype=float)
        rows = []
        for c, px in zip(coords, pix):
            val = _v65_float(arr[int(px)])
            if val is not None:
                rows.append({'ra': c.get('ra'), 'dec': c.get('dec'), 'kappa': val, 'density_proxy': None, 'source': label, 'map_source': src})
        return rows, info
    except Exception as e:
        info['sample_error'] = repr(e)[:260]
        return [], info

def _v79_euclid_kappa_fallback_artifact(args):
    native = _v78_euclid_kappa_cell_artifact()
    map_row = _v79_planck_same_mask_sampler_artifact(args)
    coords, cpath = _v79_euclid_coords(max_rows=2000)
    rows, sample_info = _v79_sample_map_at_coords(map_row, coords, 'euclid_mer_cross_route_map_sample', args)
    # Add deterministic local-density proxy by coarse RA/Dec bins for readiness diagnostics.
    if rows:
        bins = {}
        for r in rows:
            key = (int((r['ra'] or 0) // 10), int(((r['dec'] or 90) + 90) // 10))
            bins[key] = bins.get(key, 0) + 1
        for r in rows:
            key = (int((r['ra'] or 0) // 10), int(((r['dec'] or 90) + 90) // 10))
            r['density_proxy'] = bins.get(key, 0)
    stat = _v78_density_kappa_split_stat(rows)
    row = {
        'artifact_version': _V79_VERSION,
        'status': 'p30_euclid_cross_route_kappa_cells_ready_v79' if len(rows) >= 800 else 'p30_euclid_kappa_cells_absent_v79',
        'native_euclid_status_v78': native.get('status'),
        'n_native_euclid_kappa_cell_rows': native.get('n_euclid_kappa_cell_rows'),
        'n_cross_route_kappa_cell_rows': len(rows),
        'coordinate_source': cpath,
        'map_sample_info': sample_info,
        'density_kappa_split_stat': stat,
        'rows_preview': rows[:60],
        'manual_fill_required': False,
        'claim_policy_v79': 'v79 builds a MER-coordinate kappa-cell fallback by sampling the public lensing map. This is cross-route readiness only; Euclid-native kappa is still required for Euclid route confirmation.',
    }
    return row

