def _v79_parse_residual_member_text(text, member_name):
    rows = []
    pid = None
    m = _v65_re.search(r'([BJ]\d{4}[+-]\d{2,4})', str(member_name))
    if m:
        pid = m.group(1)
    for ln in str(text or '').splitlines():
        if not ln.strip() or ln.lstrip().startswith('#'):
            continue
        vals = [_v65_float(x) for x in _v65_re.findall(r'[-+]?(?:\d+\.\d*|\.\d+|\d+)(?:[eE][-+]?\d+)?', ln)]
        vals = [x for x in vals if x is not None]
        if len(vals) >= 4:
            rows.append({'pulsar_id': pid, 'mjd': vals[0], 'frequency_mhz': vals[1], 'residual_us': vals[2], 'white_residual_us': vals[3], 'uncertainty_us': vals[4] if len(vals) > 4 else None, 'source_member': member_name})
    return rows

def _v79_pta_residual_rows_and_coords(max_members=900):
    paths = _v73_public_candidate_files(['*ng_full*', '*15yr*', '*nanograv*', '*PulsarTiming*'], max_files=80)
    residual_by_pid = {}
    coords_by_pid = {}
    audit = []
    for p in paths[:20]:
        pp = _V65Path(p)
        if not pp.exists() or not _v65_tarfile.is_tarfile(str(pp)):
            continue
        try:
            with _v65_tarfile.open(str(pp), 'r:*') as tf:
                nres = npar = 0
                for m in tf.getmembers()[:max_members * 4]:
                    if not m.isfile():
                        continue
                    low = m.name.lower()
                    if not (low.endswith('.res') or low.endswith('.par')):
                        continue
                    if nres + npar >= max_members:
                        break
                    fh = tf.extractfile(m)
                    if not fh:
                        continue
                    txt = fh.read(2_000_000).decode('utf-8', errors='replace')
                    if low.endswith('.par'):
                        c = _v73_parse_par_coords(txt)
                        if c and c.get('pulsar_id'):
                            coords_by_pid[_v78_norm(c['pulsar_id'])] = {**c, 'source_member': m.name}
                            npar += 1
                    elif low.endswith('.res'):
                        rr = _v79_parse_residual_member_text(txt, m.name)
                        if rr:
                            pid = _v78_norm(rr[0].get('pulsar_id'))
                            residual_by_pid.setdefault(pid, []).extend(rr[:20000])
                            nres += 1
                audit.append(_v73_file_digest_record(pp, {'n_residual_members_parsed': nres, 'n_par_members_parsed': npar}))
        except Exception as e:
            audit.append(_v73_file_digest_record(pp, {'parse_error': repr(e)[:260]}))
    return residual_by_pid, coords_by_pid, audit

def _v79_pta_residual_kappa_artifact(args):
    v78 = _v65_read_json(_v65_dir('measurements') / 'pta_residual_kappa_join_v78_AUTO_PUBLIC.json') or {}
    residual_by_pid, coords_by_pid, audit = _v79_pta_residual_rows_and_coords()
    map_row = _v79_planck_same_mask_sampler_artifact(args)
    map_src = (((map_row.get('chosen_map_source') or {}).get('path')))
    kmap = None
    map_info = {'error': 'no_map_source'}
    if map_src:
        kmap, map_info = _v79_load_map_from_fits_or_alm(map_src, args, nside=64)
    pairs = []
    if kmap is not None:
        try:
            import healpy as hp
            import numpy as np
            arr = np.asarray(kmap, dtype=float)
            for pid, rr in residual_by_pid.items():
                coord = coords_by_pid.get(pid)
                if not coord:
                    continue
                theta, phi = _v11_ra_dec_to_theta_phi(np.asarray([coord['ra']], dtype=float), np.asarray([coord['dec']], dtype=float))
                pix = int(hp.ang2pix(hp.get_nside(kmap), theta, phi)[0])
                kap = _v65_float(arr[pix])
                if kap is None:
                    continue
                vals = [_v65_float(x.get('white_residual_us')) for x in rr if _v65_float(x.get('white_residual_us')) is not None]
                if not vals:
                    vals = [_v65_float(x.get('residual_us')) for x in rr if _v65_float(x.get('residual_us')) is not None]
                if not vals:
                    continue
                med = sorted(vals)[len(vals)//2]
                unc = [_v65_float(x.get('uncertainty_us')) for x in rr if _v65_float(x.get('uncertainty_us')) is not None and (_v65_float(x.get('uncertainty_us')) or 0) > 0]
                w = 1.0 / ((sorted(unc)[len(unc)//2] if unc else 1.0) ** 2)
                pairs.append({'pulsar_id': coord.get('pulsar_id'), 'residual': med, 'kappa': kap, 'weight': w, 'n_residual_rows': len(rr), 'coord_member': coord.get('source_member'), 'map_source': map_src})
        except Exception as e:
            map_info['join_error'] = repr(e)[:300]
    stat = _v78_residual_kappa_stat(pairs)
    row = {
        'artifact_version': _V79_VERSION,
        'status': 'pta_residual_kappa_pairs_joined_v79' if len(pairs) >= 20 else 'pta_residual_kappa_pairs_still_incomplete_v79',
        'n_residual_members_v79': len(residual_by_pid),
        'n_residual_rows_v79': sum(len(v) for v in residual_by_pid.values()),
        'n_par_coordinates_v79': len(coords_by_pid),
        'n_joined_residual_kappa_pairs': len(pairs),
        'v78_status': v78.get('status'),
        'map_info': map_info,
        'statistic': stat,
        'pairs_preview': pairs[:60],
        'source_audit': audit[:40],
        'manual_fill_required': False,
        'claim_policy_v79': 'v79 parses NANOGrav .res files directly, joins median post-fit residuals to .par coordinates, and samples the public lensing map. Confirmation still requires positive signed statistic, shuffle p<=0.05, and top-weight stability.',
    }
    return row

