def _v79_p32_second_event_artifact():
    v78 = _v65_read_json(_v65_dir('measurements') / 'p32_second_event_url_resolver_v78_AUTO_PUBLIC.json') or {}
    paths = _v73_public_candidate_files(['*GW*.hdf5', '*GW*.gwf', '*GW*.txt.gz', '*eventapi*', '*GWTC*'], max_files=3200)
    local, metadata, audit = set(), set(), []
    for p in paths[:700]:
        pp = _V65Path(p)
        ids = set(m.upper() for m in _v65_re.findall(r'GW\d{6}', str(pp), _v65_re.I))
        low = str(pp).lower()
        if ids and any(tok in low for tok in ('.hdf5', '.gwf', '.txt.gz', 'strain')):
            local.update(ids)
        if pp.exists() and pp.stat().st_size < 120_000_000 and any(tok in low for tok in ('eventapi', 'gwtc', 'confident')):
            txt = _v78_read_text(pp, max_bytes=20_000_000)
            metadata.update(m.upper() for m in _v65_re.findall(r'GW\d{6}', txt, _v65_re.I))
        audit.append(_v73_file_digest_record(pp, {'event_ids_in_name': sorted(ids)}))
    row = {
        'artifact_version': _V79_VERSION,
        'status': 'p32_multi_event_local_strain_ready_v79' if len(local) >= 2 else 'p32_second_local_strain_still_absent_v79',
        'local_strain_event_ids': sorted(local),
        'metadata_event_ids_seen': sorted(metadata)[:120],
        'n_local_strain_events': len(local),
        'n_metadata_event_ids_seen': len(metadata),
        'v78_eventapi_strain_events': v78.get('n_eventapi_strain_events'),
        'source_audit': audit[:180],
        'manual_fill_required': False,
        'claim_policy_v79': 'v79 widens local GWOSC strain and metadata discovery, but metadata-only event ids do not satisfy the two-local-strain-event gate.',
    }
    return row

