_V80_VERSION = 'v80'

_run_nanograv_for_v80 = RUNNERS.get('nanograv_retry_cache_v22', run_nanograv_coordinate_gate_v50)
_run_cl2_for_v80 = RUNNERS.get('cl2_weighted_parse_v21', run_cl2_pta_density_gate_v79)
