_run_p39_for_v80 = RUNNERS.get('p39_likelihood_gate_v22', run_p39_likelihood_gate_v79)

def _v80_gate(missing, **extra):
    missing = [m for m in missing if m]
    g = {'gate_version': _V80_VERSION, 'eligible_for_confirm_like': not missing, 'missing': missing}
    g.update(extra)
    return g

def _v80_write_measurement(name, obj):
    out = _v65_dir('measurements') / name
    _v65_write_json(out, obj)
    return out

def _v80_write_output(name, obj):
    out = _v65_dir('outputs') / name
    _v65_write_json(out, obj)
    return out

def _v80_base_existing(test_id, meta, args, runner=None, fallback_status='positive_compatible', call_runner=True):
    existing = _v72_output_by_test_id(test_id)
    if isinstance(existing, dict) and existing:
        return dict(existing)
    if runner is not None and call_runner:
        try:
            return runner(meta, args)
        except Exception as e:
            b = base_result(meta, fallback_status)
            b['v80_base_runner_error'] = repr(e)[:500]
            return b
    return base_result(meta, fallback_status)

def _v80_stat_p_le(stat, key, threshold=0.05):
    p = _v65_float((stat or {}).get(key))
    return p is not None and p <= threshold

def _v80_pta_p8_promotion_artifact(args):
    row79 = _v65_read_json(_v65_dir('measurements') / 'pta_residual_kappa_direct_res_parser_v79_AUTO_PUBLIC.json') or {}
    if (row79.get('n_joined_residual_kappa_pairs') or 0) < 20:
        try:
            row79 = _v79_pta_residual_kappa_artifact(args)
        except Exception as e:
            row79 = {'status': 'pta_residual_kappa_recompute_failed_v80', 'error': repr(e)[:500]}
    stat = row79.get('statistic') or {}
    missing = []
    if (row79.get('n_joined_residual_kappa_pairs') or 0) < 20:
        missing.append('public_residual_kappa_pairs_ge_20')
    if _v65_float(stat.get('weighted_statistic')) is None or (_v65_float(stat.get('weighted_statistic')) or 0) <= 0:
        missing.append('positive_public_weighted_statistic')
    if not _v80_stat_p_le(stat, 'public_one_sided_signed_sky_shuffle_p'):
        missing.append('public_one_sided_signed_sky_shuffle_p_le_0p05')
    if not stat.get('top_weight_removal_stable'):
        missing.append('public_top_weight_removal_stable')
    row = {
        'artifact_version': _V80_VERSION,
        'status': 'pta_p8_direct_residual_kappa_confirm_ready_v80' if not missing else 'pta_p8_direct_residual_kappa_not_confirmed_v80',
        'source_artifact': 'measurements/pta_residual_kappa_direct_res_parser_v79_AUTO_PUBLIC.json',
        'n_joined_residual_kappa_pairs': row79.get('n_joined_residual_kappa_pairs'),
        'n_residual_rows_v79': row79.get('n_residual_rows_v79'),
        'n_par_coordinates_v79': row79.get('n_par_coordinates_v79'),
        'statistic': stat,
        'promotion_missing': missing,
        'manual_fill_required': False,
        'claim_policy_v80': 'v80 promotes the P8/P8c inventory only when the direct public NANOGrav .res residual-kappa join already satisfies the signed statistic, sky-shuffle, and top-weight stability gates.',
    }
    return row

