# Scope: implement the eight requested follow-up improvements after v80:
# targeted GWOSC second-strain resolution plus likelihood rebuild, P33 sibling
# LSS resolver, P30 Planck/Euclid source resolvers, P35 real P(k)/xi
# discriminator, P3 NDskl parser, and P39 covariance URL/source expansion.
# ============================================================================

_V81_VERSION = 'v81'

_run_nanograv_for_v81 = RUNNERS.get('nanograv_retry_cache_v22', run_nanograv_retry_cache_v80)
_run_cl2_for_v81 = RUNNERS.get('cl2_weighted_parse_v21', run_cl2_pta_density_gate_v80)
_run_p33_for_v81 = RUNNERS.get('p33_density_bao_measured_scaffold_v22', run_p33_density_bao_measurement_gate_v80)
_run_p30_for_v81 = RUNNERS.get('p30_maskrandom_freeze_v22', run_p30_publication_gate_v80)
_run_planck_for_v81 = RUNNERS.get('planck_route_guard_v20', run_planck_route_guard_v80)
_run_euclid_for_v81 = RUNNERS.get('euclid_mer_catalogue_only_v13', run_euclid_route_guard_v80)
_run_p35_for_v81 = RUNNERS.get('harmonic_comb_proxy', run_harmonic_comb_proxy_v80)
_run_p3_for_v81 = RUNNERS.get('p3_exact_metadata_v21', run_p3_exact_metadata_v80)
_run_p32_for_v81 = RUNNERS.get('ringdown_strain_plan_v22', run_ringdown_strain_gate_v80)
_run_p39_for_v81 = RUNNERS.get('p39_likelihood_gate_v22', run_p39_likelihood_gate_v80)

def _v81_gate(missing, **extra):
    missing = [m for m in missing if m]
    g = {'gate_version': _V81_VERSION, 'eligible_for_confirm_like': not missing, 'missing': missing}
    g.update(extra)
    return g

def _v81_write_measurement(name, obj):
    out = _v65_dir('measurements') / name
    _v65_write_json(out, obj)
    return out

def _v81_write_output(name, obj):
    out = _v65_dir('outputs') / name
    _v65_write_json(out, obj)
    return out

def _v81_base_existing(test_id, meta, args, runner=None, fallback_status='positive_compatible', call_runner=False):
    existing = _v72_output_by_test_id(test_id)
    if isinstance(existing, dict) and existing:
        return dict(existing)
    if runner is not None and call_runner:
        try:
            return runner(meta, args)
        except Exception as e:
            b = base_result(meta, fallback_status)
            b['v81_base_runner_error'] = repr(e)[:500]
            return b
    return base_result(meta, fallback_status)

def _v81_short_args(args, timeout=8, max_mb=None, allow_large=None):
    try:
        data = dict(vars(args))
    except Exception:
        data = {}
    data['timeout'] = min(int(data.get('timeout', timeout) or timeout), timeout)
    if max_mb is not None:
        data['max_mb'] = max_mb
    if allow_large is not None:
        data['allow_large'] = allow_large
    return argparse.Namespace(**data)

def _v81_p_le(stat, key, threshold=0.05):
    p = _v65_float((stat or {}).get(key))
    return p is not None and p <= threshold

def _v81_event_stem(text):
    m = _v65_re.search(r'(GW\d{6}(?:_\d{6})?)', str(text or ''), _v65_re.I)
    return m.group(1).upper() if m else None

def _v81_load_gwtc3_events():
    paths = list((_V65Path.cwd() / '.ccdr_round10_cache').glob('*GWTC-3-confident*'))
    for p in paths:
        try:
            obj = json.loads(_v78_read_text(p, max_bytes=5_000_000))
            events = obj.get('events') if isinstance(obj, dict) else None
            if isinstance(events, dict):
                return events, str(p)
        except Exception:
            continue
    return {}, None

def _v81_top_p32_events():
    t18 = _v72_output_by_test_id('R10-T18') or {}
    events = []
    for key in ('top5_for_strain_download', 'ranked_ringdown_candidates'):
        for r in t18.get(key) or []:
            ev = _v81_event_stem((r or {}).get('event'))
            if ev and ev not in events:
                events.append(ev)
    for ev in ('GW200129_065458', 'GW200224_222234', 'GW200112_155838', 'GW191109_010717'):
        if ev not in events:
            events.append(ev)
    return events[:6]

def _v81_local_strain_files_for_event(event):
    cache = _V65Path.cwd() / '.ccdr_round10_cache'
    ev = str(event or '').lower()
    compact = ev.replace('_', '')
    out = []
    for p in cache.glob('*'):
        if not p.is_file():
            continue
        low = p.name.lower()
        if ev not in low and compact not in low:
            continue
        if not any(tok in low for tok in ('gwosc', 'strain', '16khz', '4khz', 'losc')):
            continue
        if not low.endswith(('.hdf5', '.h5', '.gwf', '.txt.gz')):
            continue
        det = 'H1' if ('h-h1' in low or 'h1' in low) else ('L1' if ('l-l1' in low or 'l1' in low) else ('V1' if 'v1' in low else None))
        out.append({'event': event, 'path': str(p), 'size_bytes': p.stat().st_size, 'detector': det, 'format': p.suffix.lower().lstrip('.')})
    return out

def _v81_strain_urls_from_event_json(path):
    urls = []
    try:
        obj = json.loads(_v78_read_text(path, max_bytes=20_000_000))
    except Exception:
        return urls
    def walk(x):
        if isinstance(x, dict):
            if 'url' in x and any(str(x.get(k, '')).lower() in ('hdf5', 'h5') for k in ('format', 'fileFormat')):
                u = str(x.get('url') or '')
                if u.endswith(('.hdf5', '.h5')):
                    urls.append({'url': u, 'detector': x.get('detector'), 'duration': x.get('duration'), 'sampling_rate': x.get('sampling_rate'), 'format': x.get('format')})
            for v in x.values():
                walk(v)
        elif isinstance(x, list):
            for v in x:
                walk(v)
    walk(obj)
    return urls

def _v81_p32_targeted_strain_fetch_artifact(args):
    v80 = _v65_read_json(_v65_dir('measurements') / 'p32_archive_strain_resolver_v80_AUTO_PUBLIC.json') or {}
    gwtc_events, gwtc_path = _v81_load_gwtc3_events()
    targets = _v81_top_p32_events()
    local_by_event = {}
    attempts = []
    short = _v81_short_args(args, timeout=8, max_mb=90.0, allow_large=False)
    for ev in targets:
        files = _v81_local_strain_files_for_event(ev)
        if not files and ev in gwtc_events:
            jsonurl = (gwtc_events.get(ev + '-v1') or gwtc_events.get(ev) or {}).get('jsonurl')
            if not jsonurl:
                for k, v in gwtc_events.items():
                    if _v81_event_stem(k) == ev:
                        jsonurl = (v or {}).get('jsonurl')
                        break
            if jsonurl:
                jp, at = download_candidates([jsonurl], _V65Path(args.cache_dir), 'p32_v81_event_json_' + ev, short)
                attempts.extend(at)
                urls = _v81_strain_urls_from_event_json(jp) if jp else []
                # Prefer small 32s 4K HDF5 files and at most H1/L1 for each target.
                selected = []
                for rec in urls:
                    u = str(rec.get('url') or '')
                    if not u.endswith(('.hdf5', '.h5')):
                        continue
                    if rec.get('duration') not in (None, 32):
                        continue
                    sr = int(rec.get('sampling_rate') or 0)
                    if sr and sr > 4096:
                        continue
                    det = str(rec.get('detector') or '')
                    if det not in ('H1', 'L1'):
                        continue
                    selected.append(rec)
                seen_det = set()
                for rec in selected[:4]:
                    det = rec.get('detector')
                    if det in seen_det:
                        continue
                    seen_det.add(det)
                    p, at2 = download_candidates([rec['url']], _V65Path(args.cache_dir), 'p32_v81_' + ev + '_' + str(det), short)
                    attempts.extend(at2)
                    if p and p.exists():
                        files.append({'event': ev, 'path': str(p), 'size_bytes': p.stat().st_size, 'detector': det, 'format': p.suffix.lower().lstrip('.'), 'downloaded_v81': True})
        if files:
            local_by_event[ev] = files
    # Always preserve the previously confirmed local event.
    for ev in (v80.get('local_strain_event_ids') or []):
        local_by_event.setdefault(ev, _v81_local_strain_files_for_event(ev))
    detector_counts = {ev: len(set(f.get('detector') for f in files if f.get('detector'))) for ev, files in local_by_event.items()}
    row = {
        'artifact_version': _V81_VERSION,
        'status': 'p32_targeted_second_strain_ready_v81' if len(local_by_event) >= 2 else 'p32_targeted_second_strain_absent_v81',
        'target_events': targets,
        'gwtc3_catalog_source': gwtc_path,
        'local_strain_events': [{'event': ev, 'n_files': len(files), 'n_detectors': detector_counts.get(ev), 'files_preview': files[:8]} for ev, files in sorted(local_by_event.items())],
        'local_strain_event_ids': sorted(local_by_event.keys()),
        'n_local_strain_events': len(local_by_event),
        'download_attempts': attempts[:30],
        'v80_status': v80.get('status'),
        'manual_fill_required': False,
        'claim_policy_v81': 'v81 targets the highest-SNR/mass GWTC-3 events from T18, resolves event JSON, and downloads only small 32s 4K HDF5 H1/L1 strain products when available. Metadata-only event ids do not satisfy the gate.',
    }
    return row

def _v81_p32_likelihood_rebuild_artifact(fetch_row):
    old = _v65_read_json(_v65_dir('measurements') / 'p32_multi_event_strain_likelihood_v74_AUTO_PUBLIC.json') or {}
    events = fetch_row.get('local_strain_events') or []
    per_event = []
    for ev in events:
        files = ev.get('files_preview') or []
        dets = sorted(set(f.get('detector') for f in files if f.get('detector')))
        small = [f for f in files if (f.get('size_bytes') or 0) <= 120_000_000]
        per_event.append({'event': ev.get('event'), 'n_detectors': len(dets), 'detectors': dets, 'n_small_strain_products': len(small), 'analysis_ready': bool(len(dets) >= 2 and small)})
    # This is deliberately conservative: a second local event is necessary but
    # not sufficient. We keep the old measured likelihood numbers unless a full
    # strain fitter is available in the cached artifacts.
    min_delta = _v65_float(old.get('v71_min_detector_delta_chi2'))
    max_p = _v65_float(old.get('v71_max_time_slide_p'))
    row = {
        'artifact_version': _V81_VERSION,
        'status': 'p32_multi_event_likelihood_rebuild_inputs_ready_v81' if len(events) >= 2 else 'p32_multi_event_likelihood_rebuild_inputs_absent_v81',
        'n_local_strain_events': len(events),
        'per_event_readiness': per_event,
        'rebuilt_detector_delta_chi2_min': min_delta,
        'rebuilt_time_slide_p_max': max_p,
        'leave_one_event_out_stable': False,
        'confirm_like': bool(len(events) >= 2 and min_delta is not None and min_delta >= 4 and max_p is not None and max_p <= 0.05),
        'manual_fill_required': False,
        'claim_policy_v81': 'v81 rebuilds the multi-event gate bookkeeping from local strain products, but does not promote unless detector split, time-slide, and leave-one-event-out checks pass.',
    }
    return row

def run_ringdown_strain_gate_v81(meta, args):
    base = _v81_base_existing('R10-T19', meta, args, _run_p32_for_v81, 'ringdown_strain_analysis_required_v80')
    fetch = _v81_p32_targeted_strain_fetch_artifact(args)
    fetch_out = _v81_write_measurement('p32_targeted_second_strain_fetch_v81_AUTO_PUBLIC.json', fetch)
    like = _v81_p32_likelihood_rebuild_artifact(fetch)
    like_out = _v81_write_measurement('p32_multi_event_likelihood_rebuild_v81_AUTO_PUBLIC.json', like)
    missing = []
    if (fetch.get('n_local_strain_events') or 0) < 2:
        missing.append('two_distinct_local_public_strain_events')
    if _v65_float(like.get('rebuilt_detector_delta_chi2_min')) is None or (_v65_float(like.get('rebuilt_detector_delta_chi2_min')) or 0) < 4:
        missing.append('min_detector_delta_chi2_ge_4')
    if _v65_float(like.get('rebuilt_time_slide_p_max')) is None or (_v65_float(like.get('rebuilt_time_slide_p_max')) or 1) > 0.05:
        missing.append('time_slide_p_le_0p05')
    if not like.get('leave_one_event_out_stable'):
        missing.append('leave_one_event_out_stable')
    base['p32_targeted_second_strain_fetch_v81'] = fetch
    base['p32_targeted_second_strain_fetch_gate_v81'] = _v81_gate([] if (fetch.get('n_local_strain_events') or 0) >= 2 else ['two_distinct_local_public_strain_events'], artifact_path=str(fetch_out), diagnostic_class=fetch['status'])
    base['p32_multi_event_likelihood_rebuild_v81'] = like
    base['p32_multi_event_likelihood_rebuild_gate_v81'] = _v81_gate(missing, artifact_path=str(like_out), diagnostic_class=like['status'])
    base['status'] = 'ringdown_strain_likelihood_confirm_like_v81' if not missing else 'ringdown_strain_analysis_required_v81'
    return base

def _v81_lss_sibling_paths_from_randoms():
    v80 = _v65_read_json(_v65_dir('measurements') / 'p33_exact_lss_classifier_v80_AUTO_PUBLIC.json') or {}
    paths = []
    seen = set()
    for rec in v80.get('source_audit') or []:
        if rec.get('classified_kind_v80') != 'random':
            continue
        p = _V65Path(rec.get('path') or '')
        if not p.exists() or 'p30_' in str(p).lower():
            continue
        names = set()
        s = str(p)
        repls = [
            ('random', 'clustering'), ('Random', 'clustering'), ('full.ran', 'clustering'),
            ('_ran', '_clustering'), ('.ran', '.clustering'), ('ran_', 'clustering_'),
        ]
        for a, b in repls:
            if a in s:
                names.add(s.replace(a, b))
        for cand in names:
            cp = _V65Path(cand)
            if cp.exists() and str(cp) not in seen:
                seen.add(str(cp))
                paths.append(cp)
    extra = _v73_public_candidate_files(['*clustering*.fits*', '*clustering*.dat*', '*clustering*.csv*', '*LSScats*clustering*', '*BGS*clustering*', '*LRG*clustering*', '*ELG*clustering*', '*QSO*clustering*'], max_files=2200)
    for p in extra:
        low = str(p).lower()
        if 'p30_' in low or 'random' in low or '_cov' in low or '_mean' in low:
            continue
        if str(p) not in seen:
            seen.add(str(p))
            paths.append(_V65Path(p))
    return paths

def _v81_p33_sibling_lss_artifact():
    v80 = _v65_read_json(_v65_dir('measurements') / 'p33_exact_lss_classifier_v80_AUTO_PUBLIC.json') or {}
    cat_rows, audit = [], []
    for p in _v81_lss_sibling_paths_from_randoms()[:220]:
        try:
            rows, info = _v69_load_rdz_any(p, max_rows=120000)
        except Exception as e:
            rows, info = [], {'path': str(p), 'error': repr(e)[:260]}
        if not rows:
            try:
                trows, tinfo = _v78_parse_table_any(p, str(p.name), max_rows=120000)
                rows = _v80_rdz_from_dict_rows(trows, tinfo, max_rows=120000)
                info = {**tinfo, **info}
            except Exception:
                pass
        cat_rows.extend(rows[:max(0, 120000 - len(cat_rows))])
        audit.append({'path': str(p), 'sha256': _v65_sha256(p) if p.exists() else None, 'n_rdz_rows': len(rows), 'columns': info.get('columns') or info.get('header'), 'error': info.get('error') or info.get('fits_error')})
        if len(cat_rows) >= 120000:
            break
    random_rows = int(v80.get('n_exact_random_rows') or 0)
    fit = _v65_pair_alpha(cat_rows[:6000]) if len(cat_rows) >= 800 else None
    if fit:
        fit['desi_randoms_used'] = bool(random_rows >= 800)
        fit['n_random_rows_available'] = random_rows
    row = {
        'artifact_version': _V81_VERSION,
        'status': 'p33_lss_sibling_alpha_fit_built_v81' if fit else 'p33_lss_sibling_catalog_still_absent_v81',
        'n_exact_catalog_rows': len(cat_rows),
        'n_exact_random_rows_v80': random_rows,
        'exact_alpha_fit': fit,
        'source_audit': audit[:160],
        'v80_status': v80.get('status'),
        'manual_fill_required': False,
        'claim_policy_v81': 'v81 infers clustering siblings from exact random products and excludes P30 random controls before attempting a density-split alpha fit.',
    }
    return row

def run_p33_density_bao_measurement_gate_v81(meta, args):
    base = _v81_base_existing('R10-T07', meta, args, _run_p33_for_v81, 'p33_density_bao_alpha_measurement_required_v80')
    row = _v81_p33_sibling_lss_artifact()
    out = _v81_write_measurement('p33_lss_sibling_resolver_v81_AUTO_PUBLIC.json', row)
    fit = row.get('exact_alpha_fit') or {}
    missing = []
    if (row.get('n_exact_catalog_rows') or 0) < 800:
        missing.append('exact_lss_clustering_rows_ge_800')
    if (row.get('n_exact_random_rows_v80') or 0) < 800:
        missing.append('exact_random_rows_ge_800')
    for k in ('alpha_high_density', 'alpha_low_density', 'delta_alpha'):
        if _v65_float(fit.get(k)) is None:
            missing.append(k)
    if not fit.get('desi_randoms_used'):
        missing.append('random_normalized_density_split')
    if not _v81_p_le(fit, 'density_label_shuffle_p'):
        missing.append('density_label_shuffle_p_le_0p05')
    if not fit.get('redshift_jackknife_stable'):
        missing.append('redshift_jackknife_stable')
    missing.append('sky_shuffle_p_le_0p05')
    base['p33_lss_sibling_resolver_v81'] = row
    base['p33_lss_sibling_resolver_gate_v81'] = _v81_gate(missing, artifact_path=str(out), diagnostic_class=row['status'])
    base['status'] = 'p33_density_bao_alpha_confirm_like_v81' if not missing else 'p33_density_bao_alpha_measurement_required_v81'
    return base

def _v81_planck_url_artifact(args):
    base = _v80_planck_true_source_artifact(args)
    urls = [
        'https://irsa.ipac.caltech.edu/data/Planck/release_3/ancillary-data/lensing/COM_Lensing_4096_R3.00/MV/dat_klm.fits',
        'https://irsa.ipac.caltech.edu/data/Planck/release_3/ancillary-data/lensing/COM_Lensing_4096_R3.00/MV/mask.fits',
        'https://portal.nersc.gov/project/cmb/planck2020/PR3/COM_Lensing_4096_R3.00/MV/dat_klm.fits',
    ]
    attempts = []
    sources = []
    short = _v81_short_args(args, timeout=8, max_mb=220.0, allow_large=False)
    for i, url in enumerate(urls):
        p, at = download_candidates([url], _V65Path(args.cache_dir), 'p30_planck_v81_' + str(i), short)
        attempts.extend(at)
        if p and p.exists() and p.suffix.lower() in ('.fits', '.fit'):
            sources.append({'path': str(p), 'url': url, 'size_bytes': p.stat().st_size})
            break
    if sources:
        # Reuse the v80 sampler logic against the downloaded true Planck source.
        catalogue, cat_path = _v79_cached_sdss_coords(max_rows=2000)
        best_stat = None
        best_source = None
        audit = []
        for src in sources:
            m, info = _v79_load_map_from_fits_or_alm(src['path'], args, nside=64)
            info.update(src)
            if m is not None and catalogue:
                st = _v13_density_stat_with_footprint(m, catalogue, args, density_nside=32)
                info['sdss_same_mask_statistic'] = st
                best_stat, best_source = st, info
            audit.append(info)
        confirm = bool(best_stat and (_v65_float(best_stat.get('delta_high_minus_low')) or 0) > 0 and _v81_p_le(best_stat, 'sky_shuffle_p_high') and _v81_p_le(best_stat, 'density_bin_shuffle_p_high') and best_stat.get('jackknife_same_sign'))
        base.update({
            'status': 'p30_planck_url_same_mask_confirm_like_v81' if confirm else 'p30_planck_url_source_seen_not_confirmed_v81',
            'n_planck_candidate_sources_v81': len(sources),
            'chosen_planck_source_v81': best_source,
            'same_mask_density_kappa_statistic_v81': best_stat,
            'planck_route_confirm_like': confirm,
            'source_audit_v81': audit[:20],
        })
    else:
        base.update({'status': 'p30_planck_url_sources_absent_v81', 'n_planck_candidate_sources_v81': 0})
    base['artifact_version'] = _V81_VERSION
    base['download_attempts_v81'] = attempts[:20]
    base['claim_policy_v81'] = 'v81 tries explicit Planck PR3 COM_Lensing/dat_klm product URLs and only confirms after same-mask statistic/nulls on the true Planck product.'
    return base

def _v81_euclid_native_artifact(args):
    base = _v80_euclid_native_kappa_artifact(args)
    sibling_patterns = ['*EUC*CONVERGENCE*', '*EUC*SHEAR*', '*euclid*shear*', '*euclid*convergence*', '*MER*shear*', '*MER*convergence*', '*VIS*kappa*']
    paths = _v73_public_candidate_files(sibling_patterns, max_files=2200)
    rows_all = []
    audit = []
    for rows, info in _v78_table_sources(paths, ['euclid', 'EUC', 'MER', 'VIS', 'kappa', 'convergence', 'shear', 'gamma'], max_files=220, max_members=3600, max_rows=120000, max_member_bytes=160_000_000):
        krows = _v80_extract_kappa_rows(rows, info, max_out=max(0, 120000 - len(rows_all)))
        # If only shear columns exist, build a diagnostic convergence proxy but do
        # not count it as native kappa confirmation unless a kappa/convergence
        # column was explicit.
        explicit = bool(krows)
        rows_all.extend(krows)
        audit.append({k: info.get(k) for k in ('path', 'archive_path', 'archive_member', 'n_rows', 'reason', 'error', 'fits_error', 'sha256')} | {'n_native_kappa_rows': len(krows), 'explicit_kappa_or_convergence': explicit})
        if len(rows_all) >= 120000:
            break
    if rows_all:
        rows_all = _v80_fill_cell_density_proxy(rows_all)
        stat = _v78_density_kappa_split_stat(rows_all)
        confirm = bool(len(rows_all) >= 800 and (_v65_float(stat.get('delta_high_minus_low')) or 0) > 0 and _v81_p_le(stat, 'density_shuffle_p_high'))
        base.update({'status': 'p30_euclid_native_kappa_confirm_like_v81' if confirm else 'p30_euclid_native_kappa_rows_ready_v81', 'n_native_euclid_kappa_cell_rows': len(rows_all), 'density_kappa_split_stat': stat, 'euclid_route_confirm_like': confirm, 'rows_preview': rows_all[:60]})
    else:
        base.update({'status': 'p30_euclid_native_kappa_cells_absent_v81', 'n_native_euclid_kappa_cell_rows': 0, 'euclid_route_confirm_like': False})
    base['artifact_version'] = _V81_VERSION
    base['source_audit_v81'] = audit[:180]
    base['claim_policy_v81'] = 'v81 adds Euclid shear/convergence sibling-product discovery, but only explicit native kappa/convergence rows can confirm the Euclid route.'
    return base

def _v81_p30_route_artifact(args):
    v80_route = _v65_read_json(_v65_dir('measurements') / 'p30_route_measurement_sampler_v80_AUTO_PUBLIC.json') or {}
    planck = _v81_planck_url_artifact(args)
    euclid = _v81_euclid_native_artifact(args)
    sdss = bool(v80_route.get('sdss_scoped_confirm_like'))
    planck_confirm = bool(planck.get('planck_route_confirm_like'))
    euclid_confirm = bool(euclid.get('euclid_route_confirm_like'))
    row = {
        'artifact_version': _V81_VERSION,
        'status': 'p30_global_second_route_confirmed_v81' if sdss and (planck_confirm or euclid_confirm) else 'p30_second_route_still_not_confirmed_v81',
        'sdss_scoped_confirm_like': sdss,
        'planck_route_confirm_like': planck_confirm,
        'euclid_route_confirm_like': euclid_confirm,
        'second_independent_route_confirm_like': bool(planck_confirm or euclid_confirm),
        'n_routes_confirm_like': int(sdss) + int(planck_confirm or euclid_confirm),
        'manual_fill_required': False,
        'claim_policy_v81': 'v81 requires SDSS plus either an explicit Planck URL-resolved same-mask confirm or an explicit Euclid-native kappa/convergence confirm.',
    }
    return row, planck, euclid

def run_p30_publication_gate_v81(meta, args):
    base = _v81_base_existing('R10-T04', meta, args, _run_p30_for_v81, 'density_kappa_global_route_blocked_v80')
    row, planck, euclid = _v81_p30_route_artifact(args)
    out = _v81_write_measurement('p30_route_measurement_sampler_v81_AUTO_PUBLIC.json', row)
    _v81_write_measurement('p30_planck_url_product_resolver_v81_AUTO_PUBLIC.json', planck)
    _v81_write_measurement('p30_euclid_native_sibling_resolver_v81_AUTO_PUBLIC.json', euclid)
    missing = []
    if not row.get('sdss_scoped_confirm_like'):
        missing.append('sdss_route_confirm_like')
    if not row.get('second_independent_route_confirm_like'):
        missing.append('second_independent_route_confirm_like_with_true_planck_or_euclid_native_public_values')
    base['p30_route_measurement_sampler_v81'] = row
    base['p30_global_second_route_gate_v81'] = _v81_gate(missing, artifact_path=str(out), diagnostic_class=row['status'])
    base['status'] = 'density_kappa_global_route_confirm_like_v81' if not missing else ('density_kappa_sdss_route_confirm_like_v81' if row.get('sdss_scoped_confirm_like') else 'density_kappa_global_route_blocked_v81')
    return base

