def _v81_is_real_pkxi_source(info):
    source = str(info.get('archive_member') or info.get('path') or '').lower()
    if any(tok in source for tok in ('arxiv_source', 'source_v13', 'kmos', 'firas', 'pantheon', 'p30_', 'random', 'cov', '_mean', 'gaussian_bao')):
        return False
    if not any(tok in source for tok in ('pofk', 'pk', 'power', 'xi', 'correlation', 'multipole', 'monopole', 'boss', 'eboss', 'desi', 'sdss')):
        return False
    return True

def _v81_real_pkxi_artifact():
    v80 = _v65_read_json(_v65_dir('measurements') / 'p35_pkxi_fits_alias_reader_v80_AUTO_PUBLIC.json') or {}
    patterns = ['*pofk*', '*pk*.dat*', '*pk*.txt*', '*pk*.fits*', '*xi*.dat*', '*xi*.txt*', '*xi*.fits*', '*multipole*.fits*', '*monopole*.fits*', '*BOSS*pk*', '*eBOSS*xi*', '*DESI*pk*', '*DESI*xi*']
    paths = _v73_public_candidate_files(patterns, max_files=2600)
    audit, rejected, best = [], [], None
    for rows, info in _v78_table_sources(paths, ['pofk', 'pk', 'Pk', 'xi', 'Xi', 'power', 'multipole', 'monopole', 'BOSS', 'eBOSS', 'DESI', 'SDSS'], max_files=300, max_members=4200, max_rows=100000, max_member_bytes=140_000_000):
        is_real = _v81_is_real_pkxi_source(info)
        prows = _v80_power_rows_from_dicts(rows, info, max_rows=100000) if is_real else []
        if not prows and is_real and info.get('path'):
            try:
                prows = _v71_parse_power_rows(info.get('path'), max_rows=100000)
            except Exception:
                prows = []
        score = _v71_harmonic_score(prows) if prows else None
        bootstrap = None
        if prows and score:
            rng = _v65_random.Random(81)
            vals = []
            nsub = min(len(prows), max(50, len(prows) // 2))
            for _ in range(64):
                sub = [prows[i] for i in sorted(rng.sample(range(len(prows)), nsub))]
                sc = _v71_harmonic_score(sub)
                if sc and sc.get('comb_spacing_cv') is not None:
                    vals.append(sc.get('comb_spacing_cv'))
            bootstrap = {'n_bootstrap': len(vals), 'median_comb_spacing_cv': sorted(vals)[len(vals)//2] if vals else None, 'stable_cv_lt_0p2_fraction': (sum(1 for x in vals if x < 0.2) / len(vals) if vals else None)}
        rec = {k: info.get(k) for k in ('path', 'archive_path', 'archive_member', 'n_rows', 'reason', 'error', 'fits_error', 'sha256')} | {'real_pkxi_source_v81': is_real, 'n_power_rows': len(prows), 'score': score, 'bootstrap': bootstrap}
        if not is_real:
            rejected.append(rec)
        else:
            audit.append(rec)
            if score and score.get('phase_randomized_p') is not None and (best is None or (score.get('n_peaks') or 0) > (((best.get('score') or {}).get('n_peaks')) or 0)):
                best = rec
    row = {
        'artifact_version': _V81_VERSION,
        'status': 'p35_real_pkxi_candidate_built_v81' if best else 'p35_real_pkxi_source_absent_v81',
        'best_lss_power_or_xi_candidate': best,
        'v80_status': v80.get('status'),
        'v80_best_candidate': v80.get('best_lss_power_or_xi_candidate'),
        'rejected_non_pkxi_candidates': rejected[:100],
        'source_audit': audit[:220],
        'manual_fill_required': False,
        'claim_policy_v81': 'v81 rejects arXiv/source text and unrelated spectra, then targets BOSS/eBOSS/DESI/SDSS P(k), xi, multipole, and monopole products only.',
    }
    return row

