def _v81_parse_ndskl(path, max_rows=2000):
    rows = []
    try:
        text = _v69_read_text_maybe_gzip(path, max_bytes=30_000_000)
    except Exception:
        return rows
    points = []
    for ln in text.splitlines():
        if not ln.strip() or ln.lstrip().startswith('#'):
            continue
        nums = [_v65_float(x) for x in _v65_re.findall(r'[-+]?(?:\d+\.\d*|\.\d+|\d+)(?:[eE][-+]?\d+)?', ln)]
        nums = [x for x in nums if x is not None]
        if len(nums) >= 3:
            points.append(nums[:4])
        if len(points) > max_rows * 2:
            break
    for i in range(0, max(0, len(points) - 1), 2):
        a, b = points[i], points[i + 1]
        if len(a) < 3 or len(b) < 3:
            continue
        ra1, dec1 = (a[0], a[1]) if 0 <= a[0] <= 360 and -90 <= a[1] <= 90 else _v78_xyz_to_radec(a[0], a[1], a[2])
        ra2, dec2 = (b[0], b[1]) if 0 <= b[0] <= 360 and -90 <= b[1] <= 90 else _v78_xyz_to_radec(b[0], b[1], b[2])
        if ra1 is None or dec1 is None or ra2 is None or dec2 is None:
            continue
        z = next((x for x in (a[2:] + b[2:]) if 0 < x < 5), None)
        angle = _v76_angle_deg([ra1, dec1, ra2, dec2])
        if angle is not None:
            rows.append({'source_path': str(path), 'schema': 'ndskl_pairwise_points', 'ra1': ra1, 'dec1': dec1, 'ra2': ra2, 'dec2': dec2, 'redshift': z, 'angle_deg': angle})
        if len(rows) >= max_rows:
            break
    return rows

def _v81_p3_ndskl_artifact():
    v80 = _v65_read_json(_v65_dir('outputs') / 'p3_endpoint_graph_parser_v80.json') or {}
    paths = _v73_public_candidate_files(['*.NDskl*', '*.a.NDskl*', '*NDskl*', '*skeleton*', '*disperse*', '*skel*'], max_files=2600)
    found, audit = [], []
    for p in paths[:260]:
        pp = _V65Path(p)
        if not pp.exists() or pp.stat().st_size > 160_000_000:
            continue
        low = str(pp).lower()
        if any(tok in low for tok in ('random', 'p30_', 'maskrandom')):
            audit.append(_v73_file_digest_record(pp, {'skipped': 'random_or_p30_scoped'}))
            continue
        rows = _v81_parse_ndskl(pp, max_rows=max(0, 2200 - len(found)))
        found.extend(rows)
        audit.append(_v73_file_digest_record(pp, {'n_ndskl_endpoint_rows': len(rows)}))
        if len(found) >= 2200:
            break
    orient = _v76_orientation_score([r['angle_deg'] for r in found if r.get('angle_deg') is not None])
    n_z = sum(1 for r in found if _v65_float(r.get('redshift')) is not None)
    row = {
        'artifact_version': _V81_VERSION,
        'status': 'p3_ndskl_endpoint_rows_recovered_v81' if found else 'p3_ndskl_endpoint_sources_absent_v81',
        'n_strict_endpoint_rows': len(found),
        'n_endpoint_rows_with_redshift': n_z,
        'orientation_statistic': orient,
        'endpoint_rows_preview': found[:100],
        'v80_status': v80.get('status'),
        'v80_n_strict_endpoint_rows': v80.get('n_strict_endpoint_rows'),
        'source_audit': audit[:180],
        'manual_fill_required': False,
        'claim_policy_v81': 'v81 adds native DisPerSE/NDskl skeleton point-pair parsing; endpoint confirmation still requires redshift rows and orientation-null significance.',
    }
    return row

