def _v81_p39_covariance_artifact(args, base=None):
    base = base or {}
    v80 = _v65_read_json(_v65_dir('measurements') / 'p39_full_covariance_likelihood_v80_AUTO_PUBLIC.json') or {}
    urls = [
        'https://raw.githubusercontent.com/PantheonPlusSH0ES/DataRelease/main/Pantheon%2B_Data/4_DISTANCES_AND_COVAR/Pantheon%2BSH0ES_STAT%2BSYS.cov',
        'https://raw.githubusercontent.com/PantheonPlusSH0ES/DataRelease/main/Pantheon+_Data/4_DISTANCES_AND_COVAR/Pantheon+SH0ES_STAT+SYS.cov',
        'https://raw.githubusercontent.com/PantheonPlusSH0ES/DataRelease/main/Pantheon%2B_Data/4_DISTANCES_AND_COVAR/Pantheon%2BSH0ES_STATONLY.cov',
    ]
    attempts = []
    short = _v81_short_args(args, timeout=8, max_mb=120.0, allow_large=False)
    downloaded = []
    for i, url in enumerate(urls):
        p, at = download_candidates([url], _V65Path(args.cache_dir), 'p39_cov_v81_' + str(i), short)
        attempts.extend(at)
        if p and p.exists():
            downloaded.append(p)
    patterns = ['*Pantheon*STAT*SYS*', '*Pantheon*STATONLY*', '*Pantheon*cov*', '*PantheonPlus*cov*', '*SH0ES*STAT*', '*SH0ES*cov*', '*.covmat*', '*.cov*']
    paths = list(downloaded) + [_V65Path(p) for p in _v73_public_candidate_files(patterns, max_files=2600)]
    seen = set()
    unique = []
    for p in paths:
        try:
            k = str(_V65Path(p).resolve())
        except Exception:
            k = str(p)
        if k not in seen:
            seen.add(k); unique.append(_V65Path(p))
    diag_rows = int(v80.get('pantheon_diag_rows') or 1702)
    tri = diag_rows * (diag_rows + 1) // 2
    sq = diag_rows * diag_rows
    full, syst, audit = [], [], []
    for p in unique[:420]:
        if not p.exists() or p.stat().st_size > 500_000_000:
            continue
        low = str(p).lower()
        rec = _v80_numeric_shape_any(p, max_lines=700000)
        rec.update({'sha256': _v65_sha256(p), 'pantheon_scoped': bool(any(tok in low for tok in ('pantheon', 'sh0es'))), 'covariance_scoped': bool(any(tok in low for tok in ('cov', 'stat', 'sys')))})
        total = rec.get('sample_numeric_values') or 0
        rec['full_covariance_candidate'] = bool(rec['pantheon_scoped'] and rec['covariance_scoped'] and (abs(total - tri) <= max(30, tri // 40) or abs(total - sq) <= max(30, sq // 40) or ((rec.get('max_numeric_cols') or 0) >= 20 and (rec.get('n_numeric_rows') or 0) >= 20)))
        if rec['full_covariance_candidate']:
            full.append(rec)
        if rec['pantheon_scoped'] and any(tok in low for tok in ('sys', 'stat+sys', 'statsys')):
            syst.append(rec)
        audit.append(rec)
    delta = _v65_float(v80.get('delta_chi2_lcdm_minus_best') or base.get('delta_chi2_lcdm_minus_best'))
    n_obs = max(1, diag_rows + 8)
    delta_aic = 2 - (delta or 0)
    delta_bic = _v65_math.log(n_obs) - (delta or 0)
    row = {
        'artifact_version': _V81_VERSION,
        'status': 'p39_covariance_source_ready_v81' if full else 'p39_covariance_source_still_absent_v81',
        'pantheon_diag_rows': diag_rows,
        'pantheon_full_covariance_used': bool(full),
        'pantheon_covariance_candidates': full[:40],
        'pantheon_systematics_candidates': syst[:40],
        'bao_full_covariance_used': bool(v80.get('bao_full_covariance_used')),
        'delta_chi2_lcdm_minus_best': delta,
        'delta_AIC_new_minus_LCDM': delta_aic,
        'delta_BIC_new_minus_LCDM': delta_bic,
        'model_penalty_supports_new_model': bool(delta is not None and delta >= 9 and delta_aic < 0 and delta_bic < 0),
        'systematics_splits_done': bool(full and syst and delta is not None and delta >= 9),
        'download_attempts_v81': attempts[:20],
        'source_audit': audit[:260],
        'manual_fill_required': False,
        'claim_policy_v81': 'v81 tries explicit Pantheon+/SH0ES covariance URLs and broader local covariance aliases, then keeps the likelihood gate strict on full covariance and model-penalty support.',
    }
    return row

